#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    int line_count;
    int word_count;
} FileStats;

void print_usage(const char *program_name) {
    printf("Usage: %s [options] input_file1.txt input_file2.txt ...\n", program_name);
    printf("Options:\n");
    printf("  --manpage          Display man page and exit\n");
    printf("  -cs                 Enable case-sensitive mode\n");
    printf("  -o output_file      Specify output file for results\n");
    printf("  -d delimiter        Specify custom delimiter for splitting lines\n");
}

FileStats process_file(const char *filename, const char *delimiter) {
    FileStats stats = {0};
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return stats;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, delimiter);
        while (token != NULL) {
            stats.word_count++;
            token = strtok(NULL, delimiter);
        }
        stats.line_count++;
    }

    fclose(file);
    return stats;
}

void signal_handler(int signum) {
    printf("Processing interrupted by user.\n");
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage(argv[0]);
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--manpage")) {
            // Display man page and exit
            print_usage(argv[0]);
            return 0;
        }
    }

    signal(SIGINT, signal_handler);

    const char *delimiter = "\n";
    int case_sensitive = 0;
    FILE *output_file = stdout;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-cs")) {
            case_sensitive = 1;
        } else if (!strncmp(argv[i], "-o", 2)) {
            output_file = fopen(strchr(argv[i], '=') + 1, "w");
            if (!output_file) {
                perror("Error opening output file");
                return 1;
            }
        } else if (!strncmp(argv[i], "-d", 2)) {
            delimiter = strchr(argv[i], '=') + 1;
        } else {
            FileStats stats = process_file(argv[i], delimiter);
            fprintf(output_file, "File: %s\nLines: %d\nWords: %d\n", argv[i], stats.line_count, stats.word_count);
        }
    }

    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}
