#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>

#define MAX_CACHE_SIZE 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

typedef struct {
    char hostname[256];
    struct in_addr ip;
    time_t last_resolved;
} DNSCacheEntry;

DNSCacheEntry cache[MAX_CACHE_SIZE];
int cache_size = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
int log_level = LOG_LEVEL_INFO;

void log_message(int level, const char *message) {
    if (level >= log_level) {
        printf("%s\n", message);
    }
}

void limit_capabilities() {
    // Set resource limits
    struct rlimit rl;
    rl.rlim_cur = 1024;  // Soft limit
    rl.rlim_max = 2048;  // Hard limit
    setrlimit(RLIMIT_NOFILE, &rl);
}

int resolve_hostname(const char *hostname, u_char *ip_address) {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            time_t current_time = time(NULL);
            if ((current_time - cache[i].last_resolved) <= 3600) {
                memcpy(ip_address, &(cache[i].ip), sizeof(struct in_addr));
                pthread_mutex_unlock(&cache_mutex);
                return 0;
            }
        }
    }

    struct hostent *he = gethostbyname(hostname);
    if (he == NULL) {
        pthread_mutex_unlock(&cache_mutex);
        log_message(LOG_LEVEL_INFO, "DNS resolution failed for hostname");
        return -1;
    }

    struct in_addr ip = *((struct in_addr *)he->h_addr_list[0]);
    memcpy(ip_address, &ip, sizeof(struct in_addr));

    if (cache_size < MAX_CACHE_SIZE) {
        cache[cache_size].last_resolved = time(NULL);
        strcpy(cache[cache_size].hostname, hostname);
        cache[cache_size].ip = ip;
        cache_size++;
    }

    pthread_mutex_unlock(&cache_mutex);
    return 0;
}

void *dns_service_thread(void *arg) {
    char hostname[256];
    u_char ip_address[sizeof(struct in_addr)];
    strcpy(hostname, (char *)arg);

    if (resolve_hostname(hostname, ip_address) == 0) {
        printf("Resolved IP for %s: %s\n", hostname, inet_ntoa(*(struct in_addr *)ip_address));
    } else {
        printf("Failed to resolve IP for %s\n", hostname);
    }

    return NULL;
}

int main() {
    limit_capabilities();

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, dns_service_thread, (void *)"example.com");
    pthread_create(&thread2, NULL, dns_service_thread, (void *)"google.com");

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
