#include <stdio.h>
#include <stdlib.h>

#define MAX_NUMBERS 1000

int findLargest(int *arr, int count) {
    if (count == 0) return -1; // Return -1 if no numbers are present
    int largest = arr[0];
    for (int i = 1; i < count; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void readNumbers(int **array, int *count) {
    *count = 0;
    while (*count < MAX_NUMBERS) {
        int number;
        printf("Enter an integer (or -1 to finish): ");
        scanf("%d", &number);
        if (number == -1) break;
        if (number < 0) {
            printf("Negative numbers are ignored.\n");
            continue;
        }
        (*array)[*count] = number;
        ++(*count);
    }
}

int main() {
    int *numbers = malloc(MAX_NUMBERS * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    int count = 0;
    readNumbers(&numbers, &count);

    int largest = findLargest(numbers, count);
    if (largest != -1) {
        printf("The largest number is: %d\n", largest);
    } else {
        printf("No numbers were entered.\n");
    }

    free(numbers);
    return 0;
}
