bool validate_oauth2_token(const char* json_str) {
    struct json_object *parsed_json, *token_type_obj, *expires_in_obj;
    const char *token_type;

    parsed_json = json_tokener_parse(json_str);
    if (!parsed_json)
        return false;

    token_type_obj = json_object_object_get_ex(parsed_json, "token_type", &token_type);
    expires_in_obj = json_object_object_get_ex(parsed_json, "expires_in", NULL);

    if (!token_type_obj || !expires_in_obj)
        goto cleanup;

    token_type = json_object_get_string(token_type_obj);
    int expires_in = json_object_get_int(expires_in_obj);

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0)
        goto cleanup;

    if (json_object_object_get_ex(parsed_json, "refresh_token", NULL))
        // Handle optional refresh token if needed

cleanup:
    json_object_put(parsed_json);
    return token_type_obj && expires_in_obj;
}

EVP_CIPHER* handle_oauth2_and_crypto(const char* json_str, enum cipher_mode mode, int null_encryption) {
    if (!validate_oauth2_token(json_str))
        return NULL;

    EVP_CIPHER* cipher = get_cipher(mode, null_encryption);
    if (!cipher)
        fprintf(stderr, "Invalid cipher mode\n");

    return cipher;
}
