from cryptography.fernet import Fernet
import sys

def get_pokemon_info():
    # Placeholder function to simulate retrieving Pokemon type and name
    type = "Fire"
    name = "Pikachu"
    return {"type": type, "name": name}

class Pokemon:
    def __init__(self, info):
        self.type = info["type"]
        self.name = info["name"]

def get_pokemon_weaknesses(pokemon):
    weaknesses = {
        "Fire": ["Water", "Ground"],
        "Water": ["Electric", "Grass"],
        "Electric": ["Grass", "Ground"],
        "Grass": ["Fire", "Ice"]
    }
    return weaknesses.get(pokemon.type, [])

def replace_placeholders(config_content, replacements):
    for placeholder, value in replacements.items():
        config_content = config_content.replace(placeholder, value)
    return config_content

def add_encrypted_password(config_content, password):
    key = Fernet.generate_key()
    fernet = Fernet(key)
    encrypted_password = fernet.encrypt(password.encode())
    config_content += f"\nEncrypted Password: {encrypted_password.decode()}"
    return key, encrypted_password

def execute_sed_command(command):
    try:
        subprocess.run(command, check=True, shell=True)
    except subprocess.CalledProcessError as e:
        print(f"Error executing sed command: {e}")
        sys.exit(1)

def update_config_file(config_path, replacements, password):
    with open(config_path, 'r') as file:
        config_content = file.read()

    updated_content = replace_placeholders(config_content, replacements)
    key, encrypted_password = add_encrypted_password(updated_content, password)

    with open('updated_config', 'w') as file:
        file.write(updated_content)

    execute_sed_command(f'sed -i "s/KEY/{key.decode()}/" updated_config')
    execute_sed_command(f'sed -i "s/ENCRYPTED_PASSWORD/{encrypted_password.decode()}/" updated_config')

def main():
    replacements = {"PLACEHOLDER1": "value1", "PLACEHOLDER2": "value2"}
    password = "mySecretPassword"

    pokemon_info = get_pokemon_info()
    pokemon = Pokemon(pokemon_info)
    weaknesses = get_pokemon_weaknesses(pokemon)

    print(f"Weaknesses of {pokemon.name}: {', '.join(weaknesses)}")

    update_config_file('config.txt', replacements, password)

if __name__ == "__main__":
    main()
