['```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10

sem_t resourceSemaphore;
pthread_mutex_t resourceMutex;

void initializeResources() {
    sem_init(&resourceSemaphore, 0, MAX_THREADS);
    pthread_mutex_init(&resourceMutex, NULL);
}

void accessResource() {
    sem_wait(&resourceSemaphore);
    pthread_mutex_lock(&resourceMutex);
    // Critical section: Access shared resource
    printf("Accessing shared resource\n");
    pthread_mutex_unlock(&resourceMutex);
    sem_post(&resourceSemaphore);
}

void cleanupResources() {
    pthread_mutex_destroy(&resourceMutex);
    sem_destroy(&resourceSemaphore);
}

int main() {
    initializeResources();

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, accessResource, NULL);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanupResources();

    return 0;
}
