#include <forward_list>

void incrementDivisibleOrAppendSum(std::forward_list<int>& fl, int incrementBy, int divisibleBy) {
    int sum = 0;
    auto it = fl.begin();
    while (it != fl.end()) {
        if (*it % divisibleBy == 0) {
            *it += incrementBy;
        } else {
            sum += *it;
        }
        ++it;
    }
    if (sum > 0) {
        fl.push_back(sum * incrementBy);
    }
}
