                std::cerr << "JSON parse error: " << e.what() << std::endl;
            } catch (const std::exception& e) {
                std::cerr << "Error loading configuration file: " << e.what() << std::endl;
            }
        }

        nlohmann::json getConfig(const std::string& key) const {
            if (!config.contains(key)) {
                throw std::runtime_error("Configuration key not found.");
            }
            return config[key];
        }

    private:
        ConfigurationManager() {}
        ConfigurationManager(ConfigurationManager const&) = delete;
        void operator=(ConfigurationManager const&) = delete;

        nlohmann::json config;
    };
}

