public async Task<int> BatchUpdateAsync(List<DataObject> dataObjects, string connectionString, string sqlCommand)
{
    int successfulUpdates = 0;

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        await connection.OpenAsync();

        using (SqlCommand command = new SqlCommand(sqlCommand, connection))
        {
            foreach (var item in dataObjects)
            {
                command.Parameters.Clear();

                // Add parameters based on the properties of your DataObject
                command.Parameters.AddWithValue("@Id", item.Id);
                command.Parameters.AddWithValue("@Value", item.Value);

                try
                {
                    await command.ExecuteNonQueryAsync();
                    successfulUpdates++;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error updating record {item.Id}: {ex.Message}");
                }
            }
        }
    }

    return successfulUpdates;
}

