    private const string ApiKey = "YOUR_API_KEY";
    private static readonly HttpClient Client = new HttpClient();

    public static async Task<string> GetGeolocationDataAsync(string address)
    {
        try
        {
            var encodedAddress = Uri.EscapeUriString(address);
            var url = $"https://api.example.com/geocode?address={encodedAddress}&key={ApiKey}";
            var response = await Client.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Error fetching geolocation data: {ex.Message}");
            return null;
        }
    }

    public static async Task<JObject> CalculateRouteAsync(string origin, string destination, DateTime[] timeWindows)
    {
        try
        {
            var encodedOrigin = Uri.EscapeUriString(origin);
            var encodedDestination = Uri.EscapeUriString(destination);
            var url = $"https://api.example.com/route?origin={encodedOrigin}&destination={encodedDestination}&time_windows={string.Join(",", timeWindows)}&key={ApiKey}";
            var response = await Client.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return JObject.Parse(await response.Content.ReadAsStringAsync());
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Error calculating route: {ex.Message}");
            return null;
        }
    }

    public static async Task Main(string[] args)
    {
        Console.Write("Enter the delivery origin address: ");
        var origin = Console.ReadLine();
        Console.Write("Enter the delivery destination address: ");
        var destination = Console.ReadLine();

        DateTime timeWindow1 = new DateTime(2023, 4, 1, 9, 0, 0);
        DateTime timeWindow2 = new DateTime(2023, 4, 1, 17, 0, 0);

        var geolocationOrigin = await GetGeolocationDataAsync(origin);
        var geolocationDestination = await GetGeolocationDataAsync(destination);

        if (geolocationOrigin != null && geolocationDestination != null)
        {
            var route = await CalculateRouteAsync(geolocationOrigin, geolocationDestination, new DateTime[] { timeWindow1, timeWindow2 });

            if (route != null)
            {
                Console.WriteLine($"Optimal route: {route}");
            }
        }
    }
}
