[ApiController]
[Route("api/[controller]")]
public class UsersController : ControllerBase
{
    private readonly IUserRepository _userRepository;
    private readonly ISystemAuditLogService _auditLogService;

    public UsersController(IUserRepository userRepository, ISystemAuditLogService auditLogService)
    {
        _userRepository = userRepository;
        _auditLogService = auditLogService;
    }

    [HttpPut("{userId}")]
    public async Task<IActionResult> UpdateUserProfile(int userId, [FromBody] UserProfileUpdateDto updateDto)
    {
        var user = await _userRepository.GetUserByIdAsync(userId);
        if (user == null)
            return NotFound();

        user.Update(updateDto);

        if (!_userRepository.TryUpdateUser(user))
        {
            return StatusCode(409, "Concurrent update conflict. Please try again.");
        }

        await _auditLogService.LogChangeAsync(userId, ChangeType.Update, user);
        return NoContent();
    }

    [HttpPost("soft-delete")]
    public async Task<IActionResult> SoftDeleteUser([FromBody] int userId)
    {
        var user = await _userRepository.GetUserByIdAsync(userId);
        if (user == null)
            return NotFound();

        user.IsDeleted = true;

        if (!_userRepository.TryUpdateUser(user))
        {
            return StatusCode(409, "Concurrent update conflict. Please try again.");
        }

        await _auditLogService.LogChangeAsync(userId, ChangeType.SoftDelete, user);
        return NoContent();
    }
}

public interface IUserRepository
{
    Task<User> GetUserByIdAsync(int userId);
    bool TryUpdateUser(User user);
}

public interface ISystemAuditLogService
{
    Task LogChangeAsync(int userId, ChangeType changeType, User user);
}

public enum ChangeType
{
    Update,
    SoftDelete
}
