using System;
using System.Collections.Generic;
using System.Xml.XPath;

public class XmlParser
{
    public List<string> ParseXmlForElementText(string xmlContent, string elementName)
    {
        var resultList = new List<string>();
        try
        {
            XPathDocument doc = new XPathDocument(new System.IO.StringReader(xmlContent));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//{elementName}");

            string previousText = null;
            while (nodes.MoveNext())
            {
                XPathNavigator node = nodes.Current;
                string text = node.Value.Trim();

                if (!string.IsNullOrEmpty(text) && !text.Equals(previousText))
                {
                    resultList.Add(text);
                    previousText = text;
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error parsing XML: {ex.Message}");
        }

        return resultList;
    }
}
