import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Hasher {

    public static String getMD5(String input) {
        if (input == null || input.length() > 1024) {
            throw new IllegalArgumentException("Input is null or exceeds the maximum length of 1024 characters.");
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Log the error without exposing sensitive information
            System.err.println("Failed to get MD5 instance.");
            throw new RuntimeException(e); // Rethrow as a runtime exception for better error handling in multi-threaded environments
        }
    }

    public static void main(String[] args) {
        try {
            String result = getMD5("Hello, World!");
            System.out.println("MD5 hash: " + result);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
