        {
            return new HttpResponseMessage(HttpStatusCode.Unauthorized);
        }

        // Check cache for valid content
        string cacheKey = $"{sessionId}_{templateId}";
        bool shouldReload = true;
        string cachedContent = null;

        lock (cacheLock)
        {
            if (cache.ContainsKey(cacheKey) && cache[cacheKey].Expiry > DateTime.UtcNow)
            {
                cachedContent = cache[cacheKey].Content;
                shouldReload = false;
            }
        }

        // If no valid cache, generate content
        if (shouldReload)
        {
            string generatedContent = GenerateDynamicContent(templateId, personalizedData);
            lock (cacheLock)
            {
                if (!cache.ContainsKey(cacheKey) || cache[cacheKey].Expiry < DateTime.UtcNow)
                {
                    cache[cacheKey] = (generatedContent, DateTime.UtcNow.AddMinutes(10));
                }
            }
        }

        // Return response based on content and user preferences
        var response = new HttpResponseMessage(HttpStatusCode.OK);
        response.Content = new StringContent(cachedContent);
        response.Headers.Add("Cache-Control", shouldReload ? "no-cache" : "public, max-age=600");
