import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;

public class StateLoader {

    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();
    private static String filePath;
    private static int versionThreshold;

    public static void init(String configServiceUrl) {
        // Initialize file path and version threshold from the external configuration service
        ExternalConfigService configService = new ExternalConfigService(configServiceUrl);
        filePath = configService.getFilePath();
        versionThreshold = configService.getVersionThreshold();
    }

    public static MoSTState loadMoSTState() throws IOException, ClassNotFoundException {
        String key = "state";
        if (cache.containsKey(key)) {
            return (MoSTState) cache.get(key);
        } else {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    MoSTState state = (MoSTState) obj;
                    if (state.getVersion() < versionThreshold) {
                        System.out.println("Warning: Incompatible state version.");
                    }
                    cache.put(key, state);
                    return state;
                } else {
                    return null;
                }
            }
        }
    }

    // ExternalConfigService is a hypothetical class that fetches configuration settings
    private static class ExternalConfigService {
        private String url;

        public ExternalConfigService(String url) {
            this.url = url;
        }

        public String getFilePath() {
            // Fetch file path from the config service
            return "path/to/state/file";
        }

        public int getVersionThreshold() {
            // Fetch version threshold from the config service
            return 2;
        }
    }
}
