["```javascript
const fs = require('fs').promises;
const path = require('path');

// Cache for stored file contents
const fileCache = new Map();

async function readFile(filePath) {
  if (fileCache.has(filePath)) {
    return fileCache.get(filePath);
  }
  try {
    const content = await fs.readFile(filePath, 'utf8');
    fileCache.set(filePath, content);
    return content;
  } catch (error) {
    throw new Error(`Failed to read file: ${filePath}`);
  }
}

async function processFileContent(content) {
  // Example processing: count words
  return content.split(/\s+/).length;
}

async function generateReport(directoryPath) {
  try {
    const files = await fs.readdir(directoryPath);
    const results = [];

    for (const file of files) {
      const filePath = path.join(directoryPath, file);
      if (path.extname(filePath) === '.txt') { // Assuming .txt files
        const content = await readFile(filePath);
        const result = await processFileContent(content);
        results.push({ fileName: file, wordCount: result });
      }
    }

    return results;
  } catch (error) {
    throw new Error(`Failed to generate report: ${error.message}`);
  }
}

// Example usage:
(async () => {
  try {
    const report = await generateReport('./path/to/directory');
    console.log(report);
  } catch (error) {
    console.error(error.message);
  }
})();
```

This code provides a basic structure for reading and processing multiple files asynchronously in JavaScript. It includes caching to minimize repeated file reads, which can be crucial for performance under high load conditions. The `generateReport` function reads all `.txt` files from the specified directory, processes their content (in this example, counting words), and returns a summary report. Error handling is integrated throughout to manage potential issues gracefully."]

