function runTests(label, f, outputPath) {
  const fs = require('fs').promises;
  const { exec } = require('child_process');
  const bluebird = require('bluebird');
  const blueslip = require('./blueslip-mock');

  function wrapTestInPromise(testFunction) {
    return new Promise((resolve, reject) => {
      try {
        testFunction(() => resolve(), () => reject());
      } catch (error) {
        reject(error);
      }
    });
  }

  async function executeTests() {
    const startTime = Date.now();
    await bluebird.map(f.tests, wrapTestInPromise, { concurrency: f.concurrency || 1 });
    blueslip.resetMock();

    const endTime = Date.now();
    const executionTime = endTime - startTime;

    const result = f.results;
    result.executionTime = executionTime;

    try {
      await fs.writeFile(outputPath, JSON.stringify(result, null, 2));
      console.log(`Tests completed successfully. Results saved to ${outputPath}`);
    } catch (writeError) {
