function generateForm(formFields, enableDynamicFields) {
  let formHtml = '<form>';

  formFields.forEach(field => {
    if (field.required) {
      formHtml += `<label for="${field.label}">${field.label}:</label>`;
      formHtml += `<input type="${field.type}" id="${field.label}" name="${field.label}" required defaultValue="${field.defaultValue || ''}">`;
    } else {
      formHtml += `<label for="${field.label}">${field.label}:</label>`;
      formHtml += `<input type="${field.type}" id="${field.label}" name="${field.label}" defaultValue="${field.defaultValue || ''}">`;
    }
  });

  if (enableDynamicFields) {
    formHtml += '<button type="button" onclick="addNewField()">Add New Field</button>';
    formHtml += `<script>
      function addNewField() {
        const container = document.createElement('div');
        const input = document.createElement('input');
        input.type = 'text';
        input.name = 'dynamic_field[]';
        container.appendChild(input);
        document.querySelector('form').appendChild(container);
      }
    </script>`;
  }

  formHtml += '</form>';

  return formHtml;
}

// Example usage:
const formFields = [
  { type: 'text', label: 'Name', required: true },
  { type: 'email', label: 'Email', required: true },
  { type: 'password', label: 'Password', required: true }
];

const enableDynamicFields = true;
console.log(generateForm(formFields, enableDynamicFields));
