["```javascript
class StreamingDataHandler {
  constructor() {
    this.dataArray = [];
    this.isPaused = false;
    this.graph = {};
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
    this.processData();
  }

  addData(data) {
    if (!this.isPaused) {
      this.dataArray.push(data);
      this.processData();
    }
  }

  processData() {
    while (this.dataArray.length > 0 && !this.isPaused) {
      const dataPoint = this.dataArray.shift();
      this.updateGraph(dataPoint);
    }
  }

  updateGraph(dataPoint) {
    if (!this.graph[dataPoint.vertexId]) {
      this.graph[dataPoint.vertexId] = {};
      Object.assign(this.graph[dataPoint.vertexId], this.generateRandomVertexProperties());
    }
    dataPoint.edges.forEach(edge => {
      if (!this.graph[edge.targetId]) {
        this.graph[edge.targetId] = {};
        Object.assign(this.graph[edge.targetId], this.generateRandomVertexProperties());
      }
      this.graph[dataPoint.vertexId][edge.targetId] = Object.assign({}, edge, this.generateRandomEdgeProperties());
    });
  }

  generateRandomVertexProperties() {
    return {
      properties: Math.random().toString(36).substring(7)
    };
  }

  generateRandomEdgeProperties() {
    return {
      weight: Math.floor(Math.random() * 100),
      attributes: Math.random().toString(36).substring(7)
    };
  }
}

// Example usage:
const handler = new StreamingDataHandler();
handler.addData({ vertexId: 'v1', edges: [{ targetId: 'v2' }, { targetId: 'v3' }] });
setTimeout(() => {
  handler.pause();
  setTimeout(() => {
    handler.resume();
  }, 5000);
}, 2000);
