["```javascript
function copyBufferChunks(dataChunks, startByte, endByte) {
  if (startByte < 0 || endByte > dataChunks.reduce((acc, chunk) => acc + chunk.length, 0)) {
    throw new Error('Requested byte range exceeds available data');
  }

  const totalLength = endByte - startByte;
  let offset = 0;
  const resultBuffer = Buffer.alloc(totalLength);

  for (const chunk of dataChunks) {
    if (offset >= totalLength) break;

    const chunkStart = Math.max(startByte - offset, 0);
    const chunkEnd = Math.min(endByte - offset, chunk.length);
    const lengthToCopy = chunkEnd - chunkStart;

    chunk.copy(resultBuffer, offset + chunkStart, chunkStart, chunkEnd);

    offset += lengthToCopy;
  }

  return resultBuffer;
}

// Example usage:
const dataChunks = [
  Buffer.from('Hello,'),
  Buffer.from(' world!'),
  Buffer.from(' This is a test.'),
];

try {
  const newBuffer = copyBufferChunks(dataChunks, 7, 20);
  console.log(newBuffer.toString()); // Output: 'world! This'
} catch (error) {
  console.error(error.message);
}
```

Note: The provided code snippet assumes that the `dataChunks` array contains instances of the Node.js `Buffer` class. If you are working in an environment where Buffers are not available, you may need to use an alternative approach or library to handle binary data efficiently."]

