function findMatchingObjects(json, targetProperty, filterFn) {
  let result = [];

  function traverse(obj) {
    if (typeof obj !== 'object' || obj === null) return;

    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let value = obj[key];
        if (key === targetProperty && filterFn(value)) {
          result.push(obj);
        }
        traverse(value);
      }
    }
  }

  traverse(json);
  return result;
}
