['```java
import java.util.*;

public class NetworkRequestProcessor {
    private static final int BATCH_SIZE = 100;

    public static void processRequests(List<NetworkRequest> requests) {
        long startTime = System.currentTimeMillis();
        int distinctResourceIds = processBatch(requests);
        long endTime = System.currentTimeMillis();

        System.out.println("Distinct resource IDs in overlapping intervals: " + distinctResourceIds);
        System.out.println("Processing time: " + (endTime - startTime) + " ms");
    }

    private static int processBatch(List<NetworkRequest> requests) {
        IntervalTree intervalTree = new IntervalTree();
        Set<Integer> uniqueResources = new HashSet<>();

        for (NetworkRequest request : requests) {
            int resourceId = request.getResourceId();
            long start = request.getTimestamp();
            long end = start + 1; // Assuming each request has a duration of 1 millisecond

            if (!intervalTree.isEmpty()) {
                List<Interval> overlappingIntervals = intervalTree.overlapping(start, end);
                for (Interval interval : overlappingIntervals) {
                    uniqueResources.add((int) interval.data);
                }
            }

            intervalTree.insert(new Interval(start, end, resourceId));
        }

        return uniqueResources.size();
    }
}

class NetworkRequest {
    private long timestamp;
    private int resourceId;

    public NetworkRequest(long timestamp, int resourceId) {
        this.timestamp = timestamp;
        this.resourceId = resourceId;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public int getResourceId() {
        return resourceId;
    }
}

class IntervalTree {
    private Node root;

    public boolean isEmpty() {
        return root == null;
    }

    public void insert(Interval interval) {
        if (root == null) {
            root = new Node(interval);
        } else {
            root.insert(interval);
        }
    }

    public List<Interval> overlapping(long start, long end) {
        List<Interval> result = new ArrayList<>();
        if (root != null) {
            root.overlapping(start, end, result);
        }
        return result;
    }

    private static class Node {
        Interval data;
        Node left, right;

        Node(Interval interval) {
            this.data = interval;
            this.left = this.right = null;
        }

        void insert(Interval interval) {
            if (interval.start < data.start) {
                if (left == null)
                    left = new Node(interval);
                else
                    left.insert(interval);
            } else {
                if (right == null)
                    right = new Node(interval);
                else
                    right.insert(interval);
            }
        }

        void overlapping(long start, long end, List<Interval> result) {
            if (data.start <= end && data.end >= start) {
                result.add(data);
            }
            if (left != null && left.data.end > start)
                left.overlapping(start, end, result);
            if (right != null && right.data.start < end)
                right.overlapping(start, end, result);
        }
    }

    private static class Interval implements Comparable<Interval> {
        long start, end;
        Object data;

        Interval(long start, long end, Object data) {
            this.start = start;
            this.end = end;
            this.data = data;
        }

        @Override
        public int compareTo(Interval other) {
            return Long.compare(this.start, other.start);
        }
    }
}
```']

