import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private ScheduledExecutorService scheduler;
    private MessagingSystem messagingSystem;

    public ServiceManager(MessagingSystem messagingSystem) {
        this.messagingSystem = messagingSystem;
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void startService() {
        Runnable serviceTask = () -> {
            try {
                // Simulate service work
                System.out.println("Service is running...");
                Thread.sleep((long) (Math.random() * 5000)); // Random delay between 0-5 seconds

                // Stop the service with a random delay
                scheduler.schedule(this::stopService, (long) (Math.random() * 5000), TimeUnit.MILLISECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.out.println("Service stopped unexpectedly.");
            }
        };

        scheduler.scheduleAtFixedRate(serviceTask, 0, 1, TimeUnit.HOURS); // Run every hour
    }

    public void stopService() {
        try {
            // Simulate service stopping
            System.out.println("Stopping service...");
            Thread.sleep((long) (Math.random() * 5000)); // Random delay between 0-5 seconds

            // Send message to messaging system
            messagingSystem.sendMessage("Service stopped");
            System.out.println("Message sent to messaging system.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Failed to send message due to interruption.");
        }
    }

    public void shutdown() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

    public static void main(String[] args) {
        MessagingSystem messagingSystem = new MessagingSystem();
        ServiceManager serviceManager = new ServiceManager(messagingSystem);
        serviceManager.startService();

        // Simulate running the program for 10 minutes
        try {
            Thread.sleep(600000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        serviceManager.shutdown();
    }
}

interface MessagingSystem {
    void sendMessage(String message);
}

class ConsoleMessagingSystem implements MessagingSystem {
    @Override
    public void sendMessage(String message) {
        System.out.println("Message: " + message);
    }
}
