import os
import yaml
from redis import Redis

class ConfigManager:
    def __init__(self, base_path):
        self.base_path = base_path
        self.config_cache = {}
        self.redis_client = None

    def initialize_redis(self):
        self.redis_client = Redis(host='localhost', port=6379, db=0)

    def load_config_file(self, file_name):
        with open(os.path.join(self.base_path, file_name), 'r') as file:
            return yaml.safe_load(file)

    def update_configuration(self, service_name, config_data):
        if service_name not in self.config_cache:
            self.config_cache[service_name] = {}
        self.config_cache[service_name].update(config_data)
        # Update Redis cache
        for key, value in config_data.items():
            self.redis_client.set(f'{service_name}:{key}', value)

    def get_configuration(self, service_name):
        if service_name not in self.config_cache:
            return None
        return self.config_cache[service_name]

# Usage
config_manager = ConfigManager('/path/to/config/files')
config_manager.initialize_redis()

# Load initial configuration files
config_manager.update_configuration('service1', config_manager.load_config_file('service1.yaml'))
config_manager.update_configuration('service2', config_manager.load_config_file('service2.yaml'))

# Update configuration dynamically
new_service1_config = {'setting1': 'value1_updated'}
config_manager.update_configuration('service1', new_service1_config)

# Retrieve and use configuration
current_config = config_manager.get_configuration('service1')
print(current_config)
