use std::time::{Instant};
use sysinfo::{ProcessExt, System, SystemExt};
use rustc_driver::{catch_with_exit_code, EarlyError};
use lazy_static::lazy_static;

lazy_static! {
    static ref SYSTEM: System = System::new_all();
}

fn get_resident_set_size(pid: u32) -> Option<usize> {
    let process = SYSTEM.process(pid)?;
    Some(process.memory())
}

fn install_logging_hook() {
    // Implement custom logging hook
}

fn main() -> Result<(), EarlyError> {
    install_logging_hook();

    let start_time = Instant::now();
    let initial_memory = get_resident_set_size(std::process::id()).unwrap_or(0);

    let output = Command::new("rustc")
        .args(&["src/main.rs"])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?
        .wait_with_output()?;

    if !output.status.success() {
        return Err(EarlyError::Bug(format!("Compilation failed: {}", String::from_utf8_lossy(&output.stderr))));
    }

    let end_time = Instant::now();
    let final_memory = get_resident_set_size(std::process::id()).unwrap_or(0);

    let time_taken = end_time.duration_since(start_time).as_secs_f64();
    let memory_used = final_memory - initial_memory;

    println!("Compilation took: {} seconds", time_taken);
    println!("Memory used: {} bytes", memory_used);

    Ok(())
}
