<?php

class PasswordUtility {
    private $defaultHashAlgorithm = 'bcrypt';
    private $retryAttempts = 3;
    private $retryDelay = 5; // in seconds

    public function generateRandomString($length) {
        return substr(str_shuffle(str_repeat($x='0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*()', ceil($length/strlen($x)))),1,$length);
    }

    public function hashPassword($password, $algorithm = null) {
        if ($algorithm === null) {
            $algorithm = $this->defaultHashAlgorithm;
        }
        return password_hash($password, constant('PASSWORD_' . strtoupper($algorithm)));
    }

    public function verifyPassword($password, $hashedPassword) {
        for ($i = 0; $i <= $this->retryAttempts; $i++) {
            try {
                if (password_verify($password, $hashedPassword)) {
                    return true;
                }
            } catch (Exception $e) {
                // External service unavailable, retry after delay
                sleep($this->retryDelay);
            }
        }
        return false;
    }

    public function rotateHashAlgorithm() {
        $algorithms = ['bcrypt', 'argon2i', 'password'];
        $currentIndex = array_search($this->defaultHashAlgorithm, $algorithms);
        $nextIndex = ($currentIndex + 1) % count($algorithms);
        $this->defaultHashAlgorithm = $algorithms[$nextIndex];
    }
}
