#include <stdlib.h>
#include <assert.h>

typedef struct {
    int *transitions;
    int num_states;
    int start_state;
} FSA;

int* allocateStateList(int **states, int *numStates, const FSA *fsa, int lastStateIndex) {
    assert(states != NULL && numStates != NULL && fsa != NULL);

    // Calculate the maximum possible size of the state list
    int maxPossibleSize = 0;
    for (int i = 0; i < fsa->num_states; ++i) {
        for (int symbol = 0; symbol < /* Assume a fixed number of symbols */ 256; ++symbol) {
            if (fsa->transitions[i * /* Symbol count */ 256 + symbol] != -1) {
                maxPossibleSize++;
            }
        }
    }

    // Dynamically allocate memory for the state list
    int *newStateList = (int *)malloc(maxPossibleSize * sizeof(int));
    if (newStateList == NULL) {
        return NULL; // Memory allocation failed
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    states[lastStateIndex] = newStateList;

    return newStateList;
}
