#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_THREADS 100
#define BATCH_SIZE 100
#define MAX_TRANSACTION_AGE 5
#define RECENT_ACTIVITY_WINDOW 3
#define WEIGHTED_SUM_THRESHOLD 1000

typedef struct {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[BATCH_SIZE];
    int count;
    pthread_mutex_t lock;
} TransactionBatch;

TransactionBatch transaction_batches[MAX_CONCURRENT_THREADS];
int processed_transactions = 0;
int dropped_due_to_age = 0;
int exceeded_weighted_sum_threshold = 0;

void* process_batch(void* thread_id) {
    int id = *(int*)thread_id;
    pthread_mutex_lock(&transaction_batches[id].lock);
    while (1) {
        if (transaction_batches[id].count > 0) {
            TransactionBatch batch = transaction_batches[id];
            transaction_batches[id].count = 0;

            double max_weighted_sum = 0;
            int max_id = -1;
            for (int i = 0; i < BATCH_SIZE && i < batch.count; i++) {
                if ((time(NULL) - batch.transactions[i].timestamp) <= MAX_TRANSACTION_AGE) {
                    double weighted_sum = batch.transactions[i].weight * (time(NULL) - batch.transactions[i].timestamp);
                    if (weighted_sum > max_weighted_sum) {
                        max_weighted_sum = weighted_sum;
                        max_id = batch.transactions[i].id;
                    }
                } else {
                    dropped_due_to_age++;
                }
            }

            printf("Thread %d: Max Weighted Sum - %.2f, Transaction ID - %d\n", id, max_weighted_sum, max_id);
            processed_transactions += batch.count;
        } else {
            pthread_mutex_unlock(&transaction_batches[id].lock);
            break;
        }
    }
    pthread_mutex_unlock(&transaction_batches[id].lock);
    return NULL;
}

void add_transaction(int id, double weight) {
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_mutex_lock(&transaction_batches[i].lock);
        if (transaction_batches[i].count < BATCH_SIZE) {
            transaction_batches[i].transactions[transaction_batches[i].count++] = (Transaction){id, weight, time(NULL)};
            pthread_mutex_unlock(&transaction_batches[i].lock);
            return;
        }
        pthread_mutex_unlock(&transaction_batches[i].lock);
    }
    exceeded_weighted_sum_threshold++;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_THREADS];
    int thread_ids[MAX_CONCURRENT_THREADS];

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_mutex_init(&transaction_batches[i].lock, NULL);
        pthread_create(&threads[i], NULL, process_batch, &thread_ids[i]);
        thread_ids[i] = i;
    }

    // Simulate adding transactions
    for (int i = 0; i < 1000; i++) {
        add_transaction(i, i % 10);
    }

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total Processed Transactions: %d\n", processed_transactions);
    printf("Dropped Due to Age: %d\n", dropped_due_to_age);
    printf("Exceeded Weighted Sum Threshold: %d\n", exceeded_weighted_sum_threshold);

    return 0;
}
```']

