const std::string logFile = "attack_log.txt";
int lastAttackTime = 0;

void logAttack(int attackNumber) {
    std::lock_guard<std::mutex> lock(logMutex);
    std::ofstream file(logFile, std::ios::app);
    if (file.is_open()) {
        auto now = std::chrono::system_clock::now();
        time_t t = std::chrono::system_clock::to_time_t(now);
        file << "Attack " << attackNumber << " at " << std::ctime(&t) << std::endl;
        file.close();
    } else {
        std::cerr << "Failed to open log file" << std::endl;
    }
}

int selectRandomAttack(int cooldownInterval, int lastAttackTime) {
    auto now = std::chrono::system_clock::now();
    int currentTime = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();

    if (currentTime - lastAttackTime < cooldownInterval) {
        return -1; // Attack not ready
    }

    int attackNumber = rand() % 2 + 1;
    lastAttackTime = currentTime;

    logAttack(attackNumber);

    return attackNumber;
}

void threadFunction(int cooldownInterval, int &lastAttackTime) {
    while (true) {
        int selectedAttack = selectRandomAttack(cooldownInterval, lastAttackTime);
        if (selectedAttack != -1) {
            std::cout << "Character attacks with attack number: " << selectedAttack << std::endl;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
}

int main() {
    srand(time(0));
    int cooldownInterval = 2; // Cooldown in seconds

    std::thread t1(threadFunction, cooldownInterval, std::ref(lastAttackTime));
    std::thread t2(threadFunction, cooldownInterval, std::ref(lastAttackTime));

    t1.join();
    t2.join();

    return 0;
}
