using System;
using System.Collections.Concurrent;

public class RandomValueGenerator
{
    private ConcurrentDictionary<string, Random> generators = new ConcurrentDictionary<string, Random>();
    private long seed;

    public RandomValueGenerator(long initialSeed)
    {
        this.seed = initialSeed;
        InitializeGenerators();
    }

    private void InitializeGenerators()
    {
        generators.TryAdd("Integers", new Random(seed));
        generators.TryAdd("Floats", new Random(seed + 1));
    }

    public int GenerateRandomInteger(int min, bool includeMax)
    {
        if (min < 0 || includeMax && min == int.MaxValue)
        {
            throw new ArgumentException("Invalid range for integer generation.");
        }
        Random intGenerator = generators["Integers"];
        return includeMax ? intGenerator.Next(min, int.MaxValue) : intGenerator.Next(min + 1);
    }

    public float GenerateRandomFloat(float min, bool includeMax)
    {
        if (min < 0 || includeMax && min == float.MaxValue)
        {
            throw new ArgumentException("Invalid range for float generation.");
        }
        Random floatGenerator = generators["Floats"];
        return includeMax ? (float)(floatGenerator.NextDouble() * (min - max) + min) : (float)(floatGenerator.NextDouble() * (max - min) + min);
    }

    public void ResetGenerators()
    {
        InitializeGenerators();
    }

    public override string ToString()
    {
        return $"Integers: Seed={seed}, Last Value=Not Generated\nFloats: Seed={seed + 1}, Last Value=Not Generated";
    }
}
