#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for a resource item
typedef struct ResourceItem {
    char* key;
    char* value;
    struct ResourceItem** items; // Pointer to an array of nested items
    int itemCount; // Number of nested items
    struct ResourceItem* next; // Pointer to the next item in the linked list
} ResourceItem;

// Function to load a resource bundle from a file and return the number of items
int loadResourceBundle(const char* filePath, ResourceItem** bundle) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Failed to open resource file");
        return -1; // Error code for file opening failure
    }

    // Initialize the head of the linked list
    *bundle = NULL;
    ResourceItem* currentBundle = NULL;

    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Trim newline character from the end of the line
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[--len] = '\0';
        }

        // Check if the line is a comment or empty
        if (len == 0 || line[0] == '#') {
            continue;
        }

        char* keyValue = strchr(line, ':');
        if (keyValue != NULL) {
            *keyValue++ = '\0'; // Null-terminate the key part

            // Allocate memory for the key and value
            ResourceItem* newItem = (ResourceItem*)malloc(sizeof(ResourceItem));
            newItem->key = strdup(line);
            newItem->value = strdup(keyValue);
            newItem->items = NULL;
            newItem->itemCount = 0;
            newItem->next = NULL;

            // If this is the first item, set it as the head of the linked list
            if (*bundle == NULL) {
                *bundle = newItem;
                currentBundle = newItem;
            } else {
                // Add the new item to the end of the current bundle's items
                if (currentBundle->items == NULL) {
                    currentBundle->items = (ResourceItem**)malloc(sizeof(ResourceItem*));
                    currentBundle->items[0] = newItem;
                } else {
                    ResourceItem** temp = realloc(currentBundle->items, sizeof(ResourceItem*) * (currentBundle->itemCount + 1));
                    if (temp == NULL) {
                        perror("Failed to reallocate memory for items");
                        free(newItem->key);
                        free(newItem->value);
                        free(newItem);
                        fclose(file);
                        return -1; // Error code for memory allocation failure
                    }
                    currentBundle->items = temp;
                    currentBundle->items[currentBundle->itemCount] = newItem;
                }
                currentBundle->itemCount++;
            }
        }
    }

    fclose(file);
    return currentBundle != NULL ? currentBundle->itemCount : 0; // Return the number of items in the bundle
}
