} LineData;

int compareLines(const void* a, const void* b) {
    LineData* lineA = *(LineData**)a;
    LineData* lineB = *(LineData**)b;
    if (lineA->data[0] != lineB->data[0]) {
        return (lineA->data[0] < lineB->data[0]) ? -1 : 1;
    } else {
        return (lineA->data[1] > lineB->data[1]) ? -1 : 1;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE* inputFile = fopen(argv[1], "r");
    if (!inputFile) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE* outputFile = fopen(argv[2], "w");
    if (!outputFile) {
        perror("Failed to open output file");
        fclose(inputFile);
        return EXIT_FAILURE;
    }

    LineData** lines = NULL;
    size_t lineCount = 0;

    while (1) {
        char buffer[MAX_LINE_LENGTH];
        if (fgets(buffer, MAX_LINE_LENGTH, inputFile) == NULL) {
            break;
        }
        size_t numNumbers = 0;
        double* numbers = malloc(MAX_LINE_LENGTH * sizeof(double));
        if (!numbers) {
            perror("Memory allocation failed");
            fclose(inputFile);
            fclose(outputFile);
            for (size_t i = 0; i < lineCount; ++i) {
                free(lines[i]->data);
                free(lines[i]);
            }
            free(lines);
            return EXIT_FAILURE;
        }

        char* token = strtok(buffer, " ");
        while (token != NULL && numNumbers < MAX_LINE_LENGTH) {
            numbers[numNumbers++] = atof(token);
            token = strtok(NULL, " ");
        }

        if (numNumbers > 1) {
            double avg = (numbers[numNumbers - 2] + numbers[numNumbers - 1]) / 2.0;
            numbers = realloc(numbers, (numNumbers + 1) * sizeof(double));
            if (!numbers) {
                perror("Memory reallocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                return EXIT_FAILURE;
            }
            numbers[numNumbers++] = avg;

            LineData* lineData = malloc(sizeof(LineData));
            if (!lineData) {
                perror("Memory allocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                free(numbers);
                return EXIT_FAILURE;
            }
            lineData->data = numbers;
            lineData->count = numNumbers;

            lines = realloc(lines, (lineCount + 1) * sizeof(LineData*));
            if (!lines) {
                perror("Memory reallocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                free(numbers);
                return EXIT_FAILURE;
            }
            lines[lineCount++] = lineData;
        } else if (numNumbers == 1) {
            numbers[numNumbers++] = NAN;

            LineData* lineData = malloc(sizeof(LineData));
            if (!lineData) {
                perror("Memory allocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                free(numbers);
                return EXIT_FAILURE;
            }
            lineData->data = numbers;
            lineData->count = numNumbers;

            lines = realloc(lines, (lineCount + 1) * sizeof(LineData*));
            if (!lines) {
                perror("Memory reallocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                free(numbers);
                return EXIT_FAILURE;
            }
            lines[lineCount++] = lineData;
        } else {
            LineData* lineData = malloc(sizeof(LineData));
            if (!lineData) {
                perror("Memory allocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                return EXIT_FAILURE;
            }
            lineData->data = NULL;
            lineData->count = 1;

            lines = realloc(lines, (lineCount + 1) * sizeof(LineData*));
            if (!lines) {
                perror("Memory reallocation failed");
                fclose(inputFile);
                fclose(outputFile);
                for (size_t i = 0; i < lineCount; ++i) {
                    free(lines[i]->data);
                    free(lines[i]);
                }
                free(lines);
                return EXIT_FAILURE;
            }
            lines[lineCount++] = lineData;
        }

        if (ftell(inputFile) > MAX_FILE_SIZE) {
            fprintf(stderr, "Maximum file size exceeded\n");
            fclose(inputFile);
            fclose(outputFile);
            for (size_t i = 0; i < lineCount; ++i) {
                free(lines[i]->data);
                free(lines[i]);
            }
            free(lines);
            return EXIT_FAILURE;
        }
    }

    qsort(lines, lineCount, sizeof(LineData*), compareLines);

    for (size_t i = 0; i < lineCount; ++i) {
        if (!isnan(lines[i]->data[lines[i]->count - 1])) {
            fprintf(outputFile, "%.2f ", lines[i]->data[0]);
            for (size_t j = 1; j < lines[i]->count - 1; ++j) {
                fprintf(outputFile, "%.2f ", lines[i]->data[j]);
            }
            fprintf(outputFile, "%.2f\n", lines[i]->data[lines[i]->count - 1]);
        } else {
            fprintf(outputFile, "%.2f\n", lines[i]->data[0]);
        }

        free(lines[i]->data);
        free(lines[i]);
    }

    free(lines);

    fclose(inputFile);
    fclose(outputFile);

    return EXIT_SUCCESS;
}
