        info->bitsPerSample != 16) {
        TIFFClose(tif);
        free(info);
        return NULL;
    }

    info->extraSamples = TIFFGetFieldDefaulted(tif, TIFFTAG_EXTRASAMPLES, &info->sampleInformation);

    EVP_CIPHER_CTX* cipher = NULL;
    if (strcmp(option, "encrypt") == 0) {
        cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, key, iv);
    } else if (strcmp(option, "decrypt") == 0) {
        cipher = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, key, iv);
    }

    info->cipher = cipher;

    TIFFClose(tif);
    return info;
}
