void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

char* modify_filename_with_random_extension(const char* filename, int max_length, const char* file_type) {
    if (filename == NULL || file_type == NULL) {
        log_error("Invalid input parameters.");
        return NULL;
    }

    // Calculate the number of digits based on the length of the original filename
    int num_digits = strlen(filename);
    if (num_digits > 10) {
        num_digits = 10; // Limit the number of digits to avoid excessively long filenames
    }

    // Allocate memory for the new filename
    char* new_filename = malloc(max_length + 1);
    if (new_filename == NULL) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    // Construct the new filename using sprintf and strcat
    int result = snprintf(new_filename, max_length, "%s_%0*d.%s", 
                          filename, num_digits, rand() % 1000000000, file_type);
    if (result < 0 || result >= max_length) {
        log_error("Failed to construct new filename.");
        free(new_filename);
        return NULL;
    }

    // Ensure the new filename does not exceed the specified maximum length
    if (strlen(new_filename) > max_length - 1) {
        log_error("New filename exceeds the maximum length constraint.");
        free(new_filename);
        return NULL;
    }

    return new_filename;
}

// Example usage
int main() {
    const char* original_filename = "example.file.txt";
    int max_length = 50;
    const char* file_type = "backup";

    char* modified_filename = modify_filename_with_random_extension(original_filename, max_length, file_type);
    if (modified_filename != NULL) {
        printf("Modified filename: %s\n", modified_filename);
        free(modified_filename);
    }

    return 0;
}
