EVP_CIPHER_CTX* init_aes_256_cbc(const char* password, size_t password_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;
    }

    unsigned char iv[EVP_CIPHER_BLOCK_SIZE];
    if (!RAND_bytes(iv, sizeof(iv))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[32];
    size_t key_len = sizeof(key);
    if (PKCS5_PBKDF2_HMAC(password, password_len, iv, sizeof(iv), 10000, EVP_sha256(), &key_len, key) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        OPENSSL_cleanse(key, sizeof(key));
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx == NULL) {
        return;
    }
    EVP_CIPHER_CTX_free(ctx);
}
