#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_CONCURRENT_PROCESSES 5
#define MAX_COMMAND_DURATION 60

typedef struct {
    pid_t pid;
    time_t start_time;
    int status;
} ProcessInfo;

void log_process(ProcessInfo *process, int success) {
    char *action = (success ? "Completed successfully" : "Failed");
    printf("Process %d %s at %ld\n", process->pid, action, time(NULL));
}

int execute_command(char *command, ProcessInfo processes[], int *active_processes, int *next_slot) {
    if (*active_processes >= MAX_CONCURRENT_PROCESSES) {
        log_process(&processes[*next_slot], 0);
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        log_process(&processes[*next_slot], 0);
        return 1;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        _exit(127); // Command not found
    }

    processes[*next_slot].pid = pid;
    processes[*next_slot].start_time = time(NULL);
    processes[*next_slot].status = 0;
    (*active_processes)++;
    (*next_slot) = (*next_slot + 1) % MAX_CONCURRENT_PROCESSES;
    return 0;
}

int manage_commands(char *commands[], int command_count) {
    ProcessInfo processes[MAX_CONCURRENT_PROCESSES];
    int active_processes = 0;
    int next_slot = 0;

    for (int i = 0; i < command_count; i++) {
        while (active_processes >= MAX_CONCURRENT_PROCESSES) {
            pid_t pid = waitpid(-1, NULL, WNOHANG);
            if (pid != -1) {
                active_processes--;
            }
        }

        execute_command(commands[i], processes, &active_processes, &next_slot);

        time_t start_time = processes[next_slot].start_time;
        int status;
        while ((pid_t)-1 == waitpid(processes[next_slot].pid, &status, WNOHANG)) {
            if (time(NULL) - start_time > MAX_COMMAND_DURATION) {
                kill(processes[next_slot].pid, SIGKILL);
                processes[next_slot].status = 1;
                break;
            }
        }

        log_process(&processes[next_slot], status == 0);
    }

    for (int i = 0; i < active_processes; i++) {
        waitpid(-1, NULL, 0);
    }

    return 1;
}

int main() {
    char *commands[] = {"sleep 1", "sleep 2", "sleep 3", "sleep 4", "sleep 5"};
    int command_count = sizeof(commands) / sizeof(commands[0]);

    if (manage_commands(commands, command_count)) {
        printf("All operations were successful.\n");
        return 0;
    } else {
        printf("Some operations failed.\n");
        return 1;
    }
}
```

This code snippet defines a `ProcessInfo` structure to track each process's PID, start time, and status. The `execute_command` function forks a new process to run the given command and logs its start time. It also manages concurrent processes and ensures no more than a specified number of processes are active at any time. If the maximum duration is exceeded, it kills the process. The `manage_commands` function orchestrates the execution of multiple commands, ensuring efficient resource management and logging the start and completion times of each command. The `main` function demonstrates how to use these functions with an array of commands.']

