['```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class CommandExecutor {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory";
        String commandToExecute = "your_command_here";

        int maxRetries = 3;
        boolean retry = true;

        for (int attempt = 1; attempt <= maxRetries && retry; attempt++) {
            try {
                // Check and clean up directory
                cleanupDirectory(directoryPath);

                long startTime = System.currentTimeMillis();
                Process process = Runtime.getRuntime().exec(commandToExecute);
                int exitCode = waitForProcess(process, startTime);

                if (exitCode == 0) {
                    retry = false;
                } else {
                    throw new IOException("Command execution failed with exit code: " + exitCode);
                }
            } catch (IOException e) {
                // Check for temporary failure conditions
                if (isTemporaryFailure(e.getMessage())) {
                    System.out.println("Temporary failure encountered, retrying...");
                } else {
                    System.err.println("I/O error occurred during execution: " + e.getMessage());
                    break;
                }
            } finally {
                cleanupResources(process);
            }
        }

        if (!retry) {
            System.out.println("Command executed successfully.");
        }
    }

    private static void cleanupDirectory(String directoryPath) throws IOException {
        Path dir = Paths.get(directoryPath);
        try (Stream<Path> files = Files.list(dir)) {
            files.filter(Files::isRegularFile)
                 .sorted(Comparator.comparing(Path::toFile, Comparator.comparingLong(File::lastModified)))
                 .limit(1)
                 .forEach(file -> {
                     try {
                         Files.delete(file);
                         System.out.println("Deleted oldest file: " + file);
                     } catch (IOException e) {
                         System.err.println("Failed to delete file: " + file + ", error: " + e.getMessage());
                     }
                 });
        }
    }

    private static int waitForProcess(Process process, long startTime) throws IOException {
        InputStream stdout = process.getInputStream();
        InputStream stderr = process.getErrorStream();

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<?> outFuture = executor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stdout))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                // Handle error
            }
        });

        Future<?> errFuture = executor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stderr))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.err.println(line);
                }
            } catch (IOException e) {
                // Handle error
            }
        });

        int exitCode = -1;
        try {
            exitCode = process.waitFor();
            outFuture.get();
            errFuture.get();
        } catch (InterruptedException | ExecutionException e) {
            throw new IOException("Error waiting for process: " + e.getMessage());
        }

        System.out.println("Total execution time: " + (System.currentTimeMillis() - startTime) + " ms");
        return exitCode;
    }

    private static boolean isTemporaryFailure(String errorMessage) {
        // Implement logic to detect temporary failure conditions
        // Example: Check if the error message contains keywords indicating a transient issue
        return errorMessage != null && (errorMessage.contains("timeout") || errorMessage.contains("temporarily unavailable"));
    }

    private static void cleanupResources(Process process) {
        try {
            if (process != null) {
                process.getInputStream().close();
                process.getErrorStream().close();
                process.getOutputStream().close();
                process.destroy();
            }
        } catch (IOException e) {
            System.err.println("Error closing resources: " + e.getMessage());
        }
    }
}
