using System;
using System.Security.Cryptography;
using System.Text.Json;

public class CryptoModule
{
    public static string DecryptAndValidateOAuthToken(string base64EncodedMessage, string oauth2TokenJson, string encryptionMode = "ECB", byte[] key = null, byte[] iv = null)
    {
        var token = JsonSerializer.Deserialize<Dictionary<string, object>>(oauth2TokenJson);

        if (token == null || !token.ContainsKey("access_token") || !token.ContainsKey("expires_in") || !token.ContainsKey("token_type"))
        {
            return null;
        }

        if ((string)token["token_type"] != "Bearer" || !(int)token["expires_in"] > 0)
        {
            return null;
        }

        if (encryptionMode == "None")
        {
            return Convert.ToBase64String(Convert.FromBase64String(base64EncodedMessage));
        }

        using (var des = DES.Create())
        {
            switch (encryptionMode)
            {
                case "ECB":
                    des.Mode = CipherMode.ECB;
                    break;
                case "EDE":
                    // EDE is not supported by TripleDES, use CFB instead
                    encryptionMode = "CFB";
                    des.Mode = CipherMode.CFB;
                    break;
                case "EDE3":
                    des.Mode = CipherMode.ECB; // Fall back to ECB for TripleDES
                    break;
                case "CFB":
                    des.Mode = CipherMode.CFB;
                    break;
                default:
                    return null;
            }

            des.Key = key ?? GenerateKey();
            des.IV = iv ?? new byte[des.BlockSize / 8];

            using (var ms = new System.IO.MemoryStream())
            {
                using (var cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    var buffer = Convert.FromBase64String(base64EncodedMessage);
                    cs.Write(buffer, 0, buffer.Length);
                }
                return Encoding.UTF8.GetString(ms.ToArray());
            }
        }
    }

    private static byte[] GenerateKey()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var key = new byte[24]; // TripleDES key size
            rng.GetBytes(key);
            return key;
        }
    }
}
