using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashService : IHashService
{
    private readonly ILogger _logger;

    public HashService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> ComputeMD5Async(string input)
    {
        if (string.IsNullOrEmpty(input))
            return string.Empty;

        using (var md5 = MD5.Create())
        {
            var hashBytes = await Task.Run(() => md5.ComputeHash(Encoding.UTF8.GetBytes(input)));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    public async Task ProcessMultipleInputsAsync(IEnumerable<string> inputs)
    {
        var tasks = inputs.Select(ComputeMD5Async).ToList();
        await Task.WhenAll(tasks);

        foreach (var result in tasks)
        {
            _logger.LogHashComputation(result.Result);
        }
    }
}

public interface IHashService
{
    Task<string> ComputeMD5Async(string input);
    Task ProcessMultipleInputsAsync(IEnumerable<string> inputs);
}

public interface ILogger
{
    void LogHashComputation(string hash);
}

public class ConsoleLogger : ILogger
{
    public void LogHashComputation(string hash)
    {
        Console.WriteLine($"Computed hash: {hash}");
    }
}

// Unit tests
[TestFixture]
public class HashServiceTests
{
    [Test]
    public async Task ComputeMD5Async_EmptyString()
    {
        var service = new HashService(new ConsoleLogger());
        var result = await service.ComputeMD5Async(string.Empty);
        Assert.IsEmpty(result);
    }

    [Test]
    public async Task ComputeMD5Async_SingleCharacter()
    {
        var service = new HashService(new ConsoleLogger());
        var result = await service.ComputeMD5Async("a");
        Assert.IsNotEmpty(result);
    }

    [Test]
    public async Task ProcessMultipleInputsAsync_MultipleStrings()
    {
        var inputs = new List<string> { "apple", "banana", "cherry" };
        var logger = new Mock<ILogger>();
        var service = new HashService(logger.Object);

        await service.ProcessMultipleInputsAsync(inputs);

        logger.Verify(l => l.LogHashComputation(It.IsAny<string>()), Times.Exactly(3));
    }
}
