using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AESDecryptionHandler
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, bool removePadding = true)
    {
        if (key.Length != 32 || iv.Length != 16) // Check for valid key and IV sizes
        {
            throw new ArgumentException("Invalid key or IV size.");
        }

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.KeySize = 256;
            aesAlg.BlockSize = 128;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7; // PKCS7 padding is used by default in AES-CBC

            using (ICryptoTransform decryptor = aesAlg.CreateDecryptor(key, iv))
            {
                int chunkSize = 64 * 1024; // 64KB
                byte[] decryptedData = new byte[0];
                int offset = 0;

                while (offset < ciphertext.Length)
                {
                    int bytesToRead = Math.Min(chunkSize, ciphertext.Length - offset);
                    byte[] chunk = new byte[bytesToRead];
                    Array.Copy(ciphertext, offset, chunk, 0, bytesToRead);

                    using (MemoryStream msDecrypt = new MemoryStream(chunk))
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (MemoryStream temp = new MemoryStream())
                        {
                            csDecrypt.CopyTo(temp);
                            byte[] decryptedChunk = temp.ToArray();

                            if (removePadding)
                            {
                                decryptedChunk = RemovePadding(decryptedChunk);
                            }

                            decryptedData = CombineArrays(decryptedData, decryptedChunk);
                        }
                    }

                    offset += bytesToRead;
                }

                // Verify IV alignment
                if (!VerifyIVAlignment(ciphertext, iv))
                {
                    throw new InvalidOperationException("Decryption failed due to IV mismatch.");
                }

                return decryptedData;
            }
        }
    }

    private static byte[] RemovePadding(byte[] data)
    {
        int paddingLength = data[data.Length - 1];
        if (paddingLength > data.Length || paddingLength == 0)
        {
            throw new CryptographicException("Invalid padding.");
        }

        for (int i = data.Length - 2; i >= data.Length - paddingLength; i--)
        {
            if (data[i] != paddingLength)
            {
                throw new CryptographicException("Invalid padding.");
            }
        }

        byte[] result = new byte[data.Length - paddingLength];
        Array.Copy(data, 0, result, 0, result.Length);
        return result;
    }

    private static byte[] CombineArrays(byte[] array1, byte[] array2)
    {
        byte[] combined = new byte[array1.Length + array2.Length];
        Buffer.BlockCopy(array1, 0, combined, 0, array1.Length);
        Buffer.BlockCopy(array2, 0, combined, array1.Length, array2.Length);
        return combined;
    }

    private static bool VerifyIVAlignment(byte[] ciphertext, byte[] iv)
    {
        if (ciphertext.Length < iv.Length)
        {
            return false;
        }

        for (int i = 0; i < iv.Length; i++)
        {
            if (ciphertext[i] != iv[i])
            {
                return false;
            }
        }

        return true;
    }
}
```

This code snippet provides a function `Decrypt` that performs AES-CBC decryption with optional padding removal. It handles large inputs in chunks, verifies the IV alignment, and includes error handling for invalid padding or IV mismatches. The implementation efficiently manages memory by using streams and buffers.']

