            {
                object deserializedObject = binaryFormatter.Deserialize(gzipStream);
                if (deserializedObject is CustomDataStructure data)
                {
                    return data;
                }
                else
                {
                    throw new InvalidCastException("Deserialized object is not of type CustomDataStructure.");
                }
            }
            catch (SerializationException ex)
            {
                Console.WriteLine("Error during deserialization: " + ex.Message);
                throw;
            }
        }
    }
