['```java
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.security.KeySpec;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;

public class SerializationUtil {

    public static Object deserialize(byte[] encryptedData, String password) {
        try {
            Cipher cipher = initializeCipher(password);
            byte[] decryptedData = decrypt(cipher, encryptedData);
            return readObject(decryptedData);
        } catch (Exception e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private static Cipher initializeCipher(String password) throws Exception {
        SecretKeySpec keySpec = generateKey(password);
        IvParameterSpec ivSpec = generateIV();
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
        return cipher;
    }

    private static byte[] decrypt(Cipher cipher, byte[] encryptedData) throws Exception {
        return cipher.doFinal(encryptedData);
    }

    private static Object readObject(byte[] data) throws Exception {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);
        try {
            return ois.readObject();
        } finally {
            ois.close();
            bis.close();
        }
    }

    private static SecretKeySpec generateKey(String password) throws NoSuchAlgorithmException, Exception {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 10000, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, "AES");
    }

    private static IvParameterSpec generateIV() throws Exception {
        SecureRandom random = new SecureRandom();
        byte[] ivBytes = new byte[16];
        random.nextBytes(ivBytes);
        return new IvParameterSpec(ivBytes);
    }

    public static void cleanup(Cipher cipher) {
        if (cipher != null) {
            try {
                cipher.doFinal(new byte[cipher.getBlockSize()]);
            } catch (Exception e) {
                // Handle exception
            }
        }
    }
}
