const axios = require('axios');
const fs = require('fs');
const path = require('path');

// Mock function for file type validation
function validateFileType(filePath, allowedTypes) {
    const fileType = path.extname(filePath).toLowerCase();
    return allowedTypes.includes(fileType);
}

// Mock function for file size validation
function validateFileSize(filePath, maxSizeInBytes) {
    const fileSize = fs.statSync(filePath).size;
    return fileSize <= maxSizeInBytes;
}

// Mock function for uploading a single file using Axios
async function uploadFile(filePath, uploadUrl) {
    try {
        const startTime = Date.now();
        const formData = new FormData();
        formData.append('file', fs.createReadStream(filePath));

        const response = await axios.post(uploadUrl, formData, {
            headers: {
                ...formData.getHeaders(),
                'Content-Type': undefined
            }
        });

        const endTime = Date.now();
        const uploadDuration = (endTime - startTime) / 1000;
        return { url: response.data.url, size: fs.statSync(filePath).size, duration: uploadDuration };
    } catch (error) {
        throw new Error(`Upload failed: ${error.message}`);
    }
}

// Main function to handle file uploads
async function handleFileUploads(fileUrls, uploadUrl, allowedTypes, maxSizeInBytes) {
    if (!fileUrls || fileUrls.length === 0) {
        throw new Error('No files provided for upload.');
    }

    const results = [];
    for (const url of fileUrls) {
        try {
            const filePath = path.resolve(__dirname, 'downloads', path.basename(url));
            if (!fs.existsSync(filePath)) {
                throw new Error(`File not found: ${url}`);
            }

            if (!validateFileType(filePath, allowedTypes)) {
                throw new Error(`Invalid file type: ${path.extname(filePath).toLowerCase()}`);
            }

            if (!validateFileSize(filePath, maxSizeInBytes)) {
                throw new Error('File size exceeds limit.');
            }

            const result = await uploadFile(filePath, uploadUrl);
            results.push(result);
        } catch (error) {
            console.error(`Error processing file ${url}: ${error.message}`);
        }
    }

    return results;
}

// Example usage
(async () => {
    try {
        const filesToUpload = ['file1.jpg', 'file2.pdf'];
        const uploadUrl = 'https://example.com/upload';
        const allowedTypes = ['.jpg', '.png', '.pdf'];
        const maxSizeInBytes = 5 * 1024 * 1024; // 5MB

        const uploadResults = await handleFileUploads(filesToUpload, uploadUrl, allowedTypes, maxSizeInBytes);
        console.log('Upload Results:', uploadResults);
    } catch (error) {
        console.error('Failed to handle file uploads:', error.message);
    }
})();
```

