["```javascript
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const commandQueue = [];
let executing = false;

function executeCommand(command) {
  return new Promise((resolve, reject) => {
    const startTime = Date.now();
    const logFilePath = path.join(__dirname, 'command_log.txt');

    function logExecution() {
      const endTime = Date.now();
      const executionTime = endTime - startTime;
      fs.appendFile(logFilePath, `${command} executed in ${executionTime}ms at ${new Date().toISOString()}\n`, (err) => {
        if (err) {
          console.error('Failed to log command execution:', err);
        }
      });
    }

    exec(command, { maxBuffer: 1024 * 500 }, (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      resolve(stdout + stderr);
      logExecution();
    });
  });
}

async function handleCommandQueue() {
  while (commandQueue.length > 0 && executing === false) {
    executing = true;
    const { command, callback } = commandQueue.shift();

    try {
      const result = await executeCommand(command);
      callback(null, result);
    } catch (error) {
      callback(error);
    } finally {
      executing = false;
      setTimeout(handleCommandQueue, 100); // Cooldown period
    }
  }
}

function runShellCommand(command, callback) {
  commandQueue.push({ command, callback });
  handleCommandQueue();
}

module.exports = { runShellCommand };
```

This code snippet provides a JavaScript function `runShellCommand` that executes a shell command using a child process and outputs the result to the browser. It implements a thread-safe mechanism to handle up to 10 concurrent calls per second by managing a queue of commands and ensuring that only one command is being executed at a time. The function includes a cooldown period between executions using `setTimeout`. Execution results are logged to a file for future analysis, with graceful handling of temporary failures in logging. The code is structured to allow easy integration with a web application for real-time updates in the browser."]

