async function addRandomGraphElementsAndExecuteCommand(command) {
    const driver = neo4j.driver('bolt://localhost:7687', neo4j.auth.basic('user', 'password'));
    try {
        const session = driver.session();
        const vertexCount = Math.floor(Math.random() * 10) + 1;
        const edgeCount = Math.floor(Math.random() * 5) + 1;

        for (let i = 0; i < vertexCount; i++) {
            await session.run('CREATE (:Vertex {id: $id, property: $property})', { id: i, property: `RandomProp${i}` });
        }

        for (let i = 0; i < edgeCount; i++) {
            const fromId = Math.floor(Math.random() * vertexCount);
            const toId = Math.floor(Math.random() * vertexCount);
            await session.run('MATCH (a:Vertex {id: $fromId}), (b:Vertex {id: $toId}) CREATE (a)-[:EDGE]->(b)', { fromId, toId });
        }

        return new Promise((resolve, reject) => {
            exec(command, (error, stdout, stderr) => {
                if (error) {
                    reject(error);
                } else {
                    resolve(stdout);
                }
            });
        });

    } catch (error) {
        throw error;
    } finally {
        await session.close();
        driver.close();
    }
}

// Usage
