#[derive(Debug)]
enum TaskCommand {
    AddTask { id: u32, priority: u8, timeout: Duration },
    RemoveTask(u32),
    ExecuteTask(u32),
}

struct Scheduler {
    tasks: HashMap<u32, (u8, oneshot::Sender<()>)>,
    task_sender: mpsc::Sender<TaskCommand>,
}

impl Scheduler {
    async fn new() -> Result<Self, Box<dyn Error>> {
        let (task_sender, mut task_receiver) = mpsc::channel(100);
        tokio::spawn(async move {
            while let Some(command) = task_receiver.recv().await {
                match command {
                    TaskCommand::AddTask { id, priority, timeout } => {
                        // Add task to scheduler
                    }
                    TaskCommand::RemoveTask(id) => {
                        // Remove task from scheduler
                    }
                    TaskCommand::ExecuteTask(id) => {
                        // Execute task
                    }
                }
            }
        });

        Ok(Scheduler {
            tasks: HashMap::new(),
            task_sender,
        })
    }

    async fn add_task(&self, id: u32, priority: u8, timeout: Duration) -> Result<(), Box<dyn Error>> {
        let (task_tx, task_rx) = oneshot::channel();
        self.task_sender.send(TaskCommand::AddTask { id, priority, timeout }).await?;
        task_tx.send(()).map_err(|_| "Failed to send task execution confirmation".into())
    }

    async fn remove_task(&self, id: u32) -> Result<(), Box<dyn Error>> {
        self.task_sender.send(TaskCommand::RemoveTask(id)).await?;
        Ok(())
    }

    async fn execute_task(&self, id: u32) -> Result<(), Box<dyn Error>> {
        self.task_sender.send(TaskCommand::ExecuteTask(id)).await?;
        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let scheduler = Scheduler::new().await?;

    // Example usage
    scheduler.add_task(1, 5, Duration::from_secs(60)).await?;
    scheduler.execute_task(1).await?;
    scheduler.remove_task(1).await?;

    Ok(())
}
