use std::env;
use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;

fn create_directory_and_set_env(
    dir_name: &str,
    env_var_name: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let (tx, rx) = std::sync::mpsc::channel();
    let mut path = Path::new(dir_name);

    loop {
        if !path.exists() {
            fs::create_dir_all(path)?;
            tx.send(path.to_str().unwrap().to_string())?;
            break;
        } else {
            let unique_id = thread::spawn(|| {
                generate_unique_id()
            }).join().unwrap();
            path.set_file_name(format!("{}-{}", dir_name, unique_id));
        }
    }

    if env::var(env_var_name).is_err() {
        env::set_var(env_var_name, path);
    } else {
        let existing_path = env::var_os(env_var_name).unwrap();
        if existing_path != path.as_os_str() {
            let unique_id = thread::spawn(|| {
                generate_unique_id()
            }).join().unwrap();
            env::set_var(env_var_name, format!("{}-{}", env_var_name, unique_id));
            tx.send(path.to_str().unwrap().to_string())?;
        }
    }

    Ok(rx.recv()?)
}

fn cleanup_directory(dir_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    fs::remove_dir_all(Path::new(dir_path))?;
    env::remove_var(env_var_name);
    Ok(())
}

fn generate_unique_id() -> String {
    use rand::{thread_rng, Rng};
    let mut rng = thread_rng();
    format!("{}", rng.gen::<u32>())
}
```

