import json
import yaml
from concurrent.futures import Lock

class JSONHandler:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register_factory(cls, factory_id, factory_func):
        with cls._lock:
            if factory_id in cls._registry:
                raise ValueError(f"Factory ID {factory_id} already exists")
            cls._registry[factory_id] = factory_func

    @classmethod
    def get_factory(cls, factory_id):
        return cls._registry.get(factory_id)

    @staticmethod
    def load_config(config_path):
        with open(config_path, 'r') as file:
            config = yaml.safe_load(file)
            if 'factories' in config:
                for factory_id, factory_func_name in config['factories'].items():
                    # Assuming factory functions are defined elsewhere and imported here
                    factory_func = globals()[factory_func_name]
                    JSONHandler.register_factory(factory_id, factory_func)

    @classmethod
    def deserialize(cls, json_data):
        try:
            data = json.loads(json_data)
            factory_id = data.get('type')
            if not factory_id:
                raise ValueError("No factory ID specified in JSON")
            factory_func = cls.get_factory(factory_id)
            if not factory_func:
                raise ValueError(f"Factory function for {factory_id} not found")
            return factory_func(data)
        except json.JSONDecodeError as e:
            print(f"JSON decoding error: {e}")
            return None
        except KeyError as e:
            print(f"Key error in JSON data: {e}")
            return None

# Example usage:

def create_user_factory(json_data):
    class User:
        def __init__(self, name, age):
            self.name = name
            self.age = age

    if json_data['type'] == 'User':
        return User(**json_data)

JSONHandler.register_factory('User', create_user_factory)
JSONHandler.load_config('config.yaml')

user_json = '{"type": "User", "name": "John Doe", "age": 30}'
user = JSONHandler.deserialize(user_json)
print(user.name, user.age)  # Output: John Doe 30
