#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define KEY_LENGTH 32
#define IV_LENGTH 16
#define PBKDF2_ITERATIONS 10000

void generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, IV_LENGTH)) {
        fprintf(stderr, "Failed to generate IV\n");
        exit(EXIT_FAILURE);
    }
}

int derive_key(const unsigned char *password, int password_len,
               unsigned char *key) {
    int iterations = PBKDF2_ITERATIONS;
    while (iterations > 1) {
        clock_t start_time = clock();
        if (!PKCS5_PBKDF2_HMAC(password, password_len, NULL, 0,
                               key, KEY_LENGTH, SHA256_DIGEST_LENGTH, SHA256,
                               iterations)) {
            fprintf(stderr, "PBKDF2 failed\n");
            return -1;
        }
        clock_t end_time = clock();
        double duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
        if (duration > 1.0) {
            break;
        }
        iterations /= 2;
    }

    // Ensure we have exactly KEY_LENGTH bytes after PBKDF2 processing
    unsigned char temp_key[KEY_LENGTH];
    if (!PKCS5_PBKDF2_HMAC(password, password_len, NULL, 0,
                           temp_key, KEY_LENGTH, SHA256_DIGEST_LENGTH, SHA256,
                           iterations)) {
        fprintf(stderr, "PBKDF2 failed\n");
        return -1;
    }
    memcpy(key, temp_key, KEY_LENGTH);

    return 0;
}

EVP_CIPHER_CTX *init_cipher(const unsigned char *password, int password_len,
                             const unsigned char *salt, EVP_CIPHER *cipher_type,
                             int encrypt) {
    if (strlen((const char *)password) < 8) {
        fprintf(stderr, "Password is too short\n");
        return NULL;
    }

    unsigned char key[KEY_LENGTH];
    if (derive_key(password, password_len, key) != 0) {
        return NULL;
    }

    unsigned char iv[IV_LENGTH];
    generate_iv(iv);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv)) {
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!encrypt) {
        if (1 != EVP_DecryptInit_ex(ctx, cipher_type, NULL, key, iv)) {
            fprintf(stderr, "Cipher initialization for decryption failed\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    // Log the duration of key derivation and cipher setup processes
    clock_t end_time = clock();
    double duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("Key derivation and cipher setup took %.2f seconds\n", duration);

    return ctx;
}

void secure_cleanup(EVP_CIPHER_CTX *ctx, unsigned char *key, unsigned char *iv) {
    EVP_CIPHER_CTX_free(ctx);
    memset(key, 0, KEY_LENGTH);
    memset(iv, 0, IV_LENGTH);
}

int main() {
    const char *password = "my_secure_password";
    int password_len = strlen(password);
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Failed to generate salt\n");
        return EXIT_FAILURE;
    }

    EVP_CIPHER_CTX *ctx = init_cipher(password, password_len, salt,
                                       EVP_aes_256_cbc(), 1);
    if (!ctx) {
        return EXIT_FAILURE;
    }

    // Use the cipher context for encryption/decryption operations

    secure_cleanup(ctx, NULL, NULL);
    return EXIT_SUCCESS;
}
