using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Threading;

public enum LogLevel { DEBUG, INFO, WARNING, ERROR }

public class SecureRandomValueLogger
{
    private static readonly Dictionary<LogLevel, string> LogFiles = new Dictionary<LogLevel, string>
    {
        { LogLevel.DEBUG, "debug.log" },
        { LogLevel.INFO, "info.log" },
        { LogLevel.WARNING, "warning.log" },
        { LogLevel.ERROR, "error.log" }
    };

    private long seed;
    private Random random;

    public SecureRandomValueLogger(long seed)
    {
        this.seed = seed;
        this.random = new Random(seed);
    }

    public void Reset()
    {
        random = new Random(seed);
    }

    public int GetRandomInt(int min, bool inclusive = true)
    {
        int max = inclusive ? (min + 1) : min;
        return random.Next(min, max);
    }

    public double GetRandomFloat(double min, double max, bool inclusiveMin = false, bool inclusiveMax = false)
    {
        if (inclusiveMin && inclusiveMax)
            return min + (max - min) * random.NextDouble();
        else if (inclusiveMin && !inclusiveMax)
            return min + (max - min) * random.NextDouble() + 1e-10;
        else if (!inclusiveMin && inclusiveMax)
            return min + (max - min) * random.NextDouble() - 1e-10;
        else
            return min + (max - min) * random.NextDouble();
    }

    public void Log(string message, LogLevel level)
    {
        string logEntry = $"{DateTime.Now}: [{level}] {message}";
        File.AppendAllText(LogFiles[level], logEntry + Environment.NewLine);
    }

    public override string ToString()
    {
        return $"RandomValueLogger: Seed={seed}, LastInt={GetRandomInt(int.MinValue, int.MaxValue)}, LastFloat={GetRandomFloat(double.MinValue, double.MaxValue)}";
    }
}
