import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.UUID;

public class IdentifierGenerator {

    public static void processFile(String filePath) throws IOException, NoSuchAlgorithmException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String uniqueId = generateUniqueId(line);
                System.out.println("Original Line: " + line + ", Unique ID: " + uniqueId);
            }
        }
    }

    private static String generateUniqueId(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        UUID uuid = new UUID((long) (hashBytes[0] & 0xFF | (hashBytes[1] << 8)),
                              (long) (hashBytes[2] & 0xFF | (hashBytes[3] << 8)));
        return uuid.toString();
    }

    public static void main(String[] args) {
        try {
            processFile("large_text_file.txt");
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
