class PerformanceAnalyticsDB {
public:
    void logStrategySelection(Strategy strategy, std::chrono::system_clock::time_point timestamp) {
        // Simulate database logging
        std::cout << "Logging strategy: " << static_cast<int>(strategy) << ", Timestamp: " << timestamp.time_since_epoch().count() << std::endl;
    }
};

class OffensiveStrategySelector {
public:
    OffensiveStrategySelector(PerformanceAnalyticsDB& db)
        : db_(db), attackCooldown_(std::chrono::system_clock::now()) {}

    Strategy selectStrategy(double matchState, double playerPerformance) {
        auto now = std::chrono::system_clock::now();
        if (now - lastDecisionTime_ < std::chrono::milliseconds(10)) {
            return currentStrategy_;
        }

        if (now - attackCooldown_ > std::chrono::seconds(1 / 3.0)) {
            currentStrategy_ = selectNewStrategy(matchState, playerPerformance);
            db_.logStrategySelection(currentStrategy_, now);
            attackCooldown_ = now;
        } else {
            currentStrategy_ = currentStrategy_;
        }

        lastDecisionTime_ = now;
        return currentStrategy_;
    }

private:
    PerformanceAnalyticsDB& db_;
    std::atomic<Strategy> currentStrategy_{Strategy::STRATEGY_A};
    std::chrono::system_clock::time_point attackCooldown_;
    std::chrono::system_clock::time_point lastDecisionTime_;

    Strategy selectNewStrategy(double matchState, double playerPerformance) {
        // Implement strategy selection logic
        return static_cast<Strategy>(rand() % 3); // Example: Random strategy for demonstration
    }
};

int main() {
    PerformanceAnalyticsDB db;
    OffensiveStrategySelector selector(db);

    std::vector<std::thread> threads;
    for (int i = 0; i < 50; ++i) {
        threads.emplace_back([&selector]() {
            double matchState = rand() / static_cast<double>(RAND_MAX);
            double playerPerformance = rand() / static_cast<double>(RAND_MAX);
            selector.selectStrategy(matchState, playerPerformance);
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
