#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    AES_128,
    AES_192,
    AES_256
} EncryptionStrength;

typedef enum {
    ENCRYPT,
    DECRYPT
} OperationMode;

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

EVP_CIPHER_CTX* initializeCipher(const char *password, size_t password_len, EncryptionStrength strength, OperationMode mode) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL)
        handleErrors();

    unsigned char iv[16];
    if (!RAND_bytes(iv, sizeof(iv)))
        handleErrors();

    const EVP_CIPHER *cipher;
    switch (strength) {
        case AES_128: cipher = EVP_aes_128_cbc(); break;
        case AES_192: cipher = EVP_aes_192_cbc(); break;
        default:      cipher = EVP_aes_256_cbc(); break; // Fallback to 256 if strength is not supported
    }

    unsigned char key[32];
    int iterations = 10000;
    int ret = PKCS5_PBKDF2_HMAC(password, password_len, iv, sizeof(iv), iterations, EVP_sha256(), 32, key);
    if (ret != 1) {
        fprintf(stderr, "PBKDF2 derivation failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        handleErrors();
    }

    ret = EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, mode == ENCRYPT ? 1 : 0);
    if (ret != 1) {
        fprintf(stderr, "Cipher initialization failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        handleErrors();
    }

    memset(key, 0, sizeof(key));
    return ctx;
}

void cleanupCipher(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

// Example usage:
int main() {
    const char *password = "mySecurePassword";
    size_t password_len = strlen(password);

    EncryptionStrength strength = AES_256;
    OperationMode mode = ENCRYPT;

    EVP_CIPHER_CTX *ctx = initializeCipher(password, password_len, strength, mode);
    // Perform encryption/decryption operations with ctx
    cleanupCipher(ctx);

    return 0;
}
```

