typedef struct {
    time_t timestamp;
    char event_type[MAX_EVENT_TYPE_LENGTH];
    char identifier[128];
} TrafficEvent;

int initialize_traffic_events(int N, size_t M, int L, FILE* log_file) {
    TrafficEvent *events = (TrafficEvent *)malloc(N * sizeof(TrafficEvent));
    if (!events) {
        log_error_with_timestamp(log_file, "Memory allocation failed for traffic events");
        return -1;
    }

    int truncated_count = 0;
    size_t total_memory_usage = 0;

    for (int i = 0; i < N; ++i) {
        events[i].timestamp = time(NULL);
        snprintf(events[i].event_type, MAX_EVENT_TYPE_LENGTH, "Event%d", rand() % 10);

        // Simulate event identifier
        char identifier_template[] = "ID%d";
        snprintf(events[i].identifier, sizeof(events[i].identifier), identifier_template, i);

        size_t event_size = sizeof(TrafficEvent) + strlen(events[i].event_type);
        while (event_size > M - total_memory_usage && L > 0) {
            // Truncate the identifier
            events[i].identifier[L-1] = '\0';
            --L;
            ++truncated_count;
            event_size = sizeof(TrafficEvent) + strlen(events[i].event_type);
        }

        total_memory_usage += event_size;

        if (total_memory_usage > M) {
            log_warning_with_timestamp(log_file, "Memory limit exceeded. Some events were truncated.");
        }
    }

    // Log the count of truncated events
    log_info_with_timestamp(log_file, "Number of truncated events: %d", truncated_count);

    return 0;
}

void free_traffic_events(TrafficEvent *events) {
    free(events);
}
