// Define log levels
typedef enum {
    DEBUG,
    INFO,
    WARN,
    ERROR
} LogLevel;

// Define log message structure
typedef struct LogMessage {
    LogLevel level;
    char* message;
    struct LogMessage* next;
} LogMessage;

// Global variables
LogLevel current_threshold = INFO;
LogMessage* log_queue_head = NULL;
LogMessage* log_queue_tail = NULL;
int total_messages_sent = 0;
int errors_encountered = 0;

// Mutex for thread safety
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t log_cv = PTHREAD_COND_INITIALIZER;

// Function to log a message
void log_message(LogLevel level, const char* format, ...) {
    // Check if the message should be logged based on threshold
    if (level < current_threshold) return;

    va_list args;
    va_start(args, format);

    // Allocate memory for the log message
    size_t size = vsnprintf(NULL, 0, format, args) + 1;
    char* buffer = (char*)malloc(size);
    if (!buffer) {
        perror("Failed to allocate memory");
        return;
    }
    va_end(args);

    // Format the message into the allocated buffer
    va_start(args, format);
    vsnprintf(buffer, size, format, args);
    va_end(args);

    // Lock the log queue for thread safety
    pthread_mutex_lock(&log_mutex);

    // Add the new log message to the queue
    LogMessage* new_message = (LogMessage*)malloc(sizeof(LogMessage));
    new_message->level = level;
    new_message->message = buffer;
    new_message->next = NULL;

    if (!log_queue_head) {
        log_queue_head = new_message;
        log_queue_tail = new_message;
    } else {
        log_queue_tail->next = new_message;
        log_queue_tail = new_message;
    }

    // Signal any waiting threads
    pthread_cond_signal(&log_cv);

    // Unlock the log queue
    pthread_mutex_unlock(&log_mutex);
}

// Function to asynchronously process log messages
void* process_logs(void* arg) {
    while (1) {
        pthread_mutex_lock(&log_mutex);

        // Wait until there are messages in the queue or a shutdown signal is received
        while (!log_queue_head) {
            pthread_cond_wait(&log_cv, &log_mutex);
        }

        // Process each log message in the queue
        LogMessage* current = log_queue_head;
        while (current) {
            LogMessage* next = current->next;

            // Log the message to the distributed service or file
            if (/* distribute_log_message(current->level, current->message) */) {
                total_messages_sent++;
            } else {
                errors_encountered++;
                // Fallback to local logging
                write_to_local_file(current->message);
            }

            // Free the log message
            free(current->message);
            free(current);

            current = next;
        }
        log_queue_head = NULL;

        pthread_mutex_unlock(&log_mutex);
    }
    return NULL;
}

// Function to distribute a log message to the external service
