typedef struct {
    int width;
    int height;
    char color_space[50];
    float compression_ratio;
    bool has_metadata;
    long metadata_size;
    char metadata_type[50];
} ImageInfo;

ImageInfo* process_jpeg_image(const char* file_path, const char* option) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open JPEG image");
        return NULL;
    }

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    ImageInfo* info = (ImageInfo*)malloc(sizeof(ImageInfo));
    info->width = cinfo.output_width;
    info->height = cinfo.output_height;

    switch (cinfo.out_color_space) {
        case JCS_GRAYSCALE: strcpy(info->color_space, "Grayscale"); break;
        case JCS_RGB: strcpy(info->color_space, "RGB"); break;
        case JCS_YCbCr: strcpy(info->color_space, "YCbCr"); break;
        case JCS_CMYK: strcpy(info->color_space, "CMYK"); break;
        default: strcpy(info->color_space, "Unknown"); break;
    }

    info->compression_ratio = (float)cinfo.input_scan_lines / cinfo.output_height;

    jpeg_decompress_struct* cinfo_exiv2 = new jpeg_decompress_struct;
    struct jpeg_error_mgr jerr_exiv2;
    cinfo_exiv2->err = jpeg_std_error(&jerr_exiv2);
    jpeg_create_decompress(cinfo_exiv2);
    jpeg_stdio_src(cinfo_exiv2, file);
    jpeg_read_header(cinfo_exiv2, TRUE);

    exv::Image::AutoPtr image(exv::ImageFactory::open(file_path));
    if (image->good()) {
        info->has_metadata = true;
        info->metadata_size = image->getSize();
        char* metadata_type_str;
        image->getType(&metadata_type_str);
        strncpy(info->metadata_type, metadata_type_str, 49);
        free(metadata_type_str);
    } else {
        info->has_metadata = false;
        info->metadata_size = 0;
        strcpy(info->metadata_type, "None");
    }

    jpeg_destroy_decompress(cinfo_exiv2);

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(file);

    // Perform Exiv2 operation based on option
    // ...

    return info;
}
