import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;

public class SerializationUtils {

    public static Object deserialize(byte[] serializedData, String password) {
        try {
            // Encrypt the data
            byte[] encryptedData = encrypt(serializedData, password);

            // Deserialize the encrypted data
            ByteArrayInputStream bais = new ByteArrayInputStream(encryptedData);
            ObjectInputStream ois = new ObjectInputStream(bais);
            Object obj = ois.readObject();
            ois.close();
            return obj;
        } catch (Exception e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private static byte[] encrypt(byte[] data, String password) throws Exception {
        SecretKey secretKey = generateSecretKey(password);
        IvParameterSpec iv = generateIV();
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);
        return cipher.doFinal(data);
    }

    private static byte[] decrypt(byte[] data, String password) throws Exception {
        SecretKey secretKey = generateSecretKey(password);
        IvParameterSpec iv = generateIV();
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);
        return cipher.doFinal(data);
    }

    private static SecretKey generateSecretKey(String password) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 10000, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, "AES");
    }

    private static IvParameterSpec generateIV() throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(128);
        SecretKey secretKey = keyGen.generateKey();
        byte[] ivBytes = secretKey.getEncoded();
        return new IvParameterSpec(ivBytes);
    }

    public static void cleanup(Cipher cipher) {
        if (cipher != null) {
            try {
                cipher.doFinal(new byte[0]);
            } catch (Exception e) {
                // Ignore
            }
        }
    }
}
