typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;
typedef struct {
    FILE *file;
    LogLevel level;
} Logger;

Logger* create_logger(const char* filename, LogLevel level) {
    Logger* logger = (Logger*)malloc(sizeof(Logger));
    logger->file = fopen(filename, "a");
    logger->level = level;
    return logger;
}

void log_message(Logger* logger, LogLevel message_level, const char* message) {
    if (logger->file && message_level >= logger->level) {
        fprintf(logger->file, "%s: %s\n", message_level == DEBUG ? "DEBUG" : 
                message_level == INFO ? "INFO" : message_level == WARNING ? "WARNING" : "ERROR", message);
        fflush(logger->file);
    }
}

EVP_CIPHER_CTX* execute_crypto_operation(const char* input, const char* command_line_option) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message(NULL, ERROR, "Failed to create cipher context");
        return NULL;
    }

    int operation = 0; // Placeholder for the operation based on command_line_option
    if (strcmp(command_line_option, "encrypt") == 0) {
        operation = EVP_EncryptInit_ex;
    } else if (strcmp(command_line_option, "decrypt") == 0) {
        operation = EVP_DecryptInit_ex;
    } else {
        log_message(NULL, ERROR, "Invalid command-line option for cryptographic operation");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    if (!operation(ctx, cipher, 1, (unsigned char*)"0123456789abcdef", (unsigned char*)"0123456789abcdef")) {
        log_message(NULL, ERROR, "Failed to initialize cryptographic operation");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform the actual cryptographic operation
    int len;
    if (!operation(ctx, cipher, 0, (unsigned char*)input, &len)) {
        log_message(NULL, ERROR, "Failed to execute cryptographic operation");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);
    return ctx;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_string> <operation>\n", argv[0]);
        return 1;
    }

    Logger* debug_logger = create_logger("debug.log", DEBUG);
    Logger* info_logger = create_logger("info.log", INFO);

    log_message(debug_logger, DEBUG, "Starting cryptographic operation");
    EVP_CIPHER_CTX* ctx = execute_crypto_operation(argv[1], argv[2]);
    if (ctx) {
        log_message(info_logger, INFO, "Cryptographic operation successful");
        EVP_CIPHER_CTX_free(ctx);
    }

    fclose(debug_logger->file);
    fclose(info_logger->file);

    return 0;
}
