#include <openssl/ssl.h>
#include <openssl/err.h>
#include <string.h>
#include <stdio.h>

#define MAX_CIPHER_LIST_LENGTH 256

SSL_CTX* initialize_secure_session(const char* server_name, int port, const char** cipher_suites) {
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (ctx == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Set up supported cipher suites
    if (SSL_CTX_set_cipher_list(ctx, cipher_suites[0]) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    for (int i = 1; i < MAX_CIPHER_LIST_LENGTH && cipher_suites[i] != NULL; i++) {
        if (SSL_CTX_add_extra_chain_cert(ctx, X509_load_certificate_file(cipher_suites[i], NULL, SSL_FILETYPE_PEM)) <= 0) {
            ERR_print_errors_fp(stderr);
            SSL_CTX_free(ctx);
            return NULL;
        }
    }

    // Generate a fresh pre-master secret
    unsigned char pre_master_secret[32];
    if (RAND_bytes(pre_master_secret, sizeof(pre_master_secret)) != 1) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Derive session keys
    EVP_PKEY* pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_RSA, NULL, pre_master_secret, sizeof(pre_master_secret));
    if (pkey == NULL) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Configure the session
    SSL* ssl = SSL_new(ctx);
    if (ssl == NULL) {
        ERR_print_errors_fp(stderr);
        EVP_PKEY_free(pkey);
        SSL_CTX_free(ctx);
        return NULL;
    }

    if (SSL_set_fd(ssl, socket(server_name, port)) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        EVP_PKEY_free(pkey);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Perform the TLS handshake
    if (SSL_connect(ssl) != 1) {
        ERR_print_errors_fp(stderr);
        SSL_shutdown(ssl);
        SSL_free(ssl);
        EVP_PKEY_free(pkey);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Log the session details
    fprintf(stderr, "TLS handshake successful\n");

    return ctx;
}

void cleanup_session(SSL_CTX* ctx) {
    if (ctx != NULL) {
        SSL_CTX_free(ctx);
    }
}
