        driver = sql::mysql::get_mysql_driver_instance();
        // Start the async error reporting thread
        errorThread = std::thread(&DatabaseConnector::errorHandler, this);
    }

    ~DatabaseConnector() {
        stop = true;
        cv.notify_all();
        if (errorThread.joinable()) {
            errorThread.join();
        }
    }

    sql::ResultSet* executeQuery(const std::string& connectionString, const std::string& query) {
        std::unique_lock<std::mutex> lock(connectionMutex);
        try {
            auto connection = driver->connect(connectionString, "user", "password");
            auto statement = connection->createStatement();
            auto resultSet = statement->executeQuery(query);
            return resultSet;
        } catch (sql::SQLException& e) {
            DatabaseErrorHandler::log("Error executing query: " + e.what(), DatabaseErrorHandler::LogLevel::ERROR);
            // Log query parameters
            // Manage error files and archiving
            return nullptr;
        }
    }

private:
    void errorHandler() {
        while (!stop) {
            std::unique_lock<std::mutex> lock(errorMutex);
            cv.wait(lock, [this]{ return !errorQueue.empty() || stop; });
            if (stop && errorQueue.empty()) break;

            std::string error = errorQueue.front();
            errorQueue.pop();
            lock.unlock();

            AsyncErrorHandler errorHandler;
            errorHandler.asyncReport(error);
        }
    }

    std::mutex errorMutex;
};

int main() {
    DatabaseConnector dbConnector;
    sql::ResultSet* resultSet = dbConnector.executeQuery("tcp://127.0.0.1:3306", "SELECT * FROM table_name");
    if (resultSet != nullptr) {
        // Process result set
    }
    return 0;
}
