#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <openssl/sha.h>

#define MAX_IP_LEN 16
#define UUID_LEN 37

typedef unsigned char u_char;

u_char* dnsResolveWithHash(const char* hostname, char* uuid) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[MAX_IP_LEN];
    static u_char hash[SHA256_DIGEST_LENGTH];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // Perform SHA-256 hashing
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, uuid, strlen(uuid));
        SHA256_Update(&sha256, ipstr, strlen(ipstr));
        SHA256_Final(hash, &sha256);

        // Output the hash
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            printf("%02x", hash[i]);
        }
        printf("\n");

        freeaddrinfo(res);
        return hash;
    }

    fprintf(stderr, "Could not resolve hostname\n");
    return NULL;
}

int main() {
    char uuid[UUID_LEN] = "12345678-1234-5678-1234-567812345678"; // Example UUID
    dnsResolveWithHash("example.com", uuid);
    return 0;
}
