#include <time.h>
#include "external_logging_library.h"

#define MAX_SESSIONS 1000
#define MEMORY_LIMIT 512 * 1024 // 512 KB

typedef struct {
    char session_id[32];
    char hashed_credentials[64];
    time_t last_active;
} UserSession;

typedef struct {
    UserSession **sessions;
    int size;
    int count;
    size_t total_memory_usage;
} HashTable;

HashTable *initialize_hash_table(int N, size_t memory_limit) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) {
        log_error("Memory allocation failed for hash table");
        return NULL;
    }
    table->sessions = (UserSession **)calloc(N, sizeof(UserSession *));
    if (!table->sessions) {
        free(table);
        log_error("Memory allocation failed for sessions array");
        return NULL;
    }
    table->size = N;
    table->count = 0;
    table->total_memory_usage = 0;
    return table;
}

void add_session(HashTable *table, UserSession *session) {
    if (table->count >= table->size) {
        log_warning("Hash table is full. Unable to add more sessions.");
        return;
    }
    table->sessions[table->count] = session;
    table->total_memory_usage += sizeof(UserSession);
    table->count++;
}

void update_session_timestamp(HashTable *table, const char *session_id) {
    for (int i = 0; i < table->count; i++) {
        if (strcmp(table->sessions[i]->session_id, session_id) == 0) {
            table->sessions[i]->last_active = time(NULL);
            return;
        }
    }
    log_error("Session with ID %s not found", session_id);
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->count; i++) {
        free(table->sessions[i]);
    }
    free(table->sessions);
    free(table);
}

int main() {
    int N = 5;
    size_t M = MEMORY_LIMIT;
    HashTable *table = initialize_hash_table(N, M);
    if (!table) return -1;

    // Example usage
    for (int i = 0; i < N; i++) {
        UserSession *session = (UserSession *)malloc(sizeof(UserSession));
        snprintf(session->session_id, sizeof(session->session_id), "session_%d", i);
        // Hashing and storing credentials securely is omitted for brevity
        session->last_active = time(NULL);
        add_session(table, session);
    }

    update_session_timestamp(table, "session_2");

    free_hash_table(table);
    return 0;
}
