        table->session_count++;
        table->memory_usage += sizeof(UserSession);
    }
    return table;
}

void update_session(HashTable *table, int index) {
    pthread_mutex_lock(&table->lock);
    UserSession *session = table->sessions[index];
    time_t current_time = time(NULL);
    if (current_time - session->last_active > 60) { // Update every minute
        session->last_active = current_time;
        // Log update details
        FILE *log_file = fopen(LOG_FILE, "a");
        fprintf(log_file, "Session %s updated at %s\n", session->session_id, ctime(&current_time));
        fclose(log_file);
    }
    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->session_count; i++) {
        free(table->sessions[i]);
    }
    pthread_mutex_destroy(&table->lock);
    free(table);
}

