#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define UserSession structure
typedef struct {
    char sessionId[128];
    char *userCredentials;
    time_t lastActiveTimestamp;
    // Additional metadata fields
} UserSession;

// Define hash table structure
typedef struct {
    UserSession **buckets;
    int capacity;
    size_t memoryUsage;
    size_t memoryLimit;
    FILE *logFile;
    int optimizedSessions;
    pthread_mutex_t lock;
} HashTable;

// Function to initialize the hash table
HashTable* initHashTable(int initialCapacity, size_t memoryLimit, const char *logFilePath) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        // Handle memory allocation failure
        return NULL;
    }
    table->buckets = (UserSession**)calloc(initialCapacity, sizeof(UserSession*));
    if (!table->buckets) {
        // Handle memory allocation failure
        free(table);
        return NULL;
    }
    table->capacity = initialCapacity;
    table->memoryUsage = 0;
    table->memoryLimit = memoryLimit;
    table->logFile = fopen(logFilePath, "a");
    if (!table->logFile) {
        // Handle file opening failure
        free(table->buckets);
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    table->optimizedSessions = 0;

    return table;
}

// Function to hash a session ID
size_t hashFunction(const char *sessionId) {
    size_t hash = 5381;
    int c;
    while ((c = *sessionId++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

// Function to insert a session into the hash table
int insertSession(HashTable *table, const char *sessionId, const char *userCredentials, time_t timestamp) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(sessionId);
    UserSession *newSession = (UserSession*)malloc(sizeof(UserSession));
    if (!newSession) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&table->lock);
        return -1;
    }
    newSession->userCredentials = strdup(userCredentials); // Secure storage by hashing
    strcpy(newSession->sessionId, sessionId);
    newSession->lastActiveTimestamp = timestamp;

    if (newSession->userCredentials == NULL) {
        free(newSession);
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    table->buckets[index] = newSession;
    table->memoryUsage += sizeof(UserSession) + strlen(userCredentials);

    if (table->memoryUsage > table->memoryLimit) {
        // Handle memory limit exceeded
        free(newSession->userCredentials);
        free(newSession);
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    pthread_mutex_unlock(&table->lock);
    return 0;
}

// Function to update session last active timestamp
int updateSessionTimestamp(HashTable *table, const char *sessionId) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(sessionId);
    if (table->buckets[index]) {
        table->buckets[index]->lastActiveTimestamp = time(NULL);
    }
    pthread_mutex_unlock(&table->lock);
    return 0;
}

// Function to free the hash table
void freeHashTable(HashTable *table) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->capacity; ++i) {
        if (table->buckets[i]) {
            free(table->buckets[i]->userCredentials);
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    fclose(table->logFile);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

