#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct UserSession {
    int sessionId;
    char hashedCredentials[64];
    time_t lastActiveTimestamp;
    char ipAddress[15];
    char browserType[32];
    char deviceInfo[64];
} UserSession;

typedef struct HashTableEntry {
    UserSession session;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct HashTable {
    int size;
    HashTableEntry **buckets;
} HashTable;

HashTable* createHashTable(int size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        logError("Memory allocation failed for hash table");
        return NULL;
    }
    table->size = size;
    table->buckets = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    if (!table->buckets) {
        logError("Memory allocation failed for buckets");
        free(table);
        return NULL;
    }
    return table;
}

void destroyHashTable(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            free(temp);
            entry = temp->next;
        }
    }
    free(table->buckets);
    free(table);
}

int hashFunction(int sessionId, int size) {
    return sessionId % size;
}

void insertSession(HashTable *table, UserSession session) {
    int index = hashFunction(session.sessionId, table->size);
    HashTableEntry *entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!entry) {
        logError("Memory allocation failed for new entry");
        return;
    }
    entry->session = session;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
}

void updateSessionTimestamp(HashTable *table, int sessionId, time_t timestamp) {
    int index = hashFunction(sessionId, table->size);
    HashTableEntry *entry = table->buckets[index];
    while (entry) {
        if (entry->session.sessionId == sessionId) {
            entry->session.lastActiveTimestamp = timestamp;
            return;
        }
        entry = entry->next;
    }
}

