public class SecureRandomValueLogger
{
    private Dictionary<string, Random> _generators = new Dictionary<string, Random>();
    private Dictionary<LogLevel, List<string>> _logs = new Dictionary<LogLevel, List<string>>();
    private string _logDirectory;
    private int _maxMessageLength;

    public SecureRandomValueLogger(string seed)
    {
        InitializeGenerators(seed);
        InitializeLogs();
        SetLogDirectory("logs");
        SetMaxMessageLength(1024);
    }

    public void ResetGenerators()
    {
        foreach (var generator in _generators.Values)
        {
            generator = new Random();
        }
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        foreach (var generator in _generators)
        {
            sb.AppendLine($"Generator {generator.Key}: Range={generator.Value.Min}, Last Value={generator.Value.Last}");
        }
        return sb.ToString();
    }

    public double GenerateSecureRandomDouble(int min, int max, bool exclusiveMax)
    {
        Random generator = GetGenerator(min.ToString() + max.ToString());
        double range = exclusiveMax ? (max - min) : (double)(max - min + 1);
        return min + (generator.NextDouble() * range);
    }

    public int GenerateSecureRandomInt(int min, int max, bool exclusiveMax)
    {
        Random generator = GetGenerator(min.ToString() + max.ToString());
        int range = exclusiveMax ? (max - min) : (max - min + 1);
        return min + generator.Next(range);
    }

    private Random GetGenerator(string seed)
    {
        if (!_generators.ContainsKey(seed))
        {
            _generators[seed] = new Random(Convert.ToInt32(seed));
        }
        return _generators[seed];
    }

    public void Log(LogLevel level, string message)
    {
        if (message.Length > _maxMessageLength)
        {
            message = message.Substring(0, _maxMessageLength);
        }
        if (!_logs.ContainsKey(level))
