#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_EVENT_TYPES 5

typedef struct TrafficEvent {
    time_t timestamp;
    char eventType[MAX_EVENT_TYPES];
    int uniqueID;
    int referenceCount;
} TrafficEvent;

typedef struct MemoryPool {
    TrafficEvent *events;
    size_t poolSize;
    size_t usedEvents;
    pthread_mutex_t lock;
} MemoryPool;

TrafficEvent* createTrafficEvent(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->usedEvents == pool->poolSize) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    TrafficEvent *event = &pool->events[pool->usedEvents++];
    event->referenceCount = 1;
    pthread_mutex_unlock(&pool->lock);
    return event;
}

void serializeTrafficEventArray(TrafficEvent *array, size_t N, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(array, sizeof(TrafficEvent), N, file);
    fclose(file);
}

// Example usage
int main() {
    MemoryPool pool;
    pool.poolSize = 1000;
    pool.usedEvents = 0;
    pthread_mutex_init(&pool.lock, NULL);

    TrafficEvent *events = malloc(pool.poolSize * sizeof(TrafficEvent));
    if (events == NULL) {
        perror("Failed to allocate memory for events");
        return EXIT_FAILURE;
    }
    pool.events = events;

    srand(time(NULL));
    for (size_t i = 0; i < pool.poolSize; ++i) {
        TrafficEvent *event = createTrafficEvent(&pool);
        if (event == NULL) {
            // Handle event creation failure
            continue;
        }
        time(&event->timestamp);
        int eventTypeIndex = rand() % MAX_EVENT_TYPES;
        sprintf(event->eventType, "Type%d", eventTypeIndex + 1);
        event->uniqueID = i + 1;
    }

    serializeTrafficEventArray(events, pool.usedEvents, "traffic_events.bin");

    // Cleanup
    for (size_t i = 0; i < pool.usedEvents; ++i) {
        TrafficEvent *event = &events[i];
        if (--event->referenceCount == 0) {
            free(event);
        }
    }
    free(events);
    pthread_mutex_destroy(&pool.lock);

    return EXIT_SUCCESS;
}
