#include <stdlib.h>
#include <time.h>

typedef struct UserSession {
    int userID;
    time_t startTime;
    int duration;
    int refCount;
    struct UserSession* next;
} UserSession;

UserSession* allocateSession(int userID, time_t startTime, int duration) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (session == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    session->userID = userID;
    session->startTime = startTime;
    session->duration = duration;
    session->refCount = 1;
    session->next = NULL;
    return session;
}

void freeSession(UserSession* session) {
    if (session != NULL) {
        free(session);
    }
}

void populateLinkedList(int M, UserSession** head) {
    srand(time(NULL));
    for (int i = 0; i < M; i++) {
        time_t startTime = time(NULL);
        int duration = rand() % 3600 + 1; // Random duration between 1 and 3600 seconds
        UserSession* newSession = allocateSession(i, startTime, duration);
        if (newSession != NULL) {
            // Append to the linked list
            if (*head == NULL) {
                *head = newSession;
            } else {
                UserSession* current = *head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = newSession;
            }
        } else {
            // Handle memory allocation failure
        }
    }
}

// Function to serialize the linked list to a binary file
void serializeLinkedList(UserSession* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }
    UserSession* current = head;
    while (current != NULL) {
        fwrite(&current->userID, sizeof(int), 1, file);
        fwrite(&current->startTime, sizeof(time_t), 1, file);
        fwrite(&current->duration, sizeof(int), 1, file);
        current = current->next;
    }
    fclose(file);
}

// Function to deserialize the linked list from a binary file
UserSession* deserializeLinkedList(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }
    UserSession* head = NULL;
    while (!feof(file)) {
        UserSession* newSession = allocateSession(0, 0, 0); // Initialize with default values
        if (newSession != NULL) {
            fread(&newSession->userID, sizeof(int), 1, file);
            fread(&newSession->startTime, sizeof(time_t), 1, file);
            fread(&newSession->duration, sizeof(int), 1, file);
            newSession->refCount = 1;
            newSession->next = NULL;
            // Append to the linked list
            if (head == NULL) {
                head = newSession;
            } else {
                UserSession* current = head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = newSession;
            }
        } else {
            // Handle memory allocation failure
        }
    }
    fclose(file);
    return head;
}

// Function to free the entire linked list
void freeLinkedList(UserSession* head) {
    UserSession* current = head;
    while (current != NULL) {
        UserSession* next = current->next;
        free(current);
        current = next;
    }
}
