    for (int i = 0; i < N; i++) {
        array[i].sensorID = i + 1;
        array[i].timestamp = time(NULL);
        array[i].readingValue = minValue + rand() / (double)(RAND_MAX / (maxValue - minValue));
        array[i].metadata = strdup("Sensor Data");
        array[i].refCount = 1;
    }

    pthread_mutex_unlock(&lock);
    successfulAllocations++;

    return array;
}

void serializeSensorDataArray(SensorData* array, int N, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fprintf(file, "sensorID,timestamp,readingValue,metadata\n");
    for (int i = 0; i < N; i++) {
        fprintf(file, "%d,%ld,%f,%s\n", array[i].sensorID, array[i].timestamp, array[i].readingValue, array[i].metadata);
    }

    fclose(file);
}

void freeSensorData(SensorData* data) {
    if (--data->refCount == 0) {
        free(data->metadata);
        free(data);
    }
}
