    if (!input) {
        perror("Failed to open input file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    FILE *output = fopen(outputFile, "w");
    if (!output) {
        perror("Failed to open output file");
        fclose(input);
        return;
    }

    // Apply rules and process lines
    while (fgets(line, MAX_LINE_LENGTH, input) && maxLines > 0) {
        if (strlen(line) <= maxLength) {
            // Transform line according to rules
            // Example: Convert all lowercase to uppercase
            for (int i = 0; line[i]; i++) {
                line[i] = toupper(line[i]);
            }
            fprintf(output, "%s", line);
            maxLines--;
        }
    }

    fclose(input);
    fclose(output);

    // Read the last line and extract sequence number
    fseek(inputFile, -MAX_LINE_LENGTH, SEEK_END);
    if (fread(line, 1, MAX_LINE_LENGTH, inputFile) == MAX_LINE_LENGTH) {
        char *sequence = strchr(line, 'S');
        if (sequence) {
            sequence++; // Move past the 'S' character
            while (*sequence && !isdigit(*sequence)) {
                sequence++;
            }
            if (isdigit(*sequence)) {
                int seqNum = atoi(sequence);
                printf("Last sequence number: %d\n", seqNum);
            } else {
                fprintf(stderr, "Failed to extract sequence number from last line.\n");
            }
        } else {
            fprintf(stderr, "No sequence indicator found in last line.\n");
        }
