#include <stdio.h>
#include <stdlib.h>

#define MAX_CAPACITY 1000
#define MAX_INTERVALS 50

int* readIntegers(int *count) {
    int *array = (int *)malloc(MAX_CAPACITY * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    *count = 0;

    int num;
    while (*count < MAX_CAPACITY && scanf("%d", &num) == 1) {
        if (num < 0) continue;
        array[(*count)++] = num;
    }

    return array;
}

void findAndPrintLargest(int *array, int count) {
    if (count == 0) {
        printf("No integers found.\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void readIntervals(int maxIntervalSize, int maxValue) {
    int intervals[MAX_INTERVALS][MAX_CAPACITY];
    int intervalCount = 0;
    int totalNumbers = 0;

    while (intervalCount < MAX_INTERVALS && totalNumbers < MAX_CAPACITY) {
        int count;
        int *array = readIntegers(&count);
        if (count == 0) break; // No more numbers to read

        for (int i = 0; i < count && totalNumbers < MAX_CAPACITY; i++) {
            if (totalNumbers >= MAX_CAPACITY - intervalCount * maxIntervalSize) {
                fprintf(stderr, "Exceeded maximum capacity.\n");
                exit(1);
            }
            intervals[intervalCount][i] = array[i];
            totalNumbers++;
        }

        free(array);
        intervalCount++;
    }

    for (int i = 0; i < intervalCount; i++) {
        findAndPrintLargest(intervals[i], intervalCount * maxIntervalSize);
    }
}

int main() {
    int maxIntervalSize, maxValue;
    printf("Enter maximum interval size: ");
    scanf("%d", &maxIntervalSize);
    printf("Enter maximum value for integers: ");
    scanf("%d", &maxValue);

    readIntervals(maxIntervalSize, maxValue);

    return 0;
}
