// Import necessary libraries
const axios = require('axios');
const crypto = require('crypto');

// Define a cache object
let cache = {};
const CACHE_MAX_SIZE = 100;
const CACHE_EXPIRY_TIME = 24 * 60 * 60 * 1000; // 24 hours in milliseconds

// Function to fetch Pokemon type and name
async function getPokemonData(pokemonName) {
    try {
        const response = await axios.get(`https://pokeapi.co/api/v2/pokemon/${pokemonName}`);
        return { type: response.data.types[0].type.name, name: response.data.name };
    } catch (error) {
        console.error('Error fetching Pokemon data:', error);
        throw new Error('Failed to fetch Pokemon data');
    }
}

// Recursive function to traverse DOM tree and find elements matching a selector
function findElementsBySelector(element, selector, classOrIdTest) {
    let matches = [];
    if (classOrIdTest(element, selector)) {
        matches.push(element);
    }
    for (let child of element.children) {
        matches = matches.concat(findElementsBySelector(child, selector, classOrIdTest));
    }
    return matches;
}

// Function to generate a cache key based on Pokemon type and name
function generateCacheKey(type, name) {
    return crypto.createHash('sha256').update(`${type}-${name}`).digest('hex');
}

// Function to fetch Pokemon weaknesses with caching and fallback mechanisms
async function fetchPokemonWeaknesses(pokemonName) {
    const pokemonData = await getPokemonData(pokemonName);
    const { type, name } = pokemonData;
    const cacheKey = generateCacheKey(type, name);

    // Check if data is cached
    if (cache[cacheKey] && Date.now() - cache[cacheKey].timestamp < CACHE_EXPIRY_TIME) {
        return cache[cacheKey].data;
    }

    // Fetch data from external API or use fallback
    let weaknesses = null;
    try {
        const response = await axios.get(`https://exampleapi.com/pokemon/${type}/weaknesses`);
        weaknesses = response.data;
    } catch (error) {
        console.error('Error fetching Pokemon weaknesses:', error);
        // Fallback to local data if external API fails
        const fallbackData = require('./fallbackData.json');
        weaknesses = fallbackData[type] || 'Unknown';
    }

    // Store data in cache with timestamp
    cache[cacheKey] = { data: weaknesses, timestamp: Date.now() };

    // Ensure cache size does not exceed maximum
    if (Object.keys(cache).length > CACHE_MAX_SIZE) {
        const oldestKey = Object.keys(cache).reduce((a, b) => 
            cache[a].timestamp < cache[b].timestamp ? a : b
        );
        delete cache[oldestKey];
    }

    return weaknesses;
}

// Example usage
fetchPokemonWeaknesses('charmander')
    .then(console.log)
    .catch(console.error);
