    HASH_FUNCTION,
    BLOCK_CIPHER
} FunctionType;

CryptoFunction* load_crypto_functions(const char* config_file, int* count) {
    // Load YAML configuration file and parse it

    YAML::Node config = YAML::LoadFile(config_file);
    *count = 0;
    for (const auto& func : config["crypto_functions"]) {
        if (!func["enabled"].as<bool>()) continue;
        (*count)++;
    }

    CryptoFunction* functions = malloc((*count) * sizeof(CryptoFunction));
    if (!functions) return NULL;

    int index = 0;
    for (const auto& func : config["crypto_functions"]) {
        if (!func["enabled"].as<bool>()) continue;

        strncpy(functions[index].name, func["name"].as<std::string>().c_str(), sizeof(functions[index].name));
        functions[index].operation = dlsym(func["library"].as<std::string>().c_str(), func["function"].as<std::string>().c_str());
        if (!functions[index].operation) {
            perror("dlsym");
            free(functions);
            return NULL;
        }

        // Load parameters, version, etc.

        index++;
    }

    return functions;
}

int main() {
    int count = 0;
    CryptoFunction* functions = load_crypto_functions("config.yaml", &count);

    if (!functions) {
        fprintf(stderr, "Failed to load cryptographic functions\n");
        return EXIT_FAILURE;
    }

    // Use loaded cryptographic functions

    free(functions);
    return EXIT_SUCCESS;
}
