class SecureSequenceGenerator {
private:
    std::mutex mtx_;
    std::condition_variable cv_;
    std::vector<std::pair<int, std::chrono::system_clock::time_point>> cache_;
    int cacheSize_;
    std::chrono::seconds cacheExpiry_;

public:
    SecureSequenceGenerator(int size, std::chrono::seconds expiry)
        : cacheSize_(size), cacheExpiry_(expiry) {}

    void CacheSequence(int sequence) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto now = std::chrono::system_clock::now();
        if (cache_.size() >= static_cast<size_t>(cacheSize_)) {
            cache_.erase(cache_.begin());
        }
        cache_.push_back({sequence, now});
        cv_.notify_all();
    }

    int GenerateSecureSequence(bool async = false) {
        std::unique_lock<std::mutex> lock(mtx_);
        if (!async) {
            while (cache_.empty()) {
                cv_.wait(lock);
            }
            auto [sequence, timestamp] = cache_.front();
            if (std::chrono::system_clock::now() - timestamp < cacheExpiry_) {
                return sequence;
            } else {
                cache_.erase(cache_.begin());
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                return GenerateSecureSequence(false);
            }
        } else {
            // Simulate async operation
            std::thread([this]() {
                std::this_thread::sleep_for(std::chrono::milliseconds(500));
                CacheSequence(rand());
            }).detach();
            cv_.wait(lock, [this]() { return !cache_.empty(); });
            auto [sequence, timestamp] = cache_.front();
            if (std::chrono::system_clock::now() - timestamp < cacheExpiry_) {
                return sequence;
            } else {
                cache_.erase(cache_.begin());
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                return GenerateSecureSequence(false);
            }
        }
    }

    int RandomNumber(int min, int max) {
        static std::mt19937 rng(static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count()));
        std::uniform_int_distribution<> dist(min, max);
        return dist(rng);
    }

    double RandomDouble(double min, double max) {
        static std::mt19937 rng(static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count()));
        std::uniform_real_distribution<> dist(min, max);
        return dist(rng);
    }
};

void UploadFileWithSensorData(int N, const std::string& fileUrl) {
    SecureSequenceGenerator generator(10, std::chrono::seconds(60));
    for (int i = 0; i < N; ++i) {
        SensorData data;
        data.id = generator.RandomNumber(1, 100);
        data.timestamp = std::chrono::system_clock::now();
        data.readingValue = generator.RandomDouble(-10.0, 10.0);
        data.metadata = "Sensor " + std::to_string(data.id) + " at " + std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(data.timestamp.time_since_epoch()).count());
        // Process and log data
    }
    std::string uploadedUrl = FileUploader::UploadFile(fileUrl);
    std::cout << "File uploaded to: " << uploadedUrl << std::endl;
}
