typedef enum {
    EVENT_TYPE_1,
    EVENT_TYPE_2,
    EVENT_TYPE_3,
    EVENT_TYPE_4,
    EVENT_TYPE_5
} EventType;

typedef struct TrafficEvent {
    time_t timestamp;
    EventType eventType;
    int uniqueID;
} TrafficEvent;

TrafficEvent* initialize_traffic_events(int N, size_t maxFileSize) {
    TrafficEvent* events = (TrafficEvent*)malloc(N * sizeof(TrafficEvent));
    if (!events) {
        perror("Memory allocation failed for traffic events");
        return NULL;
    }

    srand(time(NULL));

    int eventTypes[MAX_EVENT_TYPES] = {EVENT_TYPE_1, EVENT_TYPE_2, EVENT_TYPE_3, EVENT_TYPE_4, EVENT_TYPE_5};

    for (int i = 0; i < N; ++i) {
        events[i].timestamp = time(NULL);
        events[i].eventType = eventTypes[rand() % MAX_EVENT_TYPES];
        events[i].uniqueID = rand();
    }

    return events;
}

void serialize_events(TrafficEvent* events, int N, FILE* file, size_t maxFileSize) {
    size_t totalSize = N * sizeof(TrafficEvent);
    if (totalSize > maxFileSize) {
        fprintf(stderr, "Serialized data exceeds maximum file size. Truncating data.\n");
        totalSize = maxFileSize;
    }

    if (fwrite(events, sizeof(TrafficEvent), N, file) != N) {
        perror("Failed to serialize traffic events");
    }
}

int deserialize_events(TrafficEvent* events, int N, FILE* file) {
    size_t bytesRead = fread(events, sizeof(TrafficEvent), N, file);
    if (bytesRead < N) {
        perror("Failed to deserialize traffic events");
        return -1;
    }

    // Check data integrity
    for (int i = 0; i < bytesRead; ++i) {
        if (events[i].timestamp == 0 || events[i].uniqueID == 0) {
            fprintf(stderr, "Data integrity check failed at index %d\n", i);
            return -1;
        }
    }

    return 0;
}
