#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int id;
    char data[256];
} Resource;

Resource *sharedResources = NULL;
int resourceCount = 0;
sem_t resourceSemaphore;
pthread_mutex_t resourceMutex;

void initResources() {
    sharedResources = (Resource *)malloc(100 * sizeof(Resource)); // Example size
    resourceCount = 0;
    sem_init(&resourceSemaphore, 0, 1);
    pthread_mutex_init(&resourceMutex, NULL);
}

void cleanupResources() {
    free(sharedResources);
    sem_destroy(&resourceSemaphore);
    pthread_mutex_destroy(&resourceMutex);
}

Resource* getResource(int id) {
    Resource *res = NULL;
    sem_wait(&resourceSemaphore);
    pthread_mutex_lock(&resourceMutex);
    for (int i = 0; i < resourceCount; i++) {
        if (sharedResources[i].id == id) {
            res = &sharedResources[i];
            break;
        }
    }
    pthread_mutex_unlock(&resourceMutex);
    sem_post(&resourceSemaphore);
    return res;
}

void putResource(int id, const char *requestBody) {
    sem_wait(&resourceSemaphore);
    pthread_mutex_lock(&resourceMutex);
    for (int i = 0; i < resourceCount; i++) {
        if (sharedResources[i].id == id) {
            snprintf(sharedResources[i].data, sizeof(sharedResources[i].data), "%s", requestBody);
            pthread_mutex_unlock(&resourceMutex);
            sem_post(&resourceSemaphore);
            return;
        }
    }
    if (resourceCount < 100) { // Example limit
        sharedResources[resourceCount].id = id;
        snprintf(sharedResources[resourceCount++].data, sizeof(sharedResources[resourceCount].data), "%s", requestBody);
        pthread_mutex_unlock(&resourceMutex);
        sem_post(&resourceSemaphore);
    } else {
        pthread_mutex_unlock(&resourceMutex);
        sem_post(&resourceSemaphore);
        fprintf(stderr, "Resource limit reached\n");
    }
}

void deleteResource(int id) {
    sem_wait(&resourceSemaphore);
    pthread_mutex_lock(&resourceMutex);
    for (int i = 0; i < resourceCount; i++) {
        if (sharedResources[i].id == id) {
            sharedResources[i] = sharedResources[resourceCount - 1];
            resourceCount--;
            break;
        }
    }
    pthread_mutex_unlock(&resourceMutex);
    sem_post(&resourceSemaphore);
}

void* threadHandler(void *arg) {
    int id = *(int *)arg;
    Resource *res = getResource(id);
    if (res != NULL) {
        printf("Accessing resource %d with data: %s\n", res->id, res->data);
    }
    free(arg);
    pthread_exit(NULL);
}
```

This code provides a basic framework for managing a shared resource in a multi-threaded environment using semaphores and mutexes. It includes initialization, cleanup, access, update (PUT), and deletion (DELETE) operations. The `threadHandler` function demonstrates how threads can safely access the resources without causing race conditions or memory leaks.']

