    SensorReading data;
    struct TreeNode *left, *right;
} TreeNode;

typedef struct Tree {
    TreeNode *root;
    size_t size;
    size_t maxMemoryUsage;
} Tree;

TreeNode* createNode(SensorReading data) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (node == NULL) {
        printf("Memory allocation failed for tree node.\n");
        exit(1);
    }
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

Tree* createTree(size_t maxMemoryUsage) {
    Tree* tree = (Tree*)malloc(sizeof(Tree));
    if (tree == NULL) {
        printf("Memory allocation failed for tree.\n");
        exit(1);
    }
    tree->root = NULL;
    tree->size = 0;
    tree->maxMemoryUsage = maxMemoryUsage;
    return tree;
}

void insertNode(TreeNode** node, SensorReading data) {
    if (*node == NULL) {
        *node = createNode(data);
        return;
    }

    if (data.timestamp < (*node)->data.timestamp) {
        insertNode(&((*node)->left), data);
    } else {
        insertNode(&((*node)->right), data);
    }
}

void initializeTree(Tree* tree, size_t N) {
    srand(time(0));
    for (size_t i = 0; i < N; ++i) {
        SensorReading reading;
        reading.sensorID = rand() % 10; // Assuming up to 10 sensors
