#include <iostream>
#include <forward_list>
#include <numeric>

void processForwardList(std::forward_list<int>& list, int incrementValue, int divisor, int threshold) {
    bool modified = false;
    for (auto& elem : list) {
        if (elem % divisor == 0) {
            elem += incrementValue;
            modified = true;
        }
    }

    if (!modified) {
        int sum = std::accumulate(list.begin(), list.end(), 0);
        sum *= incrementValue;
        list.push_back(sum);
    }
}
```

