                std::ifstream file(filePath);
                if (!file.is_open()) {
                    throw std::runtime_error("Failed to open configuration file: " + filePath);
                }
                nlohmann::json config = nlohmann::json::parse(file);
                for (auto& existing : configFiles) {
                    if (existing.contains(config.key())) {
                        throw std::runtime_error("Configuration conflict in file: " + filePath);
                    }
                }
                configFiles.insert(configFiles.begin() + priority, config);
            } catch (const nlohmann::json::parse_error& e) {
                std::cerr << "Invalid JSON syntax in file: " + filePath << std::endl;
            } catch (const std::exception& e) {
                std::cerr << e.what() << std::endl;
            }
        }

        void reloadConfigurations() {
            for (auto& configFile : configFiles) {
                // Dynamically update configuration based on network connectivity
                // Example: Update database connection string based on current network status
            }
        }

        nlohmann::json getConfig(const std::string& key) {
            for (const auto& configFile : configFiles) {
                if (configFile.contains(key)) {
                    return configFile[key];
                }
            }
            throw std::runtime_error("Configuration key not found: " + key);
        }

    private:
        ~ConfigurationManager() {}
    };

    ConfigurationManager* ConfigurationManager::instance = nullptr;
}

int main() {
    ConfigManager::ConfigurationManager& manager = ConfigManager::ConfigurationManager::getInstance();
    manager.loadConfigFile("config1.json", 0);
    manager.loadConfigFile("config2.json", 1);

    try {
        std::string dbConnectionString = manager.getConfig("database.connection_string");
        std::cout << "Database Connection String: " << dbConnectionString << std::endl;
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
```

