// Function to initialize the user database

void init_user_database(UserDatabase* db, size_t initial_size) {
    db->users = malloc(initial_size * sizeof(UserProfile));
    db->count = 0;
    pthread_mutex_init(&db->lock, NULL);
}

// Function to add a new user or update an existing one

int update_user_profile(UserDatabase* db, int id, const char* json_body) {
    pthread_mutex_lock(&db->lock);

    // Search for the user
    size_t i;
    for (i = 0; i < db->count; ++i) {
        if (db->users[i].id == id) {
            // Update the existing user
            // Parse JSON body and update user fields
            pthread_mutex_unlock(&db->lock);
            return 0; // Success
        }
    }

    // If not found, add a new user
    if (i < db->count + 1) {
        db->users[i].id = id;
        // Parse JSON body and set initial values for new user
        pthread_mutex_unlock(&db->lock);
        return 0; // Success
    }

    pthread_mutex_unlock(&db->lock);
    return -1; // Error: No space in database
}

// Function to soft-delete a user

int soft_delete_user(UserDatabase* db, int id) {
    pthread_mutex_lock(&db->lock);

    for (size_t i = 0; i < db->count; ++i) {
        if (db->users[i].id == id) {
            // Mark the user as inactive
            db->users[i].status = USER_INACTIVE;
            pthread_mutex_unlock(&db->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&db->lock);
    return -1; // Error: User not found
}

