int find_largest_integer(const int* arr, size_t count) {
    if (count == 0) {
        return -1; // Error: Empty array
    }

    int max = arr[0];
    for (size_t i = 1; i < count; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

