using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;

public class DepartmentParser
{
    public static List<Department> ParseXml(string xmlFilePath)
    {
        try
        {
            XDocument xmlDoc = XDocument.Load(xmlFilePath);
            var departments = new List<Department>();

            foreach (var departmentElement in xmlDoc.Descendants("department"))
            {
                string departmentName = departmentElement.Element("name")?.Value;
                int divisionId = ParseDivisionId(departmentElement);

                if (!departments.Any(d => d.DivisionId == divisionId) && !string.IsNullOrEmpty(departmentName))
                {
                    departments.Add(new Department { Name = departmentName, DivisionId = divisionId });
                }
            }

            return departments;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return new List<Department>();
        }
    }

    private static int ParseDivisionId(XElement departmentElement)
    {
        string divisionIdStr = departmentElement.Element("division")?.Attribute("id")?.Value;
        if (int.TryParse(divisionIdStr, out int divisionId))
        {
            return divisionId;
        }
        return -1; // Return a default value indicating an invalid ID
    }
}

public class Department
{
    public string Name { get; set; }
    public int DivisionId { get; set; }
}
