async function fetchExternalApi(data) {
    try {
        const response = await axios.get('https://api.example.com/external', { data });
        return response.data;
    } catch (error) {
        console.error('Error fetching external API:', error);
        throw error;
    }
}

async function summarizeReport(files, cacheKey, maxRetries = 3) {
    if (cache.has(cacheKey)) {
        return cache.get(cacheKey);
    }

    let summaryData = {};
    const promises = files.map(async (file) => {
        try {
            const content = await readFileAsync(file.path);
            const processedContent = await processFileContent(content);

            // Example: Fetch data from external API based on processed content
            const apiResponse = await fetchExternalApi(processedContent);
            summaryData[file.name] = { lines: processedContent, apiResponse };

        } catch (error) {
            if (maxRetries > 0) {
                return summarizeReport(files, cacheKey, maxRetries - 1);
            } else {
                throw error;
            }
        }
    });

    await Promise.all(promises);

    // Store in cache for future use
    cache.set(cacheKey, summaryData);

    return summaryData;
}

