["```javascript
const blueslip = require('blueslip');
const { Worker } = require('worker_threads');

function runTestsConcurrently(label, f, timeout) {
  const maxRetries = 3;
  const maxConcurrency = 100;

  let testCount = 0;
  let successfulTests = 0;
  let failedTests = 0;

  function runTest(testFunction, attempt = 1) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(f.toString(), { eval: true });

      worker.on('message', (result) => {
        if (result.success) {
          successfulTests++;
        } else {
          failedTests++;
          if (attempt < maxRetries) {
            setTimeout(() => runTest(testFunction, attempt + 1), 100);
          } else {
            reject(new Error(`Test ${label} failed after ${maxRetries} attempts`));
          }
        }
        worker.terminate();
      });

      worker.on('error', (err) => {
        failedTests++;
        if (attempt < maxRetries) {
          setTimeout(() => runTest(testFunction, attempt + 1), 100);
        } else {
          reject(err);
        }
      });
    });
  }

  async function executeTests() {
    const testPromises = [];

    for (let i = 0; i < maxConcurrency; i++) {
      testPromises.push(runTest(f));
    }

    try {
      await Promise.all(testPromises);
      console.log(`All ${testCount} tests completed. Successful: ${successfulTests}, Failed: ${failedTests}`);
    } catch (error) {
      console.error(`Error executing test:`, error);
    }
  }

  const start = performance.now();

  for (let i = 0; i < maxConcurrency; i++) {
    testCount++;
    runTest(f).then(() => {
      const end = performance.now();
      console.log(`Test ${label} executed in ${end - start}ms`);
    });
  }

  return executeTests();
}

// Example usage:
const myModule = require('./myModule');
runTestsConcurrently('My Module Tests', () => {
  // Test implementation
}, 5000);
