app.service('DialogFieldService', ['$http', '$timeout', '$log', function($http, $timeout, $log) {
    this.refreshDialogFields = function(resourceId, url, fieldNamesToRefresh, maxRetries) {
        var retryCount = 0;

        function refreshField(fieldName) {
            if (retryCount >= maxRetries) {
                $log.error('Max retries reached for field: ' + fieldName);
                return;
            }

            var message = { fieldName: fieldName, status: 'pending' };
            parent.postMessage(message, '*');

            function handleResponse(event) {
                if (event.origin !== url.origin) return; // Security check
                if (event.data.fieldName === fieldName && event.data.status === 'success') {
                    updateDialogField(fieldName, event.data.value);
                } else {
                    retryCount++;
                    refreshField(fieldName);
                }
            }

            window.addEventListener('message', handleResponse);

            $timeout(function() {
                window.removeEventListener('message', handleResponse);
                $log.error('No response from parent for field: ' + fieldName);
                retryCount++;
                refreshField(fieldName);
            }, 5000); // Timeout after 5 seconds

            $http.get(url + '/api/refresh?resourceId=' + resourceId + '&fieldName=' + fieldName)
                .then(function(response) {
                    window.removeEventListener('message', handleResponse);
                    event = { data: { fieldName: fieldName, status: 'success', value: response.data } };
                    handleResponse(event);
                })
                .catch(function(error) {
                    $log.error('Failed to refresh field: ' + fieldName, error);
                    retryCount++;
                    refreshField(fieldName);
                });
        }

        angular.forEach(this.dialogFields, function(field) {
            if (fieldNamesToRefresh.indexOf(field.name) !== -1) {
                refreshField(field.name);
            }
        });
    };

    this.updateDialogField = function(fieldName, value) {
        // Code to update the dialog field with the provided value
        console.log('Updating field: ' + fieldName + ' with value: ', value);
    };
}]);
