// Import necessary libraries and modules
const NoSQLClient = require('nosql-client');
const LRU = require('lru-cache');

// Initialize NoSQL client and caching mechanism
const db = new NoSQLClient('your_nosql_database_url');
const cache = new LRU({ max: 1000, ttl: 60 * 60 * 1000 });

// Function to fetch user profiles based on dynamic criteria
async function fetchUserProfiles(criteria) {
    const cacheKey = JSON.stringify(criteria);

    // Check if data is available in cache
    if (cache.has(cacheKey)) {
        return cache.get(cacheKey);
    }

    // Prepare query for the NoSQL database
    let query = { ...criteria };
    if (criteria.name && criteria.name.startsWith('*')) {
        query.name = new RegExp(criteria.name.slice(1));
    }
    if (criteria.email && criteria.email.startsWith('*')) {
        query.email = new RegExp(criteria.email.slice(1));
    }

    // Batch requests and optimize data retrieval
    const batchSize = 100;
    let results = [];
    let offset = 0;

    while (true) {
        const batch = await db.find(query, { limit: batchSize, skip: offset });
        if (!batch.length) break;
        results.push(...batch);
        offset += batchSize;
    }

    // Store results in cache
    cache.set(cacheKey, results);

    return results;
}

// Function to invalidate cache entries when profile data changes
function invalidateProfileCache(profileId) {
    const keysToRemove = [];
    for (const key in cache.cache) {
        if (key.includes(profileId)) {
            keysToRemove.push(key);
        }
    }
    keysToRemove.forEach(key => cache.del(key));
}

// Example usage:
(async () => {
    const profiles = await fetchUserProfiles({ name: 'John*', email: '*@example.com' });
    console.log(profiles);

    // Simulate a profile update
    invalidateProfileCache('user123');
})();
```

