public class NetworkRequestProcessor {

    private final ConcurrentHashMap<String, ResourceNode> intervalTree = new ConcurrentHashMap<>();
    private long lastLogTime = 0;
    private double totalMemoryUsage = 0;
    private int maxCpuLoad = 0;

    public int processRequests(List<NetworkRequest> requests) {
        long startTime = System.currentTimeMillis();

        // Process each request
        for (NetworkRequest request : requests) {
            ResourceNode node = intervalTree.get(request.getResourceId());
            if (node == null) {
                node = new ResourceNode(request.getResourceId());
                intervalTree.putIfAbsent(request.getResourceId(), node);
            }
            node.insertInterval(request.getTimestampRange());
        }

        // Calculate and log metrics
        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;
        double memoryUsage = Runtime.getRuntime().totalMemory() / 1024.0 / 1024.0; // in MB
        int cpuLoad = getCpuLoad(); // Implement this method to get CPU load

        totalMemoryUsage += memoryUsage;
        if (cpuLoad > maxCpuLoad) {
            maxCpuLoad = cpuLoad;
        }

        if (endTime - lastLogTime >= 60000) { // Log every minute
            System.out.println("Processing Time: " + processingTime + "ms");
            System.out.println("Total Memory Usage: " + totalMemoryUsage + "MB");
            System.out.println("Max CPU Load: " + maxCpuLoad);
            lastLogTime = endTime;
        }

        return intervalTree.size();
    }

