import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DataTransferService {
    private static final Logger logger = LoggerFactory.getLogger(DataTransferService.class);
    private ExecutorService executorService;

    public DataTransferService(int threadPoolSize) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void transferData(DataStream inputStream, DataStream outputStream) {
        CompletableFuture.runAsync(() -> {
            try {
                while (inputStream.hasNext()) {
                    DataRecord record = inputStream.next();
                    outputStream.write(record);
                }
            } catch (Exception e) {
                logger.error("Error during data transfer", e);
            } finally {
                closeStreams(inputStream, outputStream);
            }
        }, executorService);
    }

    private void closeStreams(DataStream inputStream, DataStream outputStream) {
        try {
            inputStream.close();
            outputStream.close();
        } catch (IOException e) {
            logger.warn("Error closing streams", e);
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    interface DataStream {
        boolean hasNext();
        DataRecord next() throws IOException;
        void write(DataRecord record) throws IOException;
        void close() throws IOException;
    }

    static class DataRecord {
        // Define the structure of a data record
    }

    public static void main(String[] args) {
        DataTransferService service = new DataTransferService(10);
        try {
            DataStream inputStream = new ExternalSystemA().createDataStream();
            DataStream outputStream = new ExternalSystemB().createDataStream();
            service.transferData(inputStream, outputStream);
        } catch (IOException e) {
            logger.error("Failed to initialize data streams", e);
        }
        service.shutdown();
    }

    static class ExternalSystemA {
        public DataStream createDataStream() throws IOException {
            // Implementation to create a data stream from System A
            return new DataStream() {
                @Override
                public boolean hasNext() {
                    // Check if there are more records to read
                    return false;
                }

                @Override
                public DataRecord next() throws IOException {
                    // Read the next record from System A
                    return null;
                }

                @Override
                public void write(DataRecord record) throws IOException {
                    throw new UnsupportedOperationException("Cannot write to external system A");
                }

                @Override
                public void close() throws IOException {
                    // Close the data stream from System A
                }
            };
        }
    }

    static class ExternalSystemB {
        public DataStream createDataStream() throws IOException {
            // Implementation to create a data stream for System B
            return new DataStream() {
                @Override
                public boolean hasNext() {
                    // Check if there are more records to read
                    return false;
