['```go
package main

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"net/http"
	"time"

	"github.com/gorilla/securecookie"
)

type SessionManager struct {
	cookieName     string
	secretKey      []byte
	sessionStore   SessionStore
	timeout        time.Duration
	defaultTimeout time.Duration
	idpClient      IDPClient
}

func NewSessionManager(cookieName, secretKey string, store SessionStore, idp IDPClient) *SessionManager {
	return &SessionManager{
		cookieName:     cookieName,
		secretKey:      []byte(secretKey),
		sessionStore:   store,
		timeout:        30 * time.Minute,
		defaultTimeout: 24 * time.Hour,
		idpClient:      idp,
	}
}

func (sm *SessionManager) StartSession(w http.ResponseWriter, r *http.Request, userID string) error {
	token := generateToken()
	expiresAt := time.Now().Add(sm.timeout)
	session := &Session{UserID: userID, Token: token, ExpiresAt: expiresAt}
	err := sm.sessionStore.Set(session.Token, session)
	if err != nil {
		return err
	}

	http.SetCookie(w, &http.Cookie{
		Name:     sm.cookieName,
		Value:    securecookie.MarshalMapToBase64(map[string]interface{}{"token": token}),
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		Expires:  expiresAt.Time,
	})

	return nil
}

func (sm *SessionManager) ValidateSession(w http.ResponseWriter, r *http.Request) (*Session, error) {
	cookie, err := r.Cookie(sm.cookieName)
	if err != nil {
		return nil, fmt.Errorf("session cookie not found")
	}

	var sessionData map[string]interface{}
	err = securecookie.UnmarshalMapFromBase64(cookie.Value, &sessionData)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal session data")
	}

	token := sessionData["token"].(string)
	session, err := sm.sessionStore.Get(token)
	if err != nil {
		return nil, fmt.Errorf("session not found or invalid: %w", err)
	}

	if time.Now().After(session.ExpiresAt) {
		err = sm.sessionStore.Delete(token)
		if err != nil {
			return nil, fmt.Errorf("failed to delete expired session: %w", err)
		}
		http.SetCookie(w, &http.Cookie{
			Name:     sm.cookieName,
			Value:    "",
			Path:     "/",
			HttpOnly: true,
			Secure:   true,
			Expires:  time.Now().AddDate(0, 0, -1),
		})
		return nil, fmt.Errorf("session expired")
	}

	return session, nil
}

func (sm *SessionManager) ExtendSession(w http.ResponseWriter, r *http.Request) error {
	session, err := sm.ValidateSession(w, r)
	if err != nil {
		return err
	}

	expiresAt := time.Now().Add(sm.timeout)
	err = sm.sessionStore.Set(session.Token, &Session{UserID: session.UserID, Token: session.Token, ExpiresAt: expiresAt})
	if err != nil {
		return err
	}

	http.SetCookie(w, &http.Cookie{
		Name:     sm.cookieName,
		Value:    securecookie.MarshalMapToBase64(map[string]interface{}{"token": session.Token}),
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		Expires:  expiresAt.Time,
	})

	return nil
}

func (sm *SessionManager) Logout(w http.ResponseWriter, r *http.Request) error {
	session, err := sm.ValidateSession(w, r)
	if err != nil {
		return err
	}

	err = sm.sessionStore.Delete(session.Token)
	if err != nil {
		return err
	}

	http.SetCookie(w, &http.Cookie{
		Name:     sm.cookieName,
		Value:    "",
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		Expires:  time.Now().AddDate(0, 0, -1),
	})

	return nil
}

func generateToken() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return base64.StdEncoding.EncodeToString(b)
}
