import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private static final int MAX_CONCURRENT_REQUESTS = 100;
    private static final long BACKOFF_INITIAL_DELAY = 1000; // milliseconds
    private static final long BACKOFF_MULTIPLIER = 2;
    private static final long MAX_BACKOFF_DELAY = 60000; // milliseconds

    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);

    public void startService() {
        CompletableFuture.runAsync(() -> performServiceOperation(), executor)
            .exceptionally(ex -> handleException(ex), executor);
    }

    public void stopService() {
        CompletableFuture.runAsync(this::sendMessageToMessagingSystem, executor)
            .exceptionally(ex -> handleException(ex), executor);
    }

    private void performServiceOperation() {
        try {
            // Simulate service operation
            Thread.sleep((long) (Math.random() * 5000)); // Random delay between 0 and 5 seconds

            if (!scheduler.isShutdown()) {
                scheduler.schedule(this::stopService, (long) (Math.random() * 5000), TimeUnit.MILLISECONDS);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            handleException(e);
        }
    }

    private void sendMessageToMessagingSystem() {
        try {
            // Simulate sending message to messaging system
            System.out.println("Message sent to messaging system");

            if (!scheduler.isShutdown()) {
                scheduler.schedule(this::startService, (long) (Math.random() * 5000), TimeUnit.MILLISECONDS);
            }
        } catch (Exception e) {
            handleException(e);
        }
    }

    private <T> T handleException(Exception ex) {
        // Log exception details
        System.err.println("An error occurred: " + ex.getMessage());
        return null;
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.startService();
    }
}
