import java.util.concurrent.CompletableFuture;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;

public class PaymentService {

    private Map<String, PaymentGateway> gateways = new HashMap<>();
    private int maxRetries = 3;
    private static final String[] LOG_LEVELS = {"DEBUG", "INFO", "WARNING", "ERROR"};

    public PaymentService() {
        // Initialize payment gateways
        gateways.put("PayPal", new PayPalGateway());
        gateways.put("Stripe", new StripeGateway());
    }

    public boolean processTransactionSync(String gatewayName, Transaction transaction) {
        int retries = 0;
        while (retries <= maxRetries) {
            try {
                PaymentGateway gateway = getGateway(gatewayName);
                if (gateway.process(transaction)) {
                    log(LOG_LEVELS[1], "Transaction successful: " + transaction.getId());
                    return true;
                } else {
                    log(LOG_LEVELS[2], "Failed to process transaction, retrying...");
                }
            } catch (Exception e) {
                log(LOG_LEVELS[3], "Error processing transaction: " + e.getMessage());
                if (retries == maxRetries) {
                    throw new RuntimeException("Max retries exceeded", e);
                }
            }
            retries++;
        }
        return false;
    }

    public CompletableFuture<Boolean> processTransactionAsync(String gatewayName, Transaction transaction) {
        return CompletableFuture.supplyAsync(() -> processTransactionSync(gatewayName, transaction));
    }

    public void switchGateway(String oldGatewayName, String newGatewayName) {
        if (gateways.containsKey(oldGatewayName)) {
            gateways.remove(oldGatewayName);
        }
        PaymentGateway newGateway = getGateway(newGatewayName);
        if (newGateway != null) {
            gateways.put(newGatewayName, newGateway);
        } else {
            log(LOG_LEVELS[3], "Invalid gateway: " + newGatewayName);
        }
    }

    private PaymentGateway getGateway(String name) {
        return gateways.getOrDefault(name, null);
    }

    private void log(String level, String message) {
        System.out.println(level + ": " + message);
    }

    // Assume Transaction and PaymentGateway classes are defined elsewhere
}

abstract class PaymentGateway {
    public abstract boolean process(Transaction transaction);
}

class PayPalGateway extends PaymentGateway {
    @Override
    public boolean process(Transaction transaction) {
        Random rand = new Random();
        return rand.nextBoolean(); // Simulate success/failure
    }
}

class StripeGateway extends PaymentGateway {
    @Override
    public boolean process(Transaction transaction) {
        Random rand = new Random();
        return rand.nextBoolean(); // Simulate success/failure
    }
}

class Transaction {
    private String id;

    public Transaction(String id) {
        this.id = id;
    }

    public String getId() {
        return id;
    }
}
