        $this->authService = $authService;
    }

    /**
     * Update user's password with validation.
     *
     * @param int $userId
     * @param string $currentPassword
     * @param string $newPassword
     * @return bool
     */
    public function updateUserPasswordWithValidation($userId, $currentPassword, $newPassword) {
        // Validate the current password with an external authentication service.
        if (!$this->authService->validatePassword($userId, $currentPassword)) {
            return false;
        }

        // Retry logic for database operations.
        $maxRetries = 3;
        for ($i = 0; $i < $maxRetries; $i++) {
            try {
                // Update the user's password in the database.
                $sql = "UPDATE users SET password = :newPassword WHERE id = :userId";
                $stmt = $this->db->prepare($sql);
                $stmt->bindParam(':newPassword', $newPassword, PDO::PARAM_STR);
                $stmt->bindParam(':userId', $userId, PDO::PARAM_INT);

                return $stmt->execute();
            } catch (PDOException $e) {
                // Handle transient failures and connection timeouts.
                if ($i === $maxRetries - 1 || strpos($e->getMessage(), 'SQLSTATE[HY000]: General error') !== false) {
                    throw $e;
                }
                sleep(1); // Wait before retrying.
            }
        }

        return false;
    }
}
