import os
import struct

def process_log_directory(directory):
    events = []
    for filename in sorted(os.listdir(directory), reverse=True):
        if filename.endswith('.log'):
            try:
                with open(os.path.join(directory, filename), 'r') as file:
                    lines = file.readlines()
                    for line in lines:
                        event = parse_event(line)
                        if event and event['tag'] == 'critical':
                            events.append(event)
            except IOError as e:
                print(f"Error reading {filename}: {e}")

    events.sort(key=lambda x: x['timestamp'], reverse=True)
    return events

def parse_event(line):
    try:
        # Assuming a simple format where the first 10 characters are the timestamp
        timestamp = line[:10]
        header, data = line[10:].split(' ', 1)
        sequence_number = int(header.split(':')[1].strip())
        tag = header.split(': ')[1].strip()
        return {'timestamp': timestamp, 'sequence_number': sequence_number, 'tag': tag, 'data': data.strip()}
    except Exception as e:
        print(f"Error parsing event: {e}")
        return None
