#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int id;
    double amount;
    char tags[10];
} Transaction;

typedef struct {
    Transaction *transactions;
    int size;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TransactionQueue;

double calculate_weighted_sum(const Transaction *transaction);
int is_within_cutoff(time_t timestamp, time_t cutoff_time);

TransactionQueue transaction_queue;
time_t current_window_start;
int processed_transactions = 0;
double total_amount = 0.0;
double max_weighted_sum = 0.0;
int max_id = -1;

void init_transaction_queue() {
    pthread_mutex_init(&transaction_queue.lock, NULL);
    pthread_cond_init(&transaction_queue.cond, NULL);
    transaction_queue.transactions = NULL;
    transaction_queue.size = 0;
    transaction_queue.capacity = 0;
}

void enqueue_transaction(const Transaction *transaction) {
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.size == transaction_queue.capacity) {
        int new_capacity = transaction_queue.capacity == 0 ? 1 : transaction_queue.capacity * 2;
        transaction_queue.transactions = realloc(transaction_queue.transactions, new_capacity * sizeof(Transaction));
        transaction_queue.capacity = new_capacity;
    }
    transaction_queue.transactions[transaction_queue.size++] = *transaction;
    pthread_cond_signal(&transaction_queue.cond);
    pthread_mutex_unlock(&transaction_queue.lock);
}

int dequeue_transaction(Transaction *transaction) {
    pthread_mutex_lock(&transaction_queue.lock);
    while (transaction_queue.size == 0) {
        pthread_cond_wait(&transaction_queue.cond, &transaction_queue.lock);
    }
    *transaction = transaction_queue.transactions[--transaction_queue.size];
    pthread_mutex_unlock(&transaction_queue.lock);
    return 1;
}

double process_transactions() {
    time_t now = time(NULL);
    double max_weighted_sum_local = 0.0;
    int max_id_local = -1;

    while (dequeue_transaction(&current_transaction)) {
        if (!is_within_cutoff(current_transaction.timestamp, now)) {
            enqueue_transaction(&current_transaction); // Re-enqueue if too old
            break;
        }
        if (now - current_window_start > 3) {
            pthread_mutex_lock(&transaction_queue.lock);
            transaction_queue.size--;
            pthread_mutex_unlock(&transaction_queue.lock);
            continue; // Skip transactions outside the window
        }

        processed_transactions++;
        total_amount += current_transaction.amount;

        double weighted_sum = calculate_weighted_sum(&current_transaction);
        if (weighted_sum > max_weighted_sum_local) {
            max_weighted_sum_local = weighted_sum;
            max_id_local = current_transaction.id;
        }

        // Asynchronously log transaction details
        log_transaction(&current_transaction);

        pthread_mutex_lock(&transaction_queue.lock);
        transaction_queue.size--;
        pthread_mutex_unlock(&transaction_queue.lock);
    }

    if (max_weighted_sum_local > max_weighted_sum) {
        max_weighted_sum = max_weighted_sum_local;
        max_id = max_id_local;
    }

    return max_weighted_sum_local;
}

double calculate_weighted_sum(const Transaction *transaction) {
    double weight = 0.0;
    // Implement logic to determine weight based on transaction tags
    return transaction->amount * weight;
}

int is_within_cutoff(time_t timestamp, time_t cutoff_time) {
    return (cutoff_time - timestamp <= 5);
}

