namespace ResourceBundleNamespace {
    class ResourceBundle {
    public:
        struct Item;
        using BundlePtr = std::shared_ptr<Item>;
        using ItemsMap = std::unordered_map<std::string, BundlePtr>;

        class Item {
        public:
            std::string key;
            std::variant<std::string, int, double> value;
            ItemsMap nestedBundle;

            Item(const std::string& k, const std::variant<std::string, int, double>& v) : key(k), value(v) {}

            static BundlePtr createNestedBundle() {
                return std::make_shared<Item>("", "");
            }
        };

        ResourceBundle(std::ifstream& fileStream);
        ~ResourceBundle();

        std::optional<int> getRandomInt(const std::string& path) const;
        std::optional<double> getRandomDouble(const std::string& path) const;

    private:
        ItemsMap rootBundle;
        std::mt19937 rng;
        std::uniform_int_distribution<> intDist;
        std::uniform_real_distribution<> doubleDist;

        void parseFile(std::ifstream& fileStream);
        void parseLine(const std::string& line, ItemsMap& currentBundle);
    };

    ResourceBundle::ResourceBundle(std::ifstream& fileStream) : rng(std::random_device{}()), intDist(0), doubleDist(0.0) {
        parseFile(fileStream);
    }

    ResourceBundle::~ResourceBundle() {}

    std::optional<int> ResourceBundle::getRandomInt(const std::string& path) const {
        auto bundle = &rootBundle;
        for (const auto& key : split(path, '.')) {
            if (bundle->find(key) == bundle->end()) return std::nullopt;
            bundle = &(*bundle)[key]->nestedBundle;
        }
        if (std::holds_alternative<int>((*bundle).begin()->second.value)) {
            int value = std::get<int>((*bundle).begin()->second.value);
            return intDist(rng) % value;
        }
        return std::nullopt;
    }

    std::optional<double> ResourceBundle::getRandomDouble(const std::string& path) const {
        auto bundle = &rootBundle;
        for (const auto& key : split(path, '.')) {
            if (bundle->find(key) == bundle->end()) return std::nullopt;
            bundle = &(*bundle)[key]->nestedBundle;
        }
        if (std::holds_alternative<double>((*bundle).begin()->second.value)) {
            double value = std::get<double>((*bundle).begin()->second.value);
            return doubleDist(rng) * value;
        }
        return std::nullopt;
    }

    void ResourceBundle::parseFile(std::ifstream& fileStream) {
        std::string line;
        while (getline(fileStream, line)) {
            parseLine(line, rootBundle);
        }
    }

    void ResourceBundle::parseLine(const std::string& line, ItemsMap& currentBundle) {
        size_t colonPos = line.find(':');
        if (colonPos == std::string::npos) return;

        std::string key = line.substr(0, colonPos).trim();
        std::string value = line.substr(colonPos + 1).trim();

        if (value.empty() || value.front() != '{') {
            currentBundle[key] = std::make_shared<Item>(key, value);
        } else {
            BundlePtr nestedBundle = Item::createNestedBundle();
            currentBundle[key] = nestedBundle;
            // Recursively parse the nested bundle
            std::istringstream iss(value.substr(1, value.length() - 2));
            std::string subLine;
            while (getline(iss, subLine)) {
                parseLine(subLine, nestedBundle->nestedBundle);
            }
        }
    }

    std::vector<std::string> split(const std::string& str, char delimiter) {
        std::vector<std::string> tokens;
        std::string token;
        std::istringstream tokenStream(str);
        while (std::getline(tokenStream, token, delimiter)) {
            tokens.push_back(token);
        }
        return tokens;
    }
}
