const char* addSlashAndReplace(const char* input, size_t limit, char* buffer, const char* (*dict)[2]) {
    if (input == NULL || buffer == NULL) return NULL;

    // Calculate the length of the string and dictionary
    size_t len = strlen(input);
    size_t dict_len = 0;
    while (dict[dict_len][0] != '\0') dict_len++;

    // Check if appending a slash will exceed the limit
    if (len + 2 > limit) {
        logFailedOperation("String exceeds size limit");
        return NULL;
    }

    // Copy the input to buffer and append a slash
    strcpy(buffer, input);
    strncat(buffer, "/", limit);

    // Replace placeholders using dictionary values
    for (size_t i = 0; i < dict_len; i++) {
        char* pos = strstr(buffer, dict[i][0]);
        while (pos != NULL) {
            size_t replacement_len = strlen(dict[i][1]);
            if ((buffer + limit - pos) < replacement_len) {
                logFailedOperation("Buffer overflow during replacement");
                return NULL;
            }
            memmove(pos + replacement_len, pos + 2, strlen(pos));
            memcpy(pos, dict[i][1], replacement_len);
            pos = strstr(buffer, dict[i][0]);
        }
    }

    // Log successful operation
    logSuccessfulOperation("String processed successfully");

    return buffer;
}

void logFailedOperation(const char* message) {
    FILE* audit_file = fopen("audit.log", "a");
    if (audit_file != NULL) {
        fprintf(audit_file, "Failed: %s\n", message);
        fclose(audit_file);
    }
}

void logSuccessfulOperation(const char* message) {
    FILE* audit_file = fopen("audit.log", "a");
    if (audit_file != NULL) {
        fprintf(audit_file, "Success: %s\n", message);
        fclose(audit_file);
    }
