#include <string.h>
#include <math.h>
#include <time.h>

#define MAX_LINE_LENGTH 256
#define MAX_FILE_SIZE (10 * 1024 * 1024)
#define NUM_FIELDS 3

typedef struct {
    double data[NUM_FIELDS];
} DataLine;

void process_file(const char* input, const char* output) {
    FILE* infile = fopen(input, "r");
    if (!infile) {
        perror("Error opening input file");
        return;
    }

    FILE* outfile = fopen(output, "w");
    if (!outfile) {
        perror("Error opening output file");
        fclose(infile);
        return;
    }

    DataLine* lines = NULL;
    size_t num_lines = 0;
    size_t capacity = 1024;

    while (num_lines + 1 >= capacity) {
        capacity *= 2;
        lines = realloc(lines, capacity * sizeof(DataLine));
        if (!lines) {
            perror("Memory allocation failed");
            fclose(infile);
            fclose(outfile);
            return;
        }
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, infile)) {
        char* token = strtok(line, " ");
        int count = 0;
        while (token && count < NUM_FIELDS) {
            lines[num_lines].data[count++] = atof(token);
            token = strtok(NULL, " ");
        }
        if (count > 1) {
            double avg = (lines[num_lines].data[count - 2] + lines[num_lines].data[count - 1]) / 2;
            lines[num_lines].data[count] = avg;
            num_lines++;
        }
    }

    fclose(infile);

    qsort(lines, num_lines, sizeof(DataLine), compare_data);

    for (size_t i = 0; i < num_lines; i++) {
        fprintf(outfile, "%.6f %.6f %.6f\n", lines[i].data[0], lines[i].data[1], lines[i].data[2]);
    }

    fclose(outfile);
    free(lines);
}

int compare_data(const void* a, const void* b) {
    DataLine* da = (DataLine*)a;
    DataLine* db = (DataLine*)b;

    if (da->data[0] != db->data[0]) {
        return (da->data[0] < db->data[0]) ? -1 : 1;
    } else {
        return (da->data[1] > db->data[1]) ? -1 : 1;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    process_file(argv[1], argv[2]);

    return 0;
}
