int create_thumbnail(const char *video_file, const char *metadata_file, const char *output_file, int width, int height) {
    ThumbnailRequest request = { video_file, metadata_file, output_file, width, height };
    for (int i = 0; i < cache_size; ++i) {
        if (strcmp(cache[i].request.video_file, request.video_file) == 0 &&
            strcmp(cache[i].request.metadata_file, request.metadata_file) == 0 &&
            cache[i].request.width == width && cache[i].request.height == height) {
            // Serve from cache
            return cache[i].status;
        }
    }

    if (cache_size >= MAX_CACHE_SIZE) {
        // Cache is full, evict oldest entry
        memmove(cache, cache + 1, sizeof(ThumbnailTask) * (MAX_CACHE_SIZE - 1));
        --cache_size;
    }

    ThumbnailTask task = { request };
    pthread_create(&task.thread, NULL, generate_thumbnail, &task);
    pthread_detach(task.thread);

    // Add to cache
    cache[cache_size++] = task;

    return 0; // Assuming success for simplicity
}

