#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

void sigterm_handler(int signum) {
    // Handle SIGTERM by terminating the process group
    killpg(getpgrp(), SIGTERM);
    exit(1);
}

int execute_command_in_background(const char *command, const char *log_file) {
    pid_t pid;
    int status;

    // Register signal handler for SIGTERM
    if (signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        perror("Error registering signal handler");
        return 0;
    }

    // Fork a child process
    pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process: execute the command in the background
        int log_fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            perror("Error opening log file");
            exit(1);
        }
        dup2(log_fd, STDOUT_FILENO);
        dup2(log_fd, STDERR_FILENO);
        close(log_fd);

        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl failed");
        exit(1);
    } else {
        // Parent process: wait for the child to finish
        if (waitpid(pid, &status, 0) < 0) {
            perror("Waitpid failed");
            return 0;
        }

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status) == 0 ? 1 : 0;
        } else {
            return 0;
        }
    }

    return 0;
}
