import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class DataProcessor {
    private static final String CONFIG_FILE_PATH = "path/to/config/file.txt";
    private static final String UTILITY_PATH = "path/to/utility/processor.exe";
    private static final Path TEMP_OUTPUT_FILE = Paths.get("temp_output.txt");

    public static void main(String[] args) {
        try {
            // Delete existing configuration file
            deleteConfigFile(CONFIG_FILE_PATH);

            // Execute the command-line utility and redirect output to temporary file
            executeUtility(UTILITY_PATH, TEMP_OUTPUT_FILE.toString());

            // Log successful execution
            System.out.println("Data processing completed successfully.");
        } catch (IOException e) {
            // Handle IOExceptions and log errors
            e.printStackTrace();
            System.err.println("An error occurred during data processing: " + e.getMessage());
        } finally {
            try {
                // Delete temporary output file if it exists
                Files.deleteIfExists(TEMP_OUTPUT_FILE);
                System.out.println("Temporary output file deleted.");
            } catch (IOException e) {
                System.err.println("Failed to delete temporary output file: " + e.getMessage());
            }
        }
    }

    private static void deleteConfigFile(String filePath) throws IOException {
        File configFile = new File(filePath);
        if (configFile.exists()) {
            Files.delete(Paths.get(filePath));
            System.out.println("Configuration file deleted.");
        } else {
            System.out.println("Configuration file does not exist.");
        }
    }

    private static void executeUtility(String utilityPath, String outputFile) throws IOException {
        ProcessBuilder pb = new ProcessBuilder(utilityPath, outputFile);
        Process process = pb.start();
        int exitCode = process.waitFor();

        if (exitCode == 0) {
            System.out.println("Utility executed successfully.");
        } else {
            throw new IOException("Utility execution failed with exit code: " + exitCode);
        }
    }
}
```

This Java program demonstrates how to delete an existing configuration file, execute a command-line utility with output redirection, and handle potential exceptions. It uses `ProcessBuilder` to manage the external process and ensures that resources are properly released using a finally block. The program logs detailed information for auditing purposes and handles interruptions gracefully by deleting temporary files.']

