    for (int i = 0; i < MAX_ENV_VARS && config->env_vars[i] != NULL; i++) {
        if (strlen(config->env_vars[i]->env_name) == 0 || strlen(config->env_vars[i]->env_value) == 0) {
            return -2; // Missing environment variable name or value
        }
    }

    // Validate resource allocations
    for (int i = 0; i < MAX_RESOURCES && config->resources[i].value > 0; i++) {
