using System;
using System.Linq;
using System.Security.Cryptography;
using Newtonsoft.Json.Linq;

public class SecureMessageProcessor
{
    public string ProcessSecureMessage(string base64EncodedMessage, string oauthTokenJson, string encryptionMode)
    {
        // Validate OAuth2 token
        var token = JObject.Parse(oauthTokenJson);
        if (!token.ContainsKey("access_token") || !token["access_token"].Type.Equals(JTokenType.String))
            return null;
        if (!token.ContainsKey("expires_in") || !int.TryParse(token["expires_in"].ToString(), out _) || int.Parse(token["expires_in"].ToString()) <= 0)
            return null;
        if (token["token_type"] != "Bearer")
            return null;

        string accessToken = token["access_token"].ToString();
        // Add additional validation for refresh_token if needed

        // Setup cryptographic context
        byte[] key = Convert.FromBase64String(accessToken.Substring(0, 24)); // Assuming the access token is a Base64-encoded 192-bit key
        byte[] iv = new byte[8]; // Initialize IV based on your security requirements
        SymmetricAlgorithm des = TripleDES.Create();
        ICryptoTransform decryptor;

        switch (encryptionMode?.ToUpper())
        {
            case "ECB":
                des.Mode = CipherMode.ECB;
                des.Padding = PaddingMode.PKCS7;
                break;
            case "EDE":
                des.Mode = CipherMode.CBC; // EDE mode typically uses CBC with Triple DES
                des.Padding = PaddingMode.PKCS7;
                break;
            case "EDE3":
                des.Mode = CipherMode.CBC; // EDE3 mode also uses CBC
                des.Padding = PaddingMode.PKCS7;
                break;
            case "CFB":
                des.Mode = CipherMode.CFB;
                des.Padding = PaddingMode.None; // CFB does not use padding
                break;
            default:
                return null; // No encryption or unsupported mode
        }

        try
        {
            decryptor = des.CreateDecryptor(key, iv);
            byte[] encryptedMessageBytes = Convert.FromBase64String(base64EncodedMessage);
            using (MemoryStream msDecrypt = new MemoryStream(encryptedMessageBytes))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                {
                    return srDecrypt.ReadToEnd();
                }
            }
        }
        catch
        {
            return null; // Handle decryption failures gracefully
        }
    }
}
```

