using System;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;
using System.Diagnostics;

public class HashingService
{
    private readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();
    private readonly bool _useSHA256ForLargeInputs;
    private readonly int _largeInputSizeThreshold;

    public HashingService(bool useSHA256ForLargeInputs = true, int largeInputSizeThreshold = 1024 * 1024)
    {
        _useSHA256ForLargeInputs = useSHA256ForLargeInputs;
        _largeInputSizeThreshold = largeInputSizeThreshold;
    }

    public string ComputeHash(string input)
    {
        if (string.IsNullOrEmpty(input))
            return string.Empty;

        if (_hashCache.TryGetValue(input, out var cachedHash))
            return cachedHash;

        var hashAlgorithm = GetHashAlgorithm(input.Length);
        var hashBytes = hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input));
        var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

        _hashCache.TryAdd(input, hashString);

        LogHashComputation(input, hashString, hashAlgorithm.GetType().Name);

        return hashString;
    }

    private HashAlgorithm GetHashAlgorithm(int inputLength)
    {
        if (_useSHA256ForLargeInputs && inputLength > _largeInputSizeThreshold)
            return SHA256.Create();
        else
            return MD5.Create();
    }

    private void LogHashComputation(string input, string hash, string algorithmName)
    {
        var logMessage = $"Hash computed: Input={input.Substring(0, Math.Min(input.Length, 10))}..., Hash={hash}, Algorithm={algorithmName}, ThreadId={Thread.CurrentThread.ManagedThreadId}, Timestamp={DateTime.Now}";

        // Log the message using an existing logging framework
        Debug.WriteLine(logMessage);
    }
}
