using System.Text;

public struct SensorData
{
    public int Id { get; private set; }
    public DateTime Timestamp { get; private set; }
    public double Reading { get; private set; }
    public string Metadata { get; private set; }
    public int ReferenceCount { get; private set; }

    public void Acquire()
    {
        ReferenceCount++;
    }

    public bool Release()
    {
        if (ReferenceCount > 0)
        {
            ReferenceCount--;
            return ReferenceCount == 0;
        }
        return false;
    }
}

public class SensorDataProcessor
{
    private static readonly int MAX_BUFFER_SIZE = 64 * 1024;
    private static readonly string CSV_HEADER = "Id,Timestamp,Reading,Metadata";

    public static void DecryptAndPopulateSensorData(byte[] ciphertext, byte[] key, byte[] iv, int n)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            using (ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV))
            {
                int bytesRead;
                byte[] buffer = new byte[MAX_BUFFER_SIZE];
                List<SensorData> sensorDataList = new List<SensorData>();

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    while ((bytesRead = csDecrypt.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        // Process decrypted data in chunks
                        ProcessDecryptedData(sensorDataList, buffer, bytesRead);
                    }
                }

                // Convert list to array and serialize to CSV
                SensorData[] sensorDataArray = sensorDataList.ToArray();
                SerializeToCsv(sensorDataArray);
            }
        }
    }

    private static void ProcessDecryptedData(List<SensorData> sensorDataList, byte[] buffer, int bytesRead)
    {
        // Deserialize decrypted data into SensorData structures and add to list
        for (int i = 0; i < bytesRead; i += sizeof(SensorData))
        {
            SensorData sd = BitConverter.ToSensorData(buffer, i);
            sensorDataList.Add(sd);
        }
    }

    private static void SerializeToCsv(SensorData[] sensorDataArray)
    {
        using (StreamWriter sw = File.CreateText("sensor_data.csv"))
        {
            sw.WriteLine(CSV_HEADER);
            foreach (var sd in sensorDataArray)
            {
                sw.WriteLine($"{sd.Id},{sd.Timestamp:O},{sd.Reading},{sd.Metadata}");
            }
        }
    }

    public static SensorData ToSensorData(byte[] data, int offset)
    {
        // Implement conversion logic from byte array to SensorData structure
        return new SensorData();
    }
}
