typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C,
    NUM_EVENT_TYPES
} EventType;

typedef struct TrafficEvent {
    time_t timestamp;
    EventType eventType;
    int uniqueId;
    char* fileMetadata;
    int fileSize;
    double uploadDuration;
    int referenceCount;
    // Additional fields as needed
} TrafficEvent;

TrafficEvent** initTrafficEvents(int N) {
    TrafficEvent** events = (TrafficEvent**)malloc(N * sizeof(TrafficEvent*));
    if (!events) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        events[i] = (TrafficEvent*)malloc(sizeof(TrafficEvent));
        if (!events[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated events
            for (int j = 0; j < i; j++) {
                free(events[j]);
            }
            free(events);
            return NULL;
        }

        events[i]->timestamp = time(NULL);
        events[i]->eventType = rand() % NUM_EVENT_TYPES;
        events[i]->uniqueId = i;
        events[i]->fileMetadata = (char*)malloc(100 * sizeof(char));
        if (!events[i]->fileMetadata) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated events
            for (int j = 0; j <= i; j++) {
                free(events[j]->fileMetadata);
                free(events[j]);
            }
            free(events);
            return NULL;
        }
        snprintf(events[i]->fileMetadata, 100, "File %d metadata", i);
        events[i]->fileSize = rand() % 1024; // Random file size
        events[i]->uploadDuration = ((double)rand()) / RAND_MAX * 5.0; // Random upload duration
        events[i]->referenceCount = 1;
    }

    return events;
}

void freeTrafficEvents(TrafficEvent** events, int N) {
    for (int i = 0; i < N; i++) {
        free(events[i]->fileMetadata);
        free(events[i]);
    }
    free(events);
}

