    MD5_Init(&md5);
    MD5_Update(&md5, input, length);
    MD5_Final(hash, &md5);

    unsigned char* result = (unsigned char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (result == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

