const { exec } = require('child_process');
const neo4j = require('neo4j-driver').v1;

function addVerticesAndEdges(numOperations, batchSize = 1000, timeout = 5000) {
    const driver = neo4j.driver('bolt://localhost:7687', neo4j.auth.basic('neo4j', 'password'));
    let successCount = 0;
    let failureCount = 0;

    function getRandomProperties() {
        return {
            label: `Label${Math.floor(Math.random() * 10)}`,
            attribute: Math.random().toString(36).substr(2, 9)
        };
    }

    async function addBatch() {
        for (let i = 0; i < batchSize; i++) {
            try {
                const session = driver.session();
                await session.run(`CREATE (:Vertex ${JSON.stringify(getRandomProperties())})`);
                await session.run(`MATCH (v:Vertex) WHERE id(v) = lastNode().id CREATE (e:Edge {sourceId: id(v), targetId: rand() * 1000})`);
                session.close();
                successCount++;
            } catch (error) {
                console.error('Failed to add vertex and edge:', error);
                failureCount++;
            }
        }
    }

    function executeShellCommand(command) {
        return new Promise((resolve, reject) => {
            const child = exec(command, { timeout }, (error, stdout, stderr) => {
                if (error) {
                    console.error('Shell command failed:', error);
                    reject(stderr);
                } else {
                    console.log('Shell command output:', stdout);
                    resolve(stdout);
                }
            });
        });
    }

    async function main() {
        for (let i = 0; i < numOperations; i++) {
            try {
                await addBatch();
                const shellOutput = await executeShellCommand('your_shell_command_here');
                console.log('Shell command executed successfully:', shellOutput);
            } catch (error) {
                failureCount++;
            }
        }

        driver.close();
        return {
            summary: `Total operations: ${numOperations}, Successes: ${successCount}, Failures: ${failureCount}`
        };
    }

    return main();
}

// Example usage:
addVerticesAndEdges(10).then(summary => console.log(summary));
