    snprintf(event->eventType, sizeof(event->eventType), "%s", eventType);
    event->id = id;
    event->next = NULL;
    return event;
}

void addEvent(NetworkEvent** head, int timestamp, const char* eventType, int id) {
    NetworkEvent* newEvent = createEvent(timestamp, eventType, id);
    if (*head == NULL) {
        *head = newEvent;
    } else {
        NetworkEvent* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEvent;
    }
}

void removeOldEvents(NetworkEvent** head, int thresholdTimestamp) {
    NetworkEvent* current = *head;
    NetworkEvent* previous = NULL;
    while (current != NULL) {
        if (current->timestamp < thresholdTimestamp) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current = previous->next;
        } else {
            previous = current;
            current = current->next;
        }
    }
}

int countEventsInWindow(NetworkEvent* head, int startTimestamp, int endTimestamp) {
    int count = 0;
    NetworkEvent* current = head;
    while (current != NULL) {
        if (current->timestamp >= startTimestamp && current->timestamp <= endTimestamp) {
            count++;
        }
        current = current->next;
    }
    return count;
}

void freeEvents(NetworkEvent** head) {
    NetworkEvent* current = *head;
    while (current != NULL) {
        NetworkEvent* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
