use tokio::sync::{mpsc, oneshot};
use std::collections::HashMap;
use std::fs;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Debug)]
enum Task {
    Add { task_id: u32, priority: i32, timeout: Duration },
    Remove { task_id: u32 },
    Execute { task_id: u32 },
}

struct Scheduler {
    tasks: HashMap<u32, (i32, oneshot::Sender<()>)>,
}

impl Scheduler {
    fn new() -> Self {
        Scheduler {
            tasks: HashMap::new(),
        }
    }

    async fn add_task(&mut self, task_id: u32, priority: i32, timeout: Duration) {
        let (tx, rx) = oneshot::channel();
        self.tasks.insert(task_id, (priority, tx));
        tokio::spawn(async move {
            if let Err(_) = tx.send(()).await {
                // Handle error
            }
            tokio::time::sleep(timeout).await;
            println!("Task {} executed", task_id);
        });
    }

    async fn remove_task(&mut self, task_id: u32) {
        self.tasks.remove(&task_id);
    }

    async fn execute_task(&self, task_id: u32) {
        if let Some((_, tx)) = self.tasks.get(&task_id) {
            if let Err(_) = tx.send(()).await {
                // Handle error
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let scheduler = Arc::new(Mutex::new(Scheduler::new()));
    let mut task_tx = mpsc::channel(32).0;

    tokio::spawn(async move {
        while let Some(task) = task_rx.recv().await {
            match task {
                Task::Add { task_id, priority, timeout } => {
                    scheduler.lock().unwrap().add_task(task_id, priority, timeout).await;
                }
                Task::Remove { task_id } => {
                    scheduler.lock().unwrap().remove_task(task_id).await;
                }
                Task::Execute { task_id } => {
                    scheduler.lock().unwrap().execute_task(task_id).await;
                }
            }
        }
    });

    // Example usage
    let _ = task_tx.send(Task::Add { task_id: 1, priority: 5, timeout: Duration::from_secs(10) }).await;
    let _ = task_tx.send(Task::Execute { task_id: 1 }).await;

    Ok(())
}
