use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::sync::{Arc, Mutex};
use std::env;
use uuid::Uuid;

#[derive(Debug)]
enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

fn log_message(level: LogLevel, message: &str) -> io::Result<()> {
    let config = Arc::new(Mutex::new(LogConfig::new()));
    let mut config_lock = config.lock().unwrap();
    let file_path = config_lock.get_or_create_log_file()?;

    match level {
        LogLevel::Debug => writeln!(file, "[DEBUG] {}", message),
        LogLevel::Info => writeln!(file, "[INFO] {}", message),
        LogLevel::Warn => writeln!(file, "[WARN] {}", message),
        LogLevel::Error => writeln!(file, "[ERROR] {}", message),
    }
}

struct LogConfig {
    log_file_path: Option<String>,
    level: LogLevel,
    format: String,
}

impl LogConfig {
    fn new() -> Self {
        LogConfig {
            log_file_path: None,
            level: LogLevel::Info,
            format: "%Y-%m-%d %H:%M:%S".to_string(),
        }
    }

    fn get_or_create_log_file(&mut self) -> io::Result<String> {
        if let Some(ref path) = self.log_file_path {
            File::open(path).map(|_| path.clone()).or_else(|_| {
                self.create_new_log_file()
            })
        } else {
            self.create_new_log_file()
        }
    }

    fn create_new_log_file(&mut self) -> io::Result<String> {
        let mut file_name = "log_".to_string();
        loop {
            let uuid = Uuid::new_v4().simple();
            file_name.push_str(&format!("{}.txt", uuid));
            match File::create(&file_name) {
                Ok(_) => {
                    self.log_file_path = Some(file_name.clone());
                    env::set_var("LOG_FILE_PATH", &self.log_file_path);
                    return Ok(self.log_file_path.as_ref().unwrap().clone());
                }
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
    }

    fn set_level(&mut self, level: LogLevel) {
        self.level = level;
    }

    fn set_format(&mut self, format: String) {
        self.format = format;
    }
}
```

