#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_LIST_SIZE 1024
#define MIN_LIST_CAPACITY 64

typedef struct {
    time_t timestamp;
    int event_type;
    int unique_id;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    int count;
    int capacity;
    MD5_CTX md5_ctx;
} NetworkEventList;

int initializeNetworkEventList(NetworkEventList *list) {
    list->capacity = MIN_LIST_CAPACITY;
    list->count = 0;
    list->events = (NetworkEvent *)malloc(list->capacity * sizeof(NetworkEvent));
    if (!list->events) {
        return -1; // Memory allocation failed
    }
    MD5_Init(&list->md5_ctx);
    return 0;
}

int addEventToNetworkList(NetworkEventList *list, NetworkEvent event) {
    if (list->count >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NetworkEvent *new_events = (NetworkEvent *)realloc(list->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            return -1; // Memory reallocation failed
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }
    MD5_Update(&list->md5_ctx, &event, sizeof(event));
    list->events[list->count++] = event;
    return 0;
}

int removeOldEventsFromNetworkList(NetworkEventList *list, time_t threshold) {
    int new_count = 0;
    for (int i = 0; i < list->count; i++) {
        if (list->events[i].timestamp >= threshold) {
            MD5_Update(&list->md5_ctx, &list->events[i], sizeof(list->events[i]));
            list->events[new_count++] = list->events[i];
        }
    }
    list->count = new_count;
    return 0;
}

int getEventCountInTimeWindow(NetworkEventList *list, time_t start_time, time_t end_time) {
    int count = 0;
    for (int i = 0; i < list->count; i++) {
        if (list->events[i].timestamp >= start_time && list->events[i].timestamp <= end_time) {
            count++;
        }
    }
    return count;
}

unsigned char* getMD5HashOfNetworkList(NetworkEventList *list, unsigned char *output_buffer, int buffer_size) {
    MD5_Final(output_buffer, &list->md5_ctx);
    return output_buffer;
}

void destroyNetworkEventList(NetworkEventList *list) {
    free(list->events);
}
