#define MAX_DATA_SIZE 1024

typedef struct {
    char buffer[MAX_DATA_SIZE];
    size_t read_pos;
    size_t write_pos;
    int is_paused;
} StreamHandler;

void streamHandlerInit(StreamHandler *handler) {
    handler->read_pos = 0;
    handler->write_pos = 0;
    handler->is_paused = 0;
}

int streamHandlerPause(StreamHandler *handler) {
    if (handler->is_paused) {
        return -1; // Already paused
    }
    handler->is_paused = 1;
    return 0; // Success
}

int streamHandlerResume(StreamHandler *handler) {
    if (!handler->is_paused) {
        return -1; // Not paused
    }
    handler->is_paused = 0;
    return 0; // Success
}

ssize_t streamHandlerRead(StreamHandler *handler, char *data, size_t len) {
    if (handler->read_pos == handler->write_pos) {
        return 0; // No data available
    }

    size_t bytes_to_read = len < handler->write_pos - handler->read_pos ? len : handler->write_pos - handler->read_pos;
    memcpy(data, handler->buffer + handler->read_pos, bytes_to_read);
    handler->read_pos += bytes_to_read;
    return bytes_to_read;
}

ssize_t streamHandlerWrite(StreamHandler *handler, const char *data, size_t len) {
    if (handler->is_paused) {
        return -1; // Cannot write when paused
    }

    size_t free_space = MAX_DATA_SIZE - handler->write_pos;
    if (len > free_space) {
        return -2; // Not enough space to write
    }

    memcpy(handler->buffer + handler->write_pos, data, len);
    handler->write_pos += len;
    return len;
}
