#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Define log levels
typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

// Define log structure
typedef struct {
    FILE *file;
    LogLevel level;
    size_t max_message_length;
    pthread_mutex_t lock;
} Logger;

// Initialize logger
Logger* init_logger(const char *filename, LogLevel level, size_t max_message_length) {
    Logger *logger = (Logger*)malloc(sizeof(Logger));
    logger->file = fopen(filename, "a");
    logger->level = level;
    logger->max_message_length = max_message_length;
    pthread_mutex_init(&logger->lock, NULL);
    return logger;
}

// Log message
void log_message(Logger *logger, LogLevel current_level, const char *message) {
    if (current_level >= logger->level && strlen(message) <= logger->max_message_length) {
        pthread_mutex_lock(&logger->lock);
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(logger->file, "[%ld.%06ld] [%d] %s\n", tv.tv_sec, tv.tv_usec, current_level, message);
        fflush(logger->file);
        pthread_mutex_unlock(&logger->lock);
    }
}

// Encrypt data using OpenSSL
EVP_CIPHER_CTX *encrypt_data(const char *data, size_t data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform the encryption
    // ...

    return ctx;
}

// Main function to handle cryptographic operations with logging
void *handle_operation(void *param) {
    char *data = (char*)param;
    Logger *logger = init_logger("operation.log", INFO, 1024);

    EVP_CIPHER_CTX *ctx = encrypt_data(data, strlen(data));
    if (!ctx) {
        log_message(logger, ERROR, "Encryption failed");
        // Handle failure gracefully
        return NULL;
    }

    // Continue with the cryptographic operation
    // ...

    EVP_CIPHER_CTX_free(ctx);
    fclose(logger->file);
    pthread_mutex_destroy(&logger->lock);
    free(logger);

    return NULL;
}

// Example usage
int main() {
    char data[] = "Sensitive information";
    pthread_t thread;

    if (pthread_create(&thread, NULL, handle_operation, data) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);
    return 0;
}
