        }
    }
    printf("Failed to send email after %d attempts.\n", MAX_RETRIES);
    return 1; // Failure
}

int main() {
    const char* user_email = "user@example.com";
    const char* email_subject = "Greetings from the Code Assistant!";
    const char* email_body = "Hello, this is a test email from our coding assistant.";

    if (send_email(user_email, email_subject, email_body) == 0) {
        printf("Email sent successfully.\n");
    } else {
        printf("Failed to send email.\n");
    }

    return 0;
}
```

