['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final long cacheTtl;
    private final int cacheSize;
    private final ExternalLogger logger;

    public MD5Hasher(long cacheTtl, int cacheSize, ExternalLogger logger) {
        this.cacheTtl = cacheTtl;
        this.cacheSize = cacheSize;
        this.logger = logger;
    }

    public String getMD5(String input) throws InterruptedException {
        // Check cache
        CacheEntry cachedEntry = cache.get(input);
        if (cachedEntry != null && !cachedEntry.isExpired()) {
            return cachedEntry.getResult();
        }

        // Compute hash if not in cache or expired
        String md5Hash = computeMD5(input);

        // Put result into cache
        cache.putIfAbsent(input, new CacheEntry(md5Hash, System.currentTimeMillis()));

        // Remove least recently used entry if cache is full
        while (cache.size() > cacheSize) {
            cache.pollOldestEntry();
        }

        return md5Hash;
    }

    private String computeMD5(String input) throws InterruptedException {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.logError("MD5 algorithm not available", e);
            throw new InterruptedException("Hashing algorithm not available");
        }
    }

    private static class CacheEntry {
        private final String result;
        private final long timestamp;

        public CacheEntry(String result, long timestamp) {
            this.result = result;
            this.timestamp = timestamp;
        }

        public String getResult() {
            return result;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() - timestamp > cacheTtl;
        }
    }

    private static class ExternalLogger {
        public void logError(String message, Exception e) {
            // Implement logging logic here
        }
    }

    private static ConcurrentHashMap<String, CacheEntry> pollOldestEntry(ConcurrentHashMap<String, CacheEntry> map) {
        return map.entrySet().stream()
                .min((e1, e2) -> Long.compare(e1.getValue().timestamp, e2.getValue().timestamp))
                .map(entry -> {
                    map.remove(entry.getKey());
                    return map;
                })
                .orElse(map);
    }

    // Unit tests
    public static void main(String[] args) throws InterruptedException {
        ExternalLogger logger = new ExternalLogger();
        MD5Hasher hasher = new MD5Hasher(60, 1000, logger);

        System.out.println(hasher.getMD5("test")); // Cache miss
        System.out.println(hasher.getMD5("test")); // Cache hit

        // Simulate concurrent access
        Thread t1 = new Thread(() -> {
            try {
                System.out.println(hasher.getMD5("test"));
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        Thread t2 = new Thread(() -> {
            try {
                System.out.println(hasher.getMD5("test"));
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        t1.start();
        t2.start();

        t1.join();
        t2.join();
    }
}
```

**Explanation:**
- **Concurrency:** The `ConcurrentHashMap` is used to store cached results, ensuring thread safety.
- **Caching:** A custom `CacheEntry` class holds the hash result and timestamp. The cache is limited in size, and the oldest entry is removed when adding a new one that would exceed the limit.
- **Logging:** An `ExternalLogger` interface with a single method for logging errors is used. This can be replaced with any actual logging framework.
- **Efficiency:** The MD5 computation is offloaded to a separate method to keep the cache access logic clean and focused on caching.
- **Configuration:** Cache TTL and size are set through constructor parameters, allowing flexibility without modifying the code.
- **Unit Testing:** A simple `main` method demonstrates basic functionality and concurrency handling.

**Trade-offs:**
- Memory usage is limited by the cache size, which can lead to increased memory consumption if not configured properly.
- CPU usage is kept low by minimizing redundant hash computations through caching.
- Thread safety is achieved using concurrent data structures and methods, but could be improved with more sophisticated locking mechanisms if performance becomes an issue.

This implementation provides a solid foundation for a thread-safe MD5 hashing service with caching capabilities. Further optimization or customization may be necessary based on specific requirements and performance benchmarks.']

