import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5HashProcessor {
    private static final int MAX_CACHE_SIZE = 10;
    private static final Map<String, String> cache = new HashMap<>();
    private static final Object lock = new Object();

    public static String computeMD5(String input) throws InvalidInputException {
        if (input == null) {
            throw new InvalidInputException("Input cannot be null");
        }

        input = input.trim();
        if (input.length() > 1024) {
            throw new InvalidInputException("Input exceeds maximum length of 1024 characters");
        }

        synchronized (lock) {
            if (cache.containsKey(input)) {
                return cache.get(input);
            }
        }

        String md5Hash = generateMD5Hash(input);

        synchronized (lock) {
            if (cache.size() >= MAX_CACHE_SIZE) {
                // Simple LRU eviction for demonstration
                cache.remove(cache.keySet().iterator().next());
            }
            cache.put(input, md5Hash);
        }

        return md5Hash;
    }

    private static String generateMD5Hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle or log the exception
            throw new RuntimeException("MD5 algorithm not available", e);
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(computeMD5("example input"));
        } catch (InvalidInputException e) {
            System.err.println(e.getMessage());
        }
    }
}

class InvalidInputException extends Exception {
    public InvalidInputException(String message) {
        super(message);
    }
}
