public class HashService {
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final CacheEvictionPolicy evictionPolicy;
    private final Logger logger;
    private long maxCacheSizeBytes;
    private int maxCacheEntries;
    private long cacheExpirationSeconds;

    public HashService(Logger logger) {
        this.logger = logger;
        this.evictionPolicy = new CacheEvictionPolicy();
    }

    public void configure(long maxCacheSize, int maxEntries, long expirationTime) {
        this.maxCacheSizeBytes = maxCacheSize;
        this.maxCacheEntries = maxEntries;
        this.cacheExpirationSeconds = expirationTime;
    }

    public String getSHA256(String input) {
        try {
            return cache.computeIfAbsent(input, key -> {
                String hash = computeHash(key);
                evictionPolicy.evictLeastRecentlyUsed(maxCacheSizeBytes, maxCacheEntries);
                logger.log("Computed and cached: " + input);
                return hash;
            });
        } catch (Exception e) {
            logger.logError("Failed to compute SHA-256 for input: " + input, e);
            return null;
        }
    }

    private String computeHash(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static class CacheEvictionPolicy {
        public void evictLeastRecentlyUsed(long maxSizeBytes, int maxEntries) {
            // Implement eviction logic here
        }
    }

    interface Logger {
        void log(String message);
        void logError(String message, Exception e);
    }
}
