#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NetworkEvent {
    time_t timestamp;
    int eventType;
    int uniqueID;
    struct NetworkEvent* next;
} NetworkEvent;

typedef struct EventManager {
    NetworkEvent* head;
    pthread_mutex_t lock;
    time_t retentionPeriod;
} EventManager;

EventManager* createEventManager(time_t retention) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->retentionPeriod = retention;
    return manager;
}

void addEvent(EventManager* manager, int eventType, int uniqueID) {
    NetworkEvent* newEvent = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    newEvent->timestamp = time(NULL);
    newEvent->eventType = eventType;
    newEvent->uniqueID = uniqueID;
    newEvent->next = NULL;

    pthread_mutex_lock(&manager->lock);
    newEvent->next = manager->head;
    manager->head = newEvent;
    pthread_mutex_unlock(&manager->lock);
}

void removeOldEvents(EventManager* manager) {
    time_t currentTime = time(NULL);
    NetworkEvent* current = manager->head;
    NetworkEvent* previous = NULL;

    while (current != NULL) {
        if ((currentTime - current->timestamp) > manager->retentionPeriod) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current = previous->next;
        } else {
            previous = current;
            current = current->next;
        }
    }
}

int countEventsInWindow(EventManager* manager, time_t startTime, time_t endTime) {
    int count = 0;
    NetworkEvent* current = manager->head;

    while (current != NULL) {
        if ((current->timestamp >= startTime) && (current->timestamp <= endTime)) {
            count++;
        }
        current = current->next;
    }

    return count;
}

void synchronizeWithExternalService(EventManager* manager, const char* serviceURL) {
    // Simulate external data synchronization
    printf("Synchronizing with external service: %s\n", serviceURL);
    sleep(2); // Simulate network latency

    if (rand() % 2 == 0) { // Simulate occasional data loss
        printf("Data synchronization failed. Retrying...\n");
        synchronizeWithExternalService(manager, serviceURL);
    }
}

void* manageEvents(void* arg) {
    EventManager* manager = (EventManager*)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        removeOldEvents(manager);
        pthread_mutex_unlock(&manager->lock);

        // Simulate event generation
        addEvent(manager, rand() % 10, rand());

        // Periodic data synchronization
        synchronizeWithExternalService(manager, "https://example.com/event-log");

        sleep(5); // Simulate periodic processing
    }
}

int main() {
    EventManager* manager = createEventManager(3600 * 24); // 1 day retention

    pthread_t thread;
    pthread_create(&thread, NULL, manageEvents, (void*)manager);

    pthread_join(thread, NULL);

    return 0;
}
