IPAddress oauthAuthenticateAndResolveHostname(const char *hostname, int N) {
    IPAddress ip;
    // Perform DNS resolution
    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    if ((getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        // Handle DNS resolution error
        perror("DNS resolution failed");
        exit(EXIT_FAILURE);
    }
    for(p = res;p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];
        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy((char*)ip.ip, ipstr);
    }
    freeaddrinfo(res); // all done with this structure
    return ip;
}

UserAuthentication* createAuthArray(int N) {
    UserAuthentication *authArray = (UserAuthentication*)malloc(N * sizeof(UserAuthentication));
    if (!authArray) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < N; i++) {
        authArray[i].refCount = 1;
    }
    return authArray;
}

void populateAuthArray(UserAuthentication *authArray, int N) {
