#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

// Define a structure to hold thread-specific data
struct ThreadData {
    std::atomic<int> linesCount;
    std::atomic<int> wordsCount;
    // Add other fields as needed
};

// Function to process a single file
void processFile(const std::string& filePath, int delimiter, ThreadData& threadData) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filePath << std::endl;
        return;
    }

    std::string line;
    while (std::getline(file, line)) {
        ++threadData.linesCount;
        int wordCount = 0;
        size_t pos = 0;
        while ((pos = line.find(delimiter, pos)) != std::string::npos) {
            ++wordCount;
            pos += delimiter.length();
        }
        threadData.wordsCount += wordCount + (line.empty() ? 0 : 1);
    }

    file.close();
}

// Main function to parse arguments and dispatch tasks
int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " [-o output_file] [-d delimiter] [file1.txt file2.txt ...]" << std::endl;
        return 1;
    }

    std::string outputFile;
    int delimiter = ' ';
    std::vector<std::string> files;

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
            switch (argv[i][1]) {
                case 'o':
                    outputFile = argv[++i];
                    break;
                case 'd':
                    delimiter = std::atoi(argv[++i]);
                    break;
                default:
                    std::cerr << "Unknown option: " << argv[i] << std::endl;
                    return 1;
            }
        } else {
            files.push_back(argv[i]);
        }
    }

    if (files.empty()) {
        std::cerr << "No input file provided." << std::endl;
        return 1;
    }

    // Create a thread pool
    std::vector<std::thread> threads;
    std::vector<ThreadData> threadData(files.size());
    for (size_t i = 0; i < files.size(); ++i) {
        threads.emplace_back(processFile, files[i], delimiter, std::ref(threadData[i]));
    }

    // Wait for all threads to finish
    for (auto& t : threads) {
        t.join();
    }

    // Aggregate results and write to output file if specified
    int totalLines = 0;
    int totalWords = 0;
    for (const auto& td : threadData) {
        totalLines += td.linesCount.load();
        totalWords += td.wordsCount.load();
    }

    if (!outputFile.empty()) {
        std::ofstream out(outputFile);
        if (out.is_open()) {
            out << "Total lines: " << totalLines << std::endl;
            out << "Total words: " << totalWords << std::endl;
            out.close();
        } else {
            std::cerr << "Failed to open output file: " << outputFile << std::endl;
        }
    }

    return 0;
}
