#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define EVENT_MAX 1000

typedef struct {
    time_t timestamp;
    int type;
    int id;
} NetworkEvent;

typedef struct {
    NetworkEvent events[EVENT_MAX];
    int count;
    int max_count;
} EventList;

void init_event_list(EventList *list, int max_count) {
    list->count = 0;
    list->max_count = max_count;
}

int add_event(EventList *list, time_t timestamp, int type, int id) {
    if (list->count >= list->max_count) return -1; // List full
    list->events[list->count].timestamp = timestamp;
    list->events[list->count].type = type;
    list->events[list->count].id = id;
    list->count++;
    return 0;
}

int remove_old_events(EventList *list, time_t retention_period) {
    int removed_count = 0;
    for (int i = 0; i < list->count;) {
        if (time(NULL) - list->events[i].timestamp > retention_period) {
            for (int j = i; j < list->count - 1; j++) {
                list->events[j] = list->events[j + 1];
            }
            list->count--;
            removed_count++;
        } else {
            i++;
        }
    }
    return removed_count;
}

int get_events_in_window(EventList *list, time_t start_time, time_t end_time) {
    int count = 0;
    for (int i = 0; i < list->count; i++) {
        if (list->events[i].timestamp >= start_time && list->events[i].timestamp <= end_time) {
            count++;
        }
    }
    return count;
}

void prioritize_events(EventList *list, int (*priority_func)(NetworkEvent *)) {
    for (int i = 0; i < list->count - 1; i++) {
        for (int j = i + 1; j < list->count; j++) {
            if (priority_func(list->events[j]) > priority_func(list->events[i])) {
                NetworkEvent temp = list->events[i];
                list->events[i] = list->events[j];
                list->events[j] = temp;
            }
        }
    }
}

int notify_critical_events(EventList *list, void (*notify_func)(NetworkEvent *)) {
    int notified_count = 0;
    for (int i = 0; i < list->count; i++) {
        if (list->events[i].type == CRITICAL_EVENT_TYPE) {
            notify_func(list->events[i]);
            notified_count++;
        }
    }
    return notified_count;
}

void log_operation(const char *operation, int result) {
    printf("%s: %d\n", operation, result);
}

void sync_with_external_service(EventList *list, void (*sync_func)(EventList *)) {
    if (sync_func(list)) {
        log_operation("Sync failed", -1);
    } else {
        log_operation("Sync successful", 0);
    }
}
