EventManager* create_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) {
        return NULL;
    }
    manager->events = (NetworkEvent*)calloc(initial_capacity, sizeof(NetworkEvent));
    manager->crc_indications = (NFapiCrcIndication*)calloc(initial_capacity, sizeof(NFapiCrcIndication));
    if (!manager->events || !manager->crc_indications) {
        free(manager->events);
        free(manager->crc_indications);
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->events);
        free(manager->crc_indications);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

void add_event(EventManager* manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkEvent* new_events = realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        NFapiCrcIndication* new_crc_indications = realloc(manager->crc_indications, new_capacity * sizeof(NFapiCrcIndication));
        if (!new_events || !new_crc_indications) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->events = new_events;
        manager->crc_indications = new_crc_indications;
        manager->capacity = new_capacity;
    }
    manager->events[manager->size++] = event;
    pthread_mutex_unlock(&manager->lock);
}

void remove_old_events(EventManager* manager, time_t threshold) {
    pthread_mutex_lock(&manager->lock);
    size_t i = 0;
    while (i < manager->size && manager->events[i].timestamp < threshold) {
        i++;
    }
    memmove(manager->events, &manager->events[i], (manager->size - i) * sizeof(NetworkEvent));
    memmove(manager->crc_indications, &manager->crc_indications[i], (manager->size - i) * sizeof(NFapiCrcIndication));
    manager->size -= i;
    pthread_mutex_unlock(&manager->lock);
}

size_t get_events_in_window(EventManager* manager, time_t start_time, time_t end_time) {
    size_t count = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        if (manager->events[i].timestamp >= start_time && manager->events[i].timestamp <= end_time) {
            count++;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void generate_crc_indications(EventManager* manager, int enable_crc) {
