use tokio::sync::{mpsc, Mutex};
use std::collections::HashMap;
use std::time::{Duration, Instant};
use log4rs::{
    append::{file::FileAppender, console::ConsoleAppender},
    config::{Config, Appender, Root},
    encode::pattern::PatternEncoder,
};
use lazy_static::lazy_static;
use parking_lot::Mutex as LockMutex;

struct Logger {
    channel: mpsc::Sender<LogMessage>,
    log_level: log::LevelFilter,
    rate_limit_config: RateLimitConfig,
}

struct LogMessage {
    level: log::Level,
    message: String,
    timestamp: Instant,
}

struct RateLimitConfig {
    interval: Duration,
    limit: usize,
}

lazy_static! {
    static ref LOGGER: LockMutex<Logger> = LockMutex::new(Logger {
        channel: mpsc::channel(1024).0,
        log_level: log::LevelFilter::Info,
        rate_limit_config: RateLimitConfig {
            interval: Duration::from_secs(1),
            limit: 100,
        },
    });
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = std::env::args().skip(1);
    let log_level = match args.next() {
        Some(level) => level.parse::<log::LevelFilter>()?,
        None => log::LevelFilter::Info,
    };
    let interval: u64 = args
        .next()
        .map_or(1, |s| s.parse().expect("Invalid rate limit interval"));
    let limit: usize = args.next().map_or(100, |s| s.parse().expect("Invalid rate limit limit"));

    LOGGER.lock().log_level = log_level;
    LOGGER.lock().rate_limit_config.interval = Duration::from_secs(interval);
    LOGGER.lock().rate_limit_config.limit = limit;

    log4rs::init_config(create_logger_config()).unwrap();

    let (tx, mut rx) = mpsc::channel(1024);

    tokio::spawn(async move {
        while let Some(msg) = rx.recv().await {
            if msg.timestamp.elapsed() > LOGGER.lock().rate_limit_config.interval
                || LOGGER.lock().count_logs(&msg.level) < LOGGER.lock().rate_limit_config.limit
            {
                log!(target: "distributed_logger", level: msg.level, "{}", msg.message);
                LOGGER.lock().increment_log_count(&msg.level);
            } else if let Err(e) = send_to_distributed_service(msg).await {
                handle_network_failure(e, msg).await;
            }
        }
    });

    // Simulate log messages
    for i in 0..200 {
        log_message(log::Level::Info, format!("Log message {}", i));
        tokio::time::sleep(Duration::from_millis(10)).await;
    }

    Ok(())
}

fn create_logger_config() -> Config {
    Config {
        appenders: HashMap::from([
            (
                "console".to_string(),
                Appender::Console(Box::new(ConsoleAppender::builder().build())),
            ),
            (
                "file".to_string(),
                Appender::File(Box::new(FileAppender::builder()
                    .encoder(Box::new(PatternEncoder::new("{d(%Y-%m-%d %H:%M:%S)} [%l] %m%n"))))
                    .build("logs/app.log"))),
            ),
        ]),
        root: Root::builder()
            .appender("console".to_string())
            .appender("file".to_string())
            .level(log::LevelFilter::Debug)
            .build(),
    }
}

async fn log_message(level: log::Level, message: String) {
    LOGGER.lock().channel.send(LogMessage { level, message, timestamp: Instant::now() }).await.unwrap();
}

async fn send_to_distributed_service(msg: LogMessage) -> Result<(), Box<dyn std::error::Error>> {
    // Simulate sending to a distributed logging service
    tokio::time::sleep(Duration::from_secs(1)).await;
    Ok(())
}

async fn handle_network_failure(e: Box<dyn std::error::Error>, msg: LogMessage) {
    // Fallback mechanism: log to local file if distributed service is unavailable
    let mut logger = LOGGER.lock();
    if logger.count_logs(&msg.level) < logger.rate_limit_config.limit {
        log!(target: "local_file_logger", level: msg.level, "{}", msg.message);
        logger.increment_log_count(&msg.level);
    }
}

impl Logger {
    fn increment_log_count(&mut self, level: &log::Level) {
        // Increment the log count for the given level
    }

    fn count_logs(&self, level: &log::Level) -> usize {
        // Return the current log count for the given level
        0
    }
}
