#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct {
    int *resources;
    size_t capacity;
    size_t used;
    sem_t available;
    pthread_mutex_t mutex;
} ResourcePool;

ResourcePool* create_resource_pool(size_t initial_capacity, size_t max_capacity) {
    ResourcePool *pool = malloc(sizeof(ResourcePool));
    pool->resources = malloc(initial_capacity * sizeof(int));
    pool->capacity = initial_capacity;
    pool->used = 0;
    sem_init(&pool->available, 0, initial_capacity);
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_resource_pool(ResourcePool *pool) {
    free(pool->resources);
    sem_destroy(&pool->available);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int acquire_resource(ResourcePool *pool) {
    int resource = -1;
    if (sem_wait(&pool->available) == 0) {
        pthread_mutex_lock(&pool->mutex);
        if (pool->used < pool->capacity) {
            resource = pool->resources[pool->used++];
        }
        pthread_mutex_unlock(&pool->mutex);
    }
    return resource;
}

void release_resource(ResourcePool *pool, int resource) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = 0;
    for (; index < pool->used; ++index) {
        if (pool->resources[index] == resource) {
            break;
        }
    }
    if (index < pool->used) {
        pool->resources[index] = pool->resources[--pool->used];
    }
    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->available);
}

void resize_resource_pool(ResourcePool *pool, size_t new_capacity) {
    if (new_capacity > pool->max_capacity) {
        return;
    }
    int *new_resources = realloc(pool->resources, new_capacity * sizeof(int));
    if (new_resources != NULL) {
        pool->resources = new_resources;
        pool->capacity = new_capacity;
        sem_t temp;
        sem_init(&temp, 0, pool->used);
        sem_destroy(&pool->available);
        sem_rename(temp, &pool->available);
    }
}

void monitor_resource_pool(ResourcePool *pool) {
    printf("Current Usage: %zu/%zu\n", pool->used, pool->capacity);
}
