        int number;
        char input[5];
        fgets(input, sizeof(input), stdin);

        if (input[0] == 'q') {
            break;
        }

        if (sscanf(input, "%d", &number) != 1) {
            printf("Invalid integer format. Please enter a valid integer.\n");
            continue;
        }

        if (number > largest) {
            largest = number;
        }
    }
