        scanf("%d", &user_id);

        if (user_id == -1) {
            break;
        }

        sem_wait(&request_semaphore);

        pthread_t tid;
        if (getchar() == 'u') {
            pthread_create(&tid, NULL, update_user_profile, &user_id);
        } else if (getchar() == 'd') {
            pthread_create(&tid, NULL, soft_delete_user, &user_id);
        }

        pthread_join(tid, NULL);
        sem_post(&request_semaphore);

        log_audit(user_id, "update");
    }

    int largest = find_largest_integer();
    printf("Largest integer found: %d\n", largest);

