NFAPI_CRC_INDICATION_PDU_T** generate_NFAPI_pdu_list(int M) {
    NFAPI_CRC_INDICATION_PDU_T **pdu_list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    if (pdu_list == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

