typedef struct TAI {
    int global_id;
    UE *ue_list;
    time_t last_update;
    struct TAI *next;
} TAI;

TAI** create_ta_list(int K) {
    TAI **ta_list = (TAI**)malloc(K * sizeof(TAI*));
    if (ta_list == NULL) {
        fprintf(stderr, "Memory allocation failed for TA list\n");
        return NULL;
    }
    for (int i = 0; i < K; i++) {
        ta_list[i] = NULL;
    }
    return ta_list;
}

void destroy_ta_list(TAI **ta_list, int K) {
    if (ta_list == NULL) {
        fprintf(stderr, "Invalid TA list pointer\n");
        return;
    }
    for (int i = 0; i < K; i++) {
        TAI *current = ta_list[i];
        while (current != NULL) {
            TAI *next = current->next;
            UE *ue = current->ue_list;
            while (ue != NULL) {
                UE *next_ue = ue->next;
                free(ue);
                ue = next_ue;
            }
            free(current);
            current = next;
        }
    }
    free(ta_list);
}

TAI* find_tai(TAI **ta_list, int global_id, int K) {
    if (ta_list == NULL || global_id < 0 || global_id >= K) {
        fprintf(stderr, "Invalid TA list pointer or global ID\n");
        return NULL;
    }
    for (int i = 0; i < K; i++) {
        TAI *current = ta_list[i];
        while (current != NULL) {
            if (current->global_id == global_id) {
                return current;
            }
            current = current->next;
        }
    }
    return NULL;
}

int add_ue_to_tai(TAI **ta_list, int global_id, int ue_id, int K) {
    TAI *tai = find_tai(ta_list, global_id, K);
    if (tai == NULL) {
        fprintf(stderr, "TAI not found for given global ID\n");
        return -1;
    }
    UE *new_ue = (UE*)malloc(sizeof(UE));
    if (new_ue == NULL) {
        fprintf(stderr, "Memory allocation failed for new UE\n");
        return -1;
    }
    new_ue->ue_id = ue_id;
    new_ue->next = tai->ue_list;
    tai->ue_list = new_ue;
    tai->last_update = time(NULL);
    return 0;
}

int remove_ue_from_tai(TAI **ta_list, int global_id, int ue_id, int K) {
    TAI *tai = find_tai(ta_list, global_id, K);
    if (tai == NULL) {
        fprintf(stderr, "TAI not found for given global ID\n");
        return -1;
    }
    UE *current = tai->ue_list;
    UE *prev = NULL;
    while (current != NULL) {
        if (current->ue_id == ue_id) {
            if (prev == NULL) {
                tai->ue_list = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            tai->last_update = time(NULL);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    fprintf(stderr, "UE not found in TAI\n");
    return -1;
}
