['```php
<?php

function authenticateUser($clientId, $clientSecret, $authorizationCode) {
    session_start();

    // Define constants for configuration
    define('OAUTH_PROVIDER_URL', 'https://oauth.provider.com/token');
    define('USER_PROFILE_URL', 'https://oauth.provider.com/userinfo');
    define('ACCESS_TOKEN_EXPIRATION_GRACE_PERIOD', 60); // in seconds
    define('USER_PROFILE_CACHE_DURATION', 3600); // in seconds

    // Function to log messages
    function logMessage($message) {
        error_log($message);
    }

    // Check if the access token is already stored and valid
    $userId = $_SESSION['user_id'] ?? null;
    $accessToken = $_SESSION['access_token'] ?? null;
    $tokenExpirationTime = $_SESSION['token_expiration_time'] ?? 0;

    if ($accessToken && time() + ACCESS_TOKEN_EXPIRATION_GRACE_PERIOD < $tokenExpirationTime) {
        logMessage("Using cached access token for user $userId.");
        return $accessToken;
    }

    // Exchange authorization code for access token
    try {
        $ch = curl_init(OAUTH_PROVIDER_URL);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, [
            'grant_type' => 'authorization_code',
            'code' => $authorizationCode,
            'client_id' => $clientId,
            'client_secret' => $clientSecret
        ]);
        $response = curl_exec($ch);
        if ($response === false) {
            throw new Exception('cURL Error: ' . curl_error($ch));
        }
        curl_close($ch);

        $responseData = json_decode($response, true);
        if (!isset($responseData['access_token'])) {
            throw new Exception('Failed to obtain access token.');
        }

        $accessToken = $responseData['access_token'];
        $tokenExpirationTime = time() + $responseData['expires_in'];

    } catch (Exception $e) {
        logMessage("Authentication failed: " . $e->getMessage());
        return null;
    }

    // Invalidate previous session tokens for the user
    if ($userId && isset($_SESSION['previous_access_tokens'][$userId])) {
        foreach ($_SESSION['previous_access_tokens'][$userId] as $oldToken) {
            try {
                $ch = curl_init(OAUTH_PROVIDER_URL);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_POST, true);
                curl_setopt($ch, CURLOPT_POSTFIELDS, [
                    'grant_type' => 'revoke_token',
                    'token' => $oldToken
                ]);
                curl_exec($ch);
                curl_close($ch);
            } catch (Exception $e) {
                logMessage("Failed to revoke token: " . $e->getMessage());
            }
        }
    }

    // Store the new access token and user ID in session
    $_SESSION['access_token'] = $accessToken;
    $_SESSION['token_expiration_time'] = $tokenExpirationTime;
    if (!isset($_SESSION['previous_access_tokens'][$userId])) {
        $_SESSION['previous_access_tokens'][$userId] = [];
    }
    array_push($_SESSION['previous_access_tokens'][$userId], $accessToken);

    // Retrieve and cache user profile information
    try {
        $ch = curl_init(USER_PROFILE_URL);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            'Authorization: Bearer ' . $accessToken
        ]);
        $response = curl_exec($ch);
        if ($response === false) {
            throw new Exception('cURL Error: ' . curl_error($ch));
        }
        curl_close($ch);

        $userProfile = json_decode($response, true);
        $_SESSION['user_profile'] = $userProfile;

    } catch (Exception $e) {
        logMessage("Failed to retrieve user profile: " . $e->getMessage());
        return null;
    }

    // Cache the user profile
    setcookie('user_profile_cache', json_encode($userProfile), time() + USER_PROFILE_CACHE_DURATION, '/');

    return $accessToken;
}
?>
