#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* append_and_replace(const char* input, size_t limit, char* buffer, const char* dictionary[], const char* env_settings[]) {
    if (input == NULL || buffer == NULL || dictionary == NULL || env_settings == NULL) {
        return NULL;
    }

    size_t len = strlen(input);
    if (len >= limit - 1) {
        return NULL;
    }

    snprintf(buffer, limit, "%s/", input);

    for (int i = 0; i < 26; i++) { // Assuming dictionary has A-Z keys
        char key[3] = { 'A' + i, '=', '\0' };
        const char* value = dictionary[i];
        if (value == NULL) {
            return NULL;
        }
        snprintf(buffer, limit, "%s%s", buffer, value);
    }

    for (int i = 0; env_settings[i] != NULL; i++) {
        char* env_pair = strchr(env_settings[i], '=');
        if (env_pair == NULL) {
            return NULL;
        }
        *env_pair = '\0';
        setenv(env_settings[i], env_pair + 1, 1);
    }

    return buffer;
}
