typedef struct {
    char global_id[64];
    // Assume a linked list for UEs
    struct UE* ues;
    time_t last_update;
} TAI;

typedef struct UE {
    int ue_id;
    struct UE* next;
} UE;

typedef struct {
    TAI** tai_list;
    size_t max_k;
} TAIManager;

TAIManager* create TaiManager(size_t k) {
    TAIManager* manager = (TAIManager*)malloc(sizeof(TAIManager));
    if (!manager) return NULL;
    manager->tai_list = (TAI**)calloc(k, sizeof(TAI*));
    if (!manager->tai_list) {
        free(manager);
        return NULL;
    }
    manager->max_k = k;
    return manager;
}

void destroyTaiManager(TAIManager* manager) {
    for (size_t i = 0; i < manager->max_k; ++i) {
        TAI* tai = manager->tai_list[i];
        while (tai) {
            UE* ue = tai->ues;
            while (ue) {
                UE* next = ue->next;
                free(ue);
                ue = next;
            }
            TAI* next_tai = tai->next;
            free(tai);
            tai = next_tai;
        }
    }
    free(manager->tai_list);
    free(manager);
}

TAI* findTai(TAIManager* manager, const char* global_id) {
    for (size_t i = 0; i < manager->max_k; ++i) {
        TAI* tai = manager->tai_list[i];
        while (tai) {
            if (strcmp(tai->global_id, global_id) == 0) return tai;
            tai = tai->next;
        }
    }
    return NULL;
}

int addTai(TAIManager* manager, const char* global_id) {
    TAI* tai = findTai(manager, global_id);
    if (tai) return -1; // Tai already exists
    tai = (TAI*)malloc(sizeof(TAI));
    if (!tai) return -2; // Memory allocation failed
    strcpy(tai->global_id, global_id);
    tai->ues = NULL;
    tai->last_update = time(NULL);
    tai->next = manager->tai_list[hash(global_id)];
    manager->tai_list[hash(global_id)] = tai;
    return 0;
}

int removeTai(TAIManager* manager, const char* global_id) {
    TAI* tai = findTai(manager, global_id);
    if (!tai) return -1; // Tai not found
    TAI** prev = &(manager->tai_list[hash(global_id)]);
    while (*prev != tai) {
        prev = &((*prev)->next);
    }
    *prev = tai->next;
    free(tai);
    return 0;
}

int addUe(TAIManager* manager, const char* global_id, int ue_id) {
    TAI* tai = findTai(manager, global_id);
    if (!tai) return -1; // Tai not found
    UE* ue = (UE*)malloc(sizeof(UE));
    if (!ue) return -2; // Memory allocation failed
    ue->ue_id = ue_id;
    ue->next = tai->ues;
    tai->ues = ue;
    tai->last_update = time(NULL);
    return 0;
}

int removeUe(TAIManager* manager, const char* global_id, int ue_id) {
    TAI* tai = findTai(manager, global_id);
    if (!tai) return -1; // Tai not found
    UE** prev = &(tai->ues);
    while (*prev) {
        UE* ue = *prev;
        if (ue->ue_id == ue_id) {
            *prev = ue->next;
            free(ue);
            tai->last_update = time(NULL);
            return 0;
        }
        prev = &((*prev)->next);
    }
    return -2; // Ue not found
}

