NFAPI_CRC_INDICATION_PDU_T* establishNfadConnection(int maxPduSize, int useCrc) {
    if (maxPduSize > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: Exceeding maximum list size\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(maxPduSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < maxPduSize; i++) {
        // Initialize RX_UE_INFORMATION_TAG
        pduList[i].ueInfo = generateRxUeInformationTag();
        // Initialize RNTI
        pduList[i].RNTI = generateRandomRnti();

        if (useCrc) {
            // Initialize CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
            pduList[i].crcIndication.crcFlag = generateRandomCrcFlag();
        }
    }

    return pduList;
}

unsigned char* calculateMd5Hash(const char* inputString, size_t length) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, length, (unsigned char*)&hash);

    // Allocate memory for the resulting hash string
    char* result = (char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!result) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    // Convert the hash to a hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(result + (i * 2), "%02x", hash[i]);
    }
    result[MD5_DIGEST_LENGTH * 2] = '\0';

    return result;
}

void* resizeList(void** list, size_t oldSize, size_t newSize) {
    void* newList = realloc(*list, newSize);
    if (!newList) {
        fprintf(stderr, "Error: Memory reallocation failed\n");
        free(*list);
        *list = NULL;
        return NULL;
    }
    *list = newList;
    return newList;
}

void logOperation(char* operation, int success) {
    if (success) {
        printf("Success: %s\n", operation);
    } else {
        fprintf(stderr, "Error: Failed to perform %s\n", operation);
    }
}
