#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned long globalId;
    int* registeredUEs;
    size_t ueCount;
    time_t lastUpdate;
    int priority;
} TAI;

typedef struct {
    TAI** taiList;
    size_t capacity;
    size_t size;
    size_t K;
} TAIManager;

TAIManager* createTAIManager(size_t K) {
    TAIManager* manager = (TAIManager*)malloc(sizeof(TAIManager));
    if (!manager) return NULL;

    manager->capacity = 100; // Initial capacity
    manager->size = 0;
    manager->K = K;
    manager->taiList = (TAI**)calloc(manager->capacity, sizeof(TAI*));
    if (!manager->taiList) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroyTAIManager(TAIManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->taiList[i]->registeredUEs);
        free(manager->taiList[i]);
    }
    free(manager->taiList);
    free(manager);
}

TAI* findTAI(TAIManager* manager, unsigned long globalId) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->taiList[i]->globalId == globalId) {
            return manager->taiList[i];
        }
    }
    return NULL;
}

void addTAI(TAIManager* manager, unsigned long globalId, int* registeredUEs, size_t ueCount, time_t lastUpdate, int priority) {
    if (manager->size >= manager->capacity) {
        TAI** newTaiList = (TAI**)realloc(manager->taiList, manager->capacity * 2 * sizeof(TAI*));
        if (!newTaiList) return;

        manager->taiList = newTaiList;
        manager->capacity *= 2;
    }

    TAI* tai = (TAI*)malloc(sizeof(TAI));
    if (!tai) return;

    tai->globalId = globalId;
    tai->registeredUEs = (int*)malloc(ueCount * sizeof(int));
    if (!tai->registeredUEs) {
        free(tai);
        return;
    }

    memcpy(tai->registeredUEs, registeredUEs, ueCount * sizeof(int));
    tai->ueCount = ueCount;
    tai->lastUpdate = lastUpdate;
    tai->priority = priority;

    manager->taiList[manager->size++] = tai;
}

void removeTAI(TAIManager* manager, unsigned long globalId) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->taiList[i]->globalId == globalId) {
            free(manager->taiList[i]->registeredUEs);
            free(manager->taiList[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->taiList[j] = manager->taiList[j + 1];
            }
            --manager->size;
            break;
        }
    }
}

// Implement the remaining functions as per the requirements
