            for (size_t j = 0; j < tais[i].ue_count; j++) {
                free(tais[i].ues[j]);
            }
            free(tais[i].ues);
        }
    }
    free(tais);
}

TAI* addTai(TAI* tais, int K, int global_id) {
    for (int i = 0; i < K; i++) {
        if (!tais[i].global_id) {
            tais[i].global_id = global_id;
            tais[i].last_update = time(NULL);
            return &tais[i];
        }
    }
    // Handle the case when no TAI slot is available
    return NULL;
}

void removeTai(TAI* tais, int K, int global_id) {
    for (int i = 0; i < K; i++) {
        if (tais[i].global_id == global_id) {
            tais[i].global_id = 0;
            tais[i].ue_count = 0;
            if (tais[i].ues) {
                free(tais[i].ues);
                tais[i].ues = NULL;
            }
            break;
        }
    }
}

void updateTai(TAI* tai, char** ues, size_t ue_count) {
    tai->last_update = time(NULL);
    tai->ue_count = ue_count;
    tai->ues = (char**)realloc(tai->ues, ue_count * sizeof(char*));
    for (size_t i = 0; i < ue_count; i++) {
        tai->ues[i] = strdup(ues[i]);
    }
}
