TAIList* create_tailist(size_t k) {
    TAIList* list = malloc(sizeof(TAIList));
    if (list == NULL) return NULL;
    list->taies = malloc(k * sizeof(TAI*));
    if (list->taies == NULL) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = k;
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = fopen("tai_log.txt", "w");
    if (list->log_file == NULL) {
        free(list->taies);
        free(list);
        return NULL;
    }
    return list;
}

void destroy_tailist(TAIList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->taies[i]);
    }
    fclose(list->log_file);
    pthread_mutex_unlock(&list->lock);
    free(list->taies);
    free(list);
}

TAI* get_tai(TAIList* list, int global_id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->taies[i]->global_id == global_id) {
            return list->taies[i];
        }
    }
    return NULL;
}

int add_tai(TAIList* list, TAI* tai) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->taies[list->count++] = tai;
    time_t now = time(NULL);
    fprintf(list->log_file, "Added TAI with ID %d at %s\n", tai->global_id, ctime(&now));
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_tai(TAIList* list, int global_id, TAI* new_tai) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->taies[i]->global_id == global_id) {
            free(list->taies[i]);
            list->taies[i] = new_tai;
            time_t now = time(NULL);
            fprintf(list->log_file, "Updated TAI with ID %d at %s\n", new_tai->global_id, ctime(&now));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // TAI not found
}

int remove_tai(TAIList* list, int global_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->taies[i]->global_id == global_id) {
            free(list->taies[i]);
            for (size_t j = i; j < list->count - 1; ++j) {
                list->taies[j] = list->taies[j + 1];
            }
            list->count--;
            time_t now = time(NULL);
            fprintf(list->log_file, "Removed TAI with ID %d at %s\n", global_id, ctime(&now));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // TAI not found
}

int export_tailist(TAIList* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) return -1;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        fprintf(file, "TAI ID: %d\n", list->taies[i]->global_id);
        // Write other TAI fields
    }
    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}
