class NFVManager {
public:
    NFVManager(size_t M);
    ~NFVManager();
    void addNFV(const std::string& id, const std::vector<std::string>& vnfList, double resourceUtilization, const std::string& status);
    bool updateNFV(const std::string& id, const std::vector<std::string>& vnfList, double resourceUtilization, const std::string& status);
    bool deleteNFV(const std::string& id);
    void reset();
    void exportState(const std::string& filename);

private:
    size_t M;
    std::unordered_map<std::string, NFVInstance> nfvMap;
    std::mutex mutex;
    std::ofstream logFile;

    struct NFVInstance {
        std::vector<std::string> vnfList;
        double resourceUtilization;
        std::string status;
        time_t lastHealthCheck;
    };

    void logChange(const std::string& id, const std::string& action);
};

NFVManager::NFVManager(size_t M) : M(M), logFile("nfv_log.txt") {
    if (!logFile.is_open()) {
        throw std::runtime_error("Failed to open log file.");
    }
}

NFVManager::~NFVManager() {
    logFile.close();
}

void NFVManager::addNFV(const std::string& id, const std::vector<std::string>& vnfList, double resourceUtilization, const std::string& status) {
    std::lock_guard<std::mutex> lock(mutex);
    if (nfvMap.size() >= M) {
        throw std::runtime_error("Max NFV instances reached.");
    }
    nfvMap[id] = {vnfList, resourceUtilization, status, time(nullptr)};
    logChange(id, "add");
}

bool NFVManager::updateNFV(const std::string& id, const std::vector<std::string>& vnfList, double resourceUtilization, const std::string& status) {
    std::lock_guard<std::mutex> lock(mutex);
    if (nfvMap.find(id) == nfvMap.end()) {
        return false;
    }
    nfvMap[id] = {vnfList, resourceUtilization, status, time(nullptr)};
    logChange(id, "update");
    return true;
}

bool NFVManager::deleteNFV(const std::string& id) {
    std::lock_guard<std::mutex> lock(mutex);
    if (nfvMap.find(id) == nfvMap.end()) {
        return false;
    }
    nfvMap.erase(id);
    logChange(id, "delete");
    return true;
}

void NFVManager::reset() {
    std::lock_guard<std::mutex> lock(mutex);
    nfvMap.clear();
    logFile.close();
    logFile.open("nfv_log.txt", std::ios::out | std::ios::trunc);
}

