typedef struct {
    int timestamp;
    char event_type[50];
    int identifier;
} NetworkEvent;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicList {
    NetworkEvent* events;
    int size;
    int capacity;
    int rolling_checksum;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list(int initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->events = (NetworkEvent*)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!list->events) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    list->rolling_checksum = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    if (list) {
        free(list->events);
        free(list);
    }
}

int add_event(DynamicList* list, NetworkEvent event) {
    if (!list || list->size >= list->capacity) return -1;
    pthread_mutex_lock(&list->lock);
    list->events[list->size++] = event;
    update_rolling_checksum(list);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_old_events(DynamicList* list, int threshold) {
    if (!list || !threshold) return;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ) {
        if (list->events[i].timestamp + threshold < time(NULL)) {
            memmove(&list->events[i], &list->events[i+1], (list->size - i - 1) * sizeof(NetworkEvent));
            list->size--;
            update_rolling_checksum(list);
        } else break;
    }
    pthread_mutex_unlock(&list->lock);
}

int get_events_in_window(DynamicList* list, int start_time, int end_time) {
    if (!list || !start_time || !end_time) return -1;
    int count = 0;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->events[i].timestamp >= start_time && list->events[i].timestamp <= end_time) count++;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void update_rolling_checksum(DynamicList* list) {
    if (!list) return;
    int checksum = 0;
    for (int i = 0; i < list->size; i++) {
        checksum += list->events[i].timestamp + hash_string(list->events[i].event_type) + list->events[i].identifier;
    }
    pthread_mutex_lock(&list->lock);
    list->rolling_checksum = checksum;
    pthread_mutex_unlock(&list->lock);
}

int hash_string(const char* str) {
    int hash = 0;
    for (int i = 0; str[i]; i++) {
        hash = hash * 31 + str[i];
    }
    return hash;
}

void generate_crc_indications(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* output, int n) {
    if (!list || !output || n <= 0) return;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < n && i < list->size; i++) {
        output[i].RX_UE_INFORMATION_TAG = rand();
        output[i].RNTI = rand();
        output[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&list->lock);
}

void log_event(DynamicList* list, const char* event) {
    if (!list || !event) return;
    FILE* file = fopen("events.log", "a");
    if (file) {
        fprintf(file, "%s\n", event);
        fclose(file);
    }
}

