// Define a structure for the file reader
typedef struct {
    FILE* file;
    char* buffer;
    size_t buffer_size;
    pthread_mutex_t mutex;
} FileReader;

// Initialize the file reader
FileReader* file_reader_init(const char* filename, size_t buffer_size) {
    FileReader* reader = (FileReader*)malloc(sizeof(FileReader));
    reader->file = fopen(filename, "r");
    if (!reader->file) return NULL;

    reader->buffer = (char*)malloc(buffer_size);
    if (!reader->buffer) {
        fclose(reader->file);
        free(reader);
        return NULL;
    }

    reader->buffer_size = buffer_size;
    pthread_mutex_init(&reader->mutex, NULL);
    return reader;
}

// Function to read a line from the file
int file_reader_read_line(FileReader* reader, char** line, size_t* length) {
    pthread_mutex_lock(&reader->mutex);
    *length = fread(reader->buffer, 1, reader->buffer_size - 1, reader->file);
    if (*length > 0) {
        reader->buffer[*length] = '\0';
        *line = reader->buffer;
        pthread_mutex_unlock(&reader->mutex);
        return 0; // Success
    }
    pthread_mutex_unlock(&reader->mutex);
    fclose(reader->file);
    free(reader->buffer);
    free(reader);
    return -1; // End of file or error
}

// Function to transform a line using the given function
void transform_line(const char* line, void (*transform)(const char*)) {
    if (line) transform(line);
}

// Main function to demonstrate usage
int main() {
    FileReader* reader = file_reader_init("largefile.txt", 4096);
    if (!reader) return -1;

    char* line;
    size_t length;
    while (file_reader_read_line(reader, &line, &length) == 0) {
        // Apply transformation function to each line
        transform_line(line, my_transform_function);
    }

    file_reader_init(NULL, 0); // Clean up and exit
    return 0;
}
