        CRC_INDICATION_REL8_TAG crcTag;
        crcTag.CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
    }
}

void modifyConfigFile(char* filePath, char* configContent, int configLength, char** replacements, int replacementCount) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file for reading: %s\n", filePath);
        exit(EXIT_FAILURE);
    }

    // Check integrity of the original configuration file
    fseek(file, 0, SEEK_END);
    int fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize != configLength) {
        fprintf(stderr, "Integrity check failed: File size does not match.\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Write modified configuration to a new file
    char* tempFilePath = "temp_config.txt";
    FILE* tempFile = fopen(tempFilePath, "w");
    if (!tempFile) {
        fprintf(stderr, "Failed to open temporary configuration file for writing: %s\n", tempFilePath);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        for (int i = 0; i < replacementCount; i++) {
            if (strstr(buffer, replacements[i])) {
                int len = strlen(replacements[i]);
                char* value = strchr(buffer, '=') + 1;
                int valLen = strlen(value);
                while (value[valLen - 1] == '\n' || value[valLen - 1] == ' ') {
                    valLen--;
                }
                fprintf(tempFile, "%s=%s\n", replacements[i], value);
            } else {
                fputs(buffer, tempFile);
            }
        }
    }

    fclose(file);
    fclose(tempFile);

    // Rename the temporary file to the original file name
    if (rename(tempFilePath, filePath) != 0) {
        fprintf(stderr, "Failed to rename temporary configuration file: %s\n", tempFilePath);
        exit(EXIT_FAILURE);
    }
}

void logModification(char* auditLogPath, char* message) {
    FILE* auditFile = fopen(auditLogPath, "a");
    if (!auditFile) {
        fprintf(stderr, "Failed to open audit log for writing: %s\n", auditLogPath);
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    fprintf(auditFile, "[%s] - %s\n", ctime(&now), message);

    fclose(auditFile);
}

void encryptPassword(char* password, char* key) {
    for (int i = 0; password[i]; i++) {
        password[i] ^= key[i % strlen(key)];
    }
}

void checkComplexity(char* password, int minLength, char* requiredChars) {
    if (strlen(password) < minLength) {
        fprintf(stderr, "Password does not meet length requirement.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; requiredChars[i]; i++) {
        if (strchr(password, requiredChars[i]) == NULL) {
            fprintf(stderr, "Password does not contain the required character: %c\n", requiredChars[i]);
            exit(EXIT_FAILURE);
        }
    }
}

