#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <openssl/md5.h>

#define MAX_EVENTS 1000
#define INITIAL_CAPACITY 10

typedef enum {
    EVENT_TYPE_1,
    EVENT_TYPE_2,
    EVENT_TYPE_3
} EventType;

typedef struct {
    time_t timestamp;
    EventType type;
    int id;
} NetworkEvent;

typedef struct {
    int rnti;
    int crcFlag;
} CRCIndicationPDU;

typedef struct {
    NetworkEvent* events;
    CRCIndicationPDU* napi;
    int size;
    int capacity;
    int crcFailures[1024]; // Assuming RNTI range is 0-1023
    unsigned char rollingChecksum[MD5_DIGEST_LENGTH];
} EventManager;

EventManager* createEventManager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;

    manager->events = (NetworkEvent*)calloc(INITIAL_CAPACITY, sizeof(NetworkEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->napi = (CRCIndicationPDU*)calloc(INITIAL_CAPACITY, sizeof(CRCIndicationPDU));
    if (!manager->napi) {
        free(manager->events);
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    memset(manager->crcFailures, 0, sizeof(int) * 1024);
    memset(manager->rollingChecksum, 0, MD5_DIGEST_LENGTH);

    srand(time(NULL));
    return manager;
}

void destroyEventManager(EventManager* manager) {
    free(manager->events);
    free(manager->napi);
    free(manager);
}

int addEvent(EventManager* manager, NetworkEvent event) {
    if (manager->size >= MAX_EVENTS) return -1; // Prevent memory overflow
    if (manager->size == manager->capacity) {
        manager->events = realloc(manager->events, sizeof(NetworkEvent) * (manager->capacity * 2));
        manager->napi = realloc(manager->napi, sizeof(CRCIndicationPDU) * (manager->capacity * 2));
        if (!manager->events || !manager->napi) return -1; // Handle memory allocation failure
        manager->capacity *= 2;
    }

    manager->events[manager->size] = event;
    manager->size++;

    return 0;
}

int removeOldEvents(EventManager* manager, time_t threshold) {
    int count = 0;
    for (int i = 0; i < manager->size; i++) {
        if (manager->events[i].timestamp < threshold) {
            count++;
        } else {
            break; // Events are sorted by timestamp
        }
    }

    memmove(manager->events, &manager->events[count], sizeof(NetworkEvent) * (manager->size - count));
    memmove(manager->napi, &manager->napi[count], sizeof(CRCIndicationPDU) * (manager->size - count));

    manager->size -= count;
    return count;
}

int getEventsInWindow(EventManager* manager, time_t start, time_t end) {
    int count = 0;
    for (int i = 0; i < manager->size; i++) {
        if (manager->events[i].timestamp >= start && manager->events[i].timestamp <= end) {
            count++;
        } else if (manager->events[i].timestamp > end) {
            break; // Events are sorted by timestamp
        }
    }
    return count;
}

int generateNFAPI(EventManager* manager, int N) {
    for (int i = 0; i < N; i++) {
        CRCIndicationPDU pdu;
        pdu.rnti = rand() % 1024;
        if (rand() % 2 == 0) {
            pdu.crcFlag = 1; // Simulate random failure
            manager->crcFailures[pdu.rnti]++;
        } else {
            pdu.crcFlag = 0;
        }
        manager->napi[i] = pdu;
    }
    return 0;
}

void calculateRollingChecksum(EventManager* manager) {
    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5_Init(&md5);
    for (int i = 0; i < manager->size; i++) {
        MD5_Update(&md5, &manager->events[i], sizeof(NetworkEvent));
    }
    MD5_Final(digest, &md5);

    memcpy(manager->rollingChecksum, digest, MD5_DIGEST_LENGTH);
}

unsigned char* md5String(const char* str) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str, strlen(str));
    MD5_Final(hash, &md5);

    unsigned char* result = (unsigned char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!result) return NULL;

    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(result + i * 2, "%02x", hash[i]);

    return result;
}
