#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>

#define MAX_LINE_LENGTH 1024
#define DEFAULT_DELIMITER " "

int line_count = 0;
int word_count = 0;
FILE *output_file = NULL;

void handle_help() {
    fprintf(stderr, "Usage: program_name [options] input_files...\n");
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  --help      display this help message\n");
    fprintf(stderr, "  -cs         enable case-sensitive mode\n");
    fprintf(stderr, "  -o output_file   specify an output file for storing results\n");
    fprintf(stderr, "  -d delimiter   specify a custom delimiter for splitting lines\n");
}

void process_file(const char *filename, const char *delimiter) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Count lines
        line_count++;

        // Count words
        char *token = strtok(line, delimiter);
        while (token) {
            // Check if the token is a valid word
            int all_alphabetic = 1;
            for (int i = 0; i < strlen(token); i++) {
                if (!isalpha(token[i])) {
                    all_alphabetic = 0;
                    break;
                }
            }
            if (all_alphabetic) {
                word_count++;
            }
            token = strtok(NULL, delimiter);
        }

        // Print progress indicator
        printf("Processed %d lines\r", line_count);
    }

    fclose(file);
}

void signal_handler(int signum) {
    static int paused = 0;
    if (signum == SIGUSR1) {
        paused = !paused;
        if (paused) {
            printf("\nPaused. Press Ctrl+C to exit.\n");
        } else {
            printf("\nResuming...\n");
        }
    }
}

int main(int argc, char *argv[]) {
    int opt;
    const char *delimiter = DEFAULT_DELIMITER;
    int case_sensitive = 0;

    while ((opt = getopt(argc, argv, "cs:o:d:")) != -1) {
        switch (opt) {
            case 'c':
                case_sensitive = 1;
                break;
            case 'o':
                output_file = fopen(optarg, "a");
                if (!output_file) {
                    perror("Error opening output file");
                    return 1;
                }
                break;
            case 'd':
                delimiter = optarg;
                break;
            default:
                handle_help();
                return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "No input files specified.\n");
        handle_help();
        return 1;
    }

    for (int i = optind; i < argc; i++) {
        const char *filename = argv[i];
        struct stat file_stat;
        if (stat(filename, &file_stat) == -1 || !S_ISREG(file_stat.st_mode)) {
            fprintf(stderr, "Invalid file: %s\n", filename);
            continue;
        }
        if (strstr(filename, ".txt") == NULL) {
            printf("Skipping non-text file: %s\n", filename);
            continue;
        }

        process_file(filename, delimiter);

        if (output_file) {
            fprintf(output_file, "File: %s, Lines: %d, Words: %d\n", filename, line_count, word_count);
        }
    }

    printf("\nTotal lines processed: %d\n", line_count);
    printf("Total words counted: %d\n", word_count);

    if (output_file) {
        fclose(output_file);
    }

    signal(SIGUSR1, signal_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}
