using System;
using System.Xml.XPath;

public class XmlParser
{
    private const int MAX_INPUT_SIZE = 1024 * 1024; // 1 MB

    public static XPathNavigator ParseXmlForElement(string xml, string elementName)
    {
        if (string.IsNullOrEmpty(xml) || string.IsNullOrEmpty(elementName))
        {
            throw new ArgumentException("Input parameters cannot be null or empty.");
        }

        if (xml.Length > MAX_INPUT_SIZE)
        {
            throw new InvalidOperationException("XML input exceeds maximum allowed size.");
        }

        try
        {
            using (XPathDocument document = new XPathDocument(new System.IO.StringReader(xml)))
            {
                XPathNavigator navigator = document.CreateNavigator();
                XPathNodeIterator nodes = navigator.Select($"//{elementName}");

                if (nodes.Count == 0)
                {
                    throw new InvalidOperationException($"Element '{elementName}' not found in XML.");
                }
                else if (nodes.Count > 1)
                {
                    throw new InvalidOperationException($"Multiple elements with name '{elementName}' found in XML.");
                }

                return nodes.Current;
            }
        }
        catch (XmlException ex) when (ex.Message.Contains("OutOfMemory"))
        {
            throw new OutOfMemoryException("Failed to allocate memory for XML parsing.", ex);
        }
        catch (XPathException ex)
        {
            throw new XPathException("Invalid XPath expression encountered.", ex);
        }
    }
}
