} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
    size_t capacity;
} NFAPICRCList;

void establishNfadConnection(NFAPICRCList *list, size_t max_size) {
    if (list->size >= max_size) {
        fprintf(stderr, "Error: Maximum list size exceeded.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    // Generate valid RX_UE_INFORMATION_TAG
    new_pdu.ue_info_tag = generateRandomRX_UE_INFORMATION_TAG();
    // Set RNTI
    new_pdu.rnti = generateRandomRNTI();
    // Set CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    new_pdu.crc_indication.crcflag = (rand() % 2) == 0;

    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->list = realloc(list->list, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list->list == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
    }

    list->list[list->size++] = new_pdu;

    // Log the operation
    printf("Successfully added new CRC indication with RNTI: %d\n", new_pdu.rnti);
}

unsigned char* generateMD5(const char *input) {
    unsigned char hash[16];
    MD5_CTX mdContext;
    int bytes;
    char *output = (char*)malloc(33); // 32 characters for hex + 1 for null terminator

    if (!output) return NULL;

    MD5_Init(&mdContext);
    MD5_Update(&mdContext, input, strlen(input));
    MD5_Final(hash, &mdContext);

    for(bytes = 0; bytes < 16; ++bytes)
        sprintf(output + (bytes * 2), "%02x", hash[bytes]);

    return output;
}

void logError(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

// Function to handle concurrent access
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

void addElementToNfadConnection(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&listMutex);
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->list = realloc(list->list, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list->list == NULL) {
            logError("Memory allocation failed.");
            pthread_mutex_unlock(&listMutex);
            return;
        }
    }

