#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 1024
#define CRC32_POLYNOMIAL 0xEDB88320

typedef struct Frame {
    unsigned int timestamp;
    size_t length;
    char payload[0];
} Frame;

typedef struct QueueNode {
    Frame *frame;
    struct QueueNode *next;
} QueueNode;

typedef struct FrameQueue {
    QueueNode *front, *rear;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    int enable_crc;
} FrameQueue;

unsigned int calculateCRC32(const char *data, size_t length) {
    unsigned int crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
        crc ^= (unsigned char)data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 1) {
                crc = (crc >> 1) ^ CRC32_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

void enqueue(FrameQueue *queue, Frame *frame) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) {
        QueueNode *new_node = malloc(sizeof(QueueNode));
        new_node->frame = frame;
        new_node->next = NULL;

        if (queue->rear == NULL) {
            queue->front = queue->rear = new_node;
        } else {
            queue->rear->next = new_node;
            queue->rear = new_node;
        }
        queue->size++;
    } else {
        fprintf(stderr, "Queue overflow!\n");
    }
    pthread_mutex_unlock(&queue->lock);
}

Frame *dequeue(FrameQueue *queue) {
    Frame *frame = NULL;
    pthread_mutex_lock(&queue->lock);
    if (queue->front != NULL) {
        QueueNode *temp = queue->front;
        frame = temp->frame;
        queue->front = temp->next;

        if (queue->front == NULL) {
            queue->rear = NULL;
        }
        free(temp);
        queue->size--;
    }
    pthread_mutex_unlock(&queue->lock);
    return frame;
}

void initFrameQueue(FrameQueue *queue, size_t capacity, int enable_crc) {
    queue->front = queue->rear = NULL;
    queue->size = 0;
    queue->capacity = capacity;
    queue->enable_crc = enable_crc;
    pthread_mutex_init(&queue->lock, NULL);
}

void destroyFrameQueue(FrameQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    QueueNode *current = queue->front;
    while (current != NULL) {
        QueueNode *temp = current;
        free(current->frame);
        free(temp);
        current = temp->next;
    }
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
}

void processFrameQueue(FrameQueue *queue) {
    Frame *frame;
    while ((frame = dequeue(queue)) != NULL) {
        if (queue->enable_crc) {
            unsigned int expected_crc = calculateCRC32(frame->payload, frame->length);
            // Perform CRC check and handle errors
        }
        // Process the frame payload
        free(frame); // Free the frame after processing
    }
}
