char* httpRequestWithCaching(const char *url, const char *method, const char *body) {
    pthread_mutex_lock(&cache_lock);

    // Check if the response is in the cache
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(cache[i].url, url) == 0 && time(NULL) < cache[i].expiry) {
            pthread_mutex_unlock(&cache_lock);
            return strdup(cache[i].response);
        }
    }

    // If not in cache or expired, make the HTTP request
    char *response = NULL;
    if (strcmp(method, "GET") == 0) {
        // Make GET request and store response
        // ...
    } else if (strcmp(method, "POST") == 0) {
        // Make POST request with body and store response
        // ...
    }

    if (response != NULL) {
        // Cache the new response
        if (cache_count < MAX_CACHE_SIZE) {
            strcpy(cache[cache_count].url, url);
            cache[cache_count].expiry = time(NULL) + 3600; // Cache for 1 hour
            cache[cache_count].response = strdup(response);
            ++cache_count;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return response;
}

// Example usage
