int validate_cache_entry(const char *path) {
    struct stat file_stat;
    if (stat(path, &file_stat) != 0) {
        log_event("Cache entry validation failed: file not found");
        return -1;
    }
    if (file_stat.st_mtime > cache->modification_time) {
        log_event("Cache entry is outdated");
        return -1;
    }
    return 0;
}

int read_file_from_cache(const char *path, char **data, int *size) {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].path, path) == 0 && validate_cache_entry(path) == 0) {
            *data = strdup(cache[i].data);
            *size = strlen(cache[i].data);
            pthread_mutex_unlock(&cache_mutex);
            log_event("File read from cache");
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return -1; // Cache miss
}

int write_file_to_cache(const char *path, const char *data) {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].path, path) == 0) {
            strcpy(cache[i].data, data);
            cache[i].modification_time = time(NULL);
            log_event("File updated in cache");
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    if (cache_count >= CACHE_SIZE) {
        log_event("Cache is full, no room for new entries");
        pthread_mutex_unlock(&cache_mutex);
        return -1;
    }
    strcpy(cache[cache_count].path, path);
    strcpy(cache[cache_count].data, data);
    cache[cache_count].modification_time = time(NULL);
    cache_count++;
    log_event("File added to cache");
    pthread_mutex_unlock(&cache_mutex);
    return 0;
}

