pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t pool_not_empty = PTHREAD_COND_INITIALIZER;

void* networkResourceManager(void* arg) {
    int client_id = *(int*)arg;
    pthread_mutex_lock(&pool_lock);
    while (connection_count >= MAX_CLIENTS) {
        pthread_cond_wait(&pool_not_full, &pool_lock);
    }
    if (connection_count < MAX_CLIENTS) {
        connections[client_id].client_id = client_id;
        connection_count++;
        pthread_cond_signal(&pool_not_empty);
    }
    pthread_mutex_unlock(&pool_lock);

    // Simulate data transfer
    printf("Client %d transferring data...\n", client_id);
    sleep(1); // Simulating data processing time

    pthread_mutex_lock(&pool_lock);
    connections[client_id].client_id = -1;
    connection_count--;
    pthread_cond_signal(&pool_not_full);
    pthread_mutex_unlock(&pool_lock);

    return NULL;
}

