    pthread_mutex_unlock(&tree->lock);
}

double metrics_tree_average_in_window(MetricsTree *tree, time_t start, time_t end) {
    pthread_mutex_lock(&tree->lock);
    // Calculate average of metrics within the given time window
    pthread_mutex_unlock(&tree->lock);
    return 0.0;
}

// Additional functions for filtering, custom aggregation strategies, backpressure mechanism,
// archiving, notification system, and extensibility

void metrics_tree_destroy(MetricsTree *tree) {
    pthread_mutex_lock(&tree->lock);
    // Free all memory associated with the tree
    pthread_mutex_unlock(&tree->lock);
    free(tree);
}
