        if (!fetch_rx_ue_info(&rx_ue_info)) {
            retry_count++;
            continue;
        }

        for (int i = 0; i < N; i++) {
            pdus[i].rx_ue_info = rx_ue_info;
            pdus[i].crc_indication_rel8_tag.CRCFLAG = (retry_count > 0) ? rand() % 2 : default_crcflag;
