typedef struct Metric {
    time_t timestamp;
    char type[50];
    double value;
} Metric;

typedef struct Node {
    Metric data;
    struct Node* left, * right;
} Node;

typedef struct BinarySearchTree {
    Node* root;
    pthread_mutex_t lock;
    size_t pool_size;
    void** metric_pool;
} BinarySearchTree;

Node* createNode(Metric data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void insertNode(BinarySearchTree* bst, Metric data) {
    pthread_mutex_lock(&bst->lock);
    Node** root = &bst->root;
    while (*root != NULL) {
        if (data.timestamp < (*root)->data.timestamp)
            root = &(*root)->left;
        else
            root = &(*root)->right;
    }
    *root = createNode(data);
    pthread_mutex_unlock(&bst->lock);
}

void removeNode(Node** node, time_t timestamp) {
    if (*node == NULL) return;

    if (timestamp < (*node)->data.timestamp)
        removeNode(&(*node)->left, timestamp);
    else if (timestamp > (*node)->data.timestamp)
        removeNode(&(*node)->right, timestamp);
    else {
        Node* temp = *node;
        if ((*node)->left == NULL) {
            *node = (*node)->right;
            free(temp);
        } else if ((*node)->right == NULL) {
            *node = (*node)->left;
            free(temp);
        } else {
            Node** successor = &(*node)->right;
            while ((*successor)->left != NULL)
                successor = &(*successor)->left;

            Metric data = (*successor)->data;
            removeNode(successor, data.timestamp);
            (*node)->data = data;
        }
    }
}

Metric* getAverageMetrics(BinarySearchTree* bst, time_t start, time_t end) {
    // Implement logic to calculate average values within the given time window
    return NULL;
}

void freeTree(Node* node) {
    if (node != NULL) {
        freeTree(node->left);
        freeTree(node->right);
        free(node);
    }
}

void destroyBinarySearchTree(BinarySearchTree* bst) {
    pthread_mutex_lock(&bst->lock);
    freeTree(bst->root);
    for (size_t i = 0; i < bst->pool_size; ++i)
        free(bst->metric_pool[i]);
    free(bst->metric_pool);
    pthread_mutex_unlock(&bst->lock);
}

int main() {
    BinarySearchTree bst;
    pthread_mutex_init(&bst.lock, NULL);
    bst.root = NULL;
    bst.pool_size = 1024; // Example size
    bst.metric_pool = (void**)malloc(bst.pool_size * sizeof(void*));

    // Example usage of the binary search tree
    Metric metric1 = {time(NULL), "CPU", 90.5};
    insertNode(&bst, metric1);

    destroyBinarySearchTree(&bst);
    pthread_mutex_destroy(&bst.lock);

    return 0;
}
