typedef struct Metric {
    int64_t timestamp;
    char type[32];
    double value;
    struct Metric *left, *right;
} Metric;

typedef struct Node {
    Metric data;
    struct Node *next;
} Node;

typedef struct MetricsList {
    Node *head;
    pthread_mutex_t lock;
} MetricsList;

void initMetricsList(MetricsList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addMetric(MetricsList *list, Metric new_metric) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = new_metric;
    new_node->next = list->head;
    list->head = new_node;
}

void removeOldMetrics(MetricsList *list, int64_t retention_period) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.timestamp < (retention_period)) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

double averageValueInWindow(MetricsList *list, int64_t start_time, int64_t end_time) {
    double sum = 0.0, count = 0.0;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head;

    while (current != NULL) {
        if (current->data.timestamp >= start_time && current->data.timestamp <= end_time) {
            sum += current->data.value;
            count++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return (count > 0) ? sum / count : 0.0;
}

