    newNode->data = metric;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

