#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct TAI {
    char global_id[16];
    int ue_count;
    time_t last_update;
    int priority;
    struct TAI *next;
} TAI;

typedef struct TAICollection {
    TAI **tai_list;
    int size;
    int capacity;
    pthread_mutex_t lock;
} TAICollection;

TAICollection* create_taicol(int K) {
    TAICollection *col = (TAICollection*)malloc(sizeof(TAICollection));
    if (!col) return NULL;

    col->tai_list = (TAI**)calloc(K, sizeof(TAI*));
    if (!col->tai_list) {
        free(col);
        return NULL;
    }

    col->size = 0;
    col->capacity = K;
    pthread_mutex_init(&col->lock, NULL);

    return col;
}

void destroy_taicol(TAICollection *col) {
    for (int i = 0; i < col->size; ++i) {
        TAI *tai = col->tai_list[i];
        while (tai) {
            TAI *next = tai->next;
            free(tai);
            tai = next;
        }
    }
    free(col->tai_list);
    pthread_mutex_destroy(&col->lock);
    free(col);
}

TAI* create_tai(const char *global_id, int ue_count, time_t last_update, int priority) {
    TAI *tai = (TAI*)malloc(sizeof(TAI));
    if (!tai) return NULL;

    strncpy(tai->global_id, global_id, sizeof(tai->global_id) - 1);
    tai->ue_count = ue_count;
    tai->last_update = last_update;
    tai->priority = priority;
    tai->next = NULL;

    return tai;
}

void destroy_tai(TAI *tai) {
    free(tai);
}

int add_tai(TAICollection *col, TAI *tai) {
    pthread_mutex_lock(&col->lock);
    if (col->size >= col->capacity) {
        pthread_mutex_unlock(&col->lock);
        return -1; // Out of capacity
    }

    col->tai_list[col->size++] = tai;
    pthread_mutex_unlock(&col->lock);
    return 0;
}

TAI* find_tai(TAICollection *col, const char *global_id) {
    pthread_mutex_lock(&col->lock);
    for (int i = 0; i < col->size; ++i) {
        if (strcmp(col->tai_list[i]->global_id, global_id) == 0) {
            TAI *tai = col->tai_list[i];
            memmove(&col->tai_list[i], &col->tai_list[i+1], (col->size - i - 1) * sizeof(TAI*));
            col->size--;
            pthread_mutex_unlock(&col->lock);
            return tai;
        }
    }
    pthread_mutex_unlock(&col->lock);
    return NULL;
}

void remove_tai(TAICollection *col, TAI *tai) {
    pthread_mutex_lock(&col->lock);
    for (int i = 0; i < col->size; ++i) {
        if (col->tai_list[i] == tai) {
            memmove(&col->tai_list[i], &col->tai_list[i+1], (col->size - i - 1) * sizeof(TAI*));
            col->size--;
            break;
        }
    }
    pthread_mutex_unlock(&col->lock);
}

int serialize_taicol(TAICollection *col, FILE *file) {
    pthread_mutex_lock(&col->lock);
    fwrite(&col->size, sizeof(int), 1, file);
    for (int i = 0; i < col->size; ++i) {
        TAI *tai = col->tai_list[i];
        fwrite(tai->global_id, sizeof(char), sizeof(tai->global_id), file);
        fwrite(&tai->ue_count, sizeof(int), 1, file);
        fwrite(&tai->last_update, sizeof(time_t), 1, file);
        fwrite(&tai->priority, sizeof(int), 1, file);
    }
    pthread_mutex_unlock(&col->lock);
    return 0;
}

int deserialize_taicol(TAICollection *col, FILE *file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    if (size > col->capacity) {
        fprintf(stderr, "Deserialization error: Size exceeds collection capacity\n");
        return -1;
    }

    pthread_mutex_lock(&col->lock);
    for (int i = 0; i < size; ++i) {
        TAI *tai = create_tai(NULL, 0, 0, 0);
        if (!tai) {
            destroy_taicol(col); // Cleanup on failure
            pthread_mutex_unlock(&col->lock);
            return -1;
        }
        fread(tai->global_id, sizeof(char), sizeof(tai->global_id), file);
        fread(&tai->ue_count, sizeof(int), 1, file);
        fread(&tai->last_update, sizeof(time_t), 1, file);
        fread(&tai->priority, sizeof(int), 1, file);
        add_tai(col, tai);
    }
    pthread_mutex_unlock(&col->lock);
    return 0;
}
