#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONCURRENT_ALLOCATIONS 10

typedef struct {
    int STORAGE_LEVEL;
    char* STORAGE_PATH;
    int ACCESS_PERMISSION;
} NFPAPI_STORAGE_CONTEXT_T;

typedef enum {
    DEFAULT_PATH,
    RANDOM_PATH,
    CUSTOM_PATH,
    SECURE_PATH
} PATH_TYPE;

NFPAPI_STORAGE_CONTEXT_T** allocate_storage_contexts(int N, int path_type, const char* custom_path) {
    static pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
    static int active_allocations = 0;
    static pthread_cond_t queue_condition = PTHREAD_COND_INITIALIZER;
    static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
    static NFPAPI_STORAGE_CONTEXT_T** allocation_queue = NULL;
    static int queue_size = 0;

    pthread_mutex_lock(&allocation_lock);

    if (active_allocations >= MAX_CONCURRENT_ALLOCATIONS) {
        // Queue the request
        pthread_mutex_lock(&queue_lock);
        if (queue_size == 0) {
            queue_size = N;
            allocation_queue = malloc(sizeof(NFPAPI_STORAGE_CONTEXT_T*) * queue_size);
        }
        for (int i = 0; i < N; i++) {
            allocation_queue[active_allocations++] = NULL;
        }
        pthread_cond_signal(&queue_condition);
        pthread_mutex_unlock(&queue_lock);

        // Wait until we can allocate
        while (active_allocations >= MAX_CONCURRENT_ALLOCATIONS) {
            pthread_cond_wait(&queue_condition, &allocation_lock);
        }
    }

    NFPAPI_STORAGE_CONTEXT_T** contexts = malloc(N * sizeof(NFPAPI_STORAGE_CONTEXT_T*));
    if (!contexts) {
        perror("Failed to allocate memory for storage contexts");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        contexts[i] = malloc(sizeof(NFPAPI_STORAGE_CONTEXT_T));
        if (!contexts[i]) {
            perror("Failed to allocate memory for a single context");
            // Free previously allocated contexts
            for (int j = 0; j < i; j++) {
                free(contexts[j]);
            }
            free(contexts);
            return NULL;
        }

        switch (path_type) {
            case DEFAULT_PATH:
                strcpy(contexts[i]->STORAGE_PATH, "default_path");
                break;
            case RANDOM_PATH:
                contexts[i]->STORAGE_PATH = generate_random_path();
                break;
            case CUSTOM_PATH:
                contexts[i]->STORAGE_PATH = strdup(custom_path);
                break;
            case SECURE_PATH:
                contexts[i]->STORAGE_PATH = generate_secure_path();
                contexts[i]->ACCESS_PERMISSION = REQUIRE_ADMIN;
                break;
        }
        contexts[i]->STORAGE_LEVEL = i % 3 + 1; // Example initialization
        contexts[i]->ACCESS_PERMISSION = DEFAULT_PERMISSIONS;

        if (!validate_context(contexts[i])) {
            free_memory(contexts, i);
            return NULL;
        }
    }

    active_allocations += N;

    pthread_mutex_unlock(&allocation_lock);

    return contexts;
}

void free_memory(NFPAPI_STORAGE_CONTEXT_T** contexts, int N) {
    for (int i = 0; i < N; i++) {
        free(contexts[i]->STORAGE_PATH);
        free(contexts[i]);
    }
    free(contexts);
}

int validate_context(NFPAPI_STORAGE_CONTEXT_T* context) {
    if (!context->STORAGE_PATH || *context->STORAGE_PATH == '\0') {
        warn_uninitialized_field("STORAGE_PATH");
        return 0;
    }
    // Add more validation checks as needed
    return 1;
}

void log_error(const char* message) {
    pthread_mutex_lock(&allocation_lock);
    fprintf(stderr, "Error: %s\n", message);
    pthread_mutex_unlock(&allocation_lock);
}

void warn_uninitialized_field(const char* field) {
    pthread_mutex_lock(&allocation_lock);
    fprintf(stderr, "Warning: Uninitialized or misconfigured field '%s'\n", field);
    pthread_mutex_unlock(&allocation_lock);
}
