    INTERFACE_TYPE interface_type;
    char mac_address[18];
    char subnet_mask[16];
    struct device_config *next;
} DEVICE_CONFIG;

DEVICE_CONFIG* create_device_config(int id, INTERFACE_TYPE type, const char* mac, const char* subnet) {
    DEVICE_CONFIG* config = (DEVICE_CONFIG*)malloc(sizeof(DEVICE_CONFIG));
    if (config == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    config->device_id = id;
    config->interface_type = type;
    strcpy(config->mac_address, mac);
    strcpy(config->subnet_mask, subnet);
    config->next = NULL;
    return config;
}

void free_device_configs(DEVICE_CONFIG* head) {
    DEVICE_CONFIG* current = head;
    while (current != NULL) {
        DEVICE_CONFIG* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int num_devices = 50;
    DEVICE_CONFIG** device_list = (DEVICE_CONFIG**)malloc(num_devices * sizeof(DEVICE_CONFIG*));
