#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int PROCESSOR_ID;
    int DATA_SOURCE_TYPE;
    int PROCESSING_THREAD_POOL_SIZE;
} NFPAPI_DATA_PROCESSOR_T;

int validate_data_source_type(int type) {
    if (type < 0 || type > 2) {
        fprintf(stderr, "Invalid DATA_SOURCE_TYPE: %d\n", type);
        return -1;
    }
    return 0;
}

NFPAPI_DATA_PROCESSOR_T* allocate_processors(int N, int data_source_type, int default_thread_pool_size, int max_allocations) {
    if (validate_data_source_type(data_source_type) != 0) {
        return NULL;
    }

    NFPAPI_DATA_PROCESSOR_T* processors = malloc(N * sizeof(NFPAPI_DATA_PROCESSOR_T));
    if (processors == NULL) {
        fprintf(stderr, "Memory allocation failed for %d processors\n", N);
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        free(processors);
        return NULL;
    }

    int allocated_count = 0;

    for (int i = 0; i < N; ++i) {
        if (allocated_count >= max_allocations) {
            // Queue and process requests asynchronously
            continue;
        }

        processors[i].PROCESSOR_ID = i + 1;
        processors[i].DATA_SOURCE_TYPE = data_source_type;

        switch (data_source_type) {
            case 0:
                processors[i].PROCESSING_THREAD_POOL_SIZE = default_thread_pool_size;
                break;
            case 1:
                // Dynamically select based on current load
                processors[i].PROCESSING_THREAD_POOL_SIZE = analyze_load();
                break;
            case 2:
                // Custom type specified by the caller
                processors[i].PROCESSING_THREAD_POOL_SIZE = custom_thread_pool_size_for(i);
                break;
        }

        if (pthread_mutex_lock(&lock) != 0) {
            fprintf(stderr, "Failed to lock mutex\n");
            free(processors);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        allocated_count++;

        if (pthread_mutex_unlock(&lock) != 0) {
            fprintf(stderr, "Failed to unlock mutex\n");
            free(processors);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }

    // Validate initialization
    for (int i = 0; i < N; ++i) {
        if (processors[i].PROCESSOR_ID <= 0 || processors[i].DATA_SOURCE_TYPE < 0 || processors[i].DATA_SOURCE_TYPE > 2) {
            fprintf(stderr, "Invalid processor initialization at index %d\n", i);
            for (int j = 0; j < i; ++j) {
                free(processors[j]);
            }
            free(processors);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }

    pthread_mutex_destroy(&lock);
    return processors;
}

void validate_processors(NFPAPI_DATA_PROCESSOR_T* processors, int N) {
    for (int i = 0; i < N; ++i) {
        if (processors[i].PROCESSOR_ID <= 0 || processors[i].DATA_SOURCE_TYPE < 0 || processors[i].DATA_SOURCE_TYPE > 2) {
            fprintf(stderr, "Warning: Suspicious processor initialization at index %d\n", i);
        }
    }
}

int analyze_load() {
    // Placeholder for load analysis logic
    return 4; // Example value
}

int custom_thread_pool_size_for(int id) {
    // Placeholder for custom thread pool size logic
    return id + 2; // Example value
}
