#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Metric {
    time_t timestamp;
    char type[50];
    double value;
    struct Metric *next;
} Metric;

typedef struct MetricsList {
    Metric *head;
    pthread_mutex_t lock;
} MetricsList;

void init_metrics_list(MetricsList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_metric(MetricsList *list, time_t timestamp, const char *type, double value) {
    Metric *new_metric = (Metric *)malloc(sizeof(Metric));
    new_metric->timestamp = timestamp;
    strncpy(new_metric->type, type, 49);
    new_metric->value = value;
    new_metric->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_metric->next = list->head;
    list->head = new_metric;
    pthread_mutex_unlock(&list->lock);
}

void remove_old_metrics(MetricsList *list, time_t retention_period) {
    Metric *current = list->head;
    Metric *previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if ((time(NULL) - current->timestamp) > retention_period) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current = previous->next;
        } else {
            previous = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

double get_average_value_in_window(MetricsList *list, time_t start_time, time_t end_time) {
    Metric *current = list->head;
    double sum = 0.0;
    int count = 0;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->timestamp >= start_time && current->timestamp <= end_time) {
            sum += current->value;
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return count > 0 ? sum / count : 0.0;
}

void *metrics_processor_thread(void *arg) {
    MetricsList *list = (MetricsList *)arg;

    while (1) {
        // Process metrics
        remove_old_metrics(list, 86400); // Example: Remove metrics older than 24 hours

        // Sleep or wait for new work
        sleep(1);
    }

    return NULL;
}

int main() {
    MetricsList list;
    init_metrics_list(&list);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, metrics_processor_thread, &list);

    // Simulate adding metrics
    add_metric(&list, time(NULL), "CPU_USAGE", 75.0);
    add_metric(&list, time(NULL), "MEMORY_USAGE", 80.0);

    pthread_join(thread_id, NULL);

    return 0;
}
```

This code block demonstrates a basic implementation of a thread-safe metrics list with functionality to add, remove old metrics, and calculate the average value within a given time window. It uses a mutex for synchronization to ensure thread safety during concurrent access. The `metrics_processor_thread` function is intended to run in a separate thread and process metrics according to the specified retention policy.']

