typedef struct {
    int width;
    int height;
    char color_space[50];
    double compression_ratio;
    Exiv2::Metadata* metadata;
} ImageInfo;

ImageInfo* process_jpeg(const char* filename, const char* option, bool low_latency) {
    ImageInfo* info = (ImageInfo*)malloc(sizeof(ImageInfo));
    if (!info) return NULL;

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE* infile;
    JSAMPARRAY buffer;
    int row_stride;

    // Initialize the JPEG decompression object
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    if ((infile = fopen(filename, "rb")) == NULL) {
        free(info);
        return NULL;
    }

    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    info->width = cinfo.output_width;
    info->height = cinfo.output_height;

    switch (cinfo.out_color_space) {
        case JCS_RGB: strcpy(info->color_space, "RGB"); break;
        case JCS_YCbCr: strcpy(info->color_space, "YCbCr"); break;
        default: strcpy(info->color_space, "Unknown"); break;
    }

    // Calculate the number of bytes per row
    row_stride = cinfo.output_width * cinfo.output_components;

    buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, row_stride, 1);

    while (cinfo.output_scanline < cinfo.output_height) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
    }

    jpeg_finish_decompress(&cinfo);
    fclose(infile);
    jpeg_destroy_decompress(&cinfo);

    // Initialize Exiv2 metadata
    info->metadata = new Exiv2::Metadata();
    Exiv2::Image::AutoPtr image = Exiv2::ImageFactory::open(filename);
    if (image.get()) {
        image->readMetadata();
        *info->metadata = image->getMetadata();
    }

    // Process metadata based on option
    if (strcmp(option, "rotate") == 0) {
        Exiv2::ExifData& exifData = info->metadata->exifData();
        if (!exifData.empty()) {
            Exiv2::ExifEntry* pEntry = exifData.findKey(Exiv2::ExifKey("Exif.Image.Orientation"));
            if (pEntry) {
                int orientation = pEntry->getValue().toInt32();
                // Rotate the image based on orientation
            }
        }
    }

    return info;
}

void free_image_info(ImageInfo* info) {
    if (info) {
        delete info->metadata;
        free(info);
    }
}
