int is_valid_delimiter(char c);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        show_usage();
        return 1;
    }

    int case_sensitive = 0;
    const char *delimiter = DEFAULT_DELIMITER;
    FILE *output_file = stdout;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            show_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            case_sensitive = 1;
        } else if (strncmp(argv[i], "-o ", 3) == 0) {
            output_file = fopen(&argv[i][3], "a");
            if (!output_file) {
                perror("Failed to open output file");
                return 1;
            }
        } else if (strncmp(argv[i], "-d ", 3) == 0) {
            delimiter = &argv[i][3];
            if (!is_valid_delimiter(delimiter[0])) {
                fprintf(stderr, "Invalid delimiter: %s\n", delimiter);
                return 1;
            }
        } else {
            process_file(argv[i], delimiter, case_sensitive, output_file);
        }
    }

    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}

void show_usage() {
    printf("Usage: program [options] file1 [file2 ...]\n");
    printf("Options:\n");
    printf("  --help         Show this help message\n");
    printf("  -cs            Enable case-sensitive mode\n");
    printf("  -o output_file Specify an output file\n");
    printf("  -d delimiter   Specify a custom delimiter for splitting lines\n");
}

int is_valid_delimiter(char c) {
    // Add your validation logic here
    return c == ' ' || c == '\t' || c == '\n';
}

void process_file(const char *filename, const char *delimiter, int case_sensitive, FILE *output_file) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) == -1) {
        perror("Failed to get file statistics");
        fclose(file);
        return;
    }

    char buffer[MAX_LINE_LENGTH];
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer) - 1, file)) > 0) {
        buffer[bytes_read] = '\0';
        // Process the line here
    }

    fclose(file);
}
