#define MAX_QUEUE_SIZE 1024
#define DEFAULT_CRC_CHECK true

typedef struct Frame {
    uint64_t timestamp;
    size_t length;
    uint8_t* payload;
} Frame;

typedef struct FrameQueue {
    Frame** frames;
    size_t front;
    size_t rear;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    bool crc_check_enabled;
    uint32_t rolling_checksum;
} FrameQueue;

FrameQueue* createFrameQueue(size_t initial_capacity, bool crc_check_enabled) {
    FrameQueue* queue = (FrameQueue*)malloc(sizeof(FrameQueue));
    if (!queue) {
        perror("Failed to allocate memory for frame queue");
        return NULL;
    }
    queue->frames = (Frame**)calloc(initial_capacity, sizeof(Frame*));
    if (!queue->frames) {
        perror("Failed to allocate memory for frame queue elements");
        free(queue);
        return NULL;
    }
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    queue->front = 0;
    queue->rear = 0;
    queue->size = 0;
    queue->capacity = initial_capacity;
    queue->crc_check_enabled = crc_check_enabled;
    queue->rolling_checksum = 0;
    return queue;
}

void destroyFrameQueue(FrameQueue* queue) {
    for (size_t i = 0; i < queue->capacity; ++i) {
        if (queue->frames[i]) {
            free(queue->frames[i]->payload);
            free(queue->frames[i]);
        }
    }
    free(queue->frames);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

bool enqueueFrame(FrameQueue* queue, Frame* frame) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    if (queue->crc_check_enabled && !validateCRC(frame)) {
        fprintf(stderr, "Invalid CRC for frame\n");
        pthread_mutex_unlock(&queue->lock);
        return false;
    }
    queue->frames[queue->rear] = frame;
    queue->rear = (queue->rear + 1) % queue->capacity;
    ++queue->size;
    if (queue->size == 1) {
        pthread_cond_signal(&queue->not_empty);
    }
    updateRollingChecksum(queue, frame, true);
    pthread_mutex_unlock(&queue->lock);
    return true;
}

Frame* dequeueFrame(FrameQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    Frame* frame = queue->frames[queue->front];
    queue->frames[queue->front] = NULL;
    queue->front = (queue->front + 1) % queue->capacity;
    --queue->size;
    if (queue->size == queue->capacity - 1) {
        pthread_cond_signal(&queue->not_full);
    }
    updateRollingChecksum(queue, frame, false);
    pthread_mutex_unlock(&queue->lock);
    return frame;
}

void updateRollingChecksum(FrameQueue* queue, Frame* frame, bool add) {
    if (add) {
        queue->rolling_checksum += frame->length;
        for (size_t i = 0; i < frame->length; ++i) {
            queue->rolling_checksum += frame->payload[i];
        }
    } else {
        queue->rolling_checksum -= frame->length;
        for (size_t i = 0; i < frame->length; ++i) {
            queue->rolling_checksum -= frame->payload[i];
        }
    }
}

bool validateCRC(Frame* frame) {
    // Implement CRC validation logic here
    return true;
}

void logFrameOperation(FrameQueue* queue, const char* operation, bool success) {
    if (success) {
        printf("SUCCESS: %s\n", operation);
    } else {
        printf("ERROR: %s\n", operation);
    }
}
