#define MAX_REQUEST_SIZE 1024
#define MAX_LOG_SIZE 1024

typedef struct {
    int id;
    char *profile;
} UserProfile;

typedef struct {
    pthread_mutex_t lock;
    UserProfile users[1000];
    int count;
} UserDatabase;

UserDatabase user_db;

void init_user_db() {
    pthread_mutex_init(&user_db.lock, NULL);
    user_db.count = 0;
}

UserProfile* find_user(int id) {
    pthread_mutex_lock(&user_db.lock);
    for (int i = 0; i < user_db.count; i++) {
        if (user_db.users[i].id == id) {
            pthread_mutex_unlock(&user_db.lock);
            return &user_db.users[i];
        }
    }
    pthread_mutex_unlock(&user_db.lock);
    return NULL;
}

void update_user(int id, char *json) {
    UserProfile *user = find_user(id);
    if (user != NULL) {
        free(user->profile);
        user->profile = strdup(json);
        log_action("Updated user profile", id);
    }
}

void delete_user(int id) {
    UserProfile *user = find_user(id);
    if (user != NULL) {
        user->id = -1; // Soft-delete by marking as inactive
        log_action("Deleted user profile", id);
    }
}

void log_action(char *action, int id) {
    printf("%s: User ID %d\n", action, id);
}

int find_largest_int() {
    int max_value = INT_MIN;
    char line[MAX_REQUEST_SIZE];
    while (fgets(line, sizeof(line), stdin)) {
        char *token = strtok(line, " ");
        while (token != NULL) {
            long value = strtol(token, NULL, 10);
            if (value > max_value) {
                max_value = value;
            }
            token = strtok(NULL, " ");
        }
    }
    return max_value;
}

int main() {
    init_user_db();
    int largest_int = find_largest_int();
    printf("Largest integer: %d\n", largest_int);
    return 0;
}
