const axios = require('axios');
const FormData = require('form-data');
const retry = require('async-retry');

async function uploadFile(url, maxRetries = 3) {
    const allowedTypes = ['image/png', 'image/jpeg', 'application/pdf'];
    const maxSize = 5 * 1024 * 1024; // 5MB
    const cloudStorageUrl = 'https://your-cloud-storage-endpoint.com/upload';
    let fileContent;

    try {
        const response = await axios.get(url, { responseType: 'arraybuffer' });
        fileContent = response.data;
    } catch (error) {
        console.error('Failed to fetch the file:', error);
        throw new Error('File fetching failed');
    }

    const fileType = response.headers['content-type'];
    if (!allowedTypes.includes(fileType)) {
        throw new Error('Invalid file type');
    }
    if (fileContent.length > maxSize) {
        throw new Error('File size exceeds limit');
    }

    const form = new FormData();
    form.append('file', fileContent, { filename: 'uploaded-file', contentType: fileType });

    return await retry(async (bail) => {
        try {
            const uploadResponse = await axios.post(cloudStorageUrl, form, {
                headers: form.getHeaders()
            });
            console.log(`File uploaded successfully to ${uploadResponse.data.url}`);
            return uploadResponse.data.url;
        } catch (error) {
            if (maxRetries > 0) {
                console.warn(`Upload failed, retrying in ${Math.pow(2, maxRetries - 1)} seconds...`);
                throw error; // Retry the operation
            }
            bail(new Error('File upload failed after multiple attempts'));
        }
    }, { retries: maxRetries });
}

async function uploadFiles(urls) {
    const results = [];
    for (const url of urls) {
        try {
            const uploadedUrl = await uploadFile(url);
            results.push(uploadedUrl);
        } catch (error) {
            console.error(`Failed to upload file from ${url}:`, error);
        }
    }
    return results;
}

// Example usage
const filesToUpload = ['http://example.com/file1.png', 'http://example.com/file2.pdf'];
uploadFiles(filesToUpload).then(urls => {
    console.log('Successfully uploaded files:', urls);
}).catch(error => {
    console.error('Failed to upload any files:', error);
});
```

This code snippet includes a function `uploadFile` that handles the file upload process, including validation, retry logic, and logging. The `uploadFiles` function demonstrates how to use `uploadFile` for multiple URLs concurrently."]

