int networkConnectionManager(int protocol, int port, int priority) {
    pthread_mutex_lock(&pool_mutex);
    if (current_connections < MAX_CONNECTIONS) {
        int socket_fd = socket(AF_INET, SOCK_STREAM | protocol, 0);
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(port);
        server_addr.sin_addr.s_addr = htonl(INADDR_ANY);

        if (bind(socket_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
            perror("Bind failed");
            pthread_mutex_unlock(&pool_mutex);
            return -1;
        }

        listen(socket_fd, MAX_CONNECTIONS);

        while (current_connections < MAX_CONNECTIONS) {
            int new_connection = accept(socket_fd, NULL, NULL);
            if (new_connection == -1) {
                perror("Accept failed");
                break;
            }

            connection_pool[current_connections].socket = new_connection;
            connection_pool[current_connections].priority = priority;
            pthread_create(&connection_pool[current_connections].thread_id, NULL, handle_connection, &current_connections);

            current_connections++;
        }
    } else {
        printf("Connection pool is full\n");
    }
    pthread_mutex_unlock(&pool_mutex);
    return 0;
}

int main() {
    // Example usage of networkConnectionManager
    int result = networkConnectionManager(AF_INET6, 8080, 1);
    if (result == 0) {
        printf("Server started successfully\n");
    } else {
        printf("Failed to start server\n");
    }
    return 0;
}
