        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        logs_.erase(std::remove_if(logs_.begin(), logs_.end(),
                                   [retentionPeriod, now](const LogEntry& log) {
                                       return (now - log.timestamp) > retentionPeriod;
                                   }),
                   logs_.end());
    }

