// C code for managing dynamic list of TAI entities

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct tai_t {
    int global_id;
    char **ue_devices;
    int ue_count;
    time_t last_update;
} tai_t;

typedef struct tai_list_t {
    tai_t **tai_entities;
    int k;
    pthread_mutex_t lock;
} tai_list_t;

tai_list_t* create_tai_list(int k) {
    tai_list_t *list = (tai_list_t*) malloc(sizeof(tai_list_t));
    if (!list) return NULL;
    list->tai_entities = (tai_t**) malloc(k * sizeof(tai_t*));
    if (!list->tai_entities) {
        free(list);
        return NULL;
    }
    list->k = k;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_tai_list(tai_list_t *list) {
    for (int i = 0; i < list->k; i++) {
        if (list->tai_entities[i]) {
            free(list->tai_entities[i]->ue_devices);
            free(list->tai_entities[i]);
        }
    }
    free(list->tai_entities);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_tai(tai_list_t *list, int global_id, char **ue_devices, int ue_count) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->k; i++) {
        if (!list->tai_entities[i]) {
            tai_t *tai = (tai_t*) malloc(sizeof(tai_t));
            if (!tai) {
                pthread_mutex_unlock(&list->lock);
                return -1;
            }
            tai->global_id = global_id;
            tai->ue_devices = (char**) malloc(ue_count * sizeof(char*));
            if (!tai->ue_devices) {
                free(tai);
                pthread_mutex_unlock(&list->lock);
                return -1;
            }
            for (int j = 0; j < ue_count; j++) {
                tai->ue_devices[j] = strdup(ue_devices[j]);
            }
            tai->ue_count = ue_count;
            tai->last_update = time(NULL);
            list->tai_entities[i] = tai;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

// Java method for generating MD5 hash

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashUtils {
    public static String getMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
