#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define log levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

// Log entry structure
typedef struct {
    char timestamp[20];
    LogLevel level;
    char message[1024];
    // Additional metadata can be added here
} LogEntry;

// Circular buffer structure
typedef struct {
    LogEntry* entries;
    size_t capacity;
    size_t front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
    int resizing;
} LogBuffer;

// Function to initialize log buffer
void initLogBuffer(LogBuffer* buffer, size_t initial_capacity) {
    buffer->entries = (LogEntry*)malloc(initial_capacity * sizeof(LogEntry));
    buffer->capacity = initial_capacity;
    buffer->front = 0;
    buffer->rear = -1;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->not_full, NULL);
    pthread_cond_init(&buffer->not_empty, NULL);
    buffer->resizing = 0;
}

// Function to add a log entry
void addLogEntry(LogBuffer* buffer, LogEntry entry) {
    pthread_mutex_lock(&buffer->lock);
    while (buffer->front == (buffer->rear + 1) % buffer->capacity && !buffer->resizing) {
        pthread_cond_wait(&buffer->not_full, &buffer->lock);
    }
    if (buffer->resizing) {
        pthread_mutex_unlock(&buffer->lock);
        return;
    }
    buffer->rear = (buffer->rear + 1) % buffer->capacity;
    buffer->entries[buffer->rear] = entry;
    pthread_cond_signal(&buffer->not_empty);
    pthread_mutex_unlock(&buffer->lock);
}

// Function to resize log buffer
void resizeLogBuffer(LogBuffer* buffer, size_t new_capacity) {
    pthread_mutex_lock(&buffer->lock);
    while (1) {
        if (!buffer->resizing) {
            buffer->resizing = 1;
            break;
        }
        pthread_cond_wait(&buffer->not_empty, &buffer->lock);
    }

    LogEntry* new_entries = (LogEntry*)realloc(buffer->entries, new_capacity * sizeof(LogEntry));
    if (new_entries == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&buffer->lock);
        return;
    }
    buffer->entries = new_entries;
    size_t count = (buffer->rear + 1 - buffer->front + buffer->capacity) % buffer->capacity;
    for (size_t i = 0; i < count; ++i) {
        buffer->entries[i] = buffer->entries[(buffer->front + i) % buffer->capacity];
    }
    buffer->front = 0;
    buffer->rear = count - 1;
    buffer->capacity = new_capacity;
    pthread_cond_signal(&buffer->not_full);
    buffer->resizing = 0;
    pthread_mutex_unlock(&buffer->lock);
}

// Function to clean up log buffer
void cleanupLogBuffer(LogBuffer* buffer) {
    free(buffer->entries);
    pthread_mutex_destroy(&buffer->lock);
    pthread_cond_destroy(&buffer->not_full);
    pthread_cond_destroy(&buffer->not_empty);
}
