#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>

struct UserProfile {
    std::string id;
    std::string name;
    std::string email;
};

class UserProfileManager {
private:
    std::unordered_map<std::string, UserProfile> userProfiles;
    mutable std::mutex mutex;

public:
    void add(const UserProfile& profile) {
        std::lock_guard<std::mutex> lock(mutex);
        if (userProfiles.find(profile.id) != userProfiles.end()) {
            throw std::runtime_error("User already exists");
        }
        userProfiles[profile.id] = profile;
    }

    void update(const std::string& id, const std::string& name, const std::string& email) {
        std::lock_guard<std::mutex> lock(mutex);
        if (userProfiles.find(id) == userProfiles.end()) {
            throw std::runtime_error("User not found");
        }
        userProfiles[id].name = name;
        userProfiles[id].email = email;
    }

    void deleteProfile(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (userProfiles.find(id) == userProfiles.end()) {
            throw std::runtime_error("User not found");
        }
        userProfiles.erase(id);
    }

    UserProfile query(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mutex);
        if (userProfiles.find(id) == userProfiles.end()) {
            throw std::runtime_error("User not found");
        }
        return userProfiles.at(id);
    }
};

int main(int argc, char* argv[]) {
    UserProfileManager manager;

    // Example usage
    try {
        manager.add({"1", "Alice", "alice@example.com"});
        manager.update("1", "Alicia", "alicia@example.com");
        std::cout << "User ID: 1, Name: " << manager.query("1").name << ", Email: " << manager.query("1").email << std::endl;
        manager.deleteProfile("1");
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
