typedef struct {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} CipherContext;

SecureLogBuffer* initSecureLogBufferAndEncrypt(size_t initialCapacity, const char* password, int integrityChecksEnabled) {
    // Allocate memory for the SecureLogBuffer
    SecureLogBuffer* buffer = (SecureLogBuffer*)malloc(sizeof(SecureLogBuffer));
    if (!buffer) return NULL;

    // Initialize the buffer fields
    buffer->capacity = initialCapacity;
    buffer->count = 0;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->integrityChecksEnabled = integrityChecksEnabled;

    // Allocate memory for the log buffer
    buffer->buffer = (LogEntry*)malloc(initialCapacity * sizeof(LogEntry));
    if (!buffer->buffer) {
        free(buffer);
        return NULL;
    }

    // Initialize mutex and condition variable
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);

    // Initialize cipher context
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) {
        free(buffer->buffer);
        free(buffer);
        return NULL;
    }

    // Derive encryption key using SHA-1 hash of the password
    unsigned char derivedKey[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), derivedKey);

    // Initialize AES-256-CBC cipher context
    if (AES_set_encrypt_key(derivedKey, 256, &ctx->key) != 0) {
        free(ctx);
        free(buffer->buffer);
        free(buffer);
        return NULL;
    }

    // Copy fixed IV
    memcpy(ctx->iv, "FixedIV123", AES_BLOCK_SIZE);

    buffer->cipherContext = ctx;
    return buffer;
}

void cleanupSecureLogBuffer(SecureLogBuffer* buffer) {
    if (!buffer) return;

    // Clean up the cipher context
    CipherContext* ctx = buffer->cipherContext;
    AES_set_encrypt_key(NULL, 0, &ctx->key);
    free(ctx);

    // Free memory for log entries and the buffer itself
    free(buffer->buffer);
    pthread_mutex_destroy(&buffer->mutex);
    pthread_cond_destroy(&buffer->cond);
    free(buffer);
}

