#define N 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaip_pdu_list(int N, const char* hostname) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        perror("Failed to allocate memory for NFAPI CRC indication PDU list");
        return NULL;
    }

    struct hostent* he;
    struct sockaddr_in sa;
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);

    if (sockfd < 0) {
        perror("Failed to create socket");
        free(pdu_list);
        return NULL;
    }

    // Limit process capabilities
    if (setrlimit(RLIMIT_NOFILE, &(struct rlimit){1, 1}) != 0) { // Only allow one file descriptor
        perror("Failed to limit number of open files");
        close(sockfd);
        free(pdu_list);
        return NULL;
    }

    struct xprt_opts {
        int o_flags;
        int o_protocol;
        char* o_address;
        socklen_t o_addrlen;
    } opts = {0};

    if (rpcb_getport(hostname, "svc_cnxn", IPPROTO_UDP, &opts.o_port) != RPC_SUCCESS) {
        perror("Failed to get port number");
        close(sockfd);
        free(pdu_list);
        return NULL;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(opts.o_port);

    if (inet_pton(AF_INET, hostname, &sa.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        free(pdu_list);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_ue_information_tag.RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].rx_ue_information_tag.RNTI = rand() % 65536;
        pdu_list[i].crc_indication_rel8_flag.CRCFLAG = (rand() % 2) == 0 ? 0 : 1;
    }

    // Perform DNS resolution
    he = gethostbyname(hostname);
    if (he == NULL) {
        herror("gethostbyname");
        close(sockfd);
        free(pdu_list);
        return NULL;
    }

    struct in_addr** addr_list = (struct in_addr**)he->h_addr_list;
    u_char ip_address[4];
    memcpy(ip_address, &addr_list[0]->s_addr, 4);

    printf("Resolved IP address: %d.%d.%d.%d\n",
           ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    close(sockfd);
    return pdu_list;
}
