    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNfalogsAndResolveHost(NFAPI_CRC_INDICATION_PDU_T **pdus, int *num_pdus, const char *hostname, u_char *ip_address) {
    // Dynamically allocate memory for PDU structures
    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_PDU_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    *num_pdus = 0;

    // Populate PDU structures
    for (int i = 0; i < MAX_PDU_STRUCTS; i++) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 1000000;
        (*pdus)[i].RNTI = rand() % 65536;
        (*pdus)[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG
        (*num_pdus)++;
    }

    // Resolve hostname to IP address
    struct sockaddr_in addr;
    if (inet_pton(AF_INET, hostname, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address\n");
        free(*pdus);
        *pdus = NULL;
        *num_pdus = 0;
        return;
    }

    // Store the resolved IP address
    memcpy(ip_address, &addr.sin_addr.s_addr, sizeof(u_char));
}
