#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <arpa/inet.h>

#define MAX_PDU 100
#define MAX_HOSTNAME_LENGTH 256
#define DNS_RETRY_INTERVAL 1000  // in milliseconds
#define DNS_MAX_RETRIES 3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T pduArray[MAX_PDU];
unsigned char ipBuffer[4];

void populateNfalogsAndResolveHost(const char* hostname) {
    int pdusCreated = 0;
    struct sockaddr_in address;
    struct hostent *hostInfo;

    while (pdusCreated < MAX_PDU) {
        // Populate NFAPI_CRC_INDICATION_PDU_T structure
        pduArray[pdusCreated].RX_UE_INFORMATION_TAG = rand() % 1000;  // Example: Random RX_UE_INFORMATION_TAG
        pduArray[pdusCreated].RNTI = rand() % 65536;  // Example: Random RNTI
        pduArray[pdusCreated].CRC_INDICATION_REL8_TAG = rand() % 256;  // Example: Random CRCFLAG

        if (gethostbyname_r(hostname, &address, ipBuffer, sizeof(ipBuffer), &hostInfo, NULL) == 0) {
            inet_ntop(AF_INET, &address.sin_addr, ipBuffer, sizeof(ipBuffer));
            pdusCreated++;
        } else {
            // Handle DNS resolution failure
            printf("DNS resolution failed for hostname: %s\n", hostname);
            break;
        }

        // Throttle requests if necessary
        usleep(DNS_RETRY_INTERVAL * 1000);
    }

    if (pdusCreated == 0) {
        printf("Failed to populate PDU array and resolve host.\n");
    } else {
        printf("Successfully populated %d PDUs and resolved host: %s\n", pdusCreated, hostname);
    }
}

int main() {
    srand(time(NULL));
    const char* hostname = "example.com";
    populateNfalogsAndResolveHost(hostname);
    return 0;
}
