typedef struct {
    int sockfd;
    char remote_ip[INET_ADDRSTRLEN];
    int port;
    SSL *ssl;
} TCPConnection;

typedef struct {
    TCPConnection **connections;
    size_t count;
    size_t capacity;
    DNSCache dns_cache;
} ConnectionList;

void initialize_connection_list(ConnectionList *list, size_t initial_capacity) {
    list->connections = (TCPConnection **)malloc(initial_capacity * sizeof(TCPConnection *));
    if (!list->connections) {
        perror("Failed to allocate memory for connection list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

void add_connection(ConnectionList *list, TCPConnection *conn) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->connections = (TCPConnection **)realloc(list->connections, list->capacity * sizeof(TCPConnection *));
        if (!list->connections) {
            perror("Failed to reallocate memory for connection list");
            exit(EXIT_FAILURE);
        }
    }
    list->connections[list->count++] = conn;
}

void secure_tls_handshake(TCPConnection *conn) {
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    SSL_set_fd(ssl, conn->sockfd);
    int ret = SSL_connect(ssl);
    if (ret != 1) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    conn->ssl = ssl;
}

void gracefully_shutdown_connection(TCPConnection *conn) {
    SSL_shutdown(conn->ssl);
    SSL_free(conn->ssl);
    close(conn->sockfd);
    free(conn);
}

int resolve_hostname(const char *hostname, char ip[INET_ADDRSTRLEN]) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip, INET_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

