#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <pthread.h>

typedef struct {
    int fd;
    char remote_ip[INET6_ADDRSTRLEN];
    uint16_t port;
    SSL* ssl;
} Connection;

typedef struct {
    Connection** connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionPool;

typedef enum {
    CONN_SUCCESS,
    CONN_FAILURE,
    CONN_TEMP_FAILURE
} ConnectionStatus;

Connection* create_connection(int fd, const char* remote_ip, uint16_t port) {
    Connection* conn = (Connection*)malloc(sizeof(Connection));
    if (!conn) {
        return NULL;
    }
    conn->fd = fd;
    strcpy(conn->remote_ip, remote_ip);
    conn->port = port;
    conn->ssl = SSL_new(SSL_CTX_new(TLS_client_method()));
    if (!conn->ssl) {
        free(conn);
        return NULL;
    }
    return conn;
}

void destroy_connection(Connection* conn) {
    if (conn->ssl) {
        SSL_free(conn->ssl);
    }
    close(conn->fd);
    free(conn);
}

ConnectionPool* create_pool(size_t capacity) {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (!pool) {
        return NULL;
    }
    pool->connections = (Connection**)calloc(capacity, sizeof(Connection*));
    if (!pool->connections) {
        free(pool);
        return NULL;
    }
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_pool(ConnectionPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        destroy_connection(pool->connections[i]);
    }
    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

ConnectionStatus connect_async(ConnectionPool* pool, const char* hostname, uint16_t port) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return CONN_FAILURE;
    }
    Connection* conn = create_connection(socket(AF_INET6, SOCK_STREAM, 0), "", port);
    if (!conn) {
        pthread_mutex_unlock(&pool->lock);
        return CONN_FAILURE;
    }
    struct addrinfo hints, *res, *res0;
    int err;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if ((err = getaddrinfo(hostname, NULL, &hints, &res0)) != 0) {
        destroy_connection(conn);
        pthread_mutex_unlock(&pool->lock);
        return CONN_FAILURE;
    }
    for (res = res0; res; res = res->ai_next) {
        char ipstr[INET6_ADDRSTRLEN];
        if (getnameinfo(res->ai_addr, res->ai_addrlen, ipstr, sizeof(ipstr), NULL, 0, NI_NUMERICHOST) == 0) {
            strcpy(conn->remote_ip, ipstr);
            break;
        }
    }
    freeaddrinfo(res0);
    if (!connect(conn->fd, (struct sockaddr*)res->ai_addr, res->ai_addrlen)) {
        pool->connections[pool->size++] = conn;
        pthread_mutex_unlock(&pool->lock);
        return CONN_SUCCESS;
    } else {
        destroy_connection(conn);
        pthread_mutex_unlock(&pool->lock);
        return CONN_TEMP_FAILURE;
    }
}

