    time_t timestamp;
    char userInfo[256];
    char metadata[1024];
} UserAuthentication;

NFAPI_CRC_INDICATION_PDU_T* crcAndOAuthInitialize(int *successfulAllocations, int *failedAllocations) {
    NFAPI_CRC_INDICATION_PDU_T *pduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    UserAuthentication *authArray = (UserAuthentication *)malloc(N * sizeof(UserAuthentication));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < N; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pduArray[i].RNTI = rand() % 256;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        pduArray[i].CRCFLAG = rand() % 2;

        if (pduArray[i].CRCFLAG == 0) {
            (*successfulAllocations)++;
        } else {
            (*failedAllocations)++;
        }

        authArray[i].timestamp = time(NULL);
        snprintf(authArray[i].accessToken, sizeof(authArray[i].accessToken), "token%d", i);
        snprintf(authArray[i].userInfo, sizeof(authArray[i].userInfo), "user%d", i);
        snprintf(authArray[i].metadata, sizeof(authArray[i].metadata), "meta%d", i);

        pthread_mutex_lock(&mutex);
    }

    pthread_mutex_unlock(&mutex);

    return pduArray;
}

