#include <unistd.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>

#define MAX_CONNECTIONS 100
#define DNS_CACHE_SIZE 10
#define MAX_RETRIES 3

typedef struct {
    int sockfd;
    char remote_ip[INET6_ADDRSTRLEN];
    int port;
} TCPConnection;

TCPConnection *connection_pool[MAX_CONNECTIONS];
sem_t connection_pool_mutex;
sem_t dns_cache_mutex;
int next_connection_id = 0;

void initialize_connection_pool() {
    sem_init(&connection_pool_mutex, 0, 1);
}

void release_connection_pool() {
    sem_destroy(&connection_pool_mutex);
}

TCPConnection *acquire_connection() {
    TCPConnection *conn;
    sem_wait(&connection_pool_mutex);
    if (next_connection_id >= MAX_CONNECTIONS) {
        sem_post(&connection_pool_mutex);
        return NULL; // Pool is full
    }
    conn = connection_pool[next_connection_id++];
    sem_post(&connection_pool_mutex);
    return conn;
}

void release_connection(TCPConnection *conn) {
    sem_wait(&connection_pool_mutex);
    if (next_connection_id > 0 && next_connection_id <= MAX_CONNECTIONS) {
        next_connection_id--;
    }
    sem_post(&connection_pool_mutex);
}

int initialize_tcp_connection(const char *hostname, int port) {
    TCPConnection *conn = acquire_connection();
    if (!conn) return -1; // Pool is full

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        release_connection(conn);
        return -1; // DNS resolution failed
    }

    conn->sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (conn->sockfd == -1) {
        freeaddrinfo(res);
        release_connection(conn);
        return -1; // Socket creation failed
    }

    memcpy(&conn->port, &res->ai_addr->sa_data[2], sizeof(int));
    inet_ntop(res->ai_family, res->ai_addr->sa_data, conn->remote_ip, INET6_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

