#include <iostream>
#include <unordered_map>
#include <string>
#include <mutex>
#include <thread>
#include <fstream>

class UserProfile {
    std::string id;
    std::string name;
    int age;

public:
    UserProfile(std::string id, std::string name, int age) : id(id), name(name), age(age) {}

    std::string getId() const { return id; }
    std::string getName() const { return name; }
    void setName(const std::string& name) { this->name = name; }
    int getAge() const { return age; }
    void setAge(int age) { this->age = age; }
};

class UserProfileManager {
    std::unordered_map<std::string, UserProfile> users;
    std::mutex mutex;

public:
    void add(const std::string& id, const std::string& name, int age) {
        std::lock_guard<std::mutex> lock(mutex);
        if (users.find(id) != users.end()) {
            std::cerr << "User already exists." << std::endl;
            return;
        }
        users[id] = UserProfile(id, name, age);
        std::cout << "User added successfully." << std::endl;
    }

    void update(const std::string& id, const std::string& name, int age) {
        std::lock_guard<std::mutex> lock(mutex);
        if (users.find(id) == users.end()) {
            std::cerr << "User not found." << std::endl;
            return;
        }
        users[id].setName(name);
        users[id].setAge(age);
        std::cout << "User updated successfully." << std::endl;
    }

    void deleteUser(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (users.find(id) == users.end()) {
            std::cerr << "User not found." << std::endl;
            return;
        }
        users.erase(id);
        std::cout << "User deleted successfully." << std::endl;
    }

    void query(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (users.find(id) == users.end()) {
            std::cerr << "User not found." << std::endl;
            return;
        }
        const UserProfile& user = users[id];
        std::cout << "ID: " << user.getId() << ", Name: " << user.getName() << ", Age: " << user.getAge() << std::endl;
    }

    void saveToLog(const std::string& message) {
        static std::ofstream logFile("user_log.txt", std::ios_base::app);
        if (logFile.is_open()) {
            logFile << message << std::endl;
        }
    }
};

class CommandProcessor {
    UserProfileManager manager;

public:
    void processCommand(const std::string& command, const std::vector<std::string>& args) {
        try {
            if (command == "add") {
                if (args.size() != 3) throw std::invalid_argument("Invalid arguments for add.");
                manager.add(args[0], args[1], std::stoi(args[2]));
                manager.saveToLog("Add command executed: ID=" + args[0]);
            } else if (command == "update") {
                if (args.size() != 3) throw std::invalid_argument("Invalid arguments for update.");
                manager.update(args[0], args[1], std::stoi(args[2]));
                manager.saveToLog("Update command executed: ID=" + args[0]);
            } else if (command == "delete") {
                if (args.size() != 1) throw std::invalid_argument("Invalid arguments for delete.");
                manager.deleteUser(args[0]);
                manager.saveToLog("Delete command executed: ID=" + args[0]);
            } else if (command == "query") {
                if (args.size() != 1) throw std::invalid_argument("Invalid arguments for query.");
                manager.query(args[0]);
                manager.saveToLog("Query command executed: ID=" + args[0]);
            } else if (command == "help") {
                std::cout << "Available commands: add, update, delete, query, help" << std::endl;
            } else {
                throw std::invalid_argument("Unknown command.");
            }
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }
};

int main() {
    CommandProcessor processor;

    while (true) {
        std::string input;
        std::getline(std::cin, input);
        if (input == "exit") break;

        size_t pos = input.find(' ');
        std::string command = pos != std::string::npos ? input.substr(0, pos) : input;
        std::vector<std::string> args;
        while ((pos = input.find(' ', pos + 1)) != std::string::npos) {
            args.push_back(input.substr(pos + 1, pos - pos - 1));
        }
        if (pos != std::string::npos) args.push_back(input.substr(pos + 1));

        processor.processCommand(command, args);
    }

    return 0;
}
