typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduArray;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PDU_Array;

void initializePDUArray(PDU_Array *array, size_t initialCapacity) {
    array->pduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->pduArray) {
        perror("Failed to allocate memory for PDU array");
        exit(EXIT_FAILURE);
    }
    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void expandPDUArray(PDU_Array *array) {
    size_t newCapacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->pduArray, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        perror("Failed to reallocate memory for PDU array");
        exit(EXIT_FAILURE);
    }
    array->pduArray = newArray;
    array->capacity = newCapacity;
}

void addPDUToArray(PDU_Array *array, NFAPI_CRC_INDICATION_PDU_T pdu, int (*validateCRC)(int), FILE *logFile) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        expandPDUArray(array);
    }
    if (validateCRC(pdu.CRC_INDICATION_REL8_TAG)) {
        array->pduArray[array->count++] = pdu;
        fprintf(logFile, "PDU created: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    } else {
        fprintf(logFile, "CRC validation failed for PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    }
    pthread_mutex_unlock(&array->mutex);
}

void destroyPDUArray(PDU_Array *array) {
    free(array->pduArray);
    array->pduArray = NULL;
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_destroy(&array->mutex);
}
