    for (uint32_t i = 0; i < count; ++i) {
        pthread_mutex_lock(mutex);
        array[i] = malloc(sizeof(MAC_PDU));
        if (!array[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            for (uint32_t j = 0; j < i; ++j) free(array[j]);
            free(array);
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        pthread_mutex_unlock(mutex);

        // Populate MAC_PDU structure
        array[i]->PDCP_SN = generate_pdcp_sn(); // Implement function to generate SN
        uint16_t rlc_status = generate_rlc_status(); // Implement function to generate RLC status
        RLC_STATUS status = validate_rlc_status(rlc_status);
        if (status == RLC_STATUS_VALID) {
            array[i]->RLC_STATUS_REPORT = rlc_status;
        } else {
            array[i]->RLC_STATUS_REPORT = 0; // Set invalid status to a default value
        }
        array[i]->event = generate_mac_event(); // Implement function to generate MAC event

        log_pdu_creation(array[i]);
    }

    return array;
}

// Example usage
int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    FILE *log_file = fopen("pdu_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    uint32_t count = 1000;
    MAC_PDU **pdus = create_mac_pdus(count, &mutex, log_file);
    if (pdus) {
        // Process PDUs
        for (uint32_t i = 0; i < count; ++i) free(pdus[i]);
        free(pdus);
    }

    fclose(log_file);
    return 0;
}
