#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t* record;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_and_init_list(int size) {
    if (size > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: List size exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return NULL;
    }

    long* offsets = malloc((size + 1) * sizeof(long)); // Extra space for the last offset
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        free(list);
        return NULL;
    }

    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(list);
        free(offsets);
        return NULL;
    }

    record_t** records = malloc(size * sizeof(record_t*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(list);
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));

    long current_offset = 0;
    for (int i = 0; i < size; i++) {
        offsets[i] = current_offset;
        current_offset += rand() % 1001;

        keys[i] = -500 + rand() % 1001;

        records[i] = malloc(sizeof(record_t));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record at index %d.\n", i);
            free(list);
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            return NULL;
        }

        records[i]->value = rand() % 501;

        list[i].offset = offsets[i];
        list[i].key = keys[i];
        list[i].record = records[i];
    }

    offsets[size] = current_offset; // Last offset

    printf("Memory usage statistics:\n");
    printf("Total allocated memory: %zu bytes\n", size * sizeof(NFAPI_CRC_INDICATION_PDU_T) + (size + 1) * sizeof(long) + size * sizeof(int) + size * sizeof(record_t*));
    printf("Peak memory usage: %zu bytes\n", current_offset);

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i].record);
    }
    free(list);
}

int main() {
    int size = 1000;
    NFAPI_CRC_INDICATION_PDU_T* list = generate_and_init_list(size);
    if (list) {
        // Use the list...
        free_list(list, size);
    }
    return 0;
}
