    int value;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
} record;

typedef struct {
    void* data;
    size_t size;
    size_t capacity;
} dynamic_array;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T* create_nfa_crc_indication_list(size_t N) {
    if (N > MAX_LIST_SIZE) {
        printf("Error: List size exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for list.");
        return NULL;
    }

    list->offsets = (long*)calloc(N, sizeof(long));
    if (!list->offsets) {
        perror("Failed to allocate memory for offsets.");
        free(list);
        return NULL;
    }

    list->keys = (int*)malloc(N * sizeof(int));
    if (!list->keys) {
        perror("Failed to allocate memory for keys.");
        free(list->offsets);
        free(list);
        return NULL;
    }

    list->records = (record**)malloc(N * sizeof(record*));
    if (!list->records) {
        perror("Failed to allocate memory for records.");
        free(list->keys);
        free(list->offsets);
        free(list);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        list->records[i] = (record*)malloc(sizeof(record));
        if (!list->records[i]) {
            perror("Failed to allocate memory for record.");
            for (size_t j = 0; j < i; ++j) {
                free(list->records[j]);
            }
            free(list->keys);
            free(list->offsets);
            free(list);
            return NULL;
        }

        list->records[i]->value = rand() % 501;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        list->offsets[i] = rand() % 1001;
        list->keys[i] = rand() % 1001 - 500;
    }

    list->count = N;
    return list;
}

void free_nfa_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->records[i]);
        }
        free(list->records);
        free(list->keys);
        free(list->offsets);
        free(list);
    }
}

int serialize_nfa_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list, FILE* file) {
    if (!list || !file) {
        return -1;
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->offsets[i], sizeof(long), 1, file);
        fwrite(&list->keys[i], sizeof(int), 1, file);
        fwrite(list->records[i], sizeof(record), 1, file);
    }

    return 0;
}

NFAPI_CRC_INDICATION_LIST_T* deserialize_nfa_crc_indication_list(FILE* file) {
    if (!file) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for list.");
        return NULL;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > MAX_LIST_SIZE) {
        printf("Error: List size exceeds maximum allowed.\n");
        free(list);
        return NULL;
    }

    list->offsets = (long*)calloc(count, sizeof(long));
    if (!list->offsets) {
        perror("Failed to allocate memory for offsets.");
        free(list);
        return NULL;
    }

    list->keys = (int*)malloc(count * sizeof(int));
    if (!list->keys) {
        perror("Failed to allocate memory for keys.");
        free(list->offsets);
        free(list);
        return NULL;
    }

    list->records = (record**)malloc(count * sizeof(record*));
    if (!list->records) {
        perror("Failed to allocate memory for records.");
        free(list->keys);
        free(list->offsets);
        free(list);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        list->records[i] = (record*)malloc(sizeof(record));
        if (!list->records[i]) {
            perror("Failed to allocate memory for record.");
            for (size_t j = 0; j < i; ++j) {
                free(list->records[j]);
            }
            free(list->keys);
            free(list->offsets);
            free(list);
            return NULL;
        }

        fread(&list->offsets[i], sizeof(long), 1, file);
        fread(&list->keys[i], sizeof(int), 1, file);
        fread(list->records[i], sizeof(record), 1, file);
    }

    list->count = count;
    return list;
}
