class UserAccountManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function handleRequest() {
        $request = $_REQUEST;

        if (isset($request['sub_action']) && $request['sub_action'] === 'delete') {
            return $this->deleteUserAccount($request['id']);
        } elseif (isset($request['id'])) {
            return $this->updateUserAccount($request);
        } else {
            return $this->createUserAccount($request);
        }
    }

    private function createUserAccount($data) {
        if (!$this->validateData($data)) {
            return json_encode(['message' => 'error', 'reason' => 'Invalid data']);
        }

        $sql = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([
            ':name' => $data['name'],
            ':email' => $data['email'],
            ':password' => password_hash($data['password'], PASSWORD_DEFAULT)
        ]);

        return json_encode(['message' => 'success']);
    }

    private function updateUserAccount($data) {
        if (!$this->validateData($data)) {
            return json_encode(['message' => 'error', 'reason' => 'Invalid data']);
        }

        $sql = "UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([
            ':id' => $data['id'],
            ':name' => $data['name'],
            ':email' => $data['email'],
            ':password' => password_hash($data['password'], PASSWORD_DEFAULT)
        ]);

        return json_encode(['message' => 'success']);
    }

    private function deleteUserAccount($id) {
        $sql = "DELETE FROM users WHERE id=:id";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([
            ':id' => $id
        ]);

        return json_encode(['message' => 'success']);
    }

    private function validateData($data) {
        // Implement validation logic here
        return true;
    }
}

