#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AesCipher;

int aes_init(AesCipher *cipher, const unsigned char *password, size_t password_len,
             const unsigned char *salt, size_t salt_len, int iterations) {
    if (!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, NULL, cipher->iv)) {
        fprintf(stderr, "Failed to initialize AES context\n");
        return 0;
    }

    // Derive key using a secure hash function
    unsigned char key[32];
    if (!PKCS5_PBKDF2_HMAC_SHA1((const char *)password, password_len, salt, salt_len,
                                  iterations, key, sizeof(key))) {
        fprintf(stderr, "Failed to derive AES key\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        return 0;
    }

    if (!EVP_EncryptInit_ex(cipher->ctx, NULL, NULL, key, cipher->iv)) {
        fprintf(stderr, "Failed to initialize AES context with derived key\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        return 0;
    }

    return 1;
}

int aes_generate_iv(AesCipher *cipher) {
    if (!RAND_bytes(cipher->iv, EVP_CIPHER_block_size(EVP_aes_256_cbc()))) {
        fprintf(stderr, "Failed to generate IV\n");
        return 0;
    }
    return 1;
}

void aes_cleanup(AesCipher *cipher) {
    EVP_CIPHER_CTX_free(cipher->ctx);
    cipher->ctx = NULL;
}
```

