        fprintf(stderr, "Failed to load server certificate or key\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    if (SSL_CTX_use_certificate_file(ctx, client_cert, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ctx, client_cert, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Failed to load client certificate or key\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Set up TLS parameters
    if (!SSL_CTX_set_cipher_list(ctx, "TLS_AES_128_GCM_SHA256")) {
        fprintf(stderr, "Failed to set cipher list\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    if (!SSL_CTX_set_ecdh_auto(ctx, 1)) {
        fprintf(stderr, "Failed to set ECDH auto\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Derive session secrets using a customizable hashing algorithm
    unsigned char derived_key[hash_output_len];
    if (EVP_Digest(shared_key, strlen(shared_key), derived_key, NULL, evp_md, NULL) != hash_output_len) {
        fprintf(stderr, "Failed to derive session key\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Create and configure the SSL object
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Set custom session secrets (if necessary)
    SSL_set_session_secret_cb(ssl, (int (*)(SSL*, int, void*))0, derived_key, hash_output_len);

    // Initialize secure random nonce generation
    if (!RAND_load_file("/dev/urandom", 1024)) {
        fprintf(stderr, "Failed to load entropy for random number generator\n");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return NULL;
    }

    return ssl;
}

// Cleanup function to disable and free resources
void cleanup_tls_session(SSL* ssl, SSL_CTX* ctx) {
    if (ssl) {
        SSL_free(ssl);
    }
    if (ctx) {
        SSL_CTX_free(ctx);
    }
}

int main() {
    const char* server_cert = "server.crt";
    const char* client_cert = "client.crt";
    const char* shared_key = "shared_secret";

    // Initialize TLS session with custom hash function
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = init_tls_session(server_cert, client_cert, shared_key, EVP_sha256()->md_size, EVP_sha256());

    if (ssl) {
        // Perform TLS handshake and other operations here
        cleanup_tls_session(ssl, ctx);
    }

    return 0;
}
