#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    struct State* next;
    pthread_mutex_t mutex; // Mutex for thread-safe updates
} State;

State* createStateList(int* states, int numStates, FSA* fsa, int lastState) {
    if (numStates == 0 || states == NULL) return NULL;

    State* head = NULL;
    State** current = &head;

    for (int i = 0; i < numStates; i++) {
        // Check for duplicates
        int exists = 0;
        State* temp = head;
        while (temp != NULL) {
            if (temp->id == states[i]) {
                exists = 1;
                break;
            }
            temp = temp->next;
        }

        if (!exists) {
            State* newState = (State*)malloc(sizeof(State));
            if (newState == NULL) return NULL; // Memory allocation failed

            pthread_mutex_init(&newState->mutex, NULL);
            newState->id = states[i];
            newState->next = NULL;

            *current = newState;
            current = &newState->next;
        }
    }

    if (lastState != -1 && head != NULL) {
        State* lastNode = head;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }
        pthread_mutex_lock(&lastNode->mutex);
        lastNode->next = head; // Update 'next' pointer to point to the new state list
        pthread_mutex_unlock(&lastNode->mutex);
    }

    return head;
}
