class SecureRandomPduGenerator {
private:
    struct NFAPI_CRC_INDICATION_PDU_T {
        int RX_UE_INFORMATION_TAG;
        int RNTI;
        int CRC_INDICATION_REL8_TAG;
        bool CRCFLAG;
    };

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduArray;
    std::mutex mtx;
    std::random_device rd;
    std::mt19937 gen;

public:
    SecureRandomPduGenerator(int seed) : gen(seed), rd(rd()) {}

    void resetGenerators() {
        std::lock_guard<std::mutex> lock(mtx);
        gen.seed(rd());
        pduArray.clear();
    }

    NFAPI_CRC_INDICATION_PDU_T generatePdu() {
        std::lock_guard<std::mutex> lock(mtx);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = generateRandomInt(1, 1000);
        pdu.RNTI = generateRandomInt(100, 5000);
        pdu.CRC_INDICATION_REL8_TAG = generateRandomInt(1, 100);
        pdu.CRCFLAG = generateRandomBool();
        return pdu;
    }

    std::string ToString() {
        std::lock_guard<std::mutex> lock(mtx);
        std::ostringstream oss;
        for (const auto& pdu : pduArray) {
            oss << "RX_UE_INFORMATION_TAG: " << pdu.RX_UE_INFORMATION_TAG 
                << ", RNTI: " << pdu.RNTI 
                << ", CRC_INDICATION_REL8_TAG: " << pdu.CRC_INDICATION_REL8_TAG 
                << ", CRCFLAG: " << (pdu.CRCFLAG ? "true" : "false") << std::endl;
        }
        return oss.str();
    }

private:
    int generateRandomInt(int min, int max) {
        return std::uniform_int_distribution<>(min, max)(gen);
    }

    bool generateRandomBool() {
        return std::uniform_int_distribution<>(0, 1)(gen);
    }
};

int main() {
    SecureRandomPduGenerator generator(42);
    generator.resetGenerators();

    for (int i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generator.generatePdu();
        std::cout << generator.ToString() << std::endl;
    }

    return 0;
}
