import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class RealTimeDataProcessor {
    private ConcurrentHashMap<String, DataBuffer> buffers;
    private ExecutorService aggregationExecutor;
    private Logger logger;
    private int bufferSize;
    private double anomalyDetectionSensitivity;
    private long maxMessageLength;
    private String logFilePattern;

    public RealTimeDataProcessor(int bufferSize, double anomalyDetectionSensitivity, long maxMessageLength, String logFilePattern) {
        this.buffers = new ConcurrentHashMap<>();
        this.aggregationExecutor = Executors.newCachedThreadPool();
        this.logger = new Logger(maxMessageLength, logFilePattern);
        this.bufferSize = bufferSize;
        this.anomalyDetectionSensitivity = anomalyDetectionSensitivity;
        this.maxMessageLength = maxMessageLength;
        this.logFilePattern = logFilePattern;
    }

    public void processData(String data) {
        buffers.computeIfAbsent(data.split(":")[0], k -> new DataBuffer(bufferSize)).addData(data);
    }

    public void aggregateData(String windowKey, AggregationFunction function) throws InterruptedException {
        DataBuffer buffer = buffers.get(windowKey);
        if (buffer != null) {
            aggregationExecutor.submit(() -> {
                try {
                    long startTime = System.currentTimeMillis();
                    Object result = function.apply(buffer.getData());
                    logger.log("INFO", "Aggregated data for " + windowKey + ": " + result);
                    if (System.currentTimeMillis() - startTime > maxMessageLength) {
                        logger.log("WARNING", "Aggregation took longer than expected: " + (System.currentTimeMillis() - startTime) + "ms");
                    }
                } catch (Exception e) {
                    logger.log("ERROR", "Error during data aggregation: " + e.getMessage());
                }
            });
        }
    }

    public void resetProcessor() {
        buffers.clear();
        aggregationExecutor.shutdownNow();
        aggregationExecutor = Executors.newCachedThreadPool();
        logger.resetLogFiles();
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("RealTimeDataProcessor{\n");
        for (String key : buffers.keySet()) {
            sb.append("  Buffer ").append(key).append(": ").append(buffers.get(key).toString()).append("\n");
        }
        sb.append("  Log Level: ").append(logger.getCurrentLevel()).append("\n}");
        return sb.toString();
    }

    public void setAnomalyDetectionSensitivity(double sensitivity) {
        this.anomalyDetectionSensitivity = sensitivity;
    }

    // Inner class for data buffer
    private static class DataBuffer {
        private Object[] data;
        private int size;

        public DataBuffer(int capacity) {
            this.data = new Object[capacity];
            this.size = 0;
        }

        public synchronized void addData(Object obj) {
            if (size < data.length) {
                data[size++] = obj;
            }
        }

        public synchronized Object[] getData() {
            return data.clone();
        }

        @Override
        public String toString() {
            return "DataBuffer{" +
                    "size=" + size +
                    '}';
        }
    }

    // Interface for aggregation functions
    @FunctionalInterface
    public interface AggregationFunction {
        Object apply(Object[] data) throws Exception;
    }

    // Simple logger class
    private static class Logger {
        private String currentLevel;
        private String logFilePattern;
        private ExecutorService loggingExecutor;

        public Logger(long maxMessageLength, String logFilePattern) {
            this.currentLevel = "INFO";
            this.logFilePattern = logFilePattern;
            this.loggingExecutor = Executors.newSingleThreadExecutor();
        }

        public void log(String level, String message) {
            if (level.compareTo(currentLevel) >= 0) {
                loggingExecutor.submit(() -> {
                    try {
                        System.out.println("[" + level + "] " + message);
                        // Here you would add code to write the message to a file
                    } catch (Exception e) {
                        System.err.println("Error writing log: " + e.getMessage());
                    }
                });
            }
        }

        public void resetLogFiles() {
            loggingExecutor.shutdownNow();
            loggingExecutor = Executors.newSingleThreadExecutor();
        }

        public String getCurrentLevel() {
            return currentLevel;
        }

        public long getMaxMessageLength() {
            // Not used in this simple example
            return 0;
        }
    }
}
```

