// StringHasher.java

import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Properties;

public final class StringHasher {

    private static Properties config = new Properties();

    static {
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            config.load(fis);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration file", e);
        }
    }

    public enum HashAlgorithm {
        MD5,
        SHA_256,
        CUSTOM
    }

    private static String hash(String input, HashAlgorithm algorithm) {
        try {
            MessageDigest md = MessageDigest.getInstance(algorithm.name());
            byte[] digest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Unsupported hash algorithm: " + algorithm);
        }
    }

    public static String hashString(String input, HashAlgorithm algorithm) {
        if (input == null || input.isEmpty()) {
            return "";
        }
        return hash(input, algorithm);
    }

    public static void main(String[] args) {
        // Example usage
        String input = "Hello, World!";
        HashAlgorithm selectedAlgorithm = HashAlgorithm.valueOf(config.getProperty("hash.algorithm", "MD5").toUpperCase());
        System.out.println("Hashed: " + hashString(input, selectedAlgorithm));
    }
}
