} TLSConfig;

int initialize_tls_session(TLSConfig *config, const char *server_cert, const char *client_cert) {
    config->ctx = SSL_CTX_new(TLS_method());
    if (!config->ctx) {
        fprintf(stderr, "Failed to create TLS context\n");
        return -1;
    }

    // Load server and client certificates
    if (SSL_CTX_use_certificate_file(config->ctx, server_cert, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(config->ctx, server_cert, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_load_verify_locations(config->ctx, NULL, "/etc/ssl/certs") <= 0) {
        fprintf(stderr, "Failed to load certificates\n");
        SSL_CTX_free(config->ctx);
        return -1;
    }

    // Set hash algorithm and output length
    config->hash_algo = EVP_sha256(); // Change this based on the desired hash algo
    config->hash_output_length = EVP_MD_size(config->hash_algo);

    return 0;
}

int generate_secure_nonce(unsigned char *output, size_t output_len) {
    if (RAND_bytes(output, output_len) != 1) {
        fprintf(stderr, "Failed to generate secure nonce\n");
        return -1;
    }
    return 0;
}

void cleanup_tls_session(TLSConfig *config) {
    SSL_CTX_free(config->ctx);
    EVP_cleanup();
}

