typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t block_size;
    size_t free_blocks;
    pthread_mutex_t lock;
} MemoryPoolAllocator;

void* custom_malloc(MemoryPoolAllocator* allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);
    if (allocator->free_blocks > 0) {
        void* block = allocator->memory_pool + ((allocator->pool_size - allocator->block_size * allocator->free_blocks) / allocator->block_size) * allocator->block_size;
        allocator->free_blocks--;
        pthread_mutex_unlock(&allocator->lock);
        return block;
    } else {
        pthread_mutex_unlock(&allocator->lock);
        fprintf(stderr, "Memory allocation failure\n");
        exit(1);
    }
}

void custom_free(MemoryPoolAllocator* allocator, void* ptr) {
    pthread_mutex_lock(&allocator->lock);
    size_t index = ((char*)ptr - (char*)allocator->memory_pool) / allocator->block_size;
    if (index >= allocator->pool_size / allocator->block_size || allocator->memory_pool + index * allocator->block_size != ptr) {
        fprintf(stderr, "Invalid pointer\n");
        exit(1);
    }
    allocator->free_blocks++;
    pthread_mutex_unlock(&allocator->lock);
}

void init_memory_pool(MemoryPoolAllocator* allocator, size_t pool_size, size_t block_size) {
    allocator->memory_pool = malloc(pool_size);
    if (!allocator->memory_pool) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(1);
    }
    allocator->pool_size = pool_size;
    allocator->block_size = block_size;
    allocator->free_blocks = pool_size / block_size;
    pthread_mutex_init(&allocator->lock, NULL);
}

void deinit_memory_pool(MemoryPoolAllocator* allocator) {
