typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_PDUS];
    int size;
    int head;
    int tail;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, int max_pdus) {
    pool->size = 0;
    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) return NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->size < MAX_PDUS) {
        pool->pool[pool->tail] = pdu;
        pool->tail = (pool->tail + 1) % MAX_PDUS;
        pool->size++;
    } else {
        free(pdu);
    }
    pthread_mutex_unlock(&pool->lock);

    return pdu;
}

void deallocate_pdu(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    int index = -1;
    for (int i = 0; i < pool->size; i++) {
        if (pool->pool[(pool->head + i) % MAX_PDUS] == pdu) {
            index = (pool->head + i) % MAX_PDUS;
            break;
        }
    }
    if (index != -1) {
        for (int i = index; i < pool->tail; i++) {
            pool->pool[i] = pool->pool[(i + 1) % MAX_PDUS];
        }
        pool->tail--;
        pool->size--;
    }
    pthread_mutex_unlock(&pool->lock);
}

void* create_pdu(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(pool);
    if (pdu == NULL) return NULL;

    // Populate the PDU with random values and validate CRC flag
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 1024;
    pdu->CRCFLAG = rand() % 2;

    // Validate CRC flag (example criteria)
    if (pdu->CRCFLAG != 1) {
        deallocate_pdu(pool, pdu);
        return NULL;
    }

    // Log the creation of the PDU
    printf("PDU created: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);

    return pdu;
}

void monitor_memory_usage(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    printf("Memory pool usage: %d/%d PDU(s)\n", pool->size, MAX_PDUS);
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool);

    // Simulate concurrent creation of PDUs
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, create_pdu, &pool);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    monitor_memory_usage(&pool);

    return 0;
}
