    logFiles[INFO] = fopen("info.log", "a");
    logFiles[WARNING] = fopen("warning.log", "a");
    logFiles[ERROR] = fopen("error.log", "a");

    cipherCtx = EVP_CIPHER_CTX_new();
}

void closeLogs() {
    for (int i = DEBUG; i <= ERROR; ++i) {
        if (logFiles[i]) {
            fclose(logFiles[i]);
        }
    }

    EVP_CIPHER_CTX_free(cipherCtx);
}

void logMessage(int level, const char *message) {
    FILE *file = logFiles[level];
    if (file) {
        fprintf(file, "%s\n", message);
        fflush(file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Failed to open log file for writing.\n");
    }
}

EVP_CIPHER_CTX* performCryptoOperation(const char *input) {
    // Example cryptographic operation using OpenSSL
    EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, (unsigned char*)"0123456789abcdef", (unsigned char*)"0123456789abcdef");
    int outLen;
    unsigned char output[128];

    if (!EVP_EncryptUpdate(cipherCtx, output, &outLen, (const unsigned char*)input, strlen(input))) {
        logMessage(ERROR, "Failed to perform cryptographic operation.");
        return NULL;
    }

    // Handle the remaining data
    int finalLen;
    EVP_EncryptFinal_ex(cipherCtx, output + outLen, &finalLen);

    // Combine both parts
    int totalLen = outLen + finalLen;

    // Create a new buffer for the cipher object
    EVP_CIPHER_CTX* newCipherCtx = EVP_CIPHER_CTX_new();
    if (!newCipherCtx) {
        logMessage(ERROR, "Failed to create new cipher context.");
        return NULL;
    }

    if (!EVP_EncryptInit_ex(newCipherCtx, EVP_aes_256_cbc(), NULL, (unsigned char*)"0123456789abcdef", (unsigned char*)"0123456789abcdef")) {
        logMessage(ERROR, "Failed to initialize new cipher context.");
        EVP_CIPHER_CTX_free(newCipherCtx);
        return NULL;
    }

    if (!EVP_EncryptUpdate(newCipherCtx, output, &outLen, output, totalLen)) {
        logMessage(ERROR, "Failed to perform cryptographic operation on combined data.");
        EVP_CIPHER_CTX_free(newCipherCtx);
        return NULL;
    }

    int finalFinalLen;
    EVP_EncryptFinal_ex(newCipherCtx, output + outLen, &finalFinalLen);

    // Log the result
    logMessage(INFO, "Crypto operation successful.");

    return newCipherCtx;
}
