    private final ExecutorService executorService;
    private final Logger logger;

    public NetworkMetricsAnalyzer(int bufferSize, int windowSize) {
        this.packetBuffers = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.logger = new Logger("NetworkMetricsAnalyzer.log", 1024 * 1024);
    }

    public void processPacket(NetworkPacket packet) {
        // Process and categorize the packet
        String key = packet.getProtocol() + ":" + packet.getSourceIP() + ":" + packet.getDestinationIP();
        packetBuffers.computeIfAbsent(key, k -> new ConcurrentLinkedQueue<>()).offer(packet);
    }

    public void analyzeNetworkMetrics(int windowSize, AggregationFunction function) {
        // Analyze network metrics in real-time
        executorService.submit(() -> {
            for (ConcurrentLinkedQueue<NetworkPacket> queue : packetBuffers.values()) {
                while (!queue.isEmpty()) {
                    NetworkPacket packet = queue.poll();
                    function.aggregate(packet);
                }
            }
        });
    }

    public void logAsync(String message, LogLevel level) {
        logger.log(message, level);
    }

    public void resetAnalyzer() {
        // Reset the analyzer to its initial state
        packetBuffers.clear();
    }

    @Override
    public String toString() {
        return "NetworkMetricsAnalyzer{" +
                "packetBuffers=" + packetBuffers +
                ", executorService=" + executorService +
                ", logger=" + logger +
                '}';
    }

