#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_NODES 100
#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 4096

typedef struct {
    char key[MAX_KEY_LENGTH];
    char value[MAX_VALUE_LENGTH];
} CacheEntry;

typedef struct {
    pthread_mutex_t lock;
    int capacity;
    int size;
    CacheEntry entries[MAX_NODES];
} DistributedCache;

DistributedCache cache_cluster[MAX_NODES];

int consistent_hashing(char* key, int num_nodes) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % num_nodes;
}

void* cache_manager(void* arg) {
    int node_id = *(int*)arg;
    free(arg);

    while (1) {
        // Simulate client requests
        for (int i = 0; i < 10; i++) {
            char key[MAX_KEY_LENGTH];
            sprintf(key, "key%d", rand() % MAX_NODES);
            int node = consistent_hashing(key, MAX_NODES);
            pthread_mutex_lock(&cache_cluster[node].lock);
            if (node == node_id) {
                // Simulate read/write operations
                CacheEntry* entry = &cache_cluster[node].entries[i];
                if (strcmp(entry->key, key) == 0) {
                    printf("Node %d: Reading %s = %s\n", node_id, entry->key, entry->value);
                } else {
                    strcpy(entry->key, key);
                    sprintf(entry->value, "value%d", rand() % MAX_NODES);
                    printf("Node %d: Writing %s = %s\n", node_id, entry->key, entry->value);
                }
            }
            pthread_mutex_unlock(&cache_cluster[node].lock);
        }
        sleep(1); // Simulate time delay
    }

    return NULL;
}

void initialize_cache_cluster() {
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_mutex_init(&cache_cluster[i].lock, NULL);
        cache_cluster[i].capacity = 1000; // Maximum capacity per node
        cache_cluster[i].size = 0;
    }
}

void cleanup_cache_cluster() {
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_mutex_destroy(&cache_cluster[i].lock);
    }
}

int main() {
    initialize_cache_cluster();

    pthread_t nodes[MAX_NODES];
    for (int i = 0; i < MAX_NODES; i++) {
        int* node_id = malloc(sizeof(int));
        *node_id = i;
        pthread_create(&nodes[i], NULL, cache_manager, node_id);
    }

    // Simulate running for some time
    sleep(60);

    cleanup_cache_cluster();

    return 0;
}
