public class StringHasher {
    private static final Map<String, MessageDigest> digestMap = new HashMap<>();
    private static final long[] cache = new long[1024];

    static {
        initDigests();
    }

    private static void initDigests() {
        try {
            digestMap.put("MD5", MessageDigest.getInstance("MD5"));
            digestMap.put("SHA-256", MessageDigest.getInstance("SHA-256"));
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Error initializing digests", e);
        }
    }

    public static byte[] hash(String input, String algorithm) {
        if (input == null || algorithm == null) {
            return null;
        }
        MessageDigest digest = digestMap.get(algorithm);
        if (digest == null) {
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }
        synchronized (digest) {
            digest.reset();
            digest.update(input.getBytes());
            return digest.digest();
        }
    }

    public static void batchHash(String[] inputs, String algorithm) {
        for (String input : inputs) {
            hash(input, algorithm);
        }
    }

    // Additional methods and configurations can be added here
}
