def calculate_md5(file_path, chunk_size=64*1024, expected_hash=None):
    md5 = hashlib.md5()
    try:
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                md5.update(data)

