} Metadata;

const char* appendChecksumIfValid(const char* filePath, size_t sizeLimit, char* buffer, Metadata* metadata, int metadataCount) {
    if (filePath == NULL || buffer == NULL) {
        return NULL;
    }

    FILE* file = fopen(filePath, "r");
    if (!file) {
        logFailedOperation("File does not exist or is inaccessible.");
        return NULL;
    }
    fclose(file);

    size_t pathLength = strlen(filePath);
    if (pathLength + 10 > sizeLimit) { // Assuming checksum length <= 10
        logFailedOperation("Path exceeds size limit.");
        return NULL;
    }

    snprintf(buffer, sizeLimit, "%s", filePath);
    for (int i = 0; i < metadataCount; ++i) {
        char* pos = strstr(buffer, metadata[i].key);
        if (pos != NULL) {
            snprintf(pos, sizeLimit - (pos - buffer), "%s", metadata[i].value);
        }
    }

    return buffer;
}

