typedef struct NFAPI_CRC_INDICATION_PDU_T {
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    NFAPI_CRC_INDICATION_PDU *tail;
    pthread_mutex_t mutex;
    size_t size;
    size_t max_size;
} CyclicList;

void initialize_list(CyclicList *list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->max_size = max_size;
}

void add_to_list(CyclicList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU *new_node = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->timestamp = time(NULL);

    if (list->size >= list->max_size) {
        NFAPI_CRC_INDICATION_PDU *oldest = list->head;
        list->head = list->head->next;
        free(oldest);
        list->size--;
    }

    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU* find_by_rnti(CyclicList *list, int RNTI) {
