    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
    int max_size;
} LinkedList;

void initLinkedList(LinkedList* list, int max_size) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->max_size = max_size;
}

int addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = NULL;
    if (list->tail == NULL) {
        list->head = newNode;
    } else {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int removeElement(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (current == list->tail) {
                list->tail = previous;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

// Function to read elements from the list (example)
void* readElements(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d, Timestamp: %ld\n",
               current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG, (long)current->data.timestamp);
        current = current->next;
    }
    return NULL;
}

// Example usage
