    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 101, 8, rand()};
    NFAPI_CRC_INDICATION_PDU_T data2 = {2, 102, 8, rand()};
    pthread_create(&thread1, NULL, (void*)addElement, &list);
    pthread_create(&thread2, NULL, (void*)addElement, &list);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Simulate reading elements from another thread
    readElements(&list);

    return 0;
}
