} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T**)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 16 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_elements = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_elements == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList *list, size_t index) {
    if (index >= list->size) return NULL;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *element = list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return element;
