#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <arpa/inet.h>

#define N 10

typedef struct SensorData {
    int sensorID;
    time_t timestamp;
    float readingValue;
    char metadata[256];
    int referenceCount;
} SensorData;

u_char* resolveHostnameAndPopulateSensors(const char* hostname, int* numEntries) {
    struct addrinfo hints, *res, *p;
    u_char* ipAddress = (u_char*)malloc(16);
    if (ipAddress == NULL) {
        return NULL; // Memory allocation failed
    }

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        free(ipAddress);
        return NULL; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
        memcpy(ipAddress, &ipv4->sin_addr.s_addr, 4);
        break;
    }

    freeaddrinfo(res);

    SensorData** sensorArray = (SensorData**)malloc(N * sizeof(SensorData*));
    if (sensorArray == NULL) {
        free(ipAddress);
        return NULL; // Memory allocation failed
    }

    *numEntries = N;

    for (int i = 0; i < N; i++) {
        sensorArray[i] = (SensorData*)malloc(sizeof(SensorData));
        if (sensorArray[i] == NULL) {
            // Handle memory allocation failure
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(sensorArray[j]);
            }
            free(sensorArray);
            free(ipAddress);
            return NULL;
        }

        sensorArray[i]->sensorID = i + 1;
        sensorArray[i]->timestamp = time(NULL);
        sensorArray[i]->readingValue = ((float)rand() / RAND_MAX) * 100; // Random value between 0 and 100
        snprintf(sensorArray[i]->metadata, sizeof(sensorArray[i]->metadata), "Sensor %d", i + 1);
        sensorArray[i]->referenceCount = 1;
    }

    return ipAddress;
}

// Function to serialize the populated array to a CSV file format
int serializeToCSV(SensorData** sensorArray, int numEntries, const char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return -1; // Error opening file
    }

    fprintf(fp, "SensorID,Timestamp,ReadingValue,Metadata\n");
    for (int i = 0; i < numEntries; i++) {
        fprintf(fp, "%d,%ld,%f,%s\n", sensorArray[i]->sensorID, sensorArray[i]->timestamp,
                sensorArray[i]->readingValue, sensorArray[i]->metadata);
    }

    fclose(fp);
    return 0;
}

// Function to free memory allocated for SensorData structures
void freeSensorData(SensorData** sensorArray, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        free(sensorArray[i]);
    }
    free(sensorArray);
}
