#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
    size_t max_size;
    size_t current_size;
    time_t cleanup_threshold;
} CRC_LIST;

CRC_LIST* crc_list_init(size_t max_size, time_t cleanup_threshold) {
    CRC_LIST *list = (CRC_LIST*)malloc(sizeof(CRC_LIST));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_size = max_size;
    list->current_size = 0;
    list->cleanup_threshold = cleanup_threshold;

    return list;
}

void crc_list_add(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list->mutex);

    if (list->current_size >= list->max_size) {
        // Handle overflow, e.g., log warning or truncate oldest element
        NFAPI_CRC_INDICATION_PDU_T *oldest = list->head;
        list->head = oldest->next;
        free(oldest);
        list->current_size--;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->mutex);
}

void crc_list_remove_by_rnti(CRC_LIST *list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        if (current->rnti == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->current_size--;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void crc_list_clean_up(CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    time_t now = time(NULL);

    while (current != NULL) {
        if (difftime(now, current->timestamp) > list->cleanup_threshold) {
            NFAPI_CRC_INDICATION_PDU_T *temp = current;
            current = current->next;
            free(temp);
            list->current_size--;
        } else {
            break; // Oldest element is still within the cleanup threshold
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void crc_list_free(CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Usage example
int main() {
    CRC_LIST *list = crc_list_init(10000, 3600); // Max size 10k, cleanup threshold of 1 hour

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->rx_ue_info_tag = some_rx_ue_info;
    new_node->rnti = some_rnti;
    new_node->crc_indication_rel8_tag = some_crc_indication;
    new_node->crcflag = rand() % 2; // Randomly set CRCFLAG
    new_node->timestamp = time(NULL);

    crc_list_add(list, new_node);
    crc_list_remove_by_rnti(list, some_rnti);
    crc_list_clean_up(list);

    crc_list_free(list);

    return 0;
}
