typedef struct {
    u_char ip[4];
} IPAddress;

typedef struct SensorData {
    int id;
    time_t timestamp;
    float reading;
    char metadata[METADATA_SIZE];
    int ref_count;
    struct SensorData* next; // For a simple linked list
} SensorData;

typedef struct {
    SensorData** pool;
    size_t size;
    size_t used;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0};

int initialize_memory_pool(size_t size) {
    memory_pool.pool = (SensorData**)malloc(size * sizeof(SensorData*));
    if (!memory_pool.pool) return -1;
    for (size_t i = 0; i < size; ++i) {
        memory_pool.pool[i] = malloc(sizeof(SensorData));
        if (!memory_pool.pool[i]) {
            while (--i >= 0) free(memory_pool.pool[i]);
            free(memory_pool.pool);
            return -1;
        }
    }
    memory_pool.size = size;
    memory_pool.used = 0;
    return 0;
}

SensorData* allocate_sensor_data() {
    if (memory_pool.used < memory_pool.size) {
        SensorData* data = memory_pool.pool[memory_pool.used++];
        memset(data, 0, sizeof(SensorData));
        data->ref_count = 1;
        return data;
    } else {
        // Implement a more sophisticated memory pool management strategy here
        return malloc(sizeof(SensorData));
    }
}

void free_sensor_data(SensorData* data) {
    if (data) {
        data->ref_count--;
        if (data->ref_count == 0) {
            free(data);
        }
    }
}

int resolveHostnameAndPopulateSensors(const char* hostname, int N, SensorData** sensors) {
    struct hostent *host;
    IPAddress ip;

    // DNS resolution
    host = gethostbyname(hostname);
    if (!host) {
        return -1; // DNS resolution failed
    }

    memcpy(ip.ip, host->h_addr_list[0], sizeof(ip.ip));

    // Populate sensor data
    for (int i = 0; i < N; ++i) {
        SensorData* sensor = allocate_sensor_data();
        if (!sensor) return -1;

        sensor->id = i;
        sensor->timestamp = time(NULL);
        sensor->reading = ((float(rand()) / RAND_MAX) * 100); // Random value between 0 and 100
        snprintf(sensor->metadata, METADATA_SIZE, "Sensor %d", i);

        sensors[i] = sensor;
    }

    return 0; // Success
}

int serialize_to_csv(SensorData** sensors, int N) {
    FILE* fp = fopen("sensors.csv", "w");
    if (!fp) return -1;

    fprintf(fp, "ID,Timestamp,Reading,Metadata\n");
    for (int i = 0; i < N; ++i) {
        SensorData* sensor = sensors[i];
        fprintf(fp, "%d,%ld,%.2f,%s\n", sensor->id, sensor->timestamp, sensor->reading, sensor->metadata);
    }

    fclose(fp);
    return 0;
}

// Example usage
int main() {
    SensorData* sensors[MAX_SENSORS];
    if (resolveHostnameAndPopulateSensors("example.com", MAX_SENSORS, sensors) == 0) {
        serialize_to_csv(sensors, MAX_SENSORS);
        for (int i = 0; i < MAX_SENSORS; ++i) {
            free_sensor_data(sensors[i]);
        }
    } else {
        printf("Failed to resolve hostname or populate sensors\n");
    }
    return 0;
}
