int resolve_hostname(const char* hostname, u_char* ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message(LOG_LEVEL_DEBUG, gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), IP_ADDR_SIZE);
    freeaddrinfo(res);

    return 0;
}

int lookup_cache(const char* hostname, u_char* ip) {
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0 && time(NULL) < cache[i].expiry) {
            memcpy(ip, cache[i].ip, IP_ADDR_SIZE);
            return 1;
        }
    }
    return 0;
}

int add_to_cache(const char* hostname, const u_char* ip) {
    if (cache_count >= CACHE_LIMIT) {
        log_message(LOG_LEVEL_DEBUG, "Cache limit reached. Clearing oldest entry.");
        cache_count--;
    }

    strcpy(cache[cache_count].hostname, hostname);
    memcpy(cache[cache_count].ip, ip, IP_ADDR_SIZE);
    cache[cache_count].expiry = time(NULL) + 3600; // 1 hour

    cache_count++;
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_LEVEL_INFO, "Program interrupted. Resuming processing...");
    }
}

