#include <iostream>
#include <vector>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <string>

class Task {
public:
    virtual void execute() = 0;
    virtual ~Task() {}
};

class TaskQueue {
private:
    std::queue<std::shared_ptr<Task>> tasks;
    std::mutex mutex;
    std::condition_variable condition;
    bool running;

public:
    TaskQueue() : running(true) {}

    void enqueue(std::shared_ptr<Task> task) {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push(task);
        condition.notify_one();
    }

    std::shared_ptr<Task> dequeue() {
        std::unique_lock<std::mutex> lock(mutex);
        while (tasks.empty() && running) {
            condition.wait(lock);
        }
        if (!running) {
            return nullptr;
        }
        auto task = tasks.front();
        tasks.pop();
        return task;
    }

    void stop() {
        running = false;
        condition.notify_all();
    }
};

class TaskProcessor : public std::enable_shared_from_this<TaskProcessor> {
private:
    TaskQueue& queue;

public:
    TaskProcessor(TaskQueue& q) : queue(q) {}

    void process() {
        while (true) {
            auto task = queue.dequeue();
            if (!task) break;
            try {
                task->execute();
                std::cout << "Task executed successfully" << std::endl;
            } catch (const std::exception& e) {
                std::cerr << "Error executing task: " << e.what() << std::endl;
            }
        }
    }

    void startProcessing() {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread(&TaskProcessor::process, shared_from_this()).detach();
        }
    }
};

void handleSignal(int signal) {
    // Gracefully shut down all active tasks
}

int main() {
    TaskQueue queue;
    TaskProcessor processor(queue);

    // Signal handling
    std::signal(SIGINT, handleSignal);

    processor.startProcessing();

    // Enqueue valid tasks from command line arguments

    // Wait for termination signal

    return 0;
}
```

