DynamicList* dynamic_list_init(size_t initial_capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void dynamic_list_free(DynamicList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

