// Java method for calculating MD5 hash with caching

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class HashService {

    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final int MAX_CACHE_SIZE = 1000;
    private static final long CACHE_EXPIRATION_TIME = 3600 * 1000; // 1 hour in milliseconds

    public static synchronized String getMD5(String input) {
        try {
            if (cache.containsKey(input)) {
                return cache.get(input);
            }

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            cache.put(input, hexString.toString());

            // Remove expired entries from the cache
            cache.entrySet().removeIf(entry -> System.currentTimeMillis() - entry.getValue().hashCode() > CACHE_EXPIRATION_TIME);

            if (cache.size() > MAX_CACHE_SIZE) {
                // Implement logic to evict least recently used items or other eviction policy
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }
}
