#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 1024
#define MAX_KEY_SIZE 256
#define MAX_VALUE_SIZE 4096

typedef struct {
    char key[MAX_KEY_SIZE];
    void *value;
    int size;
} CacheEntry;

typedef struct {
    CacheEntry entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DistributedCache;

DistributedCache cache[MAX_NODES];

int hash(const char *key) {
    // Simple hash function
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return (int)(hash % MAX_NODES);
}

void init_cache() {
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_mutex_init(&cache[i].lock, NULL);
        cache[i].count = 0;
    }
}

void *put(const char *key, const void *value, int size) {
    int node = hash(key);
    pthread_mutex_lock(&cache[node].lock);

    for (int i = 0; i < cache[node].count; i++) {
        if (strcmp(cache[node].entries[i].key, key) == 0) {
            // Update existing entry
            free(cache[node].entries[i].value);
            cache[node].entries[i].value = malloc(size);
            memcpy(cache[node].entries[i].value, value, size);
            cache[node].entries[i].size = size;
            pthread_mutex_unlock(&cache[node].lock);
            return NULL; // No new entry created
        }
    }

    if (cache[node].count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&cache[node].lock);
        return "Cache full"; // Cache is full, cannot add more entries
    }

    // Add new entry
    cache[node].entries[cache[node].count].key = strdup(key);
    cache[node].entries[cache[node].count].value = malloc(size);
    memcpy(cache[node].entries[cache[node].count].value, value, size);
    cache[node].entries[cache[node].count].size = size;
    cache[node].count++;

    pthread_mutex_unlock(&cache[node].lock);
    return NULL; // No new entry created
}

void *get(const char *key) {
    int node = hash(key);
    pthread_mutex_lock(&cache[node].lock);

    for (int i = 0; i < cache[node].count; i++) {
        if (strcmp(cache[node].entries[i].key, key) == 0) {
            // Return value
            void *value = malloc(cache[node].entries[i].size);
            memcpy(value, cache[node].entries[i].value, cache[node].entries[i].size);
            pthread_mutex_unlock(&cache[node].lock);
            return value;
        }
    }

    pthread_mutex_unlock(&cache[node].lock);
    return NULL; // Key not found
}

void *delete(const char *key) {
    int node = hash(key);
    pthread_mutex_lock(&cache[node].lock);

    for (int i = 0; i < cache[node].count; i++) {
        if (strcmp(cache[node].entries[i].key, key) == 0) {
            // Delete entry
            free(cache[node].entries[i].value);
            free(cache[node].entries[i].key);
            for (int j = i; j < cache[node].count - 1; j++) {
                cache[node].entries[j] = cache[node].entries[j + 1];
            }
            cache[node].count--;
            pthread_mutex_unlock(&cache[node].lock);
            return NULL; // No new entry created
        }
    }

    pthread_mutex_unlock(&cache[node].lock);
    return "Key not found"; // Key not found
}

void cleanup_cache() {
    for (int i = 0; i < MAX_NODES; i++) {
        for (int j = 0; j < cache[i].count; j++) {
            free(cache[i].entries[j].value);
            free(cache[i].entries[j].key);
        }
        pthread_mutex_destroy(&cache[i].lock);
    }
}

// Example usage
int main() {
    init_cache();

    char *value1 = "Hello, World!";
    put("key1", value1, strlen(value1) + 1);

    char *retrieved_value = (char *)get("key1");
    if (retrieved_value != NULL) {
        printf("Retrieved value: %s\n", retrieved_value);
        free(retrieved_value);
    }

    cleanup_cache();

    return 0;
}
