#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int suspend_flag;
    double memory_compaction_threshold;
    size_t max_size;
} ConcurrentList;

ConcurrentList* create_concurrent_list(size_t max_size) {
    ConcurrentList *list = (ConcurrentList*)malloc(sizeof(ConcurrentList));
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->suspend_flag = 0;
    list->memory_compaction_threshold = 0.5; // Example threshold
    list->max_size = max_size;
    return list;
}

void insert_concurrent_list(ConcurrentList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);
    while (list->suspend_flag) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }
    if (list->max_size > 0 && list_size(list) >= list->max_size) {
        NFAPI_CRC_INDICATION_PDU_T *to_remove = list->head;
        if (to_remove != NULL) {
            remove_concurrent_list(list, to_remove);
        }
    }
    if (list->tail == NULL) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_concurrent_list(ConcurrentList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);
    while (list->suspend_flag) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }
    if (node == list->head && node == list->tail) {
        list->head = list->tail = NULL;
    } else if (node == list->head) {
        list->head = node->next;
        list->head->prev = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        list->tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    free(node);
    pthread_mutex_unlock(&list->lock);
}

size_t list_size(ConcurrentList *list) {
    size_t count = 0;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    while (node != NULL) {
        count++;
        node = node->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void suspend_concurrent_list(ConcurrentList *list) {
    pthread_mutex_lock(&list->lock);
    list->suspend_flag = 1;
    pthread_cond_signal(&list->cond_var);
    pthread_mutex_unlock(&list->lock);
}

void resume_concurrent_list(ConcurrentList *list) {
    pthread_mutex_lock(&list->lock);
    list->suspend_flag = 0;
    pthread_cond_broadcast(&list->cond_var);
    pthread_mutex_unlock(&list->lock);
}
