#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_ELEMENTS 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int count;
} NFAPI_Crc_Indication_Request;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    NFAPI_Crc_Indication_Request queue[MAX_ELEMENTS];
    int front, rear, size;
    sem_t available_spaces;
    sem_t occupied_spaces;
} NFAPI_Crc_Indication_Queue;

void init_queue(NFAPI_Crc_Indication_Queue *queue) {
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
    sem_init(&queue->available_spaces, 0, MAX_ELEMENTS);
    sem_init(&queue->occupied_spaces, 0, 0);
}

void enqueue(NFAPI_Crc_Indication_Queue *queue, NFAPI_Crc_Indication_Request request) {
    sem_wait(&queue->available_spaces);
    pthread_mutex_lock(&queue->lock);
    queue->rear = (queue->rear + 1) % MAX_ELEMENTS;
    queue->queue[queue->rear] = request;
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

NFAPI_Crc_Indication_Request dequeue(NFAPI_Crc_Indication_Queue *queue) {
    NFAPI_Crc_Indication_Request request;
    sem_wait(&queue->occupied_spaces);
    pthread_mutex_lock(&queue->lock);
    request = queue->queue[queue->front];
    queue->front = (queue->front + 1) % MAX_ELEMENTS;
    queue->size--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return request;
}

void* process_queue(void *arg) {
    NFAPI_Crc_Indication_Queue *queue = arg;
    while (1) {
        NFAPI_Crc_Indication_Request request = dequeue(queue);
        // Process the request
        // ...
    }
}

int main() {
    NFAPI_Crc_Indication_Queue queue;
    init_queue(&queue);

    pthread_t thread;
    pthread_create(&thread, NULL, process_queue, &queue);

    // Enqueue requests to the queue
    // ...

    pthread_join(thread, NULL);
    return 0;
}
```

