#define DEFAULT_ITERATIONS 10000

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AESCipherContext;

AESCipherContext* aes_init(const char *password, int iterations) {
    if (!iterations) {
        const char *env_iterations = getenv("AES_ITERATIONS");
        iterations = env_iterations ? atoi(env_iterations) : DEFAULT_ITERATIONS;
    }

    AESCipherContext *ctx = (AESCipherContext*)malloc(sizeof(AESCipherContext));
    if (!ctx) {
        perror("Failed to allocate memory for cipher context");
        return NULL;
    }

    // Generate random IV
    if (!RAND_bytes(ctx->iv, sizeof(ctx->iv))) {
        fprintf(stderr, "Error generating random IV\n");
        free(ctx);
        return NULL;
    }

    // Derive the key using PBKDF2 with SHA-256
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), ctx->iv, sizeof(ctx->iv), iterations, EVP_sha256(), 32, ctx->key) != 1) {
        fprintf(stderr, "Error deriving encryption key\n");
        free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    if (!(ctx->ctx = EVP_CIPHER_CTX_new())) {
        perror("Failed to create cipher context");
        free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        fprintf(stderr, "Error initializing AES-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void aes_cleanup(AESCipherContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        memset(ctx->key, 0, sizeof(ctx->key));
        memset(ctx->iv, 0, sizeof(ctx->iv));
        free(ctx);
    }
}
