Node** createLinkedList(int size) {
    if (size > MAX_NODES) {
        fprintf(stderr, "Error: Maximum number of nodes exceeded.\n");
        return NULL;
    }

    Node** head = (Node**)malloc(size * sizeof(Node*));
    for (int i = 0; i < size; i++) {
        head[i] = (Node*)malloc(sizeof(Node));
        if (head[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            // Cleanup allocated nodes
            for (int j = 0; j < i; j++) free(head[j]);
            free(head);
            return NULL;
        }
    }
    return head;
}

void traverseForward(Node** head, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = head[i];
        while (current != NULL) {
            // Process node
            printf("Node value: %f\n", current->value);
            current = current->next;
        }
    }
}

void traverseReverse(Node** tail, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = tail[i];
        while (current != NULL) {
            // Process node
            printf("Node value: %f\n", current->value);
            current = current->prev;
        }
    }
}

void insertNode(Node** head, int index, double value) {
    if (index < 0 || index >= MAX_NODES) return;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    newNode->value = value;
    newNode->next = head[index];
    head[index] = newNode;
}

void deleteNode(Node** head, int index) {
    if (index < 0 || index >= MAX_NODES) return;

    Node* current = head[index];
    head[index] = current->next;
    free(current);
}

