void parse_log_file(const char* input_file, const char* output_file, const char* rules, int max_lines, int max_line_length, bool advanced_filtering) {
    FILE* log_file = fopen(input_file, "r");
    if (!log_file) {
        perror("Error opening input file");
        return;
    }

    // Allocate memory for lines
    char** lines = (char**)malloc(max_lines * sizeof(char*));
    for (int i = 0; i < max_lines; ++i) {
        lines[i] = (char*)malloc(max_line_length * sizeof(char));
    }

    int line_count = 0;
    while (line_count < max_lines && fgets(lines[line_count], max_line_length, log_file)) {
        // Process each line based on rules
        // ...

        line_count++;
    }
    fclose(log_file);

    // Read and process the last line
    char last_line[256];
    if (read_last_line(input_file, last_line, sizeof(last_line))) {
        // Extract sequence number and handle exceptions
        // ...
    }

    // Sort lines based on custom comparator function
    qsort(lines, line_count, sizeof(char*), custom_sort_function);

    // Write sorted lines to output file
    FILE* summary_file = fopen(output_file, "w");
    if (summary_file) {
        for (int i = 0; i < line_count; ++i) {
            fprintf(summary_file, "%s", lines[i]);
            free(lines[i]); // Free allocated memory for each line
        }
        fclose(summary_file);
    } else {
        perror("Error opening output file");
    }

    // Free memory allocated for lines array
    free(lines);

    // Log processing status to monitoring service using external API
    // ...
}

bool read_last_line(const char* file_name, char* buffer, size_t max_buffer_size) {
    FILE* log_file = fopen(file_name, "r");
    if (!log_file) {
        perror("Error opening input file for reading last line");
        return false;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    fseek(log_file, -max_buffer_size + 1, SEEK_END);

