#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int CELL_ID;
    int PCI;
    int BANDWIDTH;
    char ANTENNA_PATTERN[50];
} LTE_ENODEB_CELL_CONFIG_T;

typedef struct Node {
    LTE_ENODEB_CELL_CONFIG_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} CellConfigList;

void initCellConfigList(CellConfigList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int addCellConfig(CellConfigList* list, LTE_ENODEB_CELL_CONFIG_T config) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    newNode->data = config;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int deleteCellConfig(CellConfigList* list, int cellID) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && current->data.CELL_ID != cellID) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Cell not found
    }
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

LTE_ENODEB_CELL_CONFIG_T* getCellConfig(CellConfigList* list, int cellID) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL && current->data.CELL_ID != cellID) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Cell not found
    }
    LTE_ENODEB_CELL_CONFIG_T* result = &current->data;
    pthread_mutex_unlock(&list->mutex);
    return result;
}

void destroyCellConfigList(CellConfigList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
