#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memoryPool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void* allocate_memory(int num_elements) {
    pthread_mutex_lock(&memoryPool.lock);

    if (memoryPool.elements == NULL || memoryPool.size < num_elements) {
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(memoryPool.elements, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_elements == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&memoryPool.lock);
            return NULL;
        }

        memoryPool.elements = new_elements;
        memoryPool.size = num_elements;
    }

    void* ptr = &memoryPool.elements[memoryPool.size - num_elements];
    pthread_mutex_unlock(&memoryPool.lock);
    return ptr;
}

void free_memory(void* ptr, int num_elements) {
    pthread_mutex_lock(&memoryPool.lock);

    if (ptr >= memoryPool.elements && ptr < memoryPool.elements + memoryPool.size) {
        ptrdiff_t index = (char*)ptr - (char*)memoryPool.elements;
        for (int i = 0; i < num_elements; ++i) {
            // Assuming CRCFLAG needs validation and random setting
            memoryPool.elements[index + i].CRC_INDICATION_REL8_TAG = rand() % 256; // Example range
        }
    } else {
        fprintf(stderr, "Invalid pointer for freeing memory\n");
    }

    pthread_mutex_unlock(&memoryPool.lock);
}

// Function to handle concurrent access and prioritize requests
void* request_memory(void* arg) {
    int num_elements = *(int*)arg;
    void* ptr = allocate_memory(num_elements);
    if (ptr != NULL) {
        // Process memory allocation
        free_memory(ptr, num_elements); // Example usage
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_ELEMENTS];
    int request_sizes[] = {50, 100, 150}; // Example request sizes

    for (int i = 0; i < sizeof(request_sizes) / sizeof(request_sizes[0]); ++i) {
        if (pthread_create(&threads[i], NULL, request_memory, &request_sizes[i]) != 0) {
            perror("Thread creation failed");
        }
    }

    for (int i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free remaining memory
    free_memory(memoryPool.elements, memoryPool.size);
    return 0;
}
```

