['```javascript
function copyBufferChunks(chunks, count) {
  if (count < 0) return Buffer.allocUnsafe(count);

  let totalBytes = 0;
  for (let chunk of chunks) {
    totalBytes += chunk.length;
  }

  if (count <= totalBytes) {
    const result = Buffer.allocUnsafe(count);
    let pos = 0;
    for (let chunk of chunks) {
      if (pos + chunk.length > count) {
        chunk.copy(result, pos, 0, count - pos);
        break;
      }
      chunk.copy(result, pos);
      pos += chunk.length;
    }
    return result;
  } else {
    const result = Buffer.allocUnsafe(count);
    let pos = 0;
    for (let chunk of chunks) {
      if (pos + chunk.length > count) {
        chunk.copy(result, pos, 0, count - pos);
        break;
      }
      chunk.copy(result, pos);
      pos += chunk.length;
    }
    result.fill(0, pos, count);
    return result;
  }
}
