function concatenateBuffers(buffers, maxSize) {
  if (!Array.isArray(buffers)) {
    throw new Error('Input must be an array of buffers.');
  }

  const validBuffers = buffers.filter(buffer => Buffer.isBuffer(buffer));
  if (validBuffers.length !== buffers.length) {
    throw new Error('All elements in the input array must be Buffers.');
  }

  let totalSize = 0;
  for (const buffer of validBuffers) {
    totalSize += buffer.length;
  }

  if (totalSize > maxSize) {
    throw new Error(`Total size of buffers (${totalSize}) exceeds max limit (${maxSize}).`);
  }

  return Buffer.concat(validBuffers);
}
