// Function to dynamically generate and populate an array of NetworkStatus structures
NetworkStatus* generateNetworkStatus(int N, int *status_count) {
    if (N <= 0 || status_count == NULL) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Calculate the required buffer size
    size_t buffer_size = N * sizeof(NetworkStatus);
    NetworkStatus *network_status_array = malloc(buffer_size);

    if (network_status_array == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Populate the array with network status updates
    for (int i = 0; i < N; i++) {
        network_status_array[i].id = i + 1;
        network_status_array[i].timestamp = time(NULL);

        // Simulate signal strength data from an external sensor
        int simulated_signal_strength = rand() % 100 - 30; // Random value between -30 and 69

        if (simulated_signal_strength < 0) {
            network_status_array[i].signal_strength = 0;
        } else {
            network_status_array[i].signal_strength = simulated_signal_strength;
        }

        // Set status flag based on signal strength
        if (network_status_array[i].signal_strength > 50) {
            network_status_array[i].status_flag = 1; // Connected
        } else {
            network_status_array[i].status_flag = 0; // Disconnected
        }

        // Calculate signal quality metric based on predefined formula
        network_status_array[i].signal_quality_metric = (float)network_status_array[i].signal_strength / 60.0;
    }

    *status_count = N;
    return network_status_array;
}

// Function to free the allocated memory for NetworkStatus structures
void freeNetworkStatus(NetworkStatus *network_status_array, int N) {
    if (network_status_array != NULL) {
        free(network_status_array);
    }
}

int main() {
    int N = 5; // Number of network interfaces
    int status_count;

    NetworkStatus *network_status_array = generateNetworkStatus(N, &status_count);

    if (network_status_array != NULL) {
        printf("Generated %d network status updates:\n", status_count);
        for (int i = 0; i < status_count; i++) {
            printf("ID: %d, Timestamp: %ld, Signal Strength: %d, Status Flag: %d, Signal Quality Metric: %.2f\n",
                   network_status_array[i].id,
                   network_status_array[i].timestamp,
                   network_status_array[i].signal_strength,
                   network_status_array[i].status_flag,
                   network_status_array[i].signal_quality_metric);
        }

        freeNetworkStatus(network_status_array, status_count);
    }

    return 0;
}
