} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void* data;
    size_t size;
    size_t capacity;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity, size_t element_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->data = malloc(initial_capacity * element_size);
    if (pool->data == NULL) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->data);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_pdu_list(size_t n_elements, uint32_t seed, uint16_t rnti_min, uint16_t rnti_max, MemoryPool* pool) {
    if (n_elements == 0 || pool == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)pool->data + pool->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    for (size_t i = 0; i < n_elements && (pool->size + i) * sizeof(NFAPI_CRC_INDICATION_PDU_T) <= pool->capacity; ++i, ++pool->size) {
        // Initialize each PDU here with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    }

    return pdus;
}

void resize_memory_pool(MemoryPool* pool, size_t new_capacity, size_t element_size) {
    if (new_capacity <= pool->capacity) return;

    void* new_data = realloc(pool->data, new_capacity * element_size);
    if (new_data == NULL) return;

    pool->data = new_data;
    pool->capacity = new_capacity;
}

int main() {
    srand(time(NULL));
    MemoryPool pool = create_memory_pool(1024, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_nfaapi_pdu_list(500, 12345, 100, 9999, &pool);

    // Use the generated PDUs

    resize_memory_pool(&pool, 2048, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    destroy_memory_pool(&pool);

    return 0;
}
