            'id': self.id,
            'timestamp': self.timestamp,
            'signal_strength': self.signal_strength,
            'connectivity_status': self.connectivity_status,
            'signal_quality_metric': self.signal_quality_metric
        })

class NetworkInterfaceStatusFactory:
    registry = {}

    @classmethod
    def add_factory(cls, id, factory):
        cls.registry[id] = factory

    @classmethod
    def create_instance(cls, id, *args, **kwargs):
        if id in cls.registry:
            return cls.registry[id](*args, **kwargs)
        else:
            raise ValueError(f"No factory registered for ID: {id}")
