#include <stdlib.h>
#include <time.h>
#include <errno.h>

#define MAX_RETRIES 5

typedef struct {
    // Define the structure fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_NFAPI(struct timespec *start, struct timespec *end) {
    int N;
    printf("Enter the number of elements (N): ");
    if(scanf("%d", &N) != 1 || N <= 0) {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    for(int retry = 0; retry < MAX_RETRIES; ++retry) {
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if(array == NULL && errno != ENOMEM) {
            fprintf(stderr, "Failed to allocate memory. Error: %s\n", strerror(errno));
            return NULL;
        } else if(array == NULL) {
            // Memory allocation failed due to ENOMEM
            sleep(1);  // Wait before retrying
            continue;
        }

        srand(time(NULL));  // Seed the random number generator

        for(int i = 0; i < N; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000;  // Example value
            array[i].RNTI = rand() % 10000;  // Example value
            array[i].CRC_INDICATION_REL8_TAG = rand() % 100;  // Example value
            array[i].CRCFLAG = (rand() % 2) ? 1 : 0;  // Randomly set CRCFLAG
        }

        clock_gettime(CLOCK_REALTIME, end);
        printf("Memory allocation and population took %f seconds\n", timespec_diff(start, end));

        return array;
    }

    fprintf(stderr, "Failed to allocate memory after multiple retries.\n");
    return NULL;
}

// Function to calculate the difference between two timespec values
double timespec_diff(struct timespec *start, struct timespec *end) {
    double diff = (double)(end->tv_sec - start->tv_sec);
    diff += (double)(end->tv_nsec - start->tv_nsec) / 1e9;
    return diff;
}
