    time_t timestamp;
    float signal_strength;
    char connected;
} NetworkInterface;

// Function to dynamically generate and populate an array of NetworkInterface structures
NetworkInterface* generate_network_status_updates(int N, int *error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid number of interfaces
        return NULL;
    }

    NetworkInterface *interfaces = malloc(N * sizeof(NetworkInterface));
    if (interfaces == NULL) {
        *error_code = -2; // Memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        interfaces[i].id = i + 1;
        time(&interfaces[i].timestamp);
        float signal = (float)rand() / RAND_MAX * 100.0; // Random signal strength between 0 and 100
        interfaces[i].signal_strength = signal > 90 ? 1.0 : (signal < 20 ? 0.0 : signal / 50);
        interfaces[i].connected = (interfaces[i].signal_strength > 20) ? 'Y' : 'N';
    }

    *error_code = 0; // Success
    return interfaces;
}

// Function to free the memory allocated for NetworkInterface structures
void free_network_status_updates(NetworkInterface *interfaces, int N) {
    if (interfaces != NULL) {
        free(interfaces);
    }
}

int main() {
    int N = 5;
    int error_code;
    NetworkInterface *status_updates = generate_network_status_updates(N, &error_code);

    if (error_code == 0) {
        for (int i = 0; i < N; i++) {
            printf("ID: %d, Timestamp: %s, Signal Strength: %.2f, Connected: %c\n",
                   status_updates[i].id,
                   ctime(&status_updates[i].timestamp),
                   status_updates[i].signal_strength,
                   status_updates[i].connected);
        }
        free_network_status_updates(status_updates, N);
    } else {
        printf("Error generating network status updates. Error code: %d\n", error_code);
    }

    return 0;
}
