#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_CAPACITY 5000
#define MAX_INTERVALS 100

// Function prototypes
double *read_numbers(int *count);
void calculate_statistics(double *numbers, int count);
int compare(const void *a, const void *b);

// Main function
int main() {
    int total_count = 0;
    double *numbers = read_numbers(&total_count);
    if (numbers == NULL) {
        printf("Memory allocation error.\n");
        return 1;
    }
    calculate_statistics(numbers, total_count);
    free(numbers);
    return 0;
}

// Function to read numbers from standard input
double *read_numbers(int *count) {
    double *array = (double *)malloc(MAX_CAPACITY * sizeof(double));
    if (array == NULL) {
        *count = -1;
        return array;
    }
    int current_count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (current_count >= MAX_CAPACITY) {
            free(array);
            *count = -1;
            return NULL;
        }
        double value;
        if (sscanf(buffer, "%lf", &value) == 1 && !isnan(value)) {
            array[current_count++] = value;
        } else {
            printf("Ignoring non-numeric or NaN value.\n");
        }
    }
    *count = current_count;
    return array;
}

// Function to calculate and print statistics
void calculate_statistics(double *numbers, int count) {
    double sum = 0;
    for (int i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    double mean = sum / count;

    qsort(numbers, count, sizeof(double), compare);
    double median = (count % 2 == 0) ? (numbers[count / 2 - 1] + numbers[count / 2]) / 2 : numbers[count / 2];

    // Mode calculation (simplified for demonstration)
    int max_count = 0;
    double mode = NAN;
    for (int i = 0; i < count; ++i) {
        int current_count = 1;
        while (i + 1 < count && numbers[i] == numbers[i + 1]) {
            ++current_count;
            ++i;
        }
        if (current_count > max_count) {
            max_count = current_count;
            mode = numbers[i];
        }
    }

    printf("Mean: %.2f\n", mean);
    printf("Median: %.2f\n", median);
    printf("Mode: %.2f\n", mode);
}

// Comparison function for qsort
int compare(const void *a, const void *b) {
    return (*(double *)a - *(double *)b);
}
