const cache = {};
const CACHE_MAX_SIZE = 1000;
const CACHE_EXPIRY_TIME = 24 * 60 * 60 * 1000; // 24 hours

function fetchPokemonWeaknesses(pokemon) {
    const type = pokemon.type;
    const name = pokemon.name;

    // Check cache
    if (cache[type] && Date.now() - cache[type].timestamp < CACHE_EXPIRY_TIME) {
        return cache[type].data;
    }

    // Fetch data from external API or use fallback
    try {
        let weaknessesData;
        if (type in cache) {
            if (Date.now() - cache[type].timestamp < CACHE_EXPIRY_TIME) {
                weaknessesData = cache[type].data;
            } else {
                weaknessesData = fetchExternalAPI(type);
                updateCache(type, weaknessesData);
            }
        } else {
            weaknessesData = fetchExternalAPI(type);
            updateCache(type, weaknessesData);
        }

        return {
            elementalAffinity: weaknessesData.affinity,
            resistance: weaknessesData.resistance,
            immunity: weaknessesData.immunity
        };
    } catch (error) {
        // Fallback to local data if external API fails
        const fallbackWeaknesses = getFallbackWeaknesses(type);
        return {
            elementalAffinity: fallbackWeaknesses.affinity,
            resistance: fallbackWeaknesses.resistance,
            immunity: fallbackWeaknesses.immunity
        };
    }
}

function fetchExternalAPI(type) {
    // Simulate external API call
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve({
                affinity: `Affinity for ${type}`,
                resistance: `Resistance for ${type}`,
                immunity: `Immunity for ${type}`
            });
        }, 500);
    });
}

function updateCache(type, data) {
    cache[type] = {
        timestamp: Date.now(),
        data: data
    };

    if (Object.keys(cache).length > CACHE_MAX_SIZE) {
        // Remove least recently used item
        const oldestKey = Object.keys(cache).reduce((a, b) => 
            cache[a].timestamp < cache[b].timestamp ? a : b
        );
        delete cache[oldestKey];
    }
}

function getFallbackWeaknesses(type) {
    // Simulate local data fallback
    return {
        affinity: `Local Affinity for ${type}`,
        resistance: `Local Resistance for ${type}`,
        immunity: `Local Immunity for ${type}`
    };
}
