#include <mutex>

class ForwardListProcessor {
public:
    static void processForwardList(std::forward_list<int>& list, int incrementValue, int divisor, int threshold, int maxOperations) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < maxOperations; ++i) {
            auto it = list.begin();
            while (it != list.end()) {
                if (*it % divisor == 0) {
                    *it += incrementValue;
                    if (*it >= threshold) {
                        it = list.erase_after(it);
                    } else {
                        ++it;
                    }
                } else {
                    ++it;
                }
            }
        }

        if (list.empty()) {
            int sum = 0;
            for (const auto& elem : list) {
                sum += elem;
            }
            list.push_back(sum * incrementValue);
        }
    }

private:
    static std::mutex mutex_;
};

std::mutex ForwardListProcessor::mutex_;

int main() {
    std::forward_list<int> myList = {10, 20, 30, 40, 50};
    int incrementValue = 5;
    int divisor = 10;
    int threshold = 45;
    int maxOperations = 2;

    ForwardListProcessor::processForwardList(myList, incrementValue, divisor, threshold, maxOperations);

    for (const auto& elem : myList) {
        std::cout << elem << " ";
    }
    return 0;
}
