namespace NetworkConfig {
    class ConfigurationManager {
    public:
        static ConfigurationManager& getInstance() {
            static ConfigurationManager instance;
            return instance;
        }

        void loadConfiguration(const std::string& filename, int priority) {
            std::lock_guard<std::mutex> lock(mutex_);
            try {
                Json::Value config = Json::parse(readFile(filename));
                applyConfiguration(config, priority);
            } catch (const std::exception& e) {
                logError("Failed to load configuration: " + std::string(e.what()));
            }
        }

        void reloadConfiguration(const std::string& filename, int priority) {
            std::lock_guard<std::mutex> lock(mutex_);
            try {
                Json::Value config = Json::parse(readFile(filename));
                applyConfiguration(config, priority);
            } catch (const std::exception& e) {
                logError("Failed to reload configuration: " + std::string(e.what()));
            }
        }

    private:
        ConfigurationManager() {}
        ~ConfigurationManager() {}

        void applyConfiguration(const Json::Value& config, int priority) {
            for (const auto& item : config.getMemberNames()) {
                if (!config[item].isNull()) {
                    configurations_[item] = std::make_pair(config[item], priority);
                }
            }
        }

        std::string readFile(const std::string& filename) {
            std::ifstream file(filename);
            if (!file.is_open()) {
                throw std::runtime_error("Failed to open file: " + filename);
            }
            std::stringstream buffer;
            buffer << file.rdbuf();
            return buffer.str();
        }

        void logError(const std::string& error) {
            // Log the error to a file or console
            std::cerr << "ERROR: " << error << std::endl;
        }

        mutable std::mutex mutex_;
        std::map<std::string, std::pair<Json::Value, int>> configurations_;
    };
}

int main() {
    NetworkConfig::ConfigurationManager& configManager = NetworkConfig::ConfigurationManager::getInstance();
    configManager.loadConfiguration("config1.json", 1);
    configManager.reloadConfiguration("config2.json", 2);
    return 0;
}
