public class XmlParser
{
    public List<string> GetDistinctElementsWithPagination(
        string xmlContent, 
        string elementName, 
        int pageSize, 
        out int processedCount)
    {
        processedCount = 0;
        List<string> distinctElements = new List<string>();
        XPathDocument doc;

        try
        {
            doc = new XPathDocument(new System.IO.StringReader(xmlContent));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return distinctElements;
        }

        XPathNavigator navigator = doc.CreateNavigator();
        XPathExpression expression = navigator.Compile($"//{elementName}");

        while (true)
        {
            XPathNodeIterator iterator = navigator.Select(expression);
            int count = 0;

            foreach (XPathNavigator node in iterator)
            {
                if (count >= pageSize) break;
                string textContent = node.Value.Trim();
                if (!string.IsNullOrEmpty(textContent) && !IsBlacklisted(textContent))
                {
                    distinctElements.Add(textContent);
                    processedCount++;
                }
                count++;
            }

            if (iterator.MoveNext()) continue;

            break;
        }

        return distinctElements;
    }

    private bool IsBlacklisted(string textContent)
