            byte[] data = storageSystem.retrieveFileVersion("example.txt", 0);
            System.out.println(new String(data));
            storageSystem.distributeFile("example.txt", 0);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Inner class to represent a version of a file
    private static class FileVersion {
        private final String fileName;
        private final byte[] data;

        public FileVersion(String fileName, byte[] data) {
            this.fileName = fileName;
            this.data = data;
        }

        public String getFileName() {
