function refreshDialogFields(resourceId, url) {
    var fields = ['field1', 'field2', 'field3']; // Configurable array of field names
    var timeout = 5000; // Timeout in milliseconds
    var cache = {}; // Caching layer for frequently accessed data

    function sendData(fieldName) {
        var message = { fieldName: fieldName, resourceId: resourceId };
        window.parent.postMessage(message, '*');

        var promise = new Promise((resolve, reject) => {
            var timer = setTimeout(() => {
                reject('Request timed out');
            }, timeout);

            window.addEventListener('message', function(event) {
                if (event.origin !== 'http://example.com') return; // Replace with actual origin
                if (event.data.fieldName === fieldName && event.data.status === 'success') {
                    resolve(event.data.data);
                }
            });
        });

        promise.then(data => {
            updateField(fieldName, data);
        }).catch(error => {
            console.error('Error updating field:', error);
        }).finally(() => {
            clearTimeout(timer);
        });
    }

    function updateField(fieldName, data) {
        // Update the dialog field with the returned data
        var element = document.getElementById(fieldName);
        if (element) {
            element.value = data;
        }
    }

    for (var i = 0; i < fields.length; i++) {
        sendData(fields[i]);
    }
}
