public class NetworkRequestProcessor {
    private final IntervalTree<RequestId> intervalTree = new IntervalTree<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(5);
    private final RateLimiter rateLimiter = RateLimiter.create(10000.0 / 60.0); // 10,000 requests per minute
    private final ConcurrentHashMap<String, Resource> resourceCache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService cacheRefresher = Executors.newScheduledThreadPool(1);
    private final AtomicInteger failedOperations = new AtomicInteger();

    public NetworkRequestProcessor() {
        cacheRefresher.scheduleAtFixedRate(() -> refreshResourceCache(), 60, 60, TimeUnit.SECONDS);
    }

    public int processRequests(List<NetworkRequest> requests) throws Exception {
        if (!rateLimiter.tryAcquire(requests.size())) {
            throw new RuntimeException("Rate limit exceeded");
        }

        int distinctResources = 0;
        for (NetworkRequest request : requests) {
            if (executorService.isShutdown()) {
                break;
            }
            executorService.submit(() -> {
                try {
                    Resource resource = getResource(request.getResourceId());
                    intervalTree.insert(new RequestId(request.getTimestamp(), request.getResourceId()));
                    distinctResources++;
                } catch (Exception e) {
                    failedOperations.incrementAndGet();
                    System.err.println("Failed to process request: " + e.getMessage());
                }
            });
        }

        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);

        return distinctResources;
    }

    private Resource getResource(String resourceId) throws Exception {
        if (resourceCache.containsKey(resourceId)) {
            return resourceCache.get(resourceId);
        } else {
            // Simulate external data source access
            Thread.sleep(200); // Simulating latency
            Resource newResource = fetchFromExternalSource(resourceId);
            resourceCache.putIfAbsent(resourceId, newResource);
            return newResource;
        }
    }

    private void refreshResourceCache() {
        try {
            for (String resourceId : resourceCache.keySet()) {
                Resource updatedResource = fetchFromExternalSource(resourceId);
                if (!updatedResource.equals(resourceCache.get(resourceId))) {
                    resourceCache.put(resourceId, updatedResource);
                }
            }
        } catch (Exception e) {
            System.err.println("Failed to refresh resource cache: " + e.getMessage());
        }
    }

    private Resource fetchFromExternalSource(String resourceId) throws Exception {
        // Simulate external data source
        if (!"resource1".equals(resourceId)) {
            throw new RuntimeException("Resource not found");
        }
        return new Resource();
    }

    public int getFailedOperations() {
        return failedOperations.get();
    }

    public static void main(String[] args) {
        NetworkRequestProcessor processor = new NetworkRequestProcessor();
        try {
            List<NetworkRequest> requests = // Initialize your list of network requests here
            int distinctResources = processor.processRequests(requests);
            System.out.println("Distinct resources: " + distinctResources);
            System.out.println("Failed operations: " + processor.getFailedOperations());
        } catch (Exception e) {
            System.err.println("Error processing requests: " + e.getMessage());
        }
    }

    static class NetworkRequest {
        private final long timestamp;
        private final String resourceId;
        // Other fields and methods

        public NetworkRequest(long timestamp, String resourceId) {
            this.timestamp = timestamp;
            this.resourceId = resourceId;
        }

        public long getTimestamp() {
            return timestamp;
        }

        public String getResourceId() {
            return resourceId;
        }
    }

    static class RequestId implements Comparable<RequestId> {
        private final long start;
        private final long end;
        private final String id;

        public RequestId(long timestamp, String id) {
            this.start = timestamp;
            this.end = timestamp + 1; // Assuming each request has a duration of 1 unit
            this.id = id;
        }

        @Override
        public int compareTo(RequestId other) {
            if (this.start != other.start) {
                return Long.compare(this.start, other.start);
            } else {
                return this.id.compareTo(other.id);
            }
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            RequestId requestId = (RequestId) o;
            return start == requestId.start && end == requestId.end && id.equals(requestId.id);
        }

        @Override
        public int hashCode() {
            return Objects.hash(start, end, id);
        }
