// Define the RetryLogic class to implement robust retry logic for transient errors
public class RetryLogic {
    private int maxRetries;
    private int delay;

    public RetryLogic(int maxRetries, int delay) {
        this.maxRetries = maxRetries;
        this.delay = delay;
    }

    // Method to handle retries for transient errors
    public void retryOnError(Runnable task) {
        int attempt = 0;
        while (attempt < maxRetries) {
            try {
                task.run();
                break;
            } catch (Exception e) {
                attempt++;
                if (attempt >= maxRetries) throw e;
                Thread.sleep(delay);
            }
        }
    }
}
