// Main class to control the lifecycle of the service
public class ServiceManager {
    private boolean isRunning = false;
    private MessagingSystem messagingSystem;

    public void startService() throws Exception {
        if (!isRunning) {
            isRunning = true;
            while (isRunning) {
                performServiceOperation();
                Thread.sleep(getRandomDelay());
            }
        } else {
            throw new IllegalStateException("Service is already running.");
        }
    }

    public void stopService() {
        isRunning = false;
        try {
            messagingSystem.sendMessage("Service stopped");
        } catch (Exception e) {
            System.err.println("Failed to send stop message: " + e.getMessage());
        }
    }

    private void performServiceOperation() throws Exception {
        // Simulate service operation
        System.out.println("Performing service operation...");

        // External API call or other operations here

        // Send a message after successful operation
        messagingSystem.sendMessage("Service operation completed");
    }

    private long getRandomDelay() {
        return (long) (Math.random() * 5000); // Random delay between 0 and 5 seconds
    }
}

