use hyper::{Client, Method, Request, Uri};
use hyper_tls::HttpsConnector;
use hyperrate::RateLimiter;
use std::time::Duration;

async fn create_http_client(disable_certificate_validation: bool) -> Result<Client<HttpsConnector>, String> {
    let https = HttpsConnector::new();
    if disable_certificate_validation {
        Ok(Client::builder().build::<_, hyper::Body>(hyper_tls::HttpsConnectorBuilder::new()
            .with_native_certs()
            .disable_hostname_verification()
            .build()))
    } else {
        Ok(Client::builder().build(https))
    }
}

async fn send_request(
    client: &Client<HttpsConnector>,
    method: Method,
    uri: Uri,
    headers: hyper::HeaderMap,
) -> Result<String, String> {
    let req = Request::builder()
        .method(method)
        .uri(uri)
        .headers(headers)
        .body(hyper::Body::empty())
        .map_err(|e| format!("Request builder error: {}", e))?;

    client
        .request(req)
        .await
        .map_err(|e| format!("HTTP request error: {}", e))
        .and_then(|res| {
            res.into_body()
                .collect()
                .map_err(|e| format!("Response body error: {}", e))
                .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
        })
}

fn main() -> Result<(), String> {
    let client = create_http_client(true).await?;
    let uri = Uri::from_static("https://example.com");
    let mut headers = hyper::HeaderMap::new();
    headers.insert("User-Agent", "Rust HTTP Client".parse().unwrap());

    let response = send_request(&client, Method::GET, uri, headers).await?;

    println!("Response: {}", response);
    Ok(())
}
```

