typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
} CRCArray;

CRCArray* create_crc_array(size_t initial_capacity) {
    CRCArray *array = malloc(sizeof(CRCArray));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->count = 0;
    array->data = realloc(NULL, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array->data) {
        free(array);
        return NULL;
    }

    return array;
}

void destroy_crc_array(CRCArray *array) {
    if (array->data) free(array->data);
    free(array);
}

int add_to_crc_array(CRCArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        void *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) return -1; // Memory allocation failed

        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->count++] = item;
    return 0;
}

