// Function to dynamically generate and populate an array of sensor readings
SensorReading* generate_sensor_readings(int N, int sensor_count) {
    if (N <= 0 || sensor_count <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the array of SensorReading structures
    SensorReading *readings = (SensorReading *)malloc(N * sizeof(SensorReading));
    if (readings == NULL) {
        perror("Failed to allocate memory for sensor readings");
        return NULL;
    }

    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < N; i++) {
        readings[i].id = i + 1;                 // Assign a unique identifier
        readings[i].timestamp = time(NULL);     // Get current timestamp
        readings[i].sensor_id = rand() % sensor_count + 1;  // Randomly select a sensor ID

        // Generate a random measurement value within a valid range
        readings[i].value = (float)rand() / RAND_MAX * 100.0f;

        // Assign a quality flag based on the validity of the reading
        if (readings[i].value >= -50.0 && readings[i].value <= 150.0) {
            readings[i].quality_flag = 'A';  // Good quality
        } else {
            readings[i].quality_flag = 'D';  // Poor quality due to out-of-range value
        }
    }

    return readings;
}

// Function to free the allocated memory for sensor readings
