typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;
    pool->pool = malloc(block_size * num_blocks);

    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) return NULL;
    void* block = (char*)pool->pool + pool->free_index * pool->block_size;
    pool->free_index++;
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index < pool->free_index && index >= 0) {
        pool->free_index--;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_pdu_array(int N, MemoryPool* pool) {
    if (N <= 0 || N > MAX_ENTRIES) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(pool);
    if (!array) return NULL;

    for (int i = 0; i < N; i++) {
        // Initialize each structure using inline assembly for low-level operations
        __asm__ volatile (
            "movl %1, %%eax\n"
            "movw %2, %%dx\n"
            "stosb\n"
