class PasswordUpdater {
    private $userDAO;
    private $passwordValidator;
    private $rateLimiter;
    private $logger;
    private $externalAuthService;

    public function __construct(
        UserDAO $userDAO,
        PasswordValidator $passwordValidator,
        RateLimiter $rateLimiter,
        Logger $logger,
        ExternalAuthService $externalAuthService
    ) {
        $this->userDAO = $userDAO;
        $this->passwordValidator = $passwordValidator;
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
        $this->externalAuthService = $externalAuthService;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            if (!$this->rateLimiter->checkRateLimit($userId)) {
                return ['status' => 429, 'message' => 'Too many requests. Please try again later.'];
            }

            if (!$this->externalAuthService->verifyUserCredentials($userId, $newPassword)) {
                return ['status' => 401, 'message' => 'Invalid user credentials.'];
            }

            if (!$this->passwordValidator->validatePasswordStrength($newPassword)) {
                return ['status' => 400, 'message' => 'Password does not meet the complexity requirements.'];
            }

            $encryptedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

            if ($this->userDAO->updateUserPassword($userId, $encryptedPassword)) {
                $this->logger->logAttempt($userId, true);
                return ['status' => 200, 'message' => 'Password updated successfully.'];
            } else {
                $this->logger->logAttempt($userId, false);
                return ['status' => 500, 'message' => 'Failed to update password.'];
            }
        } catch (Exception $e) {
            $this->logger->logAttempt($userId, false, $e->getMessage());
            return ['status' => 500, 'message' => 'Internal server error.'];
        }
    }
}

// Usage example
