import os

def process_log_files(directory):
    events = []

    # Loop through all files in the directory
    for filename in os.listdir(directory):
        if filename.endswith(".log"):
            try:
                with open(os.path.join(directory, filename), 'r') as file:
                    lines = file.readlines()

                    # Process each line to extract event data
                    for line in lines:
                        # Extract timestamp and other details from the line
                        # Assuming a simple format: "timestamp event_type sequence_number"
                        parts = line.strip().split(' ')
                        if len(parts) == 4:
                            timestamp, event_type, _, sequence_number = parts

                            # Filter events based on tag (e.g., 'error')
                            if event_type == 'error':
                                events.append((int(timestamp), int(sequence_number)))

            except IOError as e:
                print(f"Error reading {filename}: {e}")

    # Sort events by timestamp in descending order
    events.sort(reverse=True)

    # Extract the sequence number from the header of the most recent event
    if events:
        _, latest_sequence_number = events[0]
        return latest_sequence_number
    else:
        return None
