EVP_CIPHER_CTX *init_aes_cbc(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[32];
    unsigned char iv[16];
    int derived_key_len = sizeof(key);

    // Generate a random IV
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive the encryption key using PBKDF2 with SHA-256
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), iv, sizeof(iv),
                            10000, EVP_sha256(), derived_key_len, key)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context for AES-256-CBC
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_cleanup(ctx);
}

