// Define a custom data structure for network interface status updates
#[derive(Debug)]
struct NetworkStatus {
    id: u32,
    timestamp: DateTime<Utc>,
    signal_strength: f32,
    is_connected: bool,
    signal_quality: f32,
}

impl NetworkStatus {
    // Constructor to create a new NetworkStatus instance
    fn new(id: u32, signal_strength: f32) -> Result<NetworkStatus, &'static str> {
        if signal_strength < 0.0 || signal_strength > 100.0 {
            return Err("Invalid signal strength");
        }
        let timestamp = Utc::now();
        Ok(NetworkStatus {
            id,
            timestamp,
            signal_strength,
            is_connected: signal_strength > 50.0, // Example condition for connectivity
            signal_quality: (signal_strength * 10.0).round() / 10.0, // Example formula for quality
        })
    }
}

// Function to dynamically generate and populate an array of NetworkStatus instances
fn create_network_status_client(n: usize) -> Result<Vec<NetworkStatus>, &'static str> {
    let mut statuses = Vec::with_capacity(n);
    for i in 0..n {
        let status = NetworkStatus::new(i as u32, (i % 101) as f32)?;
        statuses.push(status);
    }
    Ok(statuses)
}

