['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ORDER_AGE 2
#define MAX_CONCURRENT_THREADS 50
#define BATCH_SIZE 50
#define RISK_THRESHOLD 100

typedef struct Order {
    int id;
    double risk_score;
    time_t timestamp;
} Order;

typedef struct OrderQueue {
    Order orders[BATCH_SIZE];
    int front, rear, size;
} OrderQueue;

void initOrderQueue(OrderQueue *queue) {
    queue->front = queue->rear = queue->size = 0;
}

int isFull(OrderQueue *queue) {
    return (queue->size == BATCH_SIZE);
}

int isEmpty(OrderQueue *queue) {
    return (queue->size == 0);
}

void enqueue(OrderQueue *queue, Order order) {
    if (isFull(queue)) {
        printf("Queue Full\n");
        exit(EXIT_FAILURE);
    }
    queue->rear = (queue->rear + 1) % BATCH_SIZE;
    queue->orders[queue->rear] = order;
    queue->size++;
}

Order dequeue(OrderQueue *queue) {
    if (isEmpty(queue)) {
        printf("Queue Empty\n");
        exit(EXIT_FAILURE);
    }
    Order order = queue->orders[queue->front];
    queue->front = (queue->front + 1) % BATCH_SIZE;
    queue->size--;
    return order;
}

typedef struct TradingSystem {
    OrderQueue recentOrders;
    time_t lastProcessedTime;
    int activeOrdersCount;
    double cumulativeRiskScore;
    int ordersProcessed, ordersDropped, riskExceeded;
} TradingSystem;

void initTradingSystem(TradingSystem *system) {
    initOrderQueue(&system->recentOrders);
    system->lastProcessedTime = time(NULL);
    system->activeOrdersCount = 0;
    system->cumulativeRiskScore = 0.0;
    system->ordersProcessed = 0;
    system->ordersDropped = 0;
    system->riskExceeded = 0;
}

int isOrderEligible(Order order, time_t currentTime) {
    return (currentTime - order.timestamp <= MAX_ORDER_AGE);
}

void processBatch(TradingSystem *system, OrderQueue *batch) {
    int maxRiskScore = 0;
    int maxRiskOrderId = -1;
    system->ordersProcessed += batch->size;

    while (!isEmpty(batch)) {
        Order order = dequeue(batch);
        if (isOrderEligible(order, time(NULL))) {
            system->cumulativeRiskScore += order.risk_score;
            if (system->cumulativeRiskScore > RISK_THRESHOLD) {
                system->riskExceeded++;
                continue;
            }
            if (order.risk_score > maxRiskScore) {
                maxRiskScore = order.risk_score;
                maxRiskOrderId = order.id;
            }
        } else {
            system->ordersDropped++;
        }
    }

    printf("Batch Summary:\n");
    printf("Max Risk Score: %d\n", maxRiskScore);
    printf("Order ID with Max Risk: %d\n", maxRiskOrderId);
    printf("Orders Processed: %d\n", system->ordersProcessed);
    printf("Orders Dropped Due to Age: %d\n", system->ordersDropped);
    printf("Orders Exceeding Risk Threshold: %d\n", system->riskExceeded);
}

void processOrder(TradingSystem *system, Order order) {
    if (time(NULL) - system->lastProcessedTime >= 1) {
        system->activeOrdersCount = 0;
        system->cumulativeRiskScore = 0.0;
        system->lastProcessedTime = time(NULL);
    }

    if (system->activeOrdersCount < MAX_CONCURRENT_THREADS) {
        enqueue(&system->recentOrders, order);
        system->activeOrdersCount++;
    } else {
