        {2, 30, time(NULL) - 1},
        {3, 60, time(NULL) - 2}
    };

    for (int i = 0; i < sizeof(orders) / sizeof(orders[0]); i++) {
        processOrder(&tradingSystem, orders[i]);
    }

    OrderQueue batch;
    initOrderQueue(&batch);

    while (!isEmpty(&tradingSystem.recentOrders)) {
        enqueue(&batch, dequeue(&tradingSystem.recentOrders));
    }

    processBatch(&tradingSystem, &batch);

    return 0;
}
