#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 256

typedef struct Config {
    char **keys;
    void **values;
    int count;
} Config;

int parse_config(const char *filename, Config *config) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    config->count = 0;
    while (1) {
        char line[MAX_LINE_LENGTH];
        if (!fgets(line, sizeof(line), file)) break;

        // Trim newline character
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[--len] = '\0';

        // Skip empty lines and comments
        if (len == 0 || line[0] == '#') continue;

        char key[MAX_KEY_LENGTH], value[MAX_VALUE_LENGTH];
        if (sscanf(line, "%255[^=]=%255s", key, value) != 2) {
            fclose(file);
            return -1; // Invalid format
        }

        config->count++;
        config->keys = realloc(config->keys, config->count * sizeof(char *));
        config->values = realloc(config->values, config->count * sizeof(void *));

        config->keys[config->count-1] = strdup(key);
        if (strchr(value, '.') != NULL) {
            float fval;
            if (sscanf(value, "%f", &fval) == 1) {
                config->values[config->count-1] = malloc(sizeof(float));
                *(float *)config->values[config->count-1] = fval;
            } else {
                fclose(file);
                return -1; // Invalid float value
            }
        } else if (strchr(value, '-') != NULL || isdigit(value[0])) {
            int ival;
            if (sscanf(value, "%d", &ival) == 1) {
                config->values[config->count-1] = malloc(sizeof(int));
                *(int *)config->values[config->count-1] = ival;
            } else {
                fclose(file);
                return -1; // Invalid integer value
            }
        } else {
            config->values[config->count-1] = strdup(value);
        }
    }

    fclose(file);
    return 0;
}

// Example usage:
/*
Config config;
if (parse_config("config.txt", &config) == 0) {
    // Access data using config.keys and config.values
} else {
    // Handle error
}
*/
