SensorData* generate_sensor_data(int N, int* error_code) {
    if (N <= 0 || N > MAX_SENSORS) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    SensorData* sensor_data = malloc(N * sizeof(SensorData));
    if (!sensor_data) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        sensor_data[i].id = i + 1;
        sensor_data[i].timestamp = time(NULL);
        sensor_data[i].sensor_id = rand() % 100;
        sensor_data[i].measurement = (rand() % 1000) / 10.0; // Random measurement value
        sensor_data[i].quality_flag = 'G'; // Good quality flag

        if (sensor_data[i].measurement < 0 || sensor_data[i].measurement > 1000) {
            *error_code = -3; // Invalid measurement value
            free(sensor_data);
            return NULL;
        }
    }

    *error_code = 0; // Success
    return sensor_data;
}

void profile_function(int N, int* error_code) {
    clock_t start = clock();
    SensorData* data = generate_sensor_data(N, error_code);
    if (*error_code != 0) {
        log_message("Error in generating sensor data");
        free(data);
        return;
    }
    clock_t end = clock();

    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    log_message("Function execution time: %f seconds", time_taken);

    free(data);
}

int main() {
    int N = 1000; // Example number of sensor data structures
    profile_function(N, NULL);
    return 0;
}
