import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CommandExecutor {

    public static void main(String[] args) {
        String directoryPath = "/path/to/directory";
        String command = "your_command_here";

        try {
            if (shouldDeleteFile(directoryPath)) {
                deleteOldestFile(directoryPath);
            }

            long startTime = System.currentTimeMillis();
            executeCommand(command, directoryPath);
            long endTime = System.currentTimeMillis();

            logExecutionTime(endTime - startTime);
        } catch (IOException | InterruptedException e) {
            handleException(e);
        }
    }

    private static boolean shouldDeleteFile(String directoryPath) throws IOException {
        Path dir = Paths.get(directoryPath);
        return Files.list(dir).count() > 10;
    }

    private static void deleteOldestFile(String directoryPath) throws IOException {
        Path dir = Paths.get(directoryPath);
        long minTime = Long.MAX_VALUE;
        Path oldestFile = null;

        for (Path file : Files.list(dir)) {
            if (Files.isRegularFile(file) && file.lastModified() < minTime) {
                minTime = file.lastModified();
                oldestFile = file;
            }
        }

        if (oldestFile != null) {
            Files.delete(oldestFile);
        }
    }

    private static void executeCommand(String command, String directoryPath) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command, null, new File(directoryPath));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                handleException(e);
            }
        });

        executor.submit(() -> {
            try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    System.err.println(line);
                }
            } catch (IOException e) {
                handleException(e);
            }
        });

        int exitCode = process.waitFor();
        executor.shutdownNow();
    }

    private static void logExecutionTime(long time) {
        System.out.println("Command execution time: " + time + " ms");
    }

    private static void handleException(Exception e) {
        e.printStackTrace();
        // Retry logic if necessary
    }
}
