typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void createPDU(NFAPI_CRC_INDICATION_PDU_T **pduArray, int *size, int maxAttempts) {
    for (int i = 0; i < maxAttempts; ++i) {
        if (*size >= 10000) break;

        NFAPI_CRC_INDICATION_PDU_T *newPDU = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPDU) continue;

        newPDU->RX_UE_INFORMATION_TAG = rand() % 100;
        newPDU->RNTI = rand() % 1000;
        newPDU->CRC_INDICATION_REL8_TAG = rand() % 2;

        // Validate CRC flag and add to array
        if (newPDU->CRC_INDICATION_REL8_TAG == 1) {
            (*size)++;
            if (*pduArray) {
                *pduArray = realloc(*pduArray, (*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            } else {
                *pduArray = malloc((*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
            if (*pduArray) {
                memcpy(&(*pduArray)[*size - 1], newPDU, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }

        free(newPDU);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pduArray = NULL;
    int size = 0;

    srand(time(NULL));
    createPDU(&pduArray, &size, 3);

    // Free allocated memory
    if (pduArray) {
        free(pduArray);
    }

    return 0;
}
