import java.io.*;
import java.util.concurrent.*;

public class CommandExecutor {
    private static final int MAX_RETRIES = 3;
    private static final long FILE_AGE_THRESHOLD = TimeUnit.DAYS.toMillis(1);

    public static void main(String[] args) {
        String directoryPath = "path/to/directory";
        String command = "command_to_execute";

        try {
            executeCommandWithRetry(directoryPath, command);
        } catch (IOException | InterruptedException e) {
            System.err.println("Failed to execute command: " + e.getMessage());
        }
    }

    public static void executeCommandWithRetry(String directoryPath, String command) throws IOException, InterruptedException {
        int attempt = 0;
        long startTime = System.currentTimeMillis();

        while (attempt < MAX_RETRIES) {
            try {
                if (shouldDeleteOldFile(directoryPath)) {
                    deleteOldestFile(directoryPath);
                }

                Process process = Runtime.getRuntime().exec(command);
                Future<?> errorFuture = handleErrorStream(process.getErrorStream());
                Future<?> outputFuture = handleOutputStream(process.getInputStream());

                int exitCode = process.waitFor();
                errorFuture.get(); // Ensure error handling is done
                outputFuture.get(); // Ensure output handling is done

                long endTime = System.currentTimeMillis();
                System.out.println("Total execution time: " + (endTime - startTime) + " ms");
                return;
            } catch (IOException | InterruptedException e) {
                if (!isTemporaryFailure(e)) {
                    throw new IOException("Failed to execute command after " + MAX_RETRIES + " attempts", e);
                }
                attempt++;
                System.err.println("Attempt " + attempt + " failed: " + e.getMessage());
            }
        }

        throw new IOException("Command execution failed after " + MAX_RETRIES + " attempts");
    }

    private static boolean shouldDeleteOldFile(String directoryPath) {
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();
        if (files == null || files.length <= 10) {
            return false;
        }
        Arrays.sort(files, Comparator.comparingLong(File::lastModified));
        return true;
    }

    private static void deleteOldestFile(String directoryPath) throws IOException {
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();
        if (files != null && files.length > 10) {
            Arrays.sort(files, Comparator.comparingLong(File::lastModified));
            Files.deleteIfExists(files[0].toPath());
        }
    }

    private static Future<?> handleOutputStream(InputStream inputStream) {
        return Executors.newSingleThreadExecutor().submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("Output: " + line);
                }
            } catch (IOException e) {
                System.err.println("Error reading output stream: " + e.getMessage());
            }
        });
