#include <string.h>
#include <pthread.h>

#define MAX_POOL_SIZE 64 * 1024 // 64KB per thread

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t allocated;
    size_t used;
    pthread_mutex_t lock;
} CustomAllocator;

CustomAllocator* allocator_init(size_t initial_size) {
    CustomAllocator *allocator = (CustomAllocator*)malloc(sizeof(CustomAllocator));
    if (!allocator) return NULL;

    allocator->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!allocator->data) {
        free(allocator);
        return NULL;
    }

    allocator->allocated = initial_size;
    allocator->used = 0;
    pthread_mutex_init(&allocator->lock, NULL);

    return allocator;
}

void* custom_malloc(CustomAllocator *allocator, size_t size) {
    if (size > MAX_POOL_SIZE / allocator->allocated) return NULL;

    pthread_mutex_lock(&allocator->lock);
    if (allocator->used + size > allocator->allocated) {
        // Resize the pool
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(allocator->data, 2 * allocator->allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&allocator->lock);
            return NULL;
        }
        allocator->data = new_data;
        allocator->allocated *= 2;
    }

    void* ptr = (void*)((char*)allocator->data + allocator->used * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    allocator->used++;
    pthread_mutex_unlock(&allocator->lock);

    return ptr;
}

void custom_free(CustomAllocator *allocator, void *ptr) {
    // This is a simplified example; real implementation might need tracking free blocks
    pthread_mutex_lock(&allocator->lock);
    allocator->used--;
    pthread_mutex_unlock(&allocator->lock);
}

void* allocator_realloc(CustomAllocator *allocator, void *old_ptr, size_t new_size) {
    if (new_size > MAX_POOL_SIZE / allocator->allocated) return NULL;

    pthread_mutex_lock(&allocator->lock);
    size_t old_index = ((char*)old_ptr - (char*)allocator->data) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (old_index >= allocator->used) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL;
    }

    void* new_ptr = custom_malloc(allocator, new_size);
    if (!new_ptr) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL;
    }

    memcpy(new_ptr, old_ptr, new_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) ? new_size : sizeof(NFAPI_CRC_INDICATION_PDU_T));
    custom_free(allocator, old_ptr);

    pthread_mutex_unlock(&allocator->lock);

    return new_ptr;
}

void allocator_destroy(CustomAllocator *allocator) {
    free(allocator->data);
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);
}
