#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include "json-c/json.h" // Include appropriate JSON library

bool is_valid_port(const char *port_str) {
    int port = atoi(port_str);
    return port > 0 && port <= 65535;
}

bool is_valid_log_level(const char *log_level) {
    const char* valid_levels[] = {"DEBUG", "INFO", "WARN", "ERROR", "CRITICAL"};
    for (int i = 0; i < 5; ++i) {
        if (strcasecmp(log_level, valid_levels[i]) == 0) return true;
    }
    return false;
}

bool is_valid_boolean(const char *str, bool *result) {
    if (strcasecmp(str, "true") == 0 || strcasecmp(str, "yes") == 0) {
        *result = true;
        return true;
    } else if (strcasecmp(str, "false") == 0 || strcasecmp(str, "no") == 0) {
        *result = false;
        return true;
    }
    return false;
}

bool is_valid_header(const char *header_str) {
    const char *colon_pos = strchr(header_str, ':');
    if (!colon_pos) return false;
    size_t key_len = colon_pos - header_str;
    size_t value_len = strlen(header_str) - key_len - 1;
    for (size_t i = 0; i < key_len; ++i) {
        if (!isalnum(key_str[i]) && key_str[i] != '-') return false;
    }
    for (size_t i = 0; i < value_len; ++i) {
        if (!isprint(value_str[i])) return false;
    }
    return true;
}

bool validate_json_config(const char *json_data, size_t json_size) {
    struct json_object *config_obj = json_tokener_parse(json_data);
    if (!config_obj || !json_is_object(config_obj)) {
        json_object_put(config_obj);
        return false;
    }

    struct json_object *port_obj;
    if (json_object_object_get_ex(config_obj, "server_port", &port_obj) && json_is_string(port_obj)) {
        const char *port_str = json_object_get_string(port_obj);
        if (!is_valid_port(port_str)) {
            json_object_put(config_obj);
            return false;
        }
    } else {
        json_object_put(config_obj);
        return false;
    }

    struct json_object *log_level_obj;
    if (json_object_object_get_ex(config_obj, "log_level", &log_level_obj) && json_is_string(log_level_obj)) {
        const char *log_level_str = json_object_get_string(log_level_obj);
        if (!is_valid_log_level(log_level_str)) {
            json_object_put(config_obj);
            return false;
        }
    } else {
        json_object_put(config_obj);
        return false;
    }

    struct json_object *enable_ssl_obj;
    bool enable_ssl;
    if (json_object_object_get_ex(config_obj, "enable_ssl", &enable_ssl_obj) && json_is_boolean(enable_ssl_obj)) {
        enable_ssl = json_object_get_boolean(enable_ssl_obj);
    } else if (json_object_object_get_ex(config_obj, "enable_ssl", &enable_ssl_obj) && json_is_string(enable_ssl_obj)) {
        if (!is_valid_boolean(json_object_get_string(enable_ssl_obj), &enable_ssl)) {
            json_object_put(config_obj);
            return false;
        }
    } else {
        enable_ssl = false; // Default value
    }

    struct json_object *custom_headers_obj;
    if (json_object_object_get_ex(config_obj, "custom_headers", &custom_headers_obj) && json_is_array(custom_headers_obj)) {
        struct json_array_iter iter;
        json_array_foreach(custom_headers_obj, &iter, header_obj) {
            const char *header_str = json_object_get_string(header_obj);
            if (!is_valid_header(header_str)) {
                json_object_put(config_obj);
                return false;
            }
        }
    }

    json_object_put(config_obj);
    return true;
}
