public class FileProcessor
{
    private readonly IConfiguration _configuration;
    private readonly IBlobStorageService _blobStorageService;
    private readonly ICloudStorageService _cloudStorageService;
    private readonly ICachingService _cachingService;

    public FileProcessor(IConfiguration configuration, IBlobStorageService blobStorageService, ICloudStorageService cloudStorageService, ICachingService cachingService)
    {
        _configuration = configuration;
        _blobStorageService = blobStorageService;
        _cloudStorageService = cloudStorageService;
        _cachingService = cachingService;
    }

    public async Task<ThumbnailMetadata> ProcessFileAsync(byte[] fileData, string originalFileName, string thumbnailSize, int thumbnailQuality)
    {
        var storageProvider = _configuration["DefaultStorageProvider"];
        var cacheKey = $"{originalFileName}_{thumbnailSize}";

        if (_cachingService.IsCached(cacheKey))
        {
            return await _cachingService.GetCachedValueAsync<ThumbnailMetadata>(cacheKey);
        }

        byte[] thumbnailData;
        switch (storageProvider)
        {
            case "Azure":
                var azureBlob = new AzureBlobStorage(fileData, originalFileName, thumbnailSize, thumbnailQuality);
                await azureBlob.UploadAsync();
                thumbnailData = await azureBlob.GenerateThumbnailAsync();
                break;
            case "AWS S3":
                var awsS3Object = new AWSS3Storage(fileData, originalFileName, thumbnailSize, thumbnailQuality);
                await awsS3Object.UploadAsync();
                thumbnailData = await awsS3Object.GenerateThumbnailAsync();
                break;
            case "Google Cloud Storage":
                var googleCloudBlob = new GoogleCloudStorage(fileData, originalFileName, thumbnailSize, thumbnailQuality);
                await googleCloudBlob.UploadAsync();
                thumbnailData = await googleCloudBlob.GenerateThumbnailAsync();
                break;
            default:
                throw new InvalidOperationException("Invalid storage provider");
        }

        var metadata = new ThumbnailMetadata
        {
            FileFormat = Path.GetExtension(originalFileName).TrimStart('.'),
            CreationDate = DateTime.Now,
            LastModifiedDate = DateTime.Now,
            OriginalFileSize = fileData.Length,
            ThumbnailFileSize = thumbnailData.Length,
            Dimensions = thumbnailSize
        };

        _cachingService.CacheValue(cacheKey, metadata);
        return metadata;
    }
}

