using System;
using System.Security.Cryptography;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
using System.Threading.Tasks;

public abstract class HasherBase
{
    public enum AlgorithmType { MD5, SHA1, SHA256 }

    protected abstract byte[] ComputeHash(byte[] input);

    public string GetHash(string input, AlgorithmType algorithm)
    {
        using (var memoryStream = new MemoryStream(Encoding.UTF8.GetBytes(input)))
        return BitConverter.ToString(ComputeHash(memoryStream.ToArray())).Replace("-", "").ToLower();
    }

    public async Task<string> GetHashAsync(string input, AlgorithmType algorithm)
    {
        var bytes = Encoding.UTF8.GetBytes(input);
        return await Task.Run(() => BitConverter.ToString(ComputeHash(bytes)).Replace("-", "").ToLower());
    }
}

public class SecureHasher : HasherBase
{
    protected override byte[] ComputeHash(byte[] input)
    {
        using (var hashAlgorithm = GetHashAlgorithm(this.AlgorithmType))
        using (var memoryStream = new MemoryStream(input))
        return hashAlgorithm.ComputeHash(memoryStream);
    }

    private HashAlgorithm GetHashAlgorithm(AlgorithmType algorithm)
    {
        switch (algorithm)
        {
            case AlgorithmType.MD5: return MD5.Create();
            case AlgorithmType.SHA1: return SHA1.Create();
            case AlgorithmType.SHA256: return SHA256.Create();
            default: throw new ArgumentException("Unsupported hash algorithm");
        }
    }

    public override string GetHash(string input, AlgorithmType algorithm)
    {
        var watch = Stopwatch.StartNew();

        var result = base.GetHash(input, algorithm);

        watch.Stop();
        LogPerformance(watch.ElapsedMilliseconds, result.Length * sizeof(char));

        return result;
    }

    public override async Task<string> GetHashAsync(string input, AlgorithmType algorithm)
    {
        var watch = Stopwatch.StartNew();

        var result = await base.GetHashAsync(input, algorithm);

        watch.Stop();
        LogPerformance(watch.ElapsedMilliseconds, result.Length * sizeof(char));

        return result;
    }

    private void LogPerformance(long elapsedTime, int memoryUsageBytes)
    {
        // Use existing logging framework to log performance metrics
        Console.WriteLine($"Elapsed Time: {elapsedTime} ms, Memory Usage: {memoryUsageBytes} bytes");
    }
}

// Example usage:
public class Program
{
    public static async Task Main(string[] args)
    {
        var hasher = new SecureHasher();

        string hash1 = hasher.GetHash("Hello, World!", HasherBase.AlgorithmType.SHA256);
        Console.WriteLine($"SHA256: {hash1}");

        string hash2 = await hasher.GetHashAsync("Hello, World!", HasherBase.AlgorithmType.MD5);
        Console.WriteLine($"MD5: {hash2}");
    }
}
```

