using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;

public struct SensorData
{
    public int Id { get; set; }
    public DateTime Timestamp { get; set; }
    public double Reading { get; set; }
    public string Metadata { get; set; }
    public int ReferenceCount { get; private set; }

    public void IncrementReference()
    {
        ReferenceCount++;
    }

    public bool DecrementReference()
    {
        if (ReferenceCount > 0)
        {
            ReferenceCount--;
            return ReferenceCount == 0;
        }
        return false;
    }
}

public class SensorDataPool
{
    private byte[] _buffer;
    private int _capacity;
    private int _used;

    public SensorDataPool(int capacity)
    {
        _buffer = new byte[capacity];
        _capacity = capacity;
        _used = 0;
    }

    public SensorData Allocate()
    {
        if (_used + sizeof(SensorData) > _capacity)
        {
            throw new OutOfMemoryException();
        }
        var data = BitConverter.ToInt32(_buffer, _used);
        _used += sizeof(SensorData);
        return new SensorData { ReferenceCount = 1 };
    }

    public void Free(ref SensorData data)
    {
        if (data.DecrementReference())
        {
            _used -= sizeof(SensorData);
        }
    }
}

public class Program
{
    public static async Task<string> UploadAndDecryptSensorData(
        string ciphertext,
        byte[] encryptionKey,
        byte[] iv,
        string url,
        int N)
    {
        using (var httpClient = new HttpClient())
        {
            var decryptedData = await DecryptAsync(ciphertext, encryptionKey, iv);
            if (decryptedData == null)
            {
                throw new Exception("Decryption failed.");
            }

            var sensorDataPool = new SensorDataPool(N * sizeof(SensorData));
            SensorData[] sensorDataArray = new SensorData[N];

            for (int i = 0; i < N; i++)
            {
                var data = sensorDataPool.Allocate();
                data.Id = i;
                data.Timestamp = DateTime.Now;
                data.Reading = GenerateReadingValue();
                data.Metadata = "Metadata";
                data.IncrementReference();
                sensorDataArray[i] = data;
            }

            await SerializeToCsvAsync(sensorDataArray, "sensor_data.csv");

            var uploadedUrl = await UploadFileAsync(httpClient, url, "sensor_data.csv");
            return uploadedUrl;
        }
    }

    private static async Task<string> DecryptAsync(string ciphertext, byte[] encryptionKey, byte[] iv)
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = encryptionKey;
                aesAlg.IV = iv;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(ciphertext)))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return await srDecrypt.ReadToEndAsync();
                        }
                    }
                }
            }
        }
        catch (Exception)
        {
            return null;
        }
    }

    private static async Task SerializeToCsvAsync(SensorData[] sensorDataArray, string filePath)
    {
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            await writer.WriteLineAsync("Id,Timestamp,Reading,Metadata");
            foreach (var data in sensorDataArray)
            {
                await writer.WriteLineAsync($"{data.Id},{data.Timestamp},{data.Reading},{data.Metadata}");
            }
        }
    }

    private static async Task<string> UploadFileAsync(HttpClient httpClient, string url, string filePath)
    {
        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            MultipartFormDataContent form = new MultipartFormDataContent();
            form.Add(new StreamContent(fs), "file", Path.GetFileName(filePath));

            HttpResponseMessage response = await httpClient.PostAsync(url, form);
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsStringAsync();
            }
            else
            {
                throw new Exception("Upload failed.");
            }
        }
    }

    private static double GenerateReadingValue()
    {
        // Implement logic to generate a reading value within a specified range.
        return new Random().NextDouble() * 100.0;
    }
}
