typedef struct {
    int sensor_id;
    double timestamp;
    float reading_value;
    char metadata[128];
    int ref_count;
} SensorData;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *iv;
    size_t iv_len;
    size_t buffer_size;
    size_t concurrency_limit;
    double logging_threshold;
} Config;

SensorData* create_sensor_data(int sensor_id, double timestamp, float reading_value, const char* metadata) {
    SensorData* data = malloc(sizeof(SensorData));
    if (data == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    data->sensor_id = sensor_id;
    data->timestamp = timestamp;
    data->reading_value = reading_value;
    strncpy(data->metadata, metadata, sizeof(data->metadata) - 1);
    data->metadata[sizeof(data->metadata) - 1] = '\0';
    data->ref_count = 1;
    return data;
}

void increment_ref_count(SensorData* data) {
    data->ref_count++;
}

void decrement_ref_count(SensorData* data) {
    data->ref_count--;
    if (data->ref_count == 0) {
        free(data);
    }
}

SensorData** allocate_sensor_data_array(size_t N, Config* config) {
    SensorData** array = malloc(N * sizeof(SensorData*));
    if (array == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    for (size_t i = 0; i < N; ++i) {
        array[i] = create_sensor_data(i, (double)i / 100.0, (float)i * 2.0, "Metadata");
        if (array[i] == NULL) {
            // Handle memory allocation error
            for (size_t j = 0; j < i; ++j) {
                decrement_ref_count(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

void free_sensor_data_array(SensorData** array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        decrement_ref_count(array[i]);
    }
    free(array);
}

