function copyBufferedData(bufferChunks, numBytes) {
  const newBuffer = Buffer.allocUnsafe(numBytes);
  let offset = 0;

  for (const chunk of bufferChunks) {
    if (offset >= numBytes) break;
    const bytesToCopy = Math.min(chunk.length, numBytes - offset);
    chunk.copy(newBuffer, offset, 0, bytesToCopy);
    offset += bytesToCopy;
  }

  return newBuffer;
}

