public struct SecureTrafficEvent
{
    public DateTime Timestamp { get; set; }
    public string EventType { get; set; }
    public int UniqueID { get; set; }
    public byte[] EncryptedData { get; set; }
}

public class TrafficEventInitializer
{
    private const int MaxEvents = 1024;
    private const int MaxChunkSize = 64 * 1024;

    public static SecureTrafficEvent[] InitializeSecureTrafficEvents(int N, byte[] encryptionKey, byte[] iv, int? maxFileSize = null)
    {
        if (N > MaxEvents || N <= 0) throw new ArgumentOutOfRangeException(nameof(N), "Number of events must be between 1 and 1024.");
        if (encryptionKey == null || iv == null || encryptionKey.Length != 32 || iv.Length != 16) throw new ArgumentException("Invalid encryption key or IV.");

        SecureTrafficEvent[] events = new SecureTrafficEvent[N];
        Random random = new Random();
        string[] eventTypes = { "Collision", "Speeding", "RedLightRunning" };

        for (int i = 0; i < N; i++)
        {
            events[i].Timestamp = DateTime.Now;
            events[i].EventType = eventTypes[random.Next(eventTypes.Length)];
            events[i].UniqueID = i;

            string dataToEncrypt = $"Event {i}: {events[i].Timestamp} - {events[i].EventType}";
            byte[] plainTextBytes = Encoding.UTF8.GetBytes(dataToEncrypt);

            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = encryptionKey;
                aesAlg.IV = iv;

                ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
                using (MemoryStream msEncrypt = new MemoryStream())
                {
                    using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        csEncrypt.Write(plainTextBytes, 0, plainTextBytes.Length);
                    }
                    events[i].EncryptedData = msEncrypt.ToArray();
                }
            }

            if (maxFileSize.HasValue && events[i].EncryptedData.Length > maxFileSize.Value)
            {
                throw new InvalidOperationException("Total data size exceeds maximum file size.");
            }
        }

        return events;
    }

    public static bool VerifyEventIntegrity(SecureTrafficEvent eventToVerify, byte[] encryptionKey, byte[] iv)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = encryptionKey;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            using (MemoryStream msDecrypt = new MemoryStream(eventToVerify.EncryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
