#include <sys/time.h>

#define MAX_CACHE_SIZE 1024
#define TTL_SECONDS (60 * 60)

typedef struct {
    char hostname[NI_MAXHOST];
    in_addr_t ip_address;
    time_t expiration_time;
} DNSCacheEntry;

DNSCacheEntry dns_cache[MAX_CACHE_SIZE];
int cache_count = 0;

void log_message(const char *message) {
    // Implementation of logging
}

in_addr_t resolve_hostname(const char *hostname) {
    struct addrinfo hints, *res;
    int status;
    in_addr_t ip_address = INADDR_NONE;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message("DNS resolution failed for %s: %s\n", hostname, gai_strerror(status));
        return INADDR_NONE;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    ip_address = ipv4->sin_addr.s_addr;

    freeaddrinfo(res);

    // Cache the result
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            dns_cache[i].ip_address = ip_address;
            dns_cache[i].expiration_time = time(NULL) + TTL_SECONDS;
            return ip_address;
        }
    }

    if (cache_count < MAX_CACHE_SIZE) {
        strcpy(dns_cache[cache_count].hostname, hostname);
        dns_cache[cache_count].ip_address = ip_address;
        dns_cache[cache_count].expiration_time = time(NULL) + TTL_SECONDS;
        cache_count++;
    } else {
        log_message("DNS cache is full\n");
    }

    return ip_address;
}

int main() {
    const char *hostname = "example.com";
    in_addr_t ip_address = resolve_hostname(hostname);
    if (ip_address != INADDR_NONE) {
        printf("IP address for %s: %u\n", hostname, ip_address);
    } else {
        printf("Failed to resolve IP address for %s\n", hostname);
    }
    return 0;
}
