#define MAX_CACHE_SIZE 1024

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    unsigned int ip;
    time_t expiry_time;
} DNSCacheEntry;

DNSCacheEntry dns_cache[MAX_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void init_dns_cache() {
    memset(dns_cache, 0, sizeof(dns_cache));
}

unsigned int resolve_hostname(const char *hostname) {
    pthread_mutex_lock(&cache_lock);
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (dns_cache[i].expiry_time > current_time && strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[i].ip;
        }
    }

    unsigned int ip = inet_addr(hostname);
    if (ip == INADDR_NONE) {
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        getaddrinfo(hostname, NULL, &hints, &res);

        ip = ((struct sockaddr_in*)res->ai_addr)->sin_addr.s_addr;
        freeaddrinfo(res);
    }

    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (dns_cache[i].expiry_time == 0) {
            dns_cache[i].ip = ip;
            strcpy(dns_cache[i].hostname, hostname);
            dns_cache[i].expiry_time = current_time + 3600;
            break;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return ip;
}

