#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <pthread.h>

#define MAX_NF_API_PDU 1024
#define DNS_CACHE_SIZE 512
#define DNS_TIMEOUT_SEC 2
#define MAX_RETRIES 5

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DnsCacheEntry {
    char hostname[256];
    struct in_addr ip_v4;
    struct in6_addr ip_v6;
    time_t last_updated;
} DnsCacheEntry;

DnsCacheEntry dns_cache[DNS_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* resolve_dns(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    char hostname[256];
    struct sockaddr_storage result_addr;
    socklen_t result_len = sizeof(result_addr);
    int status, i;

    // Simulate fetching hostnames from NF API PDU
    snprintf(hostname, sizeof(hostname), "example%d.com", pdu->RNTI);

    pthread_mutex_lock(&cache_lock);
    for (i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && time(NULL) - dns_cache[i].last_updated <= 3600) {
            memcpy(&pdu->ip_v4.s_addr, &dns_cache[i].ip_v4.s_addr, sizeof(pdu->ip_v4.s_addr));
            memcpy(&pdu->ip_v6.s6_addr, &dns_cache[i].ip_v6.s6_addr, sizeof(pdu->ip_v6.s6_addr));
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    for (i = 0; i < MAX_RETRIES; i++) {
        status = getaddrinfo(hostname, NULL, NULL, &result_addr);
        if (status == 0) {
            break;
        }
        sleep(DNS_TIMEOUT_SEC << i);
    }

    if (status != 0) {
        fprintf(stderr, "DNS resolution failed for %s: %s\n", hostname, gai_strerror(status));
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);
    for (i = 0; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i].hostname[0] == '\0') {
            strcpy(dns_cache[i].hostname, hostname);
            if (result_addr.ss_family == AF_INET) {
                memcpy(&dns_cache[i].ip_v4.s_addr, &((struct sockaddr_in*)&result_addr)->sin_addr, sizeof(dns_cache[i].ip_v4.s_addr));
            } else if (result_addr.ss_family == AF_INET6) {
                memcpy(&dns_cache[i].ip_v6.s6_addr, &((struct sockaddr_in6*)&result_addr)->sin6_addr, sizeof(dns_cache[i].ip_v6.s6_addr));
            }
            dns_cache[i].last_updated = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    if (i == DNS_CACHE_SIZE) {
        fprintf(stderr, "DNS cache full for %s\n", hostname);
    }

    freeaddrinfo(result_addr);
    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu[MAX_NF_API_PDU];
    pthread_t threads[MAX_NF_API_PDU];
    int i;

    // Simulate receiving PDUs with random CRC flags and hostnames
    for (i = 0; i < MAX_NF_API_PDU; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = i;
        pdu[i].RNTI = rand() % 1000;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Resolve DNS for each PDU in parallel
    for (i = 0; i < MAX_NF_API_PDU; i++) {
        if (pthread_create(&threads[i], NULL, resolve_dns, &pdu[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
        }
    }

    // Wait for all threads to complete
    for (i = 0; i < MAX_NF_API_PDU; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
