use reqwest::{ClientBuilder, RequestBuilder, Error};
use std::time::Duration;

fn create_http_client(
    url: &str,
    disable_certificate_validation: bool,
    custom_headers: Option<Vec<(String, String)>>,
    timeout: Option<Duration>,
    body: Option<&[u8]>,
) -> Result<RequestBuilder, Error> {
    let mut builder = ClientBuilder::new();

    if disable_certificate_validation {
        builder.dangerously_disable_hostname_verification();
        builder.dangerously_disable_http_redirect();
    }

    if let Some(headers) = custom_headers {
        for (key, value) in headers {
            builder = builder.header(key, value);
        }
    }

    if let Some(timeout) = timeout {
        builder = builder.timeout(timeout);
    }

    if let Some(body) = body {
        builder = builder.body(body.to_vec());
    }

    Ok(builder.build()?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use reqwest::Method;

    #[test]
    fn test_create_http_client() -> Result<(), Error> {
        let url = "https://example.com";
        let disable_certificate_validation = true;
        let custom_headers = Some(vec![
            ("User-Agent".to_string(), "MyApp/1.0".to_string()),
        ]);
        let timeout = Some(Duration::from_secs(10));
        let body = Some(b"Hello, world!".as_ref());

        let request_builder = create_http_client(
            url,
            disable_certificate_validation,
            custom_headers,
            timeout,
            body,
        )?;

        assert_eq!(request_builder.method(), Method::POST);
        assert_eq!(request_builder.url().as_str(), url);
        assert_eq!(request_builder.headers()["User-Agent"], "MyApp/1.0");
        assert_eq!(request_builder.timeout(), Some(Duration::from_secs(10)));
        assert_eq!(request_builder.body().unwrap(), b"Hello, world!".as_ref());

        Ok(())
    }
}
```

