#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CACHE_SIZE 1024
#define DEFAULT_LOG_LEVEL "INFO"
#define CACHE_EXPIRY_TIME 3600

typedef struct {
    char hostname[NI_MAXHOST];
    struct in_addr ip;
    time_t expiry_time;
} DNSCacheEntry;

DNSCacheEntry dns_cache[MAX_CACHE_SIZE];

int resolve_hostname(const char *hostname, u_char *ip_address) {
    // Check cache first
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && time(NULL) < dns_cache[i].expiry_time) {
            memcpy(ip_address, &dns_cache[i].ip.s_addr, sizeof(u_char));
            return 0;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        memcpy(ip_address, addr, sizeof(u_char));

        // Cache the result
        for (int i = 0; i < MAX_CACHE_SIZE; i++) {
            if (dns_cache[i].hostname[0] == '\0') {
                strcpy(dns_cache[i].hostname, hostname);
                dns_cache[i].ip.s_addr = *(u_int32_t*)addr;
                dns_cache[i].expiry_time = time(NULL) + CACHE_EXPIRY_TIME;
                break;
            }
        }

        freeaddrinfo(res); // Free the linked list
        return 0;
    }

    fprintf(stderr, "Failed to resolve hostname\n");
    return -1;
}

int main() {
    u_char ip_address[4];
    int status = resolve_hostname("example.com", ip_address);
    if (status == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr *)ip_address));
    } else {
        printf("Failed to resolve hostname\n");
    }
    return 0;
}
