    tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Some(data) => {
                    for processor in &processors {
                        if let Err(e) = processor.process(data.clone()).await {
                            // Handle error
                        }
                    }
                },
                None => break,
            }
        }
    });

