        tokio::spawn(async move {
            loop {
                match data_source.fetch().await {
                    Ok(data) => {
                        if let Err(e) = tx.send(data).await {
                            // Handle error
                        }
                    },
                    Err(e) => {
                        // Handle error
                    },
                }
            }
        });
    }

    while let Some(metrics) = Metrics::collect() {
        if let Err(e) = metrics_logger.log_metrics(metrics).await {
            // Handle error
        }
    }
}

