    let data_store = Arc::new(RwLock::new(HashMap::new()));
    let (tx, mut rx) = mpsc::channel(100);

    // Spawn ingestion tasks for different sources
    task::spawn(async move {
        ingest_kafka_data(tx.clone());
        ingest_http_data(tx.clone());
        ingest_grpc_data(tx.clone());
    });

