        process_data(&data_store, &data).await;
    }
}

async fn ingest_kafka_data(tx: mpsc::Sender<Value>) {
    // Simulate Kafka data ingestion
    tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
    tx.send(json!({"source": "kafka", "data": {"type": "json"}})).await.unwrap();
}

async fn ingest_http_data(tx: mpsc::Sender<Value>) {
    // Simulate HTTP data ingestion
