}

async fn process_data(data_store: &Arc<RwLock<HashMap<String, Value>>>, data: &Value) {
    let mut store = data_store.write().await;
    // Process and store data based on schema
    if let Some(data_type) = data["data"]["type"].as_str() {
        store.insert(format!("data_{}", data_type), data.clone());
    }
}
