#define MAX_N 1024

typedef struct {
    uint32_t global_id;
    // Other TAI entity fields
} TAI_ENTITY;

typedef struct {
    uint8_t crcflag;
    // Other RX_UE_INFORMATION_TAG fields
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t rnti;
    // Other RNTI fields
} RNTI;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    TAI_ENTITY* tai_list;
    size_t tai_count;
    // Other NFAPI_CRC_INDICATION_PDU_T fields
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    size_t capacity;
} NFAPI_POOL;

NFAPI_POOL* create_nfaip_pool(size_t initial_capacity) {
    NFAPI_POOL* pool = (NFAPI_POOL*)malloc(sizeof(NFAPI_POOL));
    if (!pool) return NULL;

    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdu_list) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->pdu_list[i].tai_list = NULL;
        pool->pdu_list[i].tai_count = 0;
    }

    return pool;
}

void free_nfaip_pool(NFAPI_POOL* pool) {
    if (pool) {
        for (size_t i = 0; i < pool->count; ++i) {
            if (pool->pdu_list[i].tai_list) {
                free(pool->pdu_list[i].tai_list);
                pool->pdu_list[i].tai_list = NULL;
                pool->pdu_list[i].tai_count = 0;
            }
        }
        free(pool->pdu_list);
        free(pool);
    }
}

int add_nfaip_pdu(NFAPI_POOL* pool, RX_UE_INFORMATION_TAG rx_tag, RNTI rnti, TAI_ENTITY* tai_list, size_t tai_count) {
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity == 0 ? 1 : pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) return -1;

        for (size_t i = pool->count; i < new_capacity; ++i) {
            new_list[i].tai_list = NULL;
            new_list[i].tai_count = 0;
        }

        pool->pdu_list = new_list;
        pool->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pdu_list[pool->count++];
    pdu->rx_tag = rx_tag;
    pdu->rnti = rnti;
    if (tai_count) {
        TAI_ENTITY* new_tai_list = (TAI_ENTITY*)malloc(tai_count * sizeof(TAI_ENTITY));
        if (!new_tai_list) return -1;

        memcpy(new_tai_list, tai_list, tai_count * sizeof(TAI_ENTITY));

        pdu->tai_list = new_tai_list;
        pdu->tai_count = tai_count;
    }

    return 0;
}

