#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct DATA_RECORD_T {
    long timestamp;
    float sensor_reading;
    int status_code;
} DATA_RECORD_T;

typedef struct NODE_T {
    DATA_RECORD_T data;
    struct NODE_T *next;
} NODE_T;

typedef struct LIST_T {
    NODE_T *head;
    NODE_T *tail;
    pthread_mutex_t mutex;
} LIST_T;

LIST_T list;

void init_list() {
    list.head = NULL;
    list.tail = NULL;
    pthread_mutex_init(&list.mutex, NULL);
}

NODE_T* create_node(DATA_RECORD_T data) {
    NODE_T *new_node = (NODE_T*)malloc(sizeof(NODE_T));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_record(DATA_RECORD_T data) {
    pthread_mutex_lock(&list.mutex);
    NODE_T *new_node = create_node(data);
    if (!list.head) {
        list.head = list.tail = new_node;
    } else {
        list.tail->next = new_node;
        list.tail = new_node;
    }
    pthread_mutex_unlock(&list.mutex);
}

void calculate_averages(int window_size, float *sensor_readings, int *record_count) {
    if (window_size <= 0 || sensor_readings == NULL || record_count == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    pthread_mutex_lock(&list.mutex);
    NODE_T *current = list.head;
    int count = 0;

    while (current != NULL && count < window_size) {
        sensor_readings[count] = current->data.sensor_reading;
        count++;
        current = current->next;
    }

    if (count == window_size) {
        float sum = 0.0f;
        for (int i = 0; i < window_size; i++) {
            sum += sensor_readings[i];
        }
        float average = sum / window_size;

        DATA_RECORD_T data;
        data.sensor_reading = average;
        insert_record(data);
    }

    pthread_mutex_unlock(&list.mutex);
}

void log_memory_usage() {
    // Implement memory usage logging logic here
}

int main() {
    init_list();

    int window_size = 10;
    float sensor_readings[MAX_RECORDS];
    int record_count = 0;

    calculate_averages(window_size, sensor_readings, &record_count);

    log_memory_usage();

    return 0;
}
