    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Initialize the array with random values and valid ranges
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        array[i].RNTI = rand() % UINT16_MAX;
        CRC_INDICATION_REL8_TAG *crc_tag = &array[i].crc_indication_rel8_tag;
        crc_tag->CRCFLAG = rand() % 2; // Example range
    }

    pthread_mutex_destroy(&lock);
    return array;
}

