            printf("Created PDU %d with RX_UE_INFORMATION_TAG: %llu, RNTI: %u, CRC_FLAG: %u\n", i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
