#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LogEntry {
    int logId;
    char timestamp[20];
    char source[50];
    char message[200];
} LogEntry;

typedef struct ListNode {
    LogEntry data;
    struct ListNode* next;
} ListNode;

typedef struct LogCache {
    char* message;
    int count;
} LogCache;

typedef struct LogList {
    ListNode* head;
    pthread_mutex_t mutex;
    LogCache** cache;
    int cacheSize;
} LogList;

LogList* createLogList(int cacheSize) {
    LogList* list = (LogList*)malloc(sizeof(LogList));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->cache = (LogCache**)malloc(cacheSize * sizeof(LogCache*));
    for (int i = 0; i < cacheSize; i++) {
        list->cache[i] = (LogCache*)malloc(sizeof(LogCache));
        list->cache[i]->message = (char*)malloc(200);
        list->cache[i]->count = 0;
    }
    list->cacheSize = cacheSize;
    return list;
}

void insertLogEntry(LogList* list, LogEntry entry) {
    pthread_mutex_lock(&list->mutex);
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    newNode->data = entry;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

void deleteLogEntry(LogList* list, int logId) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    ListNode* previous = NULL;

    while (current != NULL) {
        if (current->data.logId == logId) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

LogEntry* retrieveLogEntry(LogList* list, int logId) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;

    while (current != NULL) {
        if (current->data.logId == logId) {
            LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
            *entry = current->data;
            pthread_mutex_unlock(&list->mutex);
            return entry;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void updateCache(LogList* list, LogEntry entry) {
    for (int i = 0; i < list->cacheSize; i++) {
        if (strcmp(list->cache[i]->message, entry.message) == 0) {
            list->cache[i]->count++;
            return;
        }
    }

    int leastUsedIndex = 0;
    for (int i = 1; i < list->cacheSize; i++) {
        if (list->cache[i]->count < list->cache[leastUsedIndex]->count) {
            leastUsedIndex = i;
        }
    }

    free(list->cache[leastUsedIndex]->message);
    strcpy(list->cache[leastUsedIndex]->message, entry.message);
    list->cache[leastUsedIndex]->count = 1;
}

void printLogList(LogList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;

    while (current != NULL) {
        printf("Log ID: %d, Timestamp: %s, Source: %s, Message: %s\n",
               current->data.logId,
               current->data.timestamp,
               current->data.source,
               current->data.message);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void freeLogList(LogList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }

    for (int i = 0; i < list->cacheSize; i++) {
        free(list->cache[i]->message);
        free(list->cache[i]);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list->cache);
    free(list);
}
