#define N 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateAndPopulateNFAPduList() {
    NFAPI_CRC_INDICATION_PDU_T *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) return NULL;

    for (int i = 0; i < N; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pduList[i].RNTI = (uint16_t)(rand() % UINT16_MAX);
        pduList[i].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2); // Randomly set CRCFLAG
    }

    return pduList;
}

int decryptCiphertext(const unsigned char *ciphertext, size_t ciphertext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    // Remove padding
    unsigned char *padding_start = plaintext + plaintext_len - 1;
    int pad_length = *padding_start;
    if (pad_length > ciphertext_len || pad_length == 0) {
        return -1; // Invalid padding
    }
    for (int i = 1; i <= pad_length; ++i) {
        if (padding_start[i - 1] != pad_length) {
            return -1; // Invalid padding
        }
    }

    plaintext_len -= pad_length;

    return plaintext_len;
}
