#define RNTI 500
#define CRC_INDICATION_REL8_TAG 200

NFAPI_CRC_INDICATION_PDU_T* generateAndPopulateNFAPduList(int numPDUs) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) return NULL;

