        pduList[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        pduList[i].rnti = RNTI;
        pduList[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    return pduList;
}

unsigned char* decryptCiphertext(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* key, const unsigned char* iv) {
    unsigned char* plaintext = (unsigned char*)malloc(ciphertext_len);
    if (plaintext == NULL) return NULL;

    AES_KEY aes_key;
    if (AES_set_decrypt_key(key, 128, &aes_key) < 0) {
        free(plaintext);
        return NULL;
    }

    int len;
    if (AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &aes_key, iv, AES_DECRYPT) != 0) {
        free(plaintext);
        return NULL;
    }

    // Remove padding
    unsigned char padding = plaintext[len - 1];
    if (padding > 0 && padding <= 16) {
        memmove(plaintext + len - padding, plaintext + len - 1, padding);
    } else {
        free(plaintext);
        return NULL;
    }

    plaintext[len - padding] = '\0';
    return plaintext;
}
