use std::env;

fn create_logging_config(file_name: &str) -> io::Result<String> {
    let mut file_path = Path::new(".");
    if file_path.read_dir().is_err() || !file_path.canonicalize().is_ok() {
        file_path = Path::new("/tmp");
    }

    let full_path = file_path.join(file_name);
    if full_path.exists() {
        eprintln!("Warning: Logging config file already exists at {:?}", full_path);
        return Ok(full_path.to_string_lossy().into());
    }

    File::create(&full_path)?;
    env::set_var("LOGGING_CONFIG_PATH", &full_path);
    Ok(full_path.to_string_lossy().into())
}

