class PreferenceManager:
    def __init__(self, storage_backend=None, serialization_format='json'):
        self.storage_backend = storage_backend or LocalFileStorage()
        self.serialization_format = serialization_format

    def set_preference(self, key, value):
        serialized_value = serialize(value, self.serialization_format)
        self.storage_backend.save(key, serialized_value)

    def get_preference(self, key):
        serialized_value = self.storage_backend.load(key)
        return deserialize(serialized_value, self.serialization_format)

    def remove_preference(self, key):
        self.storage_backend.delete(key)

class StorageBackend:
    def save(self, key, value):
        raise NotImplementedError

    def load(self, key):
        raise NotImplementedError

    def delete(self, key):
        raise NotImplementedError

class LocalFileStorage(StorageBackend):
    def save(self, key, value):
        with open(f'{key}.pref', 'w') as file:
            file.write(value)

    def load(self, key):
        try:
            with open(f'{key}.pref', 'r') as file:
                return file.read()
        except FileNotFoundError:
            return None

    def delete(self, key):
        import os
        os.remove(f'{key}.pref')

def serialize(data, format='json'):
    if format == 'json':
        import json
        return json.dumps(data)
    elif format == 'pickle':
        import pickle
        return pickle.dumps(data)
    else:
        raise ValueError("Unsupported serialization format")

def deserialize(serialized_data, format='json'):
    if format == 'json':
        import json
        return json.loads(serialized_data)
    elif format == 'pickle':
        import pickle
        return pickle.loads(serialized_data)
    else:
        raise ValueError("Unsupported deserialization format")
