# Thread-safe reference counting
class ReferenceCounter:
    def __init__(self):
        self._ref_count = 0
        self._lock = threading.Lock()

    def increment(self):
        with self._lock:
            self._ref_count += 1

    def decrement(self):
        with self._lock:
            self._ref_count -= 1

    def get_count(self):
        return self._ref_count

# Example usage
counter = ReferenceCounter()
counter.increment()
counter.increment()
print(counter.get_count())  # Output: 2
counter.decrement()
print(counter.get_count())  # Output: 1
