#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int logId;
    time_t timestamp;
    char *source;
    char *message;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} LogList;

void initLogList(LogList *list, size_t initialCapacity) {
    list->capacity = initialCapacity;
    list->size = 0;
    list->entries = (LogEntry **)malloc(initialCapacity * sizeof(LogEntry *));
    pthread_mutex_init(&list->mutex, NULL);
}

void freeLogEntry(LogEntry *entry) {
    free(entry->source);
    free(entry->message);
    free(entry);
}

void insertLogEntry(LogList *list, LogEntry *entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(LogEntry *));
    }
    list->entries[list->size++] = entry;
    pthread_mutex_unlock(&list->mutex);
}

void deleteLogEntry(LogList *list, int logId) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->logId == logId) {
            freeLogEntry(list->entries[i]);
            memmove(&list->entries[i], &list->entries[i + 1], (list->size - i - 1) * sizeof(LogEntry *));
            --list->size;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

LogEntry *getLogEntry(LogList *list, int logId) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->logId == logId) {
            LogEntry *entry = list->entries[i];
            pthread_mutex_unlock(&list->mutex);
            return entry;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void cleanupLogList(LogList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        freeLogEntry(list->entries[i]);
    }
    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
}
