#include <pthread.h>

typedef struct {
    int packetId;
    time_t timestamp;
    size_t dataSize;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PacketArray;

void logError(const char* message) {
    // Implement error logging to a file specified by the user
}

int initializePacketArray(PacketArray* array, size_t initialCapacity) {
    array->packets = (DataPacket*)malloc(initialCapacity * sizeof(DataPacket));
    if (!array->packets) {
        logError("Memory allocation failed for packet array");
        return -1;
    }
    array->count = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

int resizePacketArray(PacketArray* array, size_t newCapacity) {
    pthread_mutex_lock(&array->mutex);
    DataPacket* newPackets = (DataPacket*)realloc(array->packets, newCapacity * sizeof(DataPacket));
    if (!newPackets) {
        logError("Memory reallocation failed for packet array");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    array->packets = newPackets;
    array->capacity = newCapacity;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int addPacket(PacketArray* array, const DataPacket* packet) {
    if (array->count >= array->capacity && resizePacketArray(array, array->capacity * 2) == -1) {
        return -1;
    }
    pthread_mutex_lock(&array->mutex);
    array->packets[array->count++] = *packet;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

double calculateAverageDataSize(const PacketArray* array) {
    if (array->count == 0) {
        return 0.0;
    }
    size_t totalSize = 0;
    for (size_t i = 0; i < array->count; ++i) {
        totalSize += array->packets[i].dataSize;
    }
    return (double)totalSize / array->count;
}

void destroyPacketArray(PacketArray* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->packets);
}
