typedef enum { false, true } bool;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} NFAPI_crc_indication_pdu_manager_t;

void NFAPI_crc_indication_pdu_manager_init(NFAPI_crc_indication_pdu_manager_t *manager) {
    manager->array = NULL;
    manager->allocated_size = 0;
    manager->used_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

bool NFAPI_crc_indication_pdu_manager_expand(NFAPI_crc_indication_pdu_manager_t *manager, size_t additional_elements) {
    if (additional_elements == 0) return true;

    size_t new_size = manager->used_size + additional_elements;
    if (new_size > 10000) return false; // Exceeds maximum capacity

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false; // Out of memory

    manager->array = new_array;
    manager->allocated_size = new_size;
    return true;
}

enum {
    SUCCESS,
    OUT_OF_MEMORY,
    INVALID_INPUT
};

int NFAPI_crc_indication_pdu_manager_process(NFAPI_crc_indication_pdu_manager_t *manager, size_t N) {
    if (N == 0 || N > 10000) return INVALID_INPUT;

    pthread_mutex_lock(&manager->lock);
    int status = NFAPI_crc_indication_pdu_manager_expand(manager, N);
    pthread_mutex_unlock(&manager->lock);

    if (!status) return OUT_OF_MEMORY; // Allocation failed

    for (size_t i = manager->used_size; i < manager->used_size + N; ++i) {
