#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initializeNFAPIPacket(NFAPI_CRC_INDICATION_PDU_T *packet) {
    packet->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    packet->RNTI = rand() % 256; // Example initialization
    packet->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

int allocateAndInitializeNFAPIArray(NFAPI_CRC_INDICATION_PDU_T **array, int N) {
    if (N > MAX_ELEMENTS || N < 0) {
        return -1; // Invalid input size
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return N; // Return number of elements processed before failure
    }

    for (int i = 0; i < N; i++) {
        initializeNFAPIPacket(&(*array)[i]);
    }

    return N; // Successfully allocated and initialized all elements
}

// Example usage with concurrency handling
pthread_mutex_t lock;
NFAPI_CRC_INDICATION_PDU_T *sharedArray[MAX_ELEMENTS];

void* initializeThread(void *arg) {
    int threadId = *(int *)arg;
    int start = threadId * (MAX_ELEMENTS / 10);
    int end = start + MAX_ELEMENTS / 10;

    for (int i = start; i < end; i++) {
        pthread_mutex_lock(&lock);
        if (sharedArray[i] == NULL) {
            sharedArray[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            initializeNFAPIPacket(sharedArray[i]);
        }
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int main() {
    srand(time(0));

    pthread_t threads[10];
    int threadIds[10];

    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < 10; i++) {
        threadIds[i] = i;
        pthread_create(&threads[i], NULL, initializeThread, &threadIds[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (sharedArray[i] != NULL) {
            free(sharedArray[i]);
        }
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
