int parse_command_line(int argc, char *argv[], int *output_mode, const char **output_file) {
    if (argc < 2) {
        printf("Usage: %s [--manpage] [-cs] [-o output_file]\n", argv[0]);
        return -1;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            *output_mode = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            *output_mode = 2;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            *output_file = argv[i] + 3;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int output_mode = 0; // Default mode
    const char *output_file = DEFAULT_OUTPUT;

    if (parse_command_line(argc, argv, &output_mode, &output_file) != 0) {
        return EXIT_FAILURE;
    }

    FILE *input_file = fopen("input.txt", "r");
    if (!input_file) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    PHY_STATS_PDU_T *array = (PHY_STATS_PDU_T *)malloc(MAX_ELEMENTS * sizeof(PHY_STATS_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int line_count = 0;

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), input_file)) {
        if (line_count >= MAX_ELEMENTS) {
            fprintf(stderr, "Input size exceeds maximum limit\n");
            break;
        }
        pthread_mutex_lock(&lock);
        initialize_struct(&array[line_count], rand() % 10, rand() % 256); // Random power level and channel ID
        pthread_mutex_unlock(&lock);
        line_count++;
    }

    fclose(input_file);

    printf("Number of lines processed: %d\n", line_count);

    free(array);

    return EXIT_SUCCESS;
}
