#include <stdlib.h>
#include <time.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T reliable_data;
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    int unique_id;
    time_t timestamp;
    int sensor_id;
    float measurement_value;
    int quality_flag;
    char* metadata;
} SensorReading;

typedef struct {
    SensorReading** readings;
    size_t count;
    size_t capacity;
} SensorDataArray;

SensorDataArray* create_sensor_data_array(size_t initial_capacity) {
    SensorDataArray* array = (SensorDataArray*)malloc(sizeof(SensorDataArray));
    if (!array) return NULL;

    array->readings = (SensorReading**)malloc(initial_capacity * sizeof(SensorReading*));
    if (!array->readings) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;

    return array;
}

void destroy_sensor_data_array(SensorDataArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->readings[i]->metadata);
        free(array->readings[i]);
    }
    free(array->readings);
    free(array);
}

int add_sensor_reading(SensorDataArray* array, NFAPI_CRC_INDICATION_PDU_T reliable_data, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_tag, int sensor_id, float measurement_value, int quality_flag, const char* metadata) {
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        SensorReading** new_readings = (SensorReading**)realloc(array->readings, new_capacity * sizeof(SensorReading*));
        if (!new_readings) return -1;

        array->readings = new_readings;
        array->capacity = new_capacity;
    }

    SensorReading* reading = (SensorReading*)malloc(sizeof(SensorReading));
    if (!reading) return -1;

    reading->reliable_data = reliable_data;
    reading->ue_info_tag = ue_info_tag;
    reading->rnti = rnti;
    reading->crc_ind_tag = crc_ind_tag;
    reading->unique_id = rand();
    reading->timestamp = time(NULL);
    reading->sensor_id = sensor_id;
    reading->measurement_value = measurement_value;
    reading->quality_flag = quality_flag;

    size_t metadata_length = strlen(metadata) + 1;
    reading->metadata = (char*)malloc(metadata_length * sizeof(char));
    if (!reading->metadata) {
        free(reading);
        return -1;
    }
    strcpy(reading->metadata, metadata);

    array->readings[array->count++] = reading;

    return 0;
}

int main() {
    srand(time(NULL));

    SensorDataArray* sensor_data = create_sensor_data_array(10);
    if (!sensor_data) return -1;

    NFAPI_CRC_INDICATION_PDU_T reliable_data = { /* initialize fields */ };
    RX_UE_INFORMATION_TAG ue_info_tag = { /* initialize fields */ };
    RNTI rnti = 1234;
    CRC_INDICATION_REL8_TAG crc_ind_tag = { /* initialize fields */ };

    if (add_sensor_reading(sensor_data, reliable_data, ue_info_tag, rnti, crc_ind_tag, 1, 25.0, 1, "Temperature")) {
        destroy_sensor_data_array(sensor_data);
        return -1;
    }

    // Process sensor data...

    destroy_sensor_data_array(sensor_data);
    return 0;
}
