#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the LogEntry structure
typedef struct {
    int logId;
    time_t timestamp;
    char source[100];
    char message[256];
} LogEntry;

// Define a Node for the linked list
typedef struct Node {
    LogEntry data;
    struct Node* next;
} Node;

// Define the List structure
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

// Function to create a new LogEntry
LogEntry* create_log_entry(int id, time_t ts, const char* src, const char* msg) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->logId = id;
    entry->timestamp = ts;
    strncpy(entry->source, src, 100);
    strncpy(entry->message, msg, 256);
    return entry;
}

// Function to create a new Node
Node* create_node(LogEntry* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = *data;
    node->next = NULL;
    return node;
}

// Function to initialize the List
void init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to insert a new LogEntry at the end of the list
void insert_log_entry(List* list, LogEntry* entry) {
    Node* new_node = create_node(entry);
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to delete a LogEntry from the list
void delete_log_entry(List* list, int id) {
    Node* current = list->head;
    Node* previous = NULL;
    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        if (current->data.logId == id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a LogEntry from the list by ID
LogEntry* get_log_entry(List* list, int id) {
    Node* current = list->head;
    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        if (current->data.logId == id) {
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to free the memory allocated for the list
void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}
