typedef struct tai_entity {
    int global_id;
    struct tai_entity *next;
} TAI_ENTITY;

typedef struct tai_manager {
    TAI_ENTITY **tai_list;
    size_t max_k;
    size_t current_k;
    pthread_mutex_t lock;
} TAI_MANAGER;

TAI_MANAGER* create_tai_manager(size_t k) {
    TAI_MANAGER *manager = (TAI_MANAGER *)malloc(sizeof(TAI_MANAGER));
    if (!manager) return NULL;

    manager->tai_list = (TAI_ENTITY **)calloc(k, sizeof(TAI_ENTITY *));
    if (!manager->tai_list) {
        free(manager);
        return NULL;
    }

    manager->max_k = k;
    manager->current_k = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_tai_manager(TAI_MANAGER *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->current_k; ++i) {
        TAI_ENTITY *current = manager->tai_list[i];
        while (current) {
            TAI_ENTITY *next = current->next;
            free(current);
            current = next;
        }
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->tai_list);
    free(manager);
}

int add_tai(TAI_MANAGER *manager, int global_id) {
    if (!manager || manager->current_k >= manager->max_k) return -1;

    TAI_ENTITY *new_tai = (TAI_ENTITY *)malloc(sizeof(TAI_ENTITY));
    if (!new_tai) return -1;

    new_tai->global_id = global_id;
    new_tai->next = NULL;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->current_k; ++i) {
        if (!manager->tai_list[i]) {
            manager->tai_list[i] = new_tai;
            ++manager->current_k;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Add more functions as needed for managing TAIs, such as remove_tai, update_tai, etc.

int main() {
    TAI_MANAGER *tai_manager = create_tai_manager(1000);
    if (tai_manager) {
        // Use the tai_manager to manage TAIs
        destroy_tai_manager(tai_manager);
    }
    return 0;
}
