typedef struct {
    int DNS_SERVER_ID;
    char *IP_ADDRESS;
    int PORT_NUMBER;
    int TIMEOUT;
    int INTERFACE_TYPE;
    int TTL;
    int DNS_CACHE_SIZE;
} DNS_CONFIG;

typedef struct DNS_POOL {
    DNS_CONFIG *configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DNS_POOL;

DNS_POOL* dns_pool_init(size_t initial_capacity) {
    DNS_POOL *pool = (DNS_POOL *)malloc(sizeof(DNS_POOL));
    if (!pool) return NULL;

    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->configs = (DNS_CONFIG *)calloc(initial_capacity, sizeof(DNS_CONFIG));
    if (!pool->configs) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void dns_pool_destroy(DNS_POOL *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->count; i++) {
        free(pool->configs[i].IP_ADDRESS);
    }
    free(pool->configs);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void dns_pool_add(DNS_POOL *pool, DNS_CONFIG config) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        DNS_CONFIG *new_configs = realloc(pool->configs, new_capacity * sizeof(DNS_CONFIG));
        if (!new_configs) {
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        pool->configs = new_configs;
        pool->capacity = new_capacity;
    }

    pool->configs[pool->count++] = config;

    pthread_mutex_unlock(&pool->lock);
}

DNS_CONFIG* dns_pool_get(DNS_POOL *pool, int DNS_SERVER_ID) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; i++) {
        if (pool->configs[i].DNS_SERVER_ID == DNS_SERVER_ID) {
            pthread_mutex_unlock(&pool->lock);
            return &pool->configs[i];
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

// Mock function to simulate data retrieval from external sources
void mock_dns_config_retrieval(DNS_POOL *pool) {
    // Simulate fetching DNS configurations from a file or database
    DNS_CONFIG config = {1, "8.8.8.8", 53, 5, 0, 3600, 256};
    dns_pool_add(pool, config);
}

int main() {
    DNS_POOL *pool = dns_pool_init(10);
    if (!pool) return 1;

    mock_dns_config_retrieval(pool);

    DNS_CONFIG *config = dns_pool_get(pool, 1);
