        printf("DNS Server ID: %d\n", config->DNS_SERVER_ID);
        printf("IP Address: %s\n", config->IP_ADDRESS);
        printf("Port Number: %d\n", config->PORT_NUMBER);
    }

    dns_pool_destroy(pool);
    return 0;
}
