#include <pthread.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPICRCList;

NFAPICRCList* createCRCList(size_t initialCapacity) {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->items = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroyCRCList(NFAPICRCList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->items);
    list->items = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int addCRCItem(NFAPICRCList* list, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&list->mutex);

    if (RNTI < 1 || RNTI > 65535) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid RNTI range
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI
        }
    }

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T* newItems = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->items, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newItems) {
            pthread_mutex_unlock(&list->mutex);
            return -3; // Memory allocation failed
        }
        list->items = newItems;
        list->capacity = newCapacity;
    }

    list->items[list->count].RNTI = RNTI;
    list->items[list->count].CRCFLAG = CRCFLAG;
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Example usage:
int main() {
    NFAPICRCList* crcList = createCRCList(10);
    if (crcList) {
        int result = addCRCItem(crcList, 12345, 1);
        if (result == 0) {
            printf("CRC item added successfully.\n");
        } else {
            printf("Failed to add CRC item: %d\n", result);
        }
        destroyCRCList(crcList);
    } else {
        printf("Failed to create CRC list.\n");
    }

    return 0;
}
