    uint8_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock;
} PduList;

PduList* createPduList(size_t initialCapacity) {
    PduList *list = (PduList*)malloc(sizeof(PduList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->length = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freePduList(PduList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void growPduList(PduList *list) {
    size_t newCapacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newData == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->data = newData;
    list->capacity = newCapacity;
}

void addPduToList(PduList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->length == list->capacity) {
        growPduList(list);
    }
    list->data[list->length++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void populateNfarxPduList(PduList *list, uint16_t minRnti, uint16_t maxRnti) {
    srand(time(NULL));
    while (list->length < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        uint16_t rnti;
        do {
            rnti = rand() % (maxRnti - minRnti + 1) + minRnti;
        } while (isRntiInList(list, rnti));
        pdu.rnti = rnti;
        pdu.crcFlag = rand() % 2;
        addPduToList(list, pdu);
    }
}

int isRntiInList(PduList *list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->length; ++i) {
        if (list->data[i].rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

