#include <string.h>

#define MAX_RNTI_RANGE 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* populateNfarxPduList(int num_entries, unsigned short rnti_range_start, unsigned short rnti_range_end) {
    if (num_entries > (rnti_range_end - rnti_range_start + 1)) {
        fprintf(stderr, "Error: Too many entries for the given RNTI range.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed.");
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    unsigned short rntis[num_entries];
    for (int i = 0; i < num_entries; ++i) {
        rntis[i] = rand() % (rnti_range_end - rnti_range_start + 1) + rnti_range_start;
    }

    for (int i = 0; i < num_entries; ++i) {
        pthread_mutex_lock(&mutex);
        while (i > 0 && rntis[i] == rntis[i-1]) {
            rntis[i] = rand() % (rnti_range_end - rnti_range_start + 1) + rnti_range_start;
        }
        pthread_mutex_unlock(&mutex);

        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = rntis[i];
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_destroy(&mutex);
    return list;
}

void readConfigFile(const char* filename, unsigned short* rnti_range_start, unsigned short* rnti_range_end) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening configuration file.");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the RNTI range from the line
        sscanf(line, "%hu %hu", rnti_range_start, rnti_range_end);
    }

    fclose(file);
}

void processTextFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening text file.");
        return;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Process each line here
        double sum = 0.0;
        int count = 0;

        // Example processing: compute average of last two numeric fields
        char* token = strtok(line, ",");
        while (token) {
            if (count >= 2) {
                sum += atof(token);
                count++;
            }
            token = strtok(NULL, ",");
        }

        if (count > 1) {
            double average = sum / (count - 1);
            printf("%s,%f\n", line, average);
        } else {
            printf("%s,\n", line);
        }
    }

    pthread_mutex_destroy(&mutex);
    fclose(file);
}

void monitorPerformance() {
    // Implement performance monitoring here
    // Use real-time alerts for anomalies
}

int main() {
    unsigned short rnti_range_start, rnti_range_end;
    readConfigFile("config.txt", &rnti_range_start, &rnti_range_end);

    int num_entries = 10; // Example number of entries
    NFAPI_CRC_INDICATION_PDU_T* list = populateNfarxPduList(num_entries, rnti_range_start, rnti_range_end);
    if (list) {
        for (int i = 0; i < num_entries; ++i) {
            printf("Entry %d: RX_UE_INFORMATION_TAG=%d, RNTI=%hu, CRC_INDICATION_REL8_TAG=%d\n",
                   i, list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG);
        }
        free(list);
    }

    processTextFile("data.txt");

    monitorPerformance();

    return 0;
}
