CRC_LIST crc_list;

void initialize_crc_list() {
    crc_list.head = NULL;
    pthread_mutex_init(&crc_list.lock, NULL);
}

int is_rnti_unique(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = crc_list.head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int is_rnti_in_range(int rnti) {
    return rnti >= crc_list.valid_rnti_range_start && rnti <= crc_list.valid_rnti_range_end;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->RX_UE_INFORMATION_TAG = rand();
    new_pdu->RNTI = rand() % MAX_RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // 0 or 1
    new_pdu->timestamp = time(NULL);
    new_pdu->next = NULL;
    return new_pdu;
}

void populateNfarxPduList() {
    pthread_mutex_lock(&crc_list.lock);
    while (is_rnti_unique(rand()) == 0) {}
    int rnti = rand();
    while (!is_rnti_in_range(rnti)) {
        rnti = rand() % MAX_RNTI;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = create_pdu();
    new_pdu->RNTI = rnti;
    if (crc_list.head == NULL) {
        crc_list.head = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = crc_list.head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_pdu;
    }
    pthread_mutex_unlock(&crc_list.lock);
}

