#define MAX_TASK_ID 1000
#define MIN_TASK_ID 1

typedef struct TASK_QUEUE_ITEM {
    int task_id;
    int priority;
    time_t timestamp;
    struct TASK_QUEUE_ITEM *next;
} TASK_QUEUE_ITEM;

TASK_QUEUE_ITEM* head = NULL;
int valid_task_id_range[2] = {MIN_TASK_ID, MAX_TASK_ID};
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;

void updateTaskIDRange() {
    FILE *config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error opening config file\n");
        return;
    }
    fscanf(config_file, "%d %d", &valid_task_id_range[0], &valid_task_id_range[1]);
    fclose(config_file);
}

int isTaskIDValid(int task_id) {
    return task_id >= valid_task_id_range[0] && task_id <= valid_task_id_range[1];
}

void addToQueue(TASK_QUEUE_ITEM *new_item) {
    pthread_mutex_lock(&queue_mutex);
    new_item->next = head;
    head = new_item;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_mutex);
}

TASK_QUEUE_ITEM* removeFromQueue() {
    pthread_mutex_lock(&queue_mutex);
    while (head == NULL) {
        pthread_cond_wait(&queue_not_empty, &queue_mutex);
    }
    TASK_QUEUE_ITEM *item = head;
    head = item->next;
    pthread_mutex_unlock(&queue_mutex);
    return item;
}

void manageDynamicTaskQueue() {
    updateTaskIDRange();
    while (1) {
        // Simulate task processing
        if (head != NULL) {
            TASK_QUEUE_ITEM *current = removeFromQueue();
            printf("Processing task %d\n", current->task_id);
            free(current);
        }
        // Add new tasks or handle updates from external dependencies
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)manageDynamicTaskQueue, NULL);
    pthread_join(thread, NULL);
    return 0;
}
