void display_help(FILE *output_stream) {
    fprintf(output_stream, "Usage: program [-h | --manpage] [-cs] -o <output_file> [-m <max_lines>] <input_file>\n");
    // Add detailed help information here
}

void display_manpage(FILE *output_stream) {
    // Add detailed documentation here
}

int count_lines(const char *filename, int max_lines, int non_empty_only, FILE *log_file) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message("Failed to open input file", log_file);
        return -1;
    }

    int line_count = 0;
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (max_lines != -1 && line_count >= max_lines)
            break;

        if (!non_empty_only || strlen(buffer) > 1) { // Check for non-empty lines
            line_count++;
        }
    }

    fclose(file);
    return line_count;
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = NULL;
    int max_lines = -1;
    int non_empty_only = 0;
    FILE *log_file = fopen("program.log", "a");

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--manpage") == 0) {
            display_help(stdout);
            if (strcmp(argv[i], "--manpage") == 0)
                display_manpage(stdout);
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            non_empty_only = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_file = argv[i] + 3;
        } else if (strncmp(argv[i], "-m", 2) == 0) {
            max_lines = atoi(argv[i] + 3);
        } else {
            input_file = argv[i];
        }
    }

    if (!input_file) {
        display_help(stderr);
        exit(1);
    }

    int line_count = count_lines(input_file, max_lines, non_empty_only, log_file);

    if (line_count >= 0 && output_file) {
        FILE *output = fopen(output_file, "w");
        if (!output) {
            log_message("Failed to open output file", log_file);
            exit(1);
        }
        fprintf(output, "%d\n", line_count);
        fclose(output);
    } else if (line_count >= 0) {
        printf("%d\n", line_count);
    }

    fclose(log_file);
    return 0;
}
