SensorData* CreateSensorData(int sensorID, uint64_t timestamp, double reading, const char* metadata) {
    SensorData* data = (SensorData*)malloc(sizeof(SensorData));
    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for SensorData\n");
        return NULL;
    }
    data->sensorID = sensorID;
    data->timestamp = timestamp;
    data->reading = reading;
    strncpy(data->metadata, metadata, sizeof(data->metadata) - 1);
    data->metadata[sizeof(data->metadata) - 1] = '\0';
    data->refCount = 1;
    return data;
}

// Function to increment reference count
void IncSensorDataRef(SensorData* data) {
    if (data != NULL) {
        data->refCount++;
    }
}

// Function to decrement reference count and free memory when zero
void DecSensorDataRef(SensorData* data) {
    if (data != NULL) {
        data->refCount--;
        if (data->refCount == 0) {
            free(data);
        }
    }
}

// AES-CBC decryption function
int DecryptAES(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* key,
                const unsigned char* iv, unsigned char* plaintext) {
    EVP_CIPHER_CTX* ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto cleanup;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        goto cleanup;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) 
        goto cleanup;
    plaintext_len += len;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

