typedef struct {
    int id;
    char server_ip[16];
    int port;
    int timeout;
    char interface_type[20];
    int ttl;
    int dns_cache_size;
} DNS_CONFIG;

typedef struct DNS_NODE {
    DNS_CONFIG data;
    struct DNS_NODE* next;
} DNS_NODE;

typedef struct {
    pthread_mutex_t lock;
    DNS_NODE* head;
} DNS_LIST;

DNS_LIST* create_dns_list() {
    DNS_LIST* list = (DNS_LIST*)malloc(sizeof(DNS_LIST));
    if (list == NULL) return NULL;
    memset(list, 0, sizeof(DNS_LIST));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dns_list(DNS_LIST* list) {
    pthread_mutex_lock(&list->lock);
    DNS_NODE* current = list->head;
    while (current != NULL) {
        DNS_NODE* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_dns_config(DNS_LIST* list, DNS_CONFIG config) {
    pthread_mutex_lock(&list->lock);
    DNS_NODE* new_node = (DNS_NODE*)malloc(sizeof(DNS_NODE));
    if (new_node != NULL) {
        memcpy(&new_node->data, &config, sizeof(DNS_CONFIG));
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_dns_config(DNS_LIST* list, int id) {
    pthread_mutex_lock(&list->lock);
    DNS_NODE* current = list->head;
    DNS_NODE* prev = NULL;
    while (current != NULL && current->data.id != id) {
        prev = current;
        current = current->next;
    }
    if (current != NULL) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void* dns_config_thread(void* arg) {
    // Simulate DNS configuration thread
    return NULL;
}

int main() {
    DNS_LIST* dns_list = create_dns_list();
    if (dns_list != NULL) {
        // Example usage
        DNS_CONFIG config1 = {1, "8.8.8.8", 53, 5, "Ethernet", 60, 1024};
        add_dns_config(dns_list, config1);
        remove_dns_config(dns_list, 1);
        destroy_dns_list(dns_list);
    }
    return 0;
}
