    struct TaskQueue *current = head, *prev = NULL;

    while (current != NULL && current->item->timestamp < new_task->timestamp) {
        prev = current;
        current = current->next;
    }

    struct TaskQueue *new_node = (struct TaskQueue *)malloc(sizeof(struct TaskQueue));
    new_node->item = new_task;
    new_node->next = current;

    if (prev == NULL)
        head = new_node;
    else
        prev->next = new_node;

    logTaskInJSON(new_task);
    pthread_mutex_unlock(&queue_lock);
}

void deleteTask(int task_id) {
    pthread_mutex_lock(&queue_lock);
    struct TaskQueue *current = head, *prev = NULL;

    while (current != NULL && current->item->task_id != task_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&queue_lock);
        return;
    }

    if (prev == NULL)
        head = current->next;
    else
        prev->next = current->next;

    free(current->item);
    free(current);
    pthread_mutex_unlock(&queue_lock);
}

