    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

struct SensorData {
    int sensorID;
    std::chrono::system_clock::time_point timestamp;
    float readingValue;
    std::string metadata;
    std::atomic<int> referenceCount{0};
};

// Global variables for tracking memory allocations
std::atomic<int> successfulAllocations(0);
std::atomic<int> failedAllocations(0);

// Function to handle NFAPI and SensorData
int HandleNfaapiAndSensorData(int N) {
    if (N <= 0 || N > 10000) return 0; // Edge case handling

    std::vector<NFAPI_CRC_INDICATION_PDU_T*> nfaapiArray(N);
    std::vector<SensorData*> sensorDataArray(N);

    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<int> processed(0);

    auto populateNfaapi = [&]() {
        for (int i = 0; i < N; ++i) {
            nfaapiArray[i] = new NFAPI_CRC_INDICATION_PDU_T;
            if (!nfaapiArray[i]) {
                failedAllocations++;
                continue;
            }
            successfulAllocations++;
            nfaapiArray[i]->RX_UE_INFORMATION_TAG = i;
            nfaapiArray[i]->RNTI = i * 10;
            nfaapiArray[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        }
    };

    auto populateSensorData = [&]() {
        for (int i = 0; i < N; ++i) {
            sensorDataArray[i] = new SensorData;
            if (!sensorDataArray[i]) {
                failedAllocations++;
                continue;
            }
            successfulAllocations++;
            sensorDataArray[i]->sensorID = i;
            sensorDataArray[i]->timestamp = std::chrono::system_clock::now();
            sensorDataArray[i]->readingValue = static_cast<float>(rand()) / RAND_MAX * 100.0f; // Random reading value
            sensorDataArray[i]->metadata = "Sensor " + std::to_string(i);
            sensorDataArray[i]->referenceCount++;
        }
    };

    auto worker = [&]() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this]() { return processed < N; });
            if (processed >= N) break;
            populateNfaapi();
            populateSensorData();
            processed += 2;
            lock.unlock();
        }
    };

    std::thread t(worker);

    t.join();

    for (auto& nd : nfaapiArray) {
        delete nd;
    }

    for (auto& sd : sensorDataArray) {
        if (sd->referenceCount.load() == 0) {
            delete sd;
        } else {
            failedAllocations++; // Handle memory leak case
        }
    }

    return processed / 2; // Return the number of successfully processed elements
}

