    *plaintext = malloc(plaintext_len);
    if (!*plaintext) {
        return -2; // Memory allocation failed
    }

    int decrypted_len = AES_cbc_encrypt(ciphertext, *plaintext, ciphertext_len, &enc_key, iv, AES_DECRYPT);
    if (decrypted_len != plaintext_len) {
        free(*plaintext);
        return -3; // Decryption error
