    void IncrementReference() { ++referenceCount; }
    void DecrementReference() { if (--referenceCount == 0) delete this; }
};

class MemoryManager {
public:
    static bool AllocateMemory(void*& ptr, size_t size) {
        ptr = malloc(size);
        return ptr != nullptr;
    }

    static void FreeMemory(void* ptr) {
        free(ptr);
    }
};

void HandleNfaapiAndSensorData(int N, const std::string& uploadUrl) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> nfaapiArray(N);
    std::vector<SensorData*> sensordataArray(N);

    for (int i = 0; i < N; ++i) {
        if (!MemoryManager::AllocateMemory(nfaapiArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            std::cerr << "Failed to allocate memory for NFAPI data" << std::endl;
            continue;
        }
        nfaapiArray[i]->RX_UE_INFORMATION_TAG = i + 1;
        nfaapiArray[i]->RNTI = i * 10;
        nfaapiArray[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!MemoryManager::AllocateMemory(sensordataArray[i], sizeof(SensorData))) {
            std::cerr << "Failed to allocate memory for Sensor data" << std::endl;
            MemoryManager::FreeMemory(nfaapiArray[i]);
            continue;
        }
        sensordataArray[i]->sensorID = i + 1;
        sensordataArray[i]->timestamp = std::time(nullptr);
        sensordataArray[i]->readingValue = rand() % 100.0 / 10.0;
        sensordataArray[i]->metadata = "Sensor metadata";
        sensordataArray[i]->IncrementReference();
    }

    // Implement file upload logic here
