public struct NFAPI_CRC_INDICATION_PDU_T
{
    public RX_UE_INFORMATION_TAG rxUeInformationTag;
    public ushort RNTI;
    public CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
}

[Flags]
public enum RX_UE_INFORMATION_TAG : byte { /* Define enumeration values */ }

public struct CRC_INDICATION_REL8_TAG
{
    public bool CRCFLAG;
}

public static class NFAPIUtils
{
    private const int InitialBufferSize = 1024;
    private const int MaxBufferSize = 65536;
    private const int ChunkSize = 8192;

    public static NFAPI_CRC_INDICATION_PDU_T[] GenerateAndPopulateNFAPduList(int capacity)
    {
        var pdus = new NFAPI_CRC_INDICATION_PDU_T[capacity];
        for (int i = 0; i < capacity; i++)
        {
            pdus[i].rxUeInformationTag = (RX_UE_INFORMATION_TAG)Random.Shared.NextEnum<RX_UE_INFORMATION_TAG>();
            pdus[i].RNTI = (ushort)Random.Shared.Next ushort();
            pdus[i].crcIndicationRel8Tag.CRCFLAG = Random.Shared.NextBoolean();
        }
        return pdus;
    }

    public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            List<byte> plaintextChunks = new List<byte>();
            for (int offset = 0; offset < ciphertext.Length; offset += ChunkSize)
            {
                int chunkLength = Math.Min(ChunkSize, ciphertext.Length - offset);
                byte[] decryptedChunk = decryptor.TransformFinalBlock(ciphertext, offset, chunkLength);
                plaintextChunks.AddRange(decryptedChunk);
            }

            return plaintextChunks.ToArray();
        }
    }
}
