#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int SEQUENCE_NUMBER;
    float TRANSMISSION_POWER_LEVEL;
    unsigned long FRAME_TIMESTAMP;
} FRAME_DATA_RECORD;

FRAME_DATA_RECORD* processAndStreamFrameData(int M) {
    if (M <= 0) {
        return NULL; // Invalid input
    }

    FRAME_DATA_RECORD* records = (FRAME_DATA_RECORD*)malloc(M * sizeof(FRAME_DATA_RECORD));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < M; i++) {
        // Initialize each record with dummy values
        records[i].SEQUENCE_NUMBER = i + 1;
        records[i].TRANSMISSION_POWER_LEVEL = 5.0f; // Example power level
        records[i].FRAME_TIMESTAMP = (unsigned long)(i * 1000); // Example timestamp in milliseconds
    }

    // Memory integrity check
    if (records[M - 1].SEQUENCE_NUMBER != M) {
        fprintf(stderr, "Memory corruption detected\n");
        free(records);
        exit(EXIT_FAILURE);
    }

    return records;
}

unsigned char* validateAndNormalizeAudioLevels(float* audioData, int sampleCount, float minThreshold, float maxThreshold) {
    if (!audioData || sampleCount <= 0 || minThreshold >= maxThreshold) {
        return NULL; // Invalid input
    }

    unsigned char* normalizedAudio = (unsigned char*)malloc(sampleCount * sizeof(unsigned char));
    if (!normalizedAudio) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < sampleCount; i++) {
        float level = audioData[i];
        if (level < minThreshold) {
            normalizedAudio[i] = (unsigned char)(minThreshold * 255.0f / maxThreshold);
        } else if (level > maxThreshold) {
            normalizedAudio[i] = (unsigned char)(maxThreshold * 255.0f / maxThreshold);
        } else {
            normalizedAudio[i] = (unsigned char)(level * 255.0f / maxThreshold);
        }
    }

    return normalizedAudio;
}
