} SensorData;

typedef struct {
    int group_id;
    int sensor_count;
    NFAPI_CRC_INDICATION_PDU_T* crc_indication;
    SensorData* data;
} SensorGroup;

SensorGroup* create_sensor_group(int group_id, int sensor_count) {
    SensorGroup* group = (SensorGroup*)malloc(sizeof(SensorGroup));
    if (!group) {
        fprintf(stderr, "Memory allocation failed for sensor group\n");
        return NULL;
    }
    group->group_id = group_id;
    group->sensor_count = sensor_count;
    group->crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sensor_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!group->crc_indication) {
        fprintf(stderr, "Memory allocation failed for CRC indications\n");
        free(group);
        return NULL;
    }
    group->data = (SensorData*)malloc(sensor_count * sizeof(SensorData));
    if (!group->data) {
        fprintf(stderr, "Memory allocation failed for sensor data\n");
        free(group->crc_indication);
        free(group);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < sensor_count; i++) {
        group->crc_indication[i].RX_UE_INFORMATION_TAG = rand() % 100;
        group->crc_indication[i].RNTI = rand() % 500;
        group->crc_indication[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        group->data[i].unique_id = i;
        group->data[i].timestamp = time(NULL);
        snprintf(group->data[i].sensor_id, sizeof(group->data[i].sensor_id), "Sensor%d", i);
        group->data[i].measurement_value = (float)(rand() % 100) / 10.0;
        group->data[i].quality_flag = rand() % 2;
        snprintf(group->data[i].metadata, sizeof(group->data[i].metadata), "Metadata%d", i);
    }

    return group;
}

void free_sensor_group(SensorGroup* group) {
    if (group) {
        free(group->crc_indication);
        free(group->data);
        free(group);
    }
}

int main() {
    SensorGroup* groups[MAX_GROUPS];
    for (int i = 0; i < MAX_GROUPS; i++) {
        groups[i] = create_sensor_group(i, rand() % MAX_SENSORS + 1);
        if (!groups[i]) {
            fprintf(stderr, "Failed to create sensor group %d\n", i);
            return 1;
        }
    }

    // Process the data as needed
    for (int i = 0; i < MAX_GROUPS; i++) {
        free_sensor_group(groups[i]);
    }

    return 0;
}
