#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[12];
} AES_GCM_CTX;

AES_GCM_CTX* aes_gcm_init(const char *password, int iterations) {
    AES_GCM_CTX *ctx = (AES_GCM_CTX *)malloc(sizeof(AES_GCM_CTX));
    if (!ctx) return NULL;

    // Generate a secure random IV
    if (!RAND_bytes(ctx->iv, sizeof(ctx->iv))) {
        perror("Failed to generate IV");
        free(ctx);
        return NULL;
    }

    // Derive the encryption key using PBKDF2 with SHA-256
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), ctx->iv, sizeof(ctx->iv),
                            iterations, EVP_sha256(), 32, ctx->key) != 1) {
        perror("PBKDF2 failed");
        free(ctx);
        return NULL;
    }

    // Set up the cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx || !EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv)) {
        perror("Cipher initialization failed");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Log initialization parameters
    printf("PBKDF2 iterations: %d\n", iterations);

    return ctx;
}

void aes_gcm_cleanup(AES_GCM_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        memset(ctx->key, 0, sizeof(ctx->key));
        memset(ctx->iv, 0, sizeof(ctx->iv));
        free(ctx);
    }
}

// Additional functions for encryption and decryption would be implemented here
