#define MAX_SEQUENCE_NUMBER 65535

typedef struct {
    uint16_t SEQUENCE_NUMBER;
    int8_t TRANSMISSION_POWER_LEVEL;
    time_t FRAME_TIMESTAMP;
} FRAME_DATA_RECORD;

FRAME_DATA_RECORD* processAndStreamFrameData(int M, float backpressureFactor) {
    if (M <= 0 || backpressureFactor < 0.0f || backpressureFactor > 1.0f) {
        return NULL; // Invalid input
    }

    FRAME_DATA_RECORD* frameData = (FRAME_DATA_RECORD*)malloc(M * sizeof(FRAME_DATA_RECORD));
    if (!frameData) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < M; ++i) {
        frameData[i].SEQUENCE_NUMBER = rand() % (MAX_SEQUENCE_NUMBER + 1);
        frameData[i].TRANSMISSION_POWER_LEVEL = (rand() % 256) - 128;
        time(&frameData[i].FRAME_TIMESTAMP);
    }

    // Simulate backpressure
    usleep((int)(backpressureFactor * 1000000));

    return frameData;
}

#define MAX_AUDIO_LEVEL 255

typedef uint8_t AudioLevel;

AudioLevel* validateAndNormalizeAudioLevels(int audioStreamSize, const int16_t* audioStream, float** normalizedBuffer) {
    if (audioStreamSize <= 0 || !audioStream) {
        return NULL; // Invalid input
    }

    AudioLevel* normalizedAudio = (AudioLevel*)malloc(audioStreamSize * sizeof(AudioLevel));
    if (!normalizedAudio) {
        return NULL; // Memory allocation failed
    }

    const float thresholdLow = -1.0f;
    const float thresholdHigh = 1.0f;

    for (int i = 0; i < audioStreamSize; ++i) {
        normalizedAudio[i] = (audioStream[i] > thresholdHigh) ? MAX_AUDIO_LEVEL :
                              (audioStream[i] < thresholdLow) ? 0 : 
                              ((audioStream[i] - thresholdLow) / (thresholdHigh - thresholdLow)) * MAX_AUDIO_LEVEL;
    }

    *normalizedBuffer = normalizedAudio;
    return normalizedAudio;
}
