#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define custom memory pool allocator structure
typedef struct {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
} MemoryPool;

// Initialize memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    if (pool->blocks == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Allocate memory from the pool
void* mem_pool_alloc(MemoryPool* pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (*(char*)(pool->blocks + i * pool->block_size) == '\0') {
            *(char*)(pool->blocks + i * pool->block_size) = '1';
            return (void*)(pool->blocks + i * pool->block_size);
        }
    }
    return NULL;
}

// Free memory in the pool
void mem_pool_free(MemoryPool* pool, void* ptr) {
    if ((char*)ptr < (char*)pool->blocks || (char*)ptr >= (char*)pool->blocks + pool->num_blocks * pool->block_size) return;
    *(char*)ptr = '\0';
}

// Destroy memory pool
void destroy_memory_pool(MemoryPool* pool) {
    free(pool->blocks);
    free(pool);
}

int main() {
    MemoryPool* pool = init_memory_pool(1024, 100);
    if (pool == NULL) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return 1;
    }

    void* block1 = mem_pool_alloc(pool);
    void* block2 = mem_pool_alloc(pool);

    if (block1 == NULL || block2 == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        destroy_memory_pool(pool);
        return 1;
    }

    // Use the allocated blocks
    memset(block1, 0, pool->block_size);
    memset(block2, 0, pool->block_size);

    mem_pool_free(pool, block1);
    mem_pool_free(pool, block2);

    destroy_memory_pool(pool);
    return 0;
}
```

