CipherObject* process_file(const char *file_path, const char *cipher_name, int mode, const char *output_path) {
    // Validate file path
    if (strstr(file_path, "/etc") || strstr(file_path, "/home")) {
        fprintf(stderr, "Error: Invalid file path.\n");
        return NULL;
    }

    // Load certificate and key
    EVP_PKEY *pkey = NULL;
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        perror("Failed to open file");
        return NULL;
    }
    pkey = PEM_read_PrivateKey(fp, NULL, NULL, NULL);
    fclose(fp);

    if (!pkey) {
        fprintf(stderr, "Error: Failed to load key.\n");
        return NULL;
    }

    // Initialize cipher context
    CipherObject *cipher_obj = malloc(sizeof(CipherObject));
    cipher_obj->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_obj->ctx || !EVP_EncryptInit_ex(cipher_obj->ctx, EVP_get_cipherbyname(cipher_name), NULL, pkey->pkey.rsa->n, pkey->pkey.rsa->e)) {
        fprintf(stderr, "Error: Failed to initialize cipher context.\n");
        EVP_PKEY_free(pkey);
        free(cipher_obj);
        return NULL;
    }

    // Set mode and prepare for encryption/decryption
    cipher_obj->cipher = EVP_get_cipherbyname(cipher_name);
    cipher_obj->mode = mode;

    // Perform encryption/decryption here (omitted for brevity)

    // Clean up
    EVP_CIPHER_CTX_free(cipher_obj->ctx);
    EVP_PKEY_free(pkey);

    return cipher_obj;
}
