#define MAX_PDU_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateAndPopulateNFAPduList(uint16_t RNTI, size_t numPdus) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    for (size_t i = 0; i < numPdus; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pduList[i].RNTI = RNTI;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    return pduList;
}

uint8_t* decryptCiphertext(const uint8_t* ciphertext, size_t ciphertextLen, const uint8_t* key, const uint8_t* iv, size_t* plaintextLen) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle OpenSSL initialization failure
        return NULL;
    }

    uint8_t* plaintext = (uint8_t*)malloc(ciphertextLen);
    if (plaintext == NULL) {
        // Handle memory allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    *plaintextLen = ciphertextLen;

    int result = EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    if (!result) {
        // Handle decryption initialization failure
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    result = EVP_DecryptUpdate(ctx, plaintext, (int*)plaintextLen, ciphertext, ciphertextLen);
    if (!result) {
        // Handle decryption update failure
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    result = EVP_DecryptFinal_ex(ctx, plaintext + *plaintextLen, (int*)(plaintextLen - 1));
    if (!result) {
        // Handle decryption finalization failure
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Remove padding
    size_t pad = plaintext[*plaintextLen - 1];
    if (pad > *plaintextLen || pad == 0) {
        // Handle invalid padding
        free(plaintext);
        return NULL;
    }
    *plaintextLen -= pad;

    return plaintext;
}
