#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint32_t packetId;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPIMemoryPool;

NFAPIMemoryPool* createMemoryPool(size_t initialCapacity) {
    NFAPIMemoryPool *pool = (NFAPIMemoryPool*)malloc(sizeof(NFAPIMemoryPool));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = 0;
    pool->capacity = initialCapacity;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroyMemoryPool(NFAPIMemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(NFAPIMemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *element;
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newPool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPool) {
            perror("Failed to reallocate memory pool");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = newPool;
        pool->capacity = newCapacity;
    }
    element = &pool->pool[pool->size++];
    pthread_mutex_unlock(&pool->lock);
    return element;
}

void populateElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Populate the structure with random data
    element->RX_UE_INFORMATION_TAG = rand();
    element->RNTI = (rand() & 0xFFFF);
    element->CRC_INDICATION_REL8_TAG = (rand() & 0xFF);
    element->packetId = rand();
    element->CRCFLAG = (rand() & 1) ? 0x01 : 0x00;
}

void logElementCreation(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Log the creation of the structure for auditing and debugging
    printf("Created element with RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, packetId: %u, CRCFLAG: %u\n",
           element->RX_UE_INFORMATION_TAG,
           element->RNTI,
           element->CRC_INDICATION_REL8_TAG,
           element->packetId,
           element->CRCFLAG);
}

void validateElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Validate the integrity of the structure
    if (!(element->RX_UE_INFORMATION_TAG && element->RNTI && element->packetId)) {
        fprintf(stderr, "Invalid element detected\n");
    }
}

int main() {
    srand(time(NULL));
    NFAPIMemoryPool *pool = createMemoryPool(1024);
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = allocateFromPool(pool);
        if (!element) continue;
        populateElement(element);
        logElementCreation(element);
        validateElement(element);
    }
    destroyMemoryPool(pool);
    return 0;
}
