    TCP_ERROR
} TcpConnectionStatus;

typedef struct {
    int connection_id;
    char source_ip[16];
    char destination_ip[16];
    int source_port;
    int destination_port;
    TcpConnectionStatus status;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD *connections[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
    int debug_logging_enabled;
    int performance_profiling_enabled;
    unsigned int random_seed;
} ConnectionManager;

ConnectionManager* connection_manager_create(int debug_logging, int performance_profiling) {
    ConnectionManager *manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->debug_logging_enabled = debug_logging;
    manager->performance_profiling_enabled = performance_profiling;
    manager->random_seed = time(NULL); // Initialize random seed

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        manager->connections[i] = NULL;
    }

    return manager;
}

void connection_manager_destroy(ConnectionManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        free(manager->connections[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int connection_manager_insert(ConnectionManager *manager, TCP_CONNECTION_RECORD *record) {
    if (!manager || !record) return -1;

    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // List is full
    }

    manager->connections[manager->count++] = record;
    pthread_mutex_unlock(&manager->lock);

    // Log the insertion
    if (manager->debug_logging_enabled) {
        printf("Connection inserted: ID %d\n", record->connection_id);
    }

    return 0;
}

// Additional functions for updating, deleting, and querying connections would go here

int main() {
    // Unit tests for the connection manager
    return 0;
}
