        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
    }

    return pduList;
}

unsigned char* decryptCiphertext(const unsigned char* key, const unsigned char* iv, const unsigned char* ciphertext, size_t ciphertext_len, size_t* plaintext_len) {
    AES_KEY aes_key;
    if (AES_set_decrypt_key(key, 256, &aes_key) != 0) {
        fprintf(stderr, "Failed to set decryption key\n");
        return NULL;
    }

    unsigned char* plaintext = (unsigned char*)malloc(ciphertext_len);
    if (plaintext == NULL) {
        fprintf(stderr, "Memory allocation failed for plaintext\n");
        return NULL;
    }

    int decrypted_len;
    if (AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &aes_key, iv, AES_DECRYPT) != 0) {
        fprintf(stderr, "Decryption failed\n");
        free(plaintext);
        return NULL;
    }

    *plaintext_len = decrypted_len;
    return plaintext;
}

int main() {
