    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateAndPopulateNFAPduList(int numPdus, int timeWindow) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < numPdus; i++) {
        // Populate each PDU with random data and set CRCFLAG
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        pduList[i].RNTI = rand() % 65536;
        pduList[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRCFLAG
    }
    return pduList;
}

uint8_t* decryptCiphertext(const uint8_t* ciphertext, size_t ciphertextLen, const uint8_t* key, const uint8_t* iv, size_t* plaintextLen) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error
        return NULL;
    }

    int decryptedLen1, decryptedLen2;
    uint8_t* plaintext = malloc(ciphertextLen);
    *plaintextLen = 0;

    if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        free(plaintext);
        return NULL;
    }

    if (!EVP_DecryptUpdate(ctx, plaintext, &decryptedLen1, ciphertext, ciphertextLen)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        free(plaintext);
        return NULL;
    }
    *plaintextLen += decryptedLen1;

    if (!EVP_DecryptFinal_ex(ctx, plaintext + decryptedLen1, &decryptedLen2)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        free(plaintext);
        return NULL;
    }
    *plaintextLen += decryptedLen2;

    EVP_CIPHER_CTX_free(ctx);

    // Remove padding if necessary
    size_t padding = plaintext[*plaintextLen - 1];
    if (padding > 0 && padding <= 16) {
        memmove(plaintext, plaintext + (*plaintextLen - padding), padding);
        *plaintextLen = padding;
    }

    return plaintext;
}
