#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PDUS 1000
#define DEFAULT_MEMORY_THRESHOLD 500

typedef struct {
    int RNTI;
    uint8_t TSN;
    uint32_t PDU_Session_ID;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int size;
    int capacity;
    int head;
    int tail;
    size_t memory_used;
    size_t max_memory_threshold;
    pthread_mutex_t lock;
} PDU_Queue;

void init_pdu_queue(PDU_Queue *queue, size_t initial_capacity) {
    queue->size = 0;
    queue->capacity = initial_capacity;
    queue->head = 0;
    queue->tail = 0;
    queue->memory_used = 0;
    queue->max_memory_threshold = DEFAULT_MEMORY_THRESHOLD;
    pthread_mutex_init(&queue->lock, NULL);
}

void destroy_pdu_queue(PDU_Queue *queue) {
    pthread_mutex_destroy(&queue->lock);
}

int enqueue_pdu(PDU_Queue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->lock);
    if (queue->memory_used + sizeof(pdu) > queue->max_memory_threshold) {
        // Graceful degradation: discard the least recently used PDU
        dequeue_pdu(queue);
    }
    if (queue->size == queue->capacity) {
        // Resize the queue dynamically
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(queue->pdus, 2 * queue->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&queue->lock);
            return -1;
        }
        queue->pdus = new_pdus;
        queue->capacity *= 2;
    }
    queue->pdus[queue->tail] = pdu;
    queue->tail = (queue->tail + 1) % queue->capacity;
    queue->size++;
    queue->memory_used += sizeof(pdu);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_pdu(PDU_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    *pdu = queue->pdus[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    queue->size--;
    queue->memory_used -= sizeof(*pdu);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

