#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define MAX_NODES 10

typedef struct Node {
    int id;
    char *data;
    struct Node *next;
} Node;

Node *node_list[MAX_NODES];

void initialize_node(int id) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->id = id;
    new_node->data = NULL;
    new_node->next = node_list[id];
    node_list[id] = new_node;
}

int add_data_to_node(int id, char *data) {
    Node *node = node_list[id];
    while (node != NULL) {
        if (node->data == NULL) {
            node->data = strdup(data);
            return 0;
        }
        node = node->next;
    }
    return -1;
}

void *handle_client(void *arg) {
    int new_socket = *(int *)arg;
    char buffer[1024] = {0};
    read(new_socket, buffer, 1024);
    char *data = strtok(buffer, " ");
    int id = atoi(strtok(NULL, " "));

    if (id >= MAX_NODES) {
        send(new_socket, "Error: Node ID out of range", 30, 0);
    } else {
        add_data_to_node(id, data);
        send(new_socket, "Data added successfully", 25, 0);
    }
    close(new_socket);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_NODES) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_NODES; i++) {
        initialize_node(i);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        pthread_t thread_id;
        pthread_create(&thread_id, NULL, handle_client, &new_socket);
        pthread_detach(thread_id);
    }

    return 0;
}
