use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone)]
struct Job {
    id: u64,
    job_type: JobType,
    resource_constraints: ResourceConstraints,
    priority: Priority,
}

enum JobType {
    CPUBound,
    IOBound,
    BatchProcessing,
}

struct ResourceConstraints {
    cpu_cores: u32,
    memory_gb: u32,
    disk_io_mb_per_sec: u32,
}

#[derive(PartialEq, Clone, Copy)]
enum Priority {
    High,
    Medium,
    Low,
}

struct WorkerNode {
    id: u64,
    available_resources: ResourceConstraints,
    jobs_in_progress: VecDeque<Job>,
}

struct TaskScheduler {
    worker_nodes: HashMap<u64, Arc<Mutex<WorkerNode>>>,
    job_queue: VecDeque<Job>,
    retry_attempts: u32,
}

impl TaskScheduler {
    fn new() -> Self {
        TaskScheduler {
            worker_nodes: HashMap::new(),
            job_queue: VecDeque::new(),
            retry_attempts: 3,
        }
    }

    fn add_worker_node(&mut self, node_id: u64, resources: ResourceConstraints) {
        let node = WorkerNode {
            id: node_id,
            available_resources: resources,
            jobs_in_progress: VecDeque::new(),
        };
        self.worker_nodes.insert(node_id, Arc::new(Mutex::new(node)));
    }

    fn submit_job(&mut self, job: Job) {
        self.job_queue.push_back(job);
        self.schedule_jobs();
    }

    fn schedule_jobs(&self) {
        while let Some(job) = self.job_queue.pop_front() {
            if let Some(worker_node_id) = self.find_available_worker(&job) {
                self.assign_job_to_worker(worker_node_id, job);
            } else {
                // Job cannot be scheduled immediately, requeue or handle overflow
                self.job_queue.push_back(job);
            }
        }
    }

    fn find_available_worker(&self, job: &Job) -> Option<u64> {
        self.worker_nodes.iter().find_map(|(_, worker_node)| {
            let mut node = worker_node.lock().unwrap();
            if node.available_resources.can_satisfy(&job.resource_constraints) && !node.jobs_in_progress.contains(job) {
                Some(node.id)
            } else {
                None
            }
        })
    }

    fn assign_job_to_worker(&self, worker_node_id: u64, job: Job) {
        let mut worker_node = self.worker_nodes.get(&worker_node_id).unwrap().lock().unwrap();
        worker_node.jobs_in_progress.push_back(job);
        // Simulate job execution time based on job type and resource constraints
        match job.job_type {
            JobType::CPUBound => thread::sleep(Duration::from_secs(2)),
            JobType::IOBound => thread::sleep(Duration::from_secs(5)),
            JobType::BatchProcessing => thread::sleep(Duration::from_secs(10)),
        }
        worker_node.jobs_in_progress.pop_front();
        self.schedule_jobs();
    }

    fn handle_job_completion(&self, job_id: u64) {
        // Logic to remove completed job from worker and schedule next if available
    }
}

trait ResourceSatisfiable {
    fn can_satisfy(&self, other: &ResourceConstraints) -> bool;
}

impl ResourceSatisfiable for ResourceConstraints {
    fn can_satisfy(&self, other: &ResourceConstraints) -> bool {
        self.cpu_cores >= other.cpu_cores
            && self.memory_gb >= other.memory_gb
            && self.disk_io_mb_per_sec >= other.disk_io_mb_per_sec
    }
}
