HostCacheEntry* host_cache = NULL;
int cache_size = 0;
int max_cache_size = 1024; // Example maximum cache size
time_t cache_expiry_time = 3600; // Cache expiry in seconds (1 hour)

void init_data_packets(DataPacket** packets, int num_packets) {
    *packets = malloc(num_packets * sizeof(DataPacket));
    if (*packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void calculate_average_data_size(DataPacket* packets, int num_packets) {
    if (num_packets == 0) return;
    size_t total_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        total_size += packets[i].dataSize;
    }
    double average_size = (double)total_size / num_packets;
    printf("Average data size: %.2f\n", average_size);
}

void process_and_sort_file(const char* filename, int max_lines) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open file");
        return;
    }

    DataPacket* packets = NULL;
    init_data_packets(&packets, max_lines);

    char** lines = malloc(max_lines * sizeof(char*));
    if (lines == NULL) {
        log_error("Memory allocation failed");
        fclose(file);
        free(packets);
        return;
    }

    for (int i = 0; i < max_lines; ++i) {
        size_t line_size = 256;
        lines[i] = malloc(line_size * sizeof(char));
        if (lines[i] == NULL) {
            log_error("Memory allocation failed");
            fclose(file);
            free(packets);
            for (int j = 0; j < i; ++j) {
                free(lines[j]);
            }
            free(lines);
            return;
        }

        if (!fgets(lines[i], line_size, file)) {
            break;
        }

        // Process and append the average
        char* token = strtok(lines[i], " ");
        double num1 = atof(token);
        token = strtok(NULL, " ");
        double num2 = atof(token);
        double average = (num1 + num2) / 2.0;
        sprintf(lines[i] + strlen(lines[i]), " %.2f", average);
    }

    fclose(file);

    // Sort the lines based on the first number
    for (int i = 0; i < max_lines - 1; ++i) {
        for (int j = 0; j < max_lines - i - 1; ++j) {
            char* token1 = strtok(lines[j], " ");
            double num1 = atof(token1);
            char* token2 = strtok(lines[j + 1], " ");
            double num2 = atof(token2);
            if (num1 > num2) {
                char* temp = lines[j];
                lines[j] = lines[j + 1];
                lines[j + 1] = temp;
            }
        }
    }

    // Output the sorted data
    for (int i = 0; i < max_lines; ++i) {
        if (lines[i] != NULL) {
            printf("%s", lines[i]);
            free(lines[i]);
        }
    }

    free(packets);
    free(lines);
}

int main() {
    const char* filename = "data.txt";
    int max_lines = 1000; // Example maximum number of lines
    process_and_sort_file(filename, max_lines);
    return 0;
}
