public class NetworkDataProcessor {
    private static final int BATCH_SIZE = 10000;
    private static final String CONFIG_FILE = "config.properties";
    private static final int MAX_CACHE_SIZE = 10000;
    private static final long LOW_PROCESSING_RATE_ALERT_THRESHOLD = 60000; // milliseconds

    private Map<String, Object> config;
    private MessageDigest digest;
    private ConcurrentHashMap<String, String> hashCache;

    public NetworkDataProcessor() {
        loadConfig();
        initHashAlgorithm(config.getProperty("HASH_ALGORITHM"));
        initHashCache();
    }

    private void loadConfig() {
        try {
            config = new HashMap<>(Files.readAllLines(Paths.get(CONFIG_FILE))
                    .stream()
                    .map(line -> line.split("="))
                    .collect(Collectors.toMap(pair -> pair[0], pair -> pair[1])));
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration file", e);
        }
    }

    private void initHashAlgorithm(String algorithmName) {
        try {
            digest = MessageDigest.getInstance(algorithmName);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unsupported hash algorithm: " + algorithmName, e);
        }
    }

    private void initHashCache() {
        hashCache = new ConcurrentHashMap<>(MAX_CACHE_SIZE);
    }

    public void processBatches(List<NFAPI_CRC_INDICATION_PDU_T> batches) {
        long startTime = System.currentTimeMillis();
        try {
            for (List<NFAPI_CRC_INDICATION_PDU_T> batch : partition(batches, BATCH_SIZE)) {
                processBatch(batch);
            }
        } catch (Exception e) {
            logError(e.getMessage());
        } finally {
            long endTime = System.currentTimeMillis();
            logProcessingTime(startTime, endTime);
            monitorHealth(endTime - startTime);
        }
    }

    private List<List<NFAPI_CRC_INDICATION_PDU_T>> partition(List<NFAPI_CRC_INDICATION_PDU_T> list, int batchSize) {
        // Implementation of partitioning logic
    }

    private void processBatch(List<NFAPI_CRC_INDICATION_PDU_T> batch) {
        for (NFAPI_CRC_INDICATION_PDU_T pdu : batch) {
            validateInput(pdu);
            String hash = calculateHash(pdu);
            updateTAI(hash, pdu);
        }
    }

    private void validateInput(NFAPI_CRC_INDICATION_PDU_T pdu) {
        // Implementation of input validation logic
    }

    private String calculateHash(NFAPI_CRC_INDICATION_PDU_T pdu) {
        String key = pdu.RX_UE_INFORMATION_TAG + "-" + pdu.RNTI;
        return hashCache.computeIfAbsent(key, k -> {
            byte[] input = (key + pdu.CRCFLAG).getBytes();
            return bytesToHex(digest.digest(input));
        });
    }

    private void updateTAI(String hash, NFAPI_CRC_INDICATION_PDU_T pdu) {
        // Implementation of TAI updating logic
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void logProcessingTime(long startTime, long endTime) {
        // Implementation of processing time logging logic
