typedef struct {
    int id;
    char ip[16];
    int port;
    int timeout;
    char interface_type[20];
    int ttl;
    int dns_cache_size;
} DNS_CONFIG;

typedef struct dns_config_node {
    DNS_CONFIG config;
    struct dns_config_node *next;
} DNS_CONFIG_NODE;

typedef struct {
    DNS_CONFIG_NODE *head;
    pthread_mutex_t mutex;
} DNS_CONFIG_LIST;

void init_dns_config_list(DNS_CONFIG_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_dns_config(DNS_CONFIG_LIST *list, DNS_CONFIG config) {
    DNS_CONFIG_NODE *new_node = (DNS_CONFIG_NODE *)malloc(sizeof(DNS_CONFIG_NODE));
    new_node->config = config;
    new_node->next = list->head;
    pthread_mutex_lock(&list->mutex);
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void free_dns_config_list(DNS_CONFIG_LIST *list) {
    DNS_CONFIG_NODE *current, *temp;
    current = list->head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}

void *retrieve_dns_configs(void *arg) {
    DNS_CONFIG_LIST *dns_list = (DNS_CONFIG_LIST *)arg;
    // Simulate data retrieval from external sources
    DNS_CONFIG config1 = {1, "8.8.8.8", 53, 2, "Ethernet", 60, 500};
    DNS_CONFIG config2 = {2, "8.8.4.4", 53, 2, "Wi-Fi", 30, 300};
    add_dns_config(dns_list, config1);
    add_dns_config(dns_list, config2);
    return NULL;
}

int main() {
    DNS_CONFIG_LIST dns_list;
    init_dns_config_list(&dns_list);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, retrieve_dns_configs, &dns_list) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);

    // Simulate usage of DNS configurations
    // ...

    free_dns_config_list(&dns_list);
    return 0;
}
