import hashlib
import os

def calculate_md5(file_path, chunk_size=64*1024):
    """Calculate MD5 hash of a file."""
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5.update(chunk)
    return md5.hexdigest()

def calculate_md5_multiple(*file_paths):
    """Calculate MD5 hash for multiple files."""
    results = {}
    for file_path in file_paths:
        try:
            results[file_path] = calculate_md5(file_path)
        except Exception as e:
            print(f"Error processing {file_path}: {e}")
    return results

# Example usage
files_to_hash = ['path/to/file1.txt', 'path/to/file2.jpg']
md5_results = calculate_md5_multiple(*files_to_hash)
for file, hash_value in md5_results.items():
    print(f"MD5({file}): {hash_value}")
