['```python
import hashlib
import os

def calculate_md5(file_path, chunk_size=64*1024):
    """
    Calculate the MD5 hash of a large file using specified chunk size.

    Args:
    - file_path: Path to the file.
    - chunk_size: Size of each chunk in bytes. Default is 64KB.

    Returns:
    - md5_hash: The MD5 hash of the file content as a hexadecimal string.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File {file_path} does not exist.")

    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hasher.update(chunk)

    return hasher.hexdigest()

# Example usage
try:
    file_md5 = calculate_md5('/path/to/large/file')
    print(f"MD5 hash of the file: {file_md5}")
except Exception as e:
    print(f"An error occurred: {e}")
