import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
import requests

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)

def calculate_md5(file_path, chunk_size=4096):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def process_files(directory, max_concurrent=5, custom_chunk_size=None, enable_logging=False):
    file_hashes = {}
    total_bytes_processed = 0

    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = {
            executor.submit(calculate_md5, os.path.join(directory, filename), chunk_size if custom_chunk_size is None else custom_chunk_size): filename
            for filename in os.listdir(directory)
            if os.path.isfile(os.path.join(directory, filename))
        }

        for future in as_completed(futures):
            try:
                hash_value = future.result()
                filename = futures[future]
                file_hashes[filename] = hash_value
                total_bytes_processed += calculate_file_size(directory, filename)

                if enable_logging:
                    logging.info(f"Processed {filename} with hash {hash_value}")

            except Exception as e:
                logging.error(f"Error processing file {futures[future]}: {e}")

    return file_hashes, total_bytes_processed

def upload_to_api(api_url, data, max_retries=3):
    for attempt in range(max_retries + 1):
        try:
            response = requests.post(api_url, json=data)
            response.raise_for_status()
            logging.info("Upload successful")
            return True
        except requests.RequestException as e:
            if attempt == max_retries:
                logging.error(f"Upload failed after {max_retries} attempts: {e}")
                return False
            else:
                logging.warning(f"Attempt {attempt + 1} failed, retrying...")
                continue

def calculate_file_size(directory, filename):
    return os.path.getsize(os.path.join(directory, filename))

# Example usage
directory_path = "/path/to/your/directory"
api_endpoint = "https://example.com/api/upload"

file_hashes, total_bytes_processed = process_files(directory_path, enable_logging=True)
upload_to_api(api_endpoint, file_hashes)
