import hashlib
import os
import asyncio
from concurrent.futures import ThreadPoolExecutor
import aiohttp

class FileHasher:
    def __init__(self, chunk_size=1024*1024):
        self.chunk_size = chunk_size
        self.file_hashes = {}
        self.total_bytes_processed = 0

    async def hash_files(self, directory, max_concurrent=5):
        semaphore = asyncio.Semaphore(max_concurrent)
        async with ThreadPoolExecutor() as executor:
            tasks = []
            for filename in os.listdir(directory):
                file_path = os.path.join(directory, filename)
                if os.path.isfile(file_path):
                    task = asyncio.ensure_future(self._hash_file_async(file_path, semaphore, executor))
                    tasks.append(task)
            await asyncio.gather(*tasks)

    async def _hash_file_async(self, file_path, semaphore, executor):
        async with semaphore:
            async with aiofiles.open(file_path, 'rb') as f:
                hasher = hashlib.md5()
                while chunk := await f.read(self.chunk_size):
                    hasher.update(chunk)
                    self.total_bytes_processed += len(chunk)
                self.file_hashes[file_path] = hasher.hexdigest()

    def get_file_hashes(self):
        return self.file_hashes

class RandomValueGenerator:
    _integer_generators = []
    _float_generators = []

    @staticmethod
    def initialize(seed):
        RandomValueGenerator._integer_generators = [RandomIntegerGenerator(seed + i) for i in range(10)]
        RandomValueGenerator._float_generators = [RandomFloatGenerator(seed + i * 11) for i in range(10)]

    @staticmethod
    async def get_random_integer(min_value, max_value, inclusive=False):
        return await RandomValueGenerator._integer_generators[min_value % 10].get_next_value_async(min_value, max_value, inclusive)

    @staticmethod
    async def get_random_float(min_value, max_value, inclusive=False):
        return await RandomValueGenerator._float_generators[min_value % 10].get_next_value_async(min_value, max_value, inclusive)

    @staticmethod
    def reset():
        for generator in RandomValueGenerator._integer_generators + RandomValueGenerator._float_generators:
            generator.reset()

class RandomIntegerGenerator:
    def __init__(self, seed):
        self.seed = seed
        self.generator = random.Random(seed)
        self.last_value = None

    async def get_next_value_async(self, min_value, max_value, inclusive=False):
        value = self.generator.randint(min_value, max_value) if inclusive else self.generator.randint(min_value + 1, max_value - 1)
        self.last_value = value
        return value

    def reset(self):
        self.generator.seed(self.seed)

class RandomFloatGenerator:
    def __init__(self, seed):
        self.seed = seed
        self.generator = random.Random(seed)
        self.last_value = None

    async def get_next_value_async(self, min_value, max_value, inclusive=False):
        value = self.generator.uniform(min_value, max_value) if inclusive else (self.generator.uniform(min_value + 0.01, max_value - 0.01))
        self.last_value = value
        return value

    def reset(self):
        self.generator.seed(self.seed)

class AsyncUploader:
    async def upload_data(self, data, url, retries=3):
        session = aiohttp.ClientSession()
        for _ in range(retries):
            try:
                async with session.post(url, json=data) as response:
                    if response.status == 200:
                        return True
            except aiohttp.ClientError as e:
                print(f"Network error: {e}")
        return False

class AsyncFileProcessor:
    def __init__(self, directory, chunk_size=1024*1024):
        self.file_hasher = FileHasher(chunk_size)
        self.random_value_generator = RandomValueGenerator()
        self.async_uploader = AsyncUploader()

    async def process_files(self, directory, max_concurrent=5):
        await self.file_hasher.hash_files(directory, max_concurrent)
        data_to_upload = self.file_hasher.get_file_hashes()
        await self.async_uploader.upload_data(data_to_upload, 'http://example.com/upload')
