import os
import hashlib
import time
import threading

def calculate_md5_of_files(directory, log_file=None, exclude_types=None):
    if not os.path.exists(directory) or not os.path.isdir(directory):
        raise ValueError("Invalid directory path")

    cumulative_hash = hashlib.md5()
    file_hashes = {}
    lock = threading.Lock()

    def process_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                md5 = hashlib.md5()
                while chunk := f.read(4096):
                    md5.update(chunk)
                return md5.hexdigest()
        except Exception as e:
            log_error(f"Error processing file {file_path}: {e}")
            return None

    def log_error(message):
        with open(log_file, 'a') if log_file else open('error.log', 'a') as log:
            log.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - ERROR: {message}\n")

    for root, _, files in os.walk(directory):
        for file in files:
            if not file.startswith('.') and not os.path.islink(os.path.join(root, file)):
                file_path = os.path.realpath(os.path.join(root, file))
                try:
                    md5_hash = process_file(file_path)
                    if md5_hash:
                        with lock:
                            cumulative_hash.update(md5_hash.encode())
                            file_hashes[file_path] = md5_hash
                except Exception as e:
                    log_error(f"Error processing file {file_path}: {e}")

    return file_hashes, cumulative_hash.hexdigest()

# Example usage
if __name__ == "__main__":
    directory_to_scan = '/path/to/directory'
    log_file_path = '/path/to/logfile.log'
    excluded_types = ['.tmp', '.log']
    try:
        file_md5s, total_md5 = calculate_md5_of_files(directory_to_scan, log_file_path, excluded_types)
        print("File MD5 Hashes:", file_md5s)
        print("Cumulative MD5 Hash:", total_md5)
    except Exception as e:
        print(f"An error occurred: {e}")
