import logging
from datetime import datetime

def calculate_md5_hashes(directory_path, max_symlink_depth=3, max_read_attempts=3, log_file=None):
    # Initialize logger
    if not os.path.exists(os.path.dirname(log_file)):
        os.makedirs(os.path.dirname(log_file))
    logging.basicConfig(filename=log_file, level=logging.DEBUG, 
                        format='%(asctime)s - %(levelname)s - %(message)s')

    cumulative_hash = hashlib.md5()
    file_hashes = {}

    # Function to resolve symlinks with depth limit
    def resolve_symlink(path, depth=0):
        if depth >= max_symlink_depth:
            return path
        try:
            return os.path.realpath(path)
        except Exception as e:
            logging.error(f"Failed to resolve symlink {path}: {e}")
            return path

    # Function to calculate MD5 hash of a file
    def calculate_file_hash(file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(4096)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()

    # Main processing loop
    for root, _, files in os.walk(directory_path):
        for file_name in files:
            if file_name.startswith('.'):
                continue  # Skip hidden files and directories
            file_path = os.path.join(root, file_name)
            resolved_path = resolve_symlink(file_path)
            try:
                individual_hash = calculate_file_hash(resolved_path)
                cumulative_hash.update(individual_hash.encode('utf-8'))
                file_hashes[file_path] = individual_hash
            except Exception as e:
                logging.error(f"Failed to hash file {file_path}: {e}")

    return file_hashes, cumulative_hash.hexdigest()

# Example usage
