import os
import hashlib
import logging
from datetime import datetime

def calculate_md5_hash(directory, max_depth=10, max_retries=3, log_file=None):
    def resolve_symlink(path, depth=0):
        if depth >= max_depth:
            return path
        if not os.path.islink(path):
            return path
        target = os.readlink(path)
        return resolve_symlink(os.path.join(os.path.dirname(path), target), depth + 1)

    def calculate_file_hash(file_path):
        hasher = hashlib.md5()
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    hasher.update(chunk)
            return hasher.hexdigest()
        except Exception as e:
            logging.error(f"Error reading {file_path}: {e}")
            return None

    def log_result(file_hash, cumulative_hash):
        if log_file:
            with open(log_file, 'a') as f:
                f.write(f"{datetime.now()}: File hash: {file_hash}, Cumulative hash: {cumulative_hash}\n")

    file_hashes = {}
    cumulative_hasher = hashlib.md5()

    for root, _, files in os.walk(directory):
        for name in files:
            if not name.startswith('.') and not name.endswith('~'):
                file_path = os.path.join(root, name)
                resolved_path = resolve_symlink(file_path)
                try:
                    file_hash = calculate_file_hash(resolved_path)
                    if file_hash is not None:
                        file_hashes[file_path] = file_hash
                        cumulative_hasher.update(file_hash.encode())
                except Exception as e:
                    logging.error(f"Error processing {resolved_path}: {e}")

    cumulative_hash = cumulative_hasher.hexdigest()
    log_result(None, cumulative_hash)
    return file_hashes, cumulative_hash

# Example usage
if __name__ == "__main__":
    directory_to_hash = '/path/to/directory'
    log_file = 'md5_log.txt'
    result = calculate_md5_hash(directory_to_hash, log_file=log_file)
    print(result)
