from threading import Timer

class TimeoutException(Exception):
    pass

def calculate_md5_hash(directory_path):
    def hash_file_in_chunks(file_path, chunk_size=65536):
        md5_hash = hashlib.md5()
        try:
            with open(file_path, 'rb') as file:
                for chunk in iter(lambda: file.read(chunk_size), b''):
                    md5_hash.update(chunk)
            return md5_hash.hexdigest()
        except Exception as e:
            print(f"Warning: Skipping {file_path} due to error - {e}")
            return None

    def recursive_directory_traversal(path, timeout=30):
        start_time = time.time()
        result = {}

        def traverse(subpath):
            nonlocal result
            for root, _, files in os.walk(subpath):
                if time.time() - start_time > timeout:
                    raise TimeoutException("Operation timed out")
                for file_name in files:
                    if not file_name.startswith('.'):
                        file_path = os.path.join(root, file_name)
                        hash_value = hash_file_in_chunks(file_path)
                        if hash_value is not None:
                            result[file_path] = hash_value

        traverse(path)
        return result

    try:
        return recursive_directory_traversal(directory_path)
    except TimeoutException as e:
        print(e)
        return {}

# Example usage
directory_path = '/path/to/your/directory'
hash_results = calculate_md5_hash(directory_path)
for file, md5 in hash_results.items():
    print(f"{file}: {md5}")
