from concurrent.futures import ThreadPoolExecutor, as_completed
import time
import logging
import redis

class MD5Hasher:
    def __init__(self, directory, max_files_per_traversal=1000, max_threads=10, retry_attempts=3, timeout=30):
        self.directory = directory
        self.max_files_per_traversal = max_files_per_traversal
        self.max_threads = max_threads
        self.retry_attempts = retry_attempts
        self.timeout = timeout
        self.redis_client = redis.Redis(host='localhost', port=6379, db=0)

    def calculate_md5(self, file_path, return_short_hash=False):
        try:
            with open(file_path, 'rb') as f:
                md5 = hashlib.md5()
                while chunk := f.read(4096):
                    md5.update(chunk)
            if return_short_hash:
                return md5.digest()[:16].hex()
            else:
                return md5.hexdigest()
        except Exception as e:
            logging.warning(f"Error calculating MD5 for {file_path}: {e}")
            return None

    def process_files(self):
        start_time = time.time()
        files_to_process = self.get_files_to_process()
        results = {}

        with ThreadPoolExecutor(max_workers=self.max_threads) as executor:
            future_to_file = {executor.submit(self.calculate_md5, file): file for file in files_to_process}
            for future in as_completed(future_to_file):
                file_path = future_to_file[future]
                try:
                    hash_value = future.result()
                    if hash_value is not None:
                        results[file_path] = hash_value
                except Exception as e:
                    logging.error(f"Exception while processing {file_path}: {e}")

        duration = time.time() - start_time
        logging.info(f"Processed {len(results)} files in {duration:.2f} seconds")
        return results

    def get_files_to_process(self):
        files = []
        for root, _, filenames in os.walk(self.directory):
            for filename in filenames:
                if not filename.startswith('.') and self.redis_client.get(filename) is None:
                    file_path = os.path.join(root, filename)
                    files.append(file_path)
                    if len(files) >= self.max_files_per_traversal:
                        break
        return files

    def check_and_handle_edge_cases(self, file_path):
        # Implement checks and handling for edge cases here
        pass

    def log_progress_and_errors(self, message, level='info'):
        logging.log(level, message)

    def run_in_batch_mode(self):
        results = self.process_files()
        return results

    def run_interactively(self):
        file_path = input("Enter the path of the file to process: ")
        if os.path.exists(file_path) and os.path.isfile(file_path):
            result = self.calculate_md5(file_path)
            print(f"MD5 hash for {file_path}: {result}")
        else:
            print(f"{file_path} is not a valid file.")

# Example usage
if __name__ == "__main__":
    hasher = MD5Hasher('/path/to/directory')
    if input("Run in batch mode? (y/n): ").lower() == 'y':
        results = hasher.run_in_batch_mode()
        print(results)
    else:
        hasher.run_interactively()
