import os
import hashlib
import concurrent.futures
import queue
import time
import warnings
import logging

def calculate_md5(file_path, truncate=False):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    if truncate and os.path.getsize(file_path) > 1024 * 1024:  # 1MB
        return hasher.digest()[:16].hex()
    return hasher.hexdigest()

def process_file_queue(queue, max_concurrent=10):
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        future_to_file = {executor.submit(calculate_md5, queue.get()): queue.get() for _ in range(max_concurrent)}
        while future_to_file:
            done, not_done = concurrent.futures.wait(future_to_file, return_when=concurrent.futures.FIRST_COMPLETED)
            for future in done:
                file_path = future_to_file[future]
                try:
                    result = future.result()
                    print(f"{file_path}: {result}")
                except Exception as e:
                    logging.warning(f"Error processing {file_path}: {e}")
                del future_to_file[future]
            time.sleep(0.1)  # Avoid busy-waiting

def traverse_directory(directory, max_files_per_traversal=1000, max_concurrent_threads=10):
    file_queue = queue.Queue()
    for root, _, files in os.walk(directory):
        for file in files:
            if not file.startswith('.'):
                file_path = os.path.join(root, file)
                file_queue.put(file_path)
                if file_queue.qsize() >= max_files_per_traversal:
                    process_file_queue(file_queue, max_concurrent=max_concurrent_threads)

def main():
    directory = input("Enter the directory path: ")
    traverse_directory(directory)

if __name__ == "__main__":
    main()
