from concurrent.futures import ThreadPoolExecutor, as_completed
from PIL import Image
import redis
import logging
from time import time

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Initialize Redis cache
redis_client = redis.Redis(host='localhost', port=6379, db=0)

def generate_thumbnail(input_path, output_path):
    try:
        with Image.open(input_path) as img:
            width, height = img.size
            aspect_ratio = width / float(height)
            new_width = 100
            if height * aspect_ratio > 100:
                new_height = int(new_width / aspect_ratio)
            else:
                new_height = 100

            img = img.resize((new_width, new_height), Image.ANTIALIAS)
            img.save(output_path)
    except Exception as e:
        logger.error(f"Failed to generate thumbnail for {input_path}: {e}")

def process_images(input_dir, output_dir, max_files_per_traversal=1000, max_threads=10, ttl=3600):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    start_time = time()
    timeout_duration = 30
    if 'EXTEND_TIMEOUT' in os.environ:
        logger.warning("Extended timeout due to EXTEND_TIMEOUT environment variable")
        timeout_duration = 60

    with ThreadPoolExecutor(max_workers=max_threads) as executor:
        futures = []
        for root, dirs, files in os.walk(input_dir):
            for file in files:
                if not file.startswith('.') and file.lower().endswith(('.png', '.jpg', '.jpeg')):
                    input_path = os.path.join(root, file)
                    output_path = os.path.join(output_dir, f"{os.path.splitext(file)[0]}_thumb.jpg")

                    if redis_client.get(input_path) is None:
                        futures.append(executor.submit(generate_thumbnail, input_path, output_path))
                        redis_client.setex(input_path, ttl, 1)

                        if len(futures) >= max_files_per_traversal:
                            for future in as_completed(futures):
                                try:
                                    future.result()
                                except Exception as e:
                                    logger.error(f"Failed to complete task: {e}")
                            futures = []

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logger.error(f"Failed to complete task: {e}")

    if time() - start_time > timeout_duration:
        raise TimeoutError("Operation timed out")

# Example usage
input_directory = "/path/to/input/images"
output_directory = "/path/to/output/thumbnails"
process_images(input_directory, output_directory)
