    def increment_ref(self):
        self.ref_count += 1

    def decrement_ref(self):
        if self.ref_count > 0:
            self.ref_count -= 1
            return True
        return False

class FileHashPipeline:
    def __init__(self, N, chunk_size=1024*1024):  # Default chunk size of 1MB
        self.N = N
        self.chunk_size = chunk_size
