import hashlib
import os

def calculate_file_md5(file_path, chunk_size=64*1024):
    """
    Calculate the MD5 hash of a file using memory-efficient streaming.

    Args:
        file_path (str): The path to the file.
        chunk_size (int): The size of each chunk in bytes.

    Returns:
        str: The MD5 hash of the file.

    Raises:
        FileNotFoundError: If the file does not exist.
        PermissionError: If the file permissions prevent reading.
        Exception: For other I/O errors.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

# Example usage
try:
    file_hash = calculate_file_md5('path/to/largefile.txt')
    print(f"MD5 hash of the file: {file_hash}")
except Exception as e:
    print(f"Error calculating MD5: {e}")
