#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_N 1024

typedef struct {
    int global_id;
    int* ues;
    time_t last_update;
    int priority;
} TAI;

typedef struct {
    uint32_t rnti;
    uint8_t crcflag;
    // Add other members as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int ntais;
    TAI* taies;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct pool_node {
    void* data;
    struct pool_node* next;
} pool_node_t;

typedef struct {
    pool_node_t* free_list;
    size_t block_size;
    size_t num_blocks;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->free_list = NULL;
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;

    for (size_t i = 0; i < num_blocks; ++i) {
        pool_node_t* node = (pool_node_t*)malloc(sizeof(pool_node_t));
        if (!node) {
            destroy_memory_pool(pool);
            return NULL;
        }
        node->data = malloc(block_size);
        if (!node->data) {
            free(node);
            destroy_memory_pool(pool);
            return NULL;
        }
        node->next = pool->free_list;
        pool->free_list = node;
    }

    return pool;
}

void destroy_memory_pool(memory_pool_t* pool) {
    while (pool->free_list) {
        pool_node_t* next = pool->free_list->next;
        free(pool->free_list->data);
        free(pool->free_list);
        pool->free_list = next;
    }
    free(pool);
}

void* allocate_from_pool(memory_pool_t* pool) {
    if (!pool->free_list) return NULL;
    void* data = pool->free_list->data;
    pool->free_list = pool->free_list->next;
    return data;
}

void deallocate_to_pool(memory_pool_t* pool, void* data) {
    pool_node_t* node = (pool_node_t*)malloc(sizeof(pool_node_t));
    if (!node) return;
    node->data = data;
    node->next = pool->free_list;
    pool->free_list = node;
}

NFAPI_CRC_INDICATION_PDU_T** create_nfaapi_array(size_t N, memory_pool_t* pool) {
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)allocate_from_pool(pool);
    if (!array) return NULL;

    for (size_t i = 0; i < N; ++i) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(pool);
        if (!array[i]) {
            destroy_nfaapi_array(array, i, pool);
            return NULL;
        }
        memset(array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Initialize RX_UE_INFORMATION_TAG and TAI entities here
    }

    return array;
}

void destroy_nfaapi_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t N, memory_pool_t* pool) {
    for (size_t i = 0; i < N; ++i) {
        if (array[i]) deallocate_to_pool(pool, array[i]);
    }
    if (array) deallocate_to_pool(pool, array);
}

void log_message(const char* message) {
    printf("%s\n", message);
}

int main() {
    memory_pool_t* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_N);
    if (!pool) {
        log_message("Failed to create memory pool");
