#include <stdlib.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct ListElement {
    NFAPI_CRC_INDICATION_PDU data;
    struct ListElement* next;
} ListElement;

typedef struct DynamicList {
    ListElement* head;
    size_t count;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list) {
        list->head = NULL;
        list->count = 0;
    }
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    while (list->head) {
        ListElement* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    free(list);
}

bool add_to_dynamic_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU new_data) {
    ListElement* new_element = (ListElement*)malloc(sizeof(ListElement));
    if (!new_element) return false;

    new_element->data = new_data;
    new_element->next = list->head;
    list->head = new_element;
    ++list->count;

    return true;
}

NFAPI_CRC_INDICATION_PDU* get_from_dynamic_list(DynamicList* list, size_t index) {
    if (index >= list->count || list->count == 0) return NULL;

    ListElement* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    return &current->data;
}

bool remove_from_dynamic_list(DynamicList* list, size_t index) {
    if (index >= list->count || list->count == 0) return false;

    ListElement* current = list->head;
    ListElement* previous = NULL;
    for (size_t i = 0; i < index; ++i) {
        previous = current;
        current = current->next;
    }

    if (previous) {
        previous->next = current->next;
    } else {
        list->head = current->next;
    }
    free(current);
    --list->count;

    return true;
}
