import java.util.concurrent.PriorityBlockingQueue;
import java.util.concurrent.locks.ReentrantLock;

public class ThreadSafePriorityQueue<T extends Comparable<T>> {
    private final PriorityBlockingQueue<T> queue;
    private final ReentrantLock lock;

    public ThreadSafePriorityQueue(int capacity) {
        this.queue = new PriorityBlockingQueue<>(capacity);
        this.lock = new ReentrantLock();
    }

    public void enqueue(T item) {
        lock.lock();
        try {
            queue.put(item);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }
    }

    public T dequeue() {
        lock.lock();
        try {
            return queue.poll();
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }

    public void updateCapacity(int newCapacity) {
        lock.lock();
        try {
            // Implement logic to dynamically adjust the capacity
        } finally {
            lock.unlock();
        }
    }

    public void logQueueOperations(String operation, T item) {
        // Implement logging mechanism
    }
}
