#define MAX_PACKETS 1024

typedef struct {
    uint8_t src_mac[6];
    uint8_t dst_mac[6];
    size_t length;
    uint8_t payload[];
} MLDU;

MLDU* generate_packets(size_t num_packets, size_t max_payload_size) {
    if (num_packets > MAX_PACKETS) {
        fprintf(stderr, "Error: Maximum number of packets exceeded\n");
        return NULL;
    }

    MLDU* packet_pool = malloc(num_packets * sizeof(MLDU));
    if (!packet_pool) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        // Simulate generating valid MAC addresses and payload data
        for (int j = 0; j < 6; ++j) {
            packet_pool[i].src_mac[j] = rand() % 256;
            packet_pool[i].dst_mac[j] = rand() % 256;
        }
        packet_pool[i].length = max_payload_size + (rand() % (max_payload_size / 4));
        packet_pool[i].payload = malloc(packet_pool[i].length);
        if (!packet_pool[i].payload) {
            fprintf(stderr, "Memory allocation failed for payload\n");
            // Clean up previously allocated memory
            while (i--) {
                free(packet_pool[i].payload);
            }
            free(packet_pool);
            return NULL;
        }
    }

    return packet_pool;
}

void free_packets(MLDU* packets, size_t num_packets) {
    for (size_t i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}
