        packets[i].src_mac[4] = rand() % 256;
        packets[i].src_mac[5] = rand() % 256;

        packets[i].dst_mac[0] = rand() % 256;
        packets[i].dst_mac[1] = rand() % 256;
        packets[i].dst_mac[2] = rand() % 256;
        packets[i].dst_mac[3] = rand() % 256;
        packets[i].dst_mac[4] = rand() % 256;
        packets[i].dst_mac[5] = rand() % 256;

        packets[i].length = lengths[i];
        packets[i].payload = malloc(packets[i].length);
        if (!packets[i].payload) {
            for (size_t j = 0; j < i; ++j) free(packets[j].payload);
            free(packets);
            return NULL;
        }
        memcpy(packets[i].payload, payloads[i], packets[i].length);
    }

    return packets;
}

void free_packets(NetworkPacket* packets, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        if (packets[i].payload) free(packets[i].payload);
    }
    free(packets);
