#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned char src_mac[6];
    unsigned char dst_mac[6];
    size_t length;
    void* payload;
    time_t timestamp;
} NetworkPacket;

NetworkPacket** generate_packets(size_t N, size_t packet_size, int use_timestamp) {
    NetworkPacket** packets = (NetworkPacket**)malloc(N * sizeof(NetworkPacket*));
    if (!packets) {
        return NULL; // Handle memory allocation failure
    }

    for (size_t i = 0; i < N; ++i) {
        packets[i] = (NetworkPacket*)malloc(sizeof(NetworkPacket));
        if (!packets[i]) {
            // Handle memory allocation failure and free previously allocated packets
            for (size_t j = 0; j < i; ++j) {
                free(packets[j]);
            }
            free(packets);
            return NULL;
        }

        // Initialize MAC addresses, packet length, payload, and timestamp
        memset(packets[i]->src_mac, 0x00, 6);
        memset(packets[i]->dst_mac, 0xFF, 6); // Example destination MAC address
        packets[i]->length = packet_size;
        packets[i]->payload = malloc(packet_size);
        if (!packets[i]->payload) {
            // Handle memory allocation failure and free previously allocated resources
            for (size_t j = 0; j <= i; ++j) {
                free(packets[j]->payload);
                free(packets[j]);
            }
            free(packets);
            return NULL;
        }

        if (use_timestamp) {
            packets[i]->timestamp = time(NULL);
        } else {
            memset(&packets[i]->timestamp, 0x00, sizeof(time_t));
        }
    }

    return packets;
}

void free_packets(NetworkPacket** packets, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        free(packets[i]->payload);
        free(packets[i]);
    }
    free(packets);
}
