    if (log_file == NULL) return;
    time_t now = time(NULL);
    fprintf(log_file, "%s - %s - %s\n", ctime(&now), user_id, event_type);
    fclose(log_file);
}

void add_user(UserDatabase *db, const char *user_id, const char *name, const char *email, const char *roles) {
    if (db->user_count >= MAX_USERS) return;
    UserProfile *new_user = &db->profiles[db->user_count];
    strcpy(new_user->user_id, user_id);
    strcpy(new_user->name, name);
    strcpy(new_user->email, email);
    new_user->registration_timestamp = time(NULL);
    strcpy(new_user->roles, roles);
    log_event(db, user_id, "User Added");
    db->user_count++;
}

void add_session(UserDatabase *db, const char *session_id, const char *user_id, const char *ip_address) {
    if (db->session_count >= MAX_USERS) return;
    SessionState *new_session = &db->sessions[db->session_count];
    strcpy(new_session->session_id, session_id);
    strcpy(new_session->ip_address, ip_address);
    new_session->login_time = time(NULL);
    new_session->last_active_timestamp = new_session->login_time;
    log_event(db, user_id, "Session Added");
    db->session_count++;
}

void update_session(UserDatabase *db, const char *session_id, const char *ip_address) {
    for (int i = 0; i < db->session_count; i++) {
        if (strcmp(db->sessions[i].session_id, session_id) == 0) {
            SessionState *session = &db->sessions[i];
            session->last_active_timestamp = time(NULL);
            strcpy(session->ip_address, ip_address);
            log_event(db, session->ip_address, "Session Updated");
            return;
        }
    }
}

void delete_session(UserDatabase *db, const char *session_id) {
    for (int i = 0; i < db->session_count; i++) {
        if (strcmp(db->sessions[i].session_id, session_id) == 0) {
            log_event(db, db->sessions[i].ip_address, "Session Deleted");
            memmove(&db->sessions[i], &db->sessions[i + 1], sizeof(SessionState) * (db->session_count - i - 1));
            db->session_count--;
            return;
        }
    }
}

void export_to_json(UserDatabase *db) {
    FILE *json_file = fopen("user_db.json", "w");
    if (json_file == NULL) return;
    fprintf(json_file, "[\n");
    for (int i = 0; i < db->user_count; i++) {
        UserProfile *user = &db->profiles[i];
        fprintf(json_file, "{\"user_id\":\"%s\",\"name\":\"%s\",\"email\":\"%s\",\"registration_timestamp\":%ld,\"roles\":\"%s\"}", 
                user->user_id, user->name, user->email, user->registration_timestamp, user->roles);
        if (i < db->user_count - 1) fprintf(json_file, ",");
        fprintf(json_file, "\n");
    }
    fprintf(json_file, "]");
    fclose(json_file);
}

int main() {
    UserDatabase db = {0};
    add_user(&db, "user1", "John Doe", "john@example.com", "admin,user");
    add_session(&db, "session1", "user1", "192.168.1.1");
    update_session(&db, "session1", "192.168.1.2");
    delete_session(&db, "session1");
    export_to_json(&db);
    return 0;
}
