typedef struct {
    char *user_id;
    char *name;
    char *email;
    time_t registration_timestamp;
    char **roles;
    int num_roles;
    // Session state fields
    time_t login_time;
    char *ip_address;
    time_t last_active_timestamp;
    char *session_id;
    char *metadata;
} UserProfile;

typedef struct {
    UserProfile *profile;
    time_t log_timestamp;
} UserProfileLogEntry;

typedef struct {
    UserProfile **profiles;
    int num_profiles;
    // Add more fields for session state
    UserProfileLogEntry **log_entries;
    int num_log_entries;
} UserDatabase;

UserDatabase* create_user_database() {
    UserDatabase *db = (UserDatabase*)malloc(sizeof(UserDatabase));
    if (db == NULL) {
        return NULL; // Handle memory allocation failure
    }
    db->profiles = NULL;
    db->num_profiles = 0;
    db->log_entries = NULL;
    db->num_log_entries = 0;
    return db;
}

void add_user_profile(UserDatabase *db, UserProfile *profile) {
    if (db == NULL || profile == NULL) {
        return; // Handle invalid input
    }
    db->profiles = realloc(db->profiles, (db->num_profiles + 1) * sizeof(UserProfile*));
    if (db->profiles == NULL) {
        return; // Handle memory allocation failure
    }
    db->profiles[db->num_profiles++] = profile;
}

void log_user_profile_change(UserDatabase *db, UserProfile *profile) {
    if (db == NULL || profile == NULL) {
        return; // Handle invalid input
    }
    db->log_entries = realloc(db->log_entries, (db->num_log_entries + 1) * sizeof(UserProfileLogEntry));
    if (db->log_entries == NULL) {
        return; // Handle memory allocation failure
    }
    UserProfileLogEntry entry;
    entry.profile = profile;
    entry.log_timestamp = time(NULL);
    db->log_entries[db->num_log_entries++] = entry;
}

void delete_user_profile(UserDatabase *db, char *user_id) {
    if (db == NULL || user_id == NULL) {
        return; // Handle invalid input
    }
    for (int i = 0; i < db->num_profiles; i++) {
        if (strcmp(db->profiles[i]->user_id, user_id) == 0) {
            free_profile(db->profiles[i]);
            memmove(&db->profiles[i], &db->profiles[i + 1], (db->num_profiles - i - 1) * sizeof(UserProfile*));
            db->num_profiles--;
            break;
        }
    }
}

void export_to_json(UserDatabase *db, const char *filename) {
    if (db == NULL || filename == NULL) {
        return; // Handle invalid input
    }
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        return; // Handle file opening failure
    }
    fprintf(file, "[\n");
    for (int i = 0; i < db->num_profiles; i++) {
        if (i > 0) {
            fprintf(file, ",\n");
        }
        fprintf(file, "  {\n");
        fprintf(file, "    \"user_id\": \"%s\",\n", db->profiles[i]->user_id);
        fprintf(file, "    \"name\": \"%s\",\n", db->profiles[i]->name);
        fprintf(file, "    \"email\": \"%s\",\n", db->profiles[i]->email);
        // Add other fields for JSON export
        fprintf(file, "  }\n");
    }
    fprintf(file, "]\n");
    fclose(file);
}

void free_profile(UserProfile *profile) {
    if (profile == NULL) {
        return; // Handle invalid input
    }
    free(profile->user_id);
    free(profile->name);
    free(profile->email);
    for (int i = 0; i < profile->num_roles; i++) {
        free(profile->roles[i]);
    }
    free(profile->roles);
    free(profile->session_id);
    free(profile->ip_address);
    free(profile->metadata);
    free(profile);
}

void destroy_user_database(UserDatabase *db) {
    if (db == NULL) {
        return; // Handle invalid input
    }
    for (int i = 0; i < db->num_profiles; i++) {
        free_profile(db->profiles[i]);
    }
    free(db->profiles);
    for (int i = 0; i < db->num_log_entries; i++) {
        free(db->log_entries[i].profile);
    }
    free(db->log_entries);
    free(db);
}
