#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_PDUS 1000
#define MIN_PHY_CELL_ID 1
#define MAX_PHY_CELL_ID 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDUS];
    int count;
    int head;
    int tail;
    pthread_mutex_t mutex;
} MemoryPool;

void init_memory_pool(MemoryPool *pool) {
    pool->count = 0;
    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count >= MAX_PDUS) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    pool->pdus[pool->tail] = pdu;
    pool->tail = (pool->tail + 1) % MAX_PDUS;
    pool->count++;
    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void free_pdu(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->mutex);
    int i;
    for (i = 0; i < MAX_PDUS; i++) {
        if (pool->pdus[i] == pdu) {
            pool->pdus[i] = NULL;
            pool->count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void* create_pdus(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    int phy_cell_id = rand() % 100 + 1; // Random PHY cell ID
    if (phy_cell_id < MIN_PHY_CELL_ID || phy_cell_id > MAX_PHY_CELL_ID) {
        printf("Invalid PHY cell ID: %d\n", phy_cell_id);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(pool);
    if (!pdu) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Populate PDU with random data
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 4096;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;

    // Simulate CRC validation
    int crc_flag = rand() % 2; // Randomly set CRC flag for demonstration purposes

    if (crc_flag == 1) {
        printf("PDU created with PHY cell ID: %d, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               phy_cell_id, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, crc_flag);
    } else {
        printf("PDU creation rejected due to invalid CRC flag: %d\n", crc_flag);
        free_pdu(pool, pdu);
    }

    return NULL;
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool);

    pthread_t threads[10];
    int i;

    srand(time(NULL));

    for (i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, create_pdus, &pool) != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    int j;
    for (j = 0; j < pool.count; j++) {
        free(pool.pdus[(pool.head + j) % MAX_PDUS]);
    }
    pthread_mutex_destroy(&pool.mutex);

    return 0;
}
