void process_input_file(const char *filename, PHY_STATS_PDU_T *stats, int size, const char *output_filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open input file");
        return;
    }

    FILE *output_file = NULL;
    if (output_filename && strcmp(output_filename, "-") != 0) {
        output_file = fopen(output_filename, "w");
        if (!output_file) {
            perror("Failed to open output file");
            fclose(file);
            return;
        }
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Parse line and apply filtering mechanism
        // Example: only include entries with power level > 50
        if (stats->tx_power_level > 50) {
            // Write to output file or perform further processing
            if (output_file) {
                fprintf(output_file, "%d %d %.2f\n", stats->tx_power_level, stats->channel_id, stats->snr_measurement);
            }
        }
    }

    fclose(file);
    if (output_file) {
        fclose(output_file);
    }
}

int main(int argc, char *argv[]) {
