    int size = MAX_ENTRIES;
    PHY_STATS_PDU_T *stats = malloc(size * sizeof(PHY_STATS_PDU_T));
    if (!stats) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    initialize_stats(stats, size);

    const char *input_filename = NULL;
    const char *output_filename = NULL;
    int verbose = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [options] input_file [output_file]\n", argv[0]);
            printf("Options:\n");
            printf("  --verbose      Enable verbose mode\n");
            printf("  --output-file  Specify output file (default is stdout)\n");
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "--output-file") == 0 && i + 1 < argc) {
            output_filename = argv[++i];
        } else {
            input_filename = argv[i];
        }
    }

    if (!input_filename) {
        fprintf(stderr, "No input file specified\n");
        free(stats);
        return EXIT_FAILURE;
    }

    process_input_file(input_filename, stats, size, output_filename);

    free(stats);
    return EXIT_SUCCESS;
}
