#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000000
#define MEMORY_POOL_SIZE 100

typedef struct {
    uint32_t BYTE_COUNT;
    uint64_t PACKET_COUNT;
    float Mbps_BANDWIDTH;
} TRAFFIC_STATS_PDU_T;

typedef struct {
    uint32_t LATENCY_MS;
    uint32_t JITTER_MS;
    float THRUPUT_MBPS;
} NETWORK_PERF_METRICS_PDU_T;

typedef enum { T_TRAFFIC_STATS, T_NETWORK_PERF } PDUTYPE;

typedef struct pdu_struct {
    PDUTYPE type;
    union {
        TRAFFIC_STATS_PDU_T traffic_stats;
        NETWORK_PERF_METRICS_PDU_T network_perf;
    } u;
} PDU_T;

typedef struct {
    double *values;
    size_t count;
} AggregateMetricsResult;

AggregateMetricsResult *aggregateMetrics(PDU_T *pdus, size_t count) {
    AggregateMetricsResult *result = (AggregateMetricsResult *)malloc(sizeof(AggregateMetricsResult));
    if (!result) return NULL;

    result->count = 0;
    result->values = (double *)calloc(count, sizeof(double));
    if (!result->values) {
        free(result);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        if (pdus[i].type == T_TRAFFIC_STATS) {
            result->values[result->count++] = pdus[i].u.traffic_stats.Mbps_BANDWIDTH;
        } else if (pdus[i].type == T_NETWORK_PERF) {
            result->values[result->count++] = pdus[i].u.network_perf.LATENCY_MS;
        }
    }

    // Sort the array for median calculation
    qsort(result->values, result->count, sizeof(double), [](const void *a, const void *b) {
        return (*(double *)a - *(double *)b);
    });

    return result;
}

void processAndAggregateTrafficMetrics(PDU_T *pdus, size_t count) {
    AggregateMetricsResult *result = aggregateMetrics(pdus, count);
    if (!result) {
        printf("Failed to allocate memory for aggregation.\n");
        return;
    }

    // Calculate and print average, median, and standard deviation
    double sum = 0.0, avg = 0.0, variance = 0.0, std_dev = 0.0;
    size_t valid_count = result->count;

    for (size_t i = 0; i < valid_count; ++i) {
        sum += result->values[i];
    }
    avg = sum / valid_count;

    for (size_t i = 0; i < valid_count; ++i) {
        variance += pow(result->values[i] - avg, 2);
    }
    std_dev = sqrt(variance / valid_count);

    printf("Average: %.2f\n", avg);
    printf("Median: %.2f\n", result->count % 2 != 0 ? result->values[result->count / 2] : (result->values[(result->count - 1) / 2] + result->values[result->count / 2]) / 2.0);
    printf("Standard Deviation: %.2f\n", std_dev);

    free(result->values);
    free(result);
}

int main() {
    srand(time(NULL));
    PDU_T pdus[MAX_ELEMENTS];
    size_t count = MAX_ELEMENTS;

    for (size_t i = 0; i < count; ++i) {
        if (rand() % 2 == 0) {
            pdus[i].type = T_TRAFFIC_STATS;
            pdus[i].u.traffic_stats.BYTE_COUNT = rand() % 1000;
            pdus[i].u.traffic_stats.PACKET_COUNT = rand() % 10000;
            pdus[i].u.traffic_stats.Mbps_BANDWIDTH = (float)(rand() % 10 + 1) * 10; // 10 to 20 Mbps
        } else {
            pdus[i].type = T_NETWORK_PERF;
            pdus[i].u.network_perf.LATENCY_MS = rand() % 5;
            pdus[i].u.network_perf.JITTER_MS = rand() % 3;
            pdus[i].u.network_perf.THRUPUT_MBPS = (float)(rand() % 10 + 1); // 1 to 10 Mbps
        }
    }

    processAndAggregateTrafficMetrics(pdus, count);

    return 0;
}
```

This code provides a basic implementation of the required functionality. It includes the `processAndAggregateTrafficMetrics` function that generates random traffic statistics and network performance metrics, aggregates them using the `aggregateMetrics` function, and calculates the average, median, and standard deviation. The main function demonstrates how to populate an array of PDU_T structures with mixed types of data and process it.']

