// Define the DataPacket structure
typedef struct {
    int packetId;
    time_t timestamp;
    size_t dataSize;
} DataPacket;

// Function to initialize and populate an array of DataPacket structures
void initializeDataPackets(DataPacket **dataPackets, size_t *capacity, size_t requestedCapacity) {
    if (requestedCapacity > *capacity) {
        *capacity = requestedCapacity;
        *dataPackets = realloc(*dataPackets, (*capacity) * sizeof(DataPacket));
        if (*dataPackets == NULL) {
            // Handle memory allocation failure
            perror("Failed to allocate memory for data packets");
            return;
        }
    }

    for (size_t i = 0; i < requestedCapacity; ++i) {
        (*dataPackets)[i].packetId = i + 1;
        time(&(*dataPackets)[i].timestamp);
        // Generate a random dataSize between 1 and 1024 bytes
        (*dataPackets)[i].dataSize = rand() % 1024 + 1;
    }

    // Calculate the average data size
    size_t totalDataSize = 0;
    for (size_t i = 0; i < requestedCapacity; ++i) {
        totalDataSize += (*dataPackets)[i].dataSize;
    }
    double averageDataSize = (double)totalDataSize / requestedCapacity;

    // Log the average data size
    printf("Average Data Size: %.2f bytes\n", averageDataSize);
}

// Function to initialize a symmetric encryption cipher with a given password using OpenSSL
void initSymmetricCipher(const char *password, unsigned char **key, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error in creating context
        perror("Failed to create EVP_CIPHER_CTX");
        return;
    }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    int keyLength = EVP_CIPHER_key_length(cipher);
    int ivLength = EVP_CIPHER_iv_length(cipher);

    *key = malloc(keyLength);
    if (*key == NULL) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for key");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *iv = malloc(ivLength);
    if (*iv == NULL) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for IV");
        free(*key);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Generate a random initialization vector (IV)
    if (!RAND_bytes(*iv, ivLength)) {
        // Handle error in generating IV
        perror("Failed to generate random IV");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Derive the encryption key from the password using PBKDF2 with SHA-256, iterating 10,000 times
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), *iv, ivLength, 10000, EVP_sha256(), keyLength, *key)) {
        // Handle error in deriving key
        perror("Failed to derive encryption key");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    DataPacket *dataPackets = NULL;
    size_t capacity = 1024; // Initial capacity
    initializeDataPackets(&dataPackets, &capacity, 512); // Requesting 512 packets

    unsigned char *key = NULL;
    unsigned char *iv = NULL;
    initSymmetricCipher("password123", &key, &iv);

    if (dataPackets != NULL) {
        free(dataPackets);
    }
    if (key != NULL) {
        free(key);
    }
    if (iv != NULL) {
        free(iv);
    }

    return 0;
}
