#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char* ERROR_DETAILS;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} DynamicallyAllocatedArray;

DynamicallyAllocatedArray* init_array(size_t initial_size) {
    DynamicallyAllocatedArray* array = malloc(sizeof(DynamicallyAllocatedArray));
    if (!array) return NULL;

    array->allocated_size = initial_size;
    array->used_size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    array->array = realloc(array->array, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; i++) {
        array->array[i].RX_UE_INFORMATION_TAG = i + 1;
        array->array[i].RNTI = i * 2;
        array->array[i].CRC_INDICATION_REL8_TAG = i % 2 ? 1 : 0;
        array->array[i].ERROR_DETAILS = NULL; // Optional field
    }

    return array;
}

void free_array(DynamicallyAllocatedArray* array) {
    for (size_t i = 0; i < array->used_size; i++) {
        free(array->array[i].ERROR_DETAILS);
    }
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int resize_array(DynamicallyAllocatedArray* array, size_t new_size) {
    pthread_mutex_lock(&array->mutex);
    if (new_size > array->allocated_size) {
        array->array = realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array->array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        for (size_t i = array->used_size; i < new_size; i++) {
            array->array[i].RX_UE_INFORMATION_TAG = i + 1;
            array->array[i].RNTI = i * 2;
            array->array[i].CRC_INDICATION_REL8_TAG = i % 2 ? 1 : 0;
            array->array[i].ERROR_DETAILS = NULL; // Optional field
        }
    } else {
        for (size_t i = new_size; i < array->used_size; i++) {
            free(array->array[i].ERROR_DETAILS);
        }
        array->array = realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array->array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }
    array->allocated_size = new_size;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void clear_cache(DynamicallyAllocatedArray* array) {
    for (size_t i = 0; i < array->used_size; i++) {
        free(array->array[i].ERROR_DETAILS);
        array->array[i].RX_UE_INFORMATION_TAG = 0;
        array->array[i].RNTI = 0;
        array->array[i].CRC_INDICATION_REL8_TAG = 0;
        array->array[i].ERROR_DETAILS = NULL;
    }
    array->used_size = 0;
}

void validate_array(DynamicallyAllocatedArray* array) {
    for (size_t i = 0; i < array->used_size; i++) {
        if (array->array[i].RX_UE_INFORMATION_TAG == 0 ||
            array->array[i].RNTI == 0 ||
            (array->array[i].CRC_INDICATION_REL8_TAG != 0 && array->array[i].CRC_INDICATION_REL8_TAG != 1)) {
            printf("Validation error at index %zu\n", i);
        }
    }
}
