#define DEFAULT_CACHE_SIZE 1024

typedef struct {
    uint32_t SEQ_NUMBER;
    uint32_t PDCP_SN;
    void* DL_SRB_DATA_PDU;
    char* ERROR_DETAILS;
} MAC_RX_QUEUE_ELEMENT;

typedef struct {
    MAC_RX_QUEUE_ELEMENT** elements;
    size_t size;
    size_t capacity;
    size_t cache_size;
    pthread_mutex_t lock;
} MAC_RX_QUEUE;

MAC_RX_QUEUE* initialize_mac_rx_queue(size_t initial_capacity) {
    MAC_RX_QUEUE* queue = (MAC_RX_QUEUE*)malloc(sizeof(MAC_RX_QUEUE));
    if (!queue) {
        perror("Failed to allocate memory for MAC RX Queue");
        return NULL;
    }

    queue->elements = (MAC_RX_QUEUE_ELEMENT**)malloc(initial_capacity * sizeof(MAC_RX_QUEUE_ELEMENT*));
    if (!queue->elements) {
        free(queue);
        perror("Failed to allocate memory for queue elements");
        return NULL;
    }

    queue->size = 0;
    queue->capacity = initial_capacity;
    queue->cache_size = DEFAULT_CACHE_SIZE;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void enqueue_mac_rx_queue(MAC_RX_QUEUE* queue, MAC_RX_QUEUE_ELEMENT* element) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) {
        // Resize the array
        size_t new_capacity = queue->capacity * 2;
        MAC_RX_QUEUE_ELEMENT** new_elements = (MAC_RX_QUEUE_ELEMENT**)realloc(queue->elements, new_capacity * sizeof(MAC_RX_QUEUE_ELEMENT*));
        if (!new_elements) {
            perror("Failed to resize MAC RX Queue");
            pthread_mutex_unlock(&queue->lock);
            return;
        }
        queue->elements = new_elements;
        queue->capacity = new_capacity;
    }

    queue->elements[queue->size++] = element;
    pthread_mutex_unlock(&queue->lock);
}

void free_mac_rx_queue(MAC_RX_QUEUE* queue) {
    pthread_mutex_lock(&queue->lock);
    for (size_t i = 0; i < queue->size; ++i) {
        if (queue->elements[i]->ERROR_DETAILS) {
            free(queue->elements[i]->ERROR_DETAILS);
        }
        // Free other dynamically allocated fields here
        free(queue->elements[i]);
    }
    pthread_mutex_unlock(&queue->lock);

    free(queue->elements);
    free(queue);
}

// Additional functions for caching, resizing, and validation can be added here
