#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS 100
#define BUFFER_SIZE 1024 * 1024 * 5 // 5 MB

typedef struct {
    int numbers[MAX_NUMBERS];
    int count;
} LineData;

int compare(const void *a, const void *b) {
    int *first = (int *)a;
    int *second = (int *)b;
    if (*first != *(first + 1)) return *first - *(first + 1);
    else return *(first + 2) - *(second + 2);
}

void processFile(const char *inputFile, const char *outputFile) {
    FILE *inFile = fopen(inputFile, "r");
    if (!inFile) {
        perror("Error opening input file");
        return;
    }

    FILE *outFile = fopen(outputFile, "w");
    if (!outFile) {
        fclose(inFile);
        perror("Error opening output file");
        return;
    }

    LineData *lines = (LineData *)malloc(BUFFER_SIZE);
    int lineIndex = 0;

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), inFile)) {
        if (lineIndex >= BUFFER_SIZE / sizeof(LineData)) {
            // Handle buffer overflow
            fprintf(stderr, "Buffer overflow detected!\n");
            break;
        }

        LineData line = {0};
        char *token = strtok(buffer, " ");
        while (token && token[0] != '\0') {
            if (isdigit(token[0]) || (token[0] == '-' && strlen(token) > 1)) {
                line.numbers[line.count++] = atoi(token);
            }
            token = strtok(NULL, " ");
        }

        if (line.count >= 2) {
            double avg = ((double)(line.numbers[line.count - 1] + line.numbers[line.count - 2])) / 2;
            fprintf(outFile, "%d %d %.2f\n", line.numbers[0], line.numbers[1], avg);
        } else {
            fprintf(outFile, "%s", buffer);
        }

        lineIndex++;
    }

    fclose(inFile);
    fclose(outFile);

    free(lines);
}

int main() {
    processFile("input.txt", "output.txt");
    return 0;
}
