#define MAX_LINE_LENGTH 1024
#define MAX_FILE_SIZE (10 * 1024 * 1024)
#define LOG_FILE "process.log"
#define MESSAGE_SYSTEM_URL "http://example.com/message"

typedef struct {
    double* numbers;
    int count;
} LineData;

void log_message(const char* message) {
    FILE* log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int compare_lines(const void* a, const void* b) {
    LineData* lineA = (LineData*)a;
    LineData* lineB = (LineData*)b;
    if (lineA->numbers[0] != lineB->numbers[0]) {
        return (lineA->numbers[0] < lineB->numbers[0]) ? -1 : 1;
    } else {
        return (lineB->numbers[1] > lineB->numbers[1]) ? -1 : 1;
    }
}

void process_file(const char* input_file, const char* output_file) {
    FILE* infile = fopen(input_file, "r");
    if (!infile) {
        log_message("Failed to open input file.");
        return;
    }

    FILE* outfile = fopen(output_file, "w");
    if (!outfile) {
        fclose(infile);
        log_message("Failed to open output file.");
        return;
    }

    size_t total_size = 0;
    LineData* lines = NULL;
    int line_count = 0;

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), infile)) {
        if (total_size + strlen(buffer) > MAX_FILE_SIZE) {
            log_message("File exceeds maximum size limit.");
            break;
        }

        LineData* line_data = malloc(sizeof(LineData));
        line_data->count = 0;
        line_data->numbers = NULL;

        char* token = strtok(buffer, " ");
        while (token != NULL) {
            double number = atof(token);
            if (line_data->numbers == NULL) {
                line_data->numbers = malloc(2 * sizeof(double));
            } else {
                line_data->numbers = realloc(line_data->numbers, (line_data->count + 1) * sizeof(double));
            }
            line_data->numbers[line_data->count++] = number;
            token = strtok(NULL, " ");
        }

        if (line_data->count >= 2) {
            double avg = (line_data->numbers[line_data->count - 1] + line_data->numbers[line_data->count - 2]) / 2.0;
            line_data->numbers = realloc(line_data->numbers, (line_data->count + 1) * sizeof(double));
            line_data->numbers[line_data->count++] = avg;
        }

        lines = realloc(lines, (line_count + 1) * sizeof(LineData));
        lines[line_count++] = *line_data;

        free(line_data);
        total_size += strlen(buffer);
    }

    qsort(lines, line_count, sizeof(LineData), compare_lines);

    for (int i = 0; i < line_count; i++) {
        LineData line = lines[i];
        for (int j = 0; j < line.count; j++) {
            fprintf(outfile, "%.2f ", line.numbers[j]);
        }
        fprintf(outfile, "\n");
        free(line.numbers);
    }

    fclose(infile);
    fclose(outfile);
    free(lines);

    log_message("File processing completed.");
}

int main() {
    process_file("input.txt", "output.txt");
    return 0;
}
