#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char timestamp[20];
    char log_level;
    unsigned int thread_id;
    char error_message[1024];
} LOG_ENTRY;

typedef struct {
    LOG_ENTRY *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LOG_LIST;

void init_log_list(LOG_LIST *list, size_t initial_capacity) {
    list->entries = (LOG_ENTRY *)malloc(initial_capacity * sizeof(LOG_ENTRY));
    if (!list->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_log_entry(LOG_LIST *list, const char *timestamp, char log_level, unsigned int thread_id, const char *error_message) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LOG_ENTRY *new_entries = (LOG_ENTRY *)realloc(list->entries, new_capacity * sizeof(LOG_ENTRY));
        if (!new_entries) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&list->mutex);
            exit(EXIT_FAILURE);
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    strcpy(list->entries[list->count].timestamp, timestamp);
    list->entries[list->count].log_level = log_level;
    list->entries[list->count].thread_id = thread_id;
    strncpy(list->entries[list->count].error_message, error_message, sizeof(list->entries[list->count].error_message) - 1);
    list->entries[list->count].error_message[sizeof(list->entries[list->count].error_message) - 1] = '\0';
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void free_log_list(LOG_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->entries);
    list->entries = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    LOG_LIST log_list;
    init_log_list(&log_list, 10);

    add_log_entry(&log_list, "2023-04-15 12:34:56", 'I', 12345, "Initialization successful");
    add_log_entry(&log_list, "2023-04-15 12:35:00", 'W', 12345, "Resource limit approaching");

    free_log_list(&log_list);
    return 0;
}
