#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS 100

typedef struct {
    double numbers[MAX_NUMBERS];
    int count;
} LineData;

LineData* read_and_process_line(const char* line) {
    LineData* data = malloc(sizeof(LineData));
    data->count = 0;
    char* token = strtok((char*)line, " ");
    while (token != NULL && data->count < MAX_NUMBERS) {
        data->numbers[data->count++] = atof(token);
        token = strtok(NULL, " ");
    }
    if (data->count >= 2) {
        double avg = (data->numbers[data->count - 1] + data->numbers[data->count - 2]) / 2.0;
        data->numbers[data->count++] = avg;
    } else {
        data->numbers[data->count++] = 0; // Handle lines with fewer than two numbers
    }
    return data;
}

void process_file(const char* input_filename, const char* output_filename) {
    FILE* infile = fopen(input_filename, "r");
    if (!infile) {
        perror("Failed to open input file");
        return;
    }

    FILE* outfile = fopen(output_filename, "w");
    if (!outfile) {
        perror("Failed to open output file");
        fclose(infile);
        return;
    }

    LineData** lines = NULL;
    int line_count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, infile)) {
        LineData* data = read_and_process_line(line);
        if (data) {
            lines = realloc(lines, (line_count + 1) * sizeof(LineData*));
            lines[line_count++] = data;
        }
    }

    qsort(lines, line_count, sizeof(LineData*), compare_lines);

    for (int i = 0; i < line_count; ++i) {
        for (int j = 0; j < lines[i]->count - 1; ++j) {
            fprintf(outfile, "%.2f ", lines[i]->numbers[j]);
        }
        if (lines[i]->count > 0) {
            fprintf(outfile, "\n");
        }
    }

    for (int i = 0; i < line_count; ++i) {
        free(lines[i]);
