        memset(&array->data[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_cached_array_element(CachedArray* array) {
