#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS 100
#define MAX_SENSORS 50

typedef struct {
    int type;
    char data[256];
} SensorData;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long unique_id;
    time_t timestamp;
    float value;
    // Add more fields as needed
} NFapiCrcIndicationPduT;

int compare_numerical(const void *a, const void *b) {
    double val_a = *(double *)a;
    double val_b = *(double *)b;
    if (val_a == val_b) return 0;
    return (val_a > val_b) ? -1 : 1;
}

int compare_sensor(const void *a, const void *b) {
    NFapiCrcIndicationPduT *sensor_a = (NFapiCrcIndicationPduT *)a;
    NFapiCrcIndicationPduT *sensor_b = (NFapiCrcIndicationPduT *)b;
    if (sensor_a->unique_id != sensor_b->unique_id) return (sensor_a->unique_id > sensor_b->unique_id) ? -1 : 1;
    return (sensor_a->timestamp < sensor_b->timestamp) ? -1 : 1;
}

void process_line(char *line, double **numerical_data, SensorData **sensor_data, int *num_numerical, int *num_sensor) {
    char *token = strtok(line, " ");
    double numbers[MAX_NUMBERS];
    SensorData sensors[MAX_SENSORS];
    int num_numbers = 0;
    int num_sensors = 0;

    while (token != NULL) {
        if (strchr(token, '.') != NULL || strchr(token, 'e') != NULL) {
            numbers[num_numbers++] = atof(token);
        } else {
            sensors[num_sensors].type = atoi(token);
            token = strtok(NULL, " ");
            strncpy(sensors[num_sensors].data, token, sizeof(sensors[num_sensors].data));
            num_sensors++;
        }
        token = strtok(NULL, " ");
    }

    if (num_numbers >= 2) {
        double avg = (numbers[num_numbers - 1] + numbers[num_numbers - 2]) / 2.0;
        *numerical_data = realloc(*numerical_data, (*num_numerical + 1) * sizeof(double));
        (*numerical_data)[*num_numerical] = avg;
        (*num_numerical)++;
    }

    if (num_sensors > 0) {
        for (int i = 0; i < num_sensors; i++) {
            sensor_data[num_sensor][i] = sensors[i];
        }
        *num_sensor += num_sensors;
    }
}

void process_file(const char *input_file, const char *output_file) {
    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        perror("Failed to open input file");
        return;
    }

    double *numerical_data = NULL;
    SensorData sensor_data[MAX_SENSORS];
    int num_numerical = 0;
    int num_sensor = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        process_line(line, &numerical_data, sensor_data, &num_numerical, &num_sensor);
    }

    qsort(numerical_data, num_numerical, sizeof(double), compare_numerical);
    qsort(sensor_data, num_sensor, sizeof(SensorData), compare_sensor);

    FILE *out_fp = fopen(output_file, "w");
    if (out_fp == NULL) {
        perror("Failed to open output file");
        fclose(fp);
        return;
    }

    for (int i = 0; i < num_numerical; i++) {
        fprintf(out_fp, "%.2f ", numerical_data[i]);
    }
    for (int i = 0; i < num_sensor; i++) {
        fprintf(out_fp, "%d %s ", sensor_data[i].type, sensor_data[i].data);
    }

    fclose(fp);
    fclose(out_fp);

    free(numerical_data);
}

void start_service() {
    srand(time(NULL));
    int delay = rand() % 10 + 1; // Random delay between 1 and 10 seconds
    sleep(delay);
    process_file("input.txt", "output.txt");
}

int main() {
    while (1) {
        start_service();
    }
    return 0;
}
```

This code snippet provides a basic structure for processing a text file, computing averages of numerical data, handling sensor data using custom structures, sorting the dataset, and logging events. It includes error handling for file operations and dynamic memory management to avoid leaks. The `main` function starts a service that periodically calls `start_service`, which handles processing with a random delay. This design is extensible and can be further developed to include additional features like background service management, message sending, network monitoring, and more.']

