    printf("Usage: metadata_processor [options]\n");
    printf("-h\t\tDisplay help information\n");
    printf("--version\tDisplay version details\n");
    printf("-t <tag>\tTag images with custom metadata\n");
    printf("-d <directory>\tSpecify the directory containing image files\n");
    printf("-o <output_file>\tSpecify an output file for the metadata report\n");
    printf("-s <size_limit>\tSpecify a maximum size limit for the output file\n");
    printf("-f <format>\tChoose the format of the output (e.g., CSV, JSON)\n");
}

void display_version() {
    printf("Metadata Processor v1.0\n");
}

int main(int argc, char *argv[]) {
    // Parse command line options
    if (argc <= 1) {
        display_help();
        return 0;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            display_help();
            return 0;
        } else if (strcmp(argv[i], "--version") == 0) {
            display_version();
            return 0;
