            printf("Tagging images with: %s\n", tag);
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            // Specify the directory containing image files
            char *directory = argv[++i];
            DIR *dir;
            struct dirent *ent;

            if ((dir = opendir(directory)) != NULL) {
                while ((ent = readdir(dir)) != NULL) {
                    char path[1024];
                    snprintf(path, sizeof(path), "%s/%s", directory, ent->d_name);

                    struct stat file_stat;
                    if (stat(path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
                        // Process each image file
                        printf("Processing image: %s\n", path);
                    } else {
                        fprintf(stderr, "Error: Unable to access file %s\n", path);
                    }
                }
                closedir(dir);
            } else {
                perror("opendir");
            }
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Specify an output file for the metadata report
            char *output_file = argv[++i];
            FILE *file = fopen(output_file, "a+");
            if (file == NULL) {
                perror("fopen");
                return 1;
            }
            // Write metadata to the output file
            fprintf(file, "Metadata Report\n");
            fclose(file);
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            // Specify a maximum size limit for the output file
            char *size_limit_str = argv[++i];
            long long size_limit = atoll(size_limit_str);
            if (size_limit <= 0) {
                fprintf(stderr, "Error: Invalid size limit\n");
                return 1;
            }
            printf("Maximum file size: %lld bytes\n", size_limit);
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            // Choose the format of the output
            char *format = argv[++i];
            printf("Output format: %s\n", format);
        } else {
            fprintf(stderr, "Error: Unknown option: %s\n", argv[i]);
            display_help();
            return 1;
        }
    }

    return 0;
}
