#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

void processLogFile(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Remove trailing newline character
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }

        // Dynamically allocate memory for the fields
        char *fields[MAX_LINE_LENGTH];
        int fieldCount = 0;
        char *token = strtok(line, ",");
        while (token != NULL && fieldCount < MAX_LINE_LENGTH) {
            fields[fieldCount++] = strdup(token);
            token = strtok(NULL, ",");
        }

        // Calculate average of the last three numeric fields
        double sum = 0.0;
        int validFields = 0;
        for (int i = fieldCount - 1; i >= 0 && i > fieldCount - 4; i--) {
            char *endptr;
            long num = strtol(fields[i], &endptr, 10);
            if (*endptr == '\0') { // Valid number
                sum += num;
                validFields++;
            }
        }
        double average = (validFields > 0) ? sum / validFields : 0.0;

        // Print the line with the average appended
        printf("%s,%.2f\n", line, average);

        // Free dynamically allocated memory for fields
        for (int i = 0; i < fieldCount; i++) {
            free(fields[i]);
        }
    }

    fclose(file);
}

int main() {
    const char *filePath = "system_log.txt";
    processLogFile(filePath);
    return 0;
}
