    if (!cache->cache) {
        free(cache);
        return NULL;
    }

    cache->cache_size = initial_size;
    cache->current_size = 0;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

bool nfapi_crc_cache_resize(NFAPI_CRC_CACHE_T *cache, size_t new_size) {
    pthread_mutex_lock(&cache->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_cache = (NFAPI_CRC_INDICATION_PDU_T*)realloc(cache->cache, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_cache) {
        pthread_mutex_unlock(&cache->lock);
        return false;
    }
    cache->cache = new_cache;
    cache->cache_size = new_size;
    pthread_mutex_unlock(&cache->lock);
    return true;
}

void nfapi_crc_cache_clear(NFAPI_CRC_CACHE_T *cache) {
