    if (cache->current_size >= cache->cache_size && !nfapi_crc_cache_resize(cache, cache->cache_size * CACHE_SIZE_MULTIPLIER)) {
        pthread_mutex_unlock(&cache->lock);
        return false;
    }
    cache->cache[cache->current_size++] = item;
    pthread_mutex_unlock(&cache->lock);
    return true;
}

// Example usage:
int main() {
    NFAPI_CRC_CACHE_T *cache = nfapi_crc_cache_init(100, 1000);
    if (!cache) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345;
    pdu.RNTI = 67890;
    pdu.CRC_INDICATION_REL8_TAG = true;
    pdu.ERROR_DETAILS = (char*)malloc(256);
    strcpy(pdu.ERROR_DETAILS, "CRC error detected");

    if (!nfapi_crc_cache_add(cache, pdu)) {
        nfapi_crc_cache_free(cache);
        return -1;
    }

    nfapi_crc_cache_clear(cache);
    nfapi_crc_cache_free(cache);

    return 0;
}
