#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS_PER_LINE 50
#define FILE_SIZE_LIMIT 10 * 1024 * 1024

typedef struct {
    double numbers[MAX_NUMBERS_PER_LINE];
    int count;
} LineData;

int compare(const void* a, const void* b) {
    LineData* dataA = (LineData*)a;
    LineData* dataB = (LineData*)b;
    if (dataA->numbers[0] != dataB->numbers[0]) {
        return (dataA->numbers[0] < dataB->numbers[0]) ? -1 : 1;
    } else {
        return (dataA->numbers[1] > dataB->numbers[1]) ? -1 : 1;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    FILE* inputFile = fopen(argv[1], "r");
    FILE* outputFile = fopen(argv[2], "w");

    if (!inputFile || !outputFile) {
        perror("Failed to open file");
        return 1;
    }

    LineData* lines = (LineData*)malloc(sizeof(LineData));
    int lineCount = 0;

    while (fgets(lines[lineCount].numbers, MAX_LINE_LENGTH, inputFile)) {
        char* token = strtok(lines[lineCount].numbers, " ");
        int index = 0;
        while (token != NULL && index < MAX_NUMBERS_PER_LINE) {
            lines[lineCount].numbers[index++] = atof(token);
            token = strtok(NULL, " ");
        }
        lines[lineCount].count = index;
        if (lines[lineCount].count > 1) {
            double average = (lines[lineCount].numbers[index - 2] + lines[lineCount].numbers[index - 1]) / 2.0;
            fprintf(outputFile, "%s %.2f\n", lines[lineCount].numbers, average);
        }
        lineCount++;
        if (ftell(inputFile) > FILE_SIZE_LIMIT) {
            fprintf(stderr, "File size limit exceeded\n");
            break;
        }
    }

    qsort(lines, lineCount, sizeof(LineData), compare);

    for (int i = 0; i < lineCount; i++) {
        fprintf(outputFile, "%s", lines[i].numbers);
    }

    fclose(inputFile);
    fclose(outputFile);
    free(lines);

    return 0;
}
