#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_Indication_Array;

int init_crc_array(NFAPI_CRC_Indication_Array *array, size_t initial_capacity) {
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) return -1; // Memory allocation failed
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

void resize_crc_array(NFAPI_CRC_Indication_Array *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return; // Memory reallocation failed
    array->data = new_data;
    array->capacity = new_capacity;
}

int add_to_crc_array(NFAPI_CRC_Indication_Array *array, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) resize_crc_array(array, array->capacity * 2);
    array->data[array->size++] = *pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void clear_crc_cache(NFAPI_CRC_Indication_Array *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}

void destroy_crc_array(NFAPI_CRC_Indication_Array *array) {
    clear_crc_cache(array);
    pthread_mutex_destroy(&array->mutex);
}
