// C-style function to process data from a file
void ProcessFile(const std::string& inputFilePath, const std::string& outputFilePath) {
    std::ifstream inputFile(inputFilePath);
    if (!inputFile.is_open()) {
        std::cerr << "Error opening input file: " << inputFilePath << std::endl;
        return;
    }

    std::ofstream outputFile(outputFilePath);
    if (!outputFile.is_open()) {
        std::cerr << "Error opening output file: " << outputFilePath << std::endl;
        inputFile.close();
        return;
    }

    // Process each line of the input file
    std::string line;
    while (std::getline(inputFile, line)) {
        std::istringstream iss(line);
        std::vector<double> numbers;
        double num;
        while (iss >> num) {
            numbers.push_back(num);
        }

        if (numbers.size() < 2) {
            continue; // Skip lines with less than two numbers
        }

        double average = (numbers[numbers.size() - 1] + numbers[numbers.size() - 2]) / 2.0;
        numbers.push_back(average);

        std::ostringstream oss;
        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i > 0) oss << " ";
            oss << numbers[i];
        }
        outputFile << oss.str() << std::endl;
    }

    inputFile.close();
    outputFile.close();
}

