int compareLines(const void *a, const void *b) {
    LineData *lineA = (LineData *)a;
    LineData *lineB = (LineData *)b;

    if (lineA->sensor_count == 0 && lineB->sensor_count == 0) {
        return lineA->numbers[0] - lineB->numbers[0];
    } else if (lineA->sensor_count == 0) {
        return -1;
    } else if (lineB->sensor_count == 0) {
        return 1;
    }

