#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    char* ERROR_DETAILS;
} NFAPI_CRC_INDICATION_PDU_T;

#define CACHE_SIZE_MULTIPLIER 10

typedef struct CacheEntry {
    void* data;
    int inUse;
} CacheEntry;

typedef struct {
    CacheEntry** entries;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->entries = (CacheEntry**)malloc(initial_capacity * sizeof(CacheEntry*));
    for (size_t i = 0; i < initial_capacity; ++i) {
        cache->entries[i] = (CacheEntry*)malloc(sizeof(CacheEntry));
        cache->entries[i]->data = NULL;
        cache->entries[i]->inUse = 0;
    }
    cache->capacity = initial_capacity * CACHE_SIZE_MULTIPLIER;
    cache->used = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void* get_from_cache(Cache* cache) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (!cache->entries[i]->inUse) {
            cache->entries[i]->inUse = 1;
            pthread_mutex_unlock(&cache->lock);
            return cache->entries[i]->data;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void free_cache_entry(Cache* cache, void* entry) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i]->data == entry) {
            pthread_mutex_lock(&cache->lock);
            cache->entries[i]->inUse = 0;
            pthread_mutex_unlock(&cache->lock);
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* initialize_array(size_t N, Cache* cache) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)get_from_cache(cache);
    if (!array) {
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) {
            // Handle memory allocation failure
            return NULL;
        }
        for (size_t i = 0; i < N; ++i) {
            array[i].RX_UE_INFORMATION_TAG = i;
            array[i].RNTI = i % 1024;
            array[i].CRC_INDICATION_REL8_TAG = 0;
            array[i].ERROR_DETAILS = NULL;
        }
    }
    // Log initialization details
    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, Cache* cache) {
    if (array) {
        if (get_from_cache(cache)) {
            // Return to cache instead of freeing
        } else {
            free(array);
        }
    }
}
