void process_log_file(const char* input_file, const char* output_file) {
    FILE *input = fopen(input_file, "r");
    if (input == NULL) {
        perror("Failed to open input file");
        return;
    }

    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        perror("Failed to open output file");
        fclose(input);
        return;
    }

    char line[MAX_LINE_LENGTH];
    SensorData sensor_data[MAX_SENSOR_DATA];

    int total_lines_processed = 0;

    while (fgets(line, sizeof(line), input)) {
        total_lines_processed++;

        // Trim newline character
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }

        // Process numerical data
        char *token = strtok(line, " ");
        double num1 = atof(token);
        token = strtok(NULL, " ");
        double num2 = atof(token);

        double average = (num1 + num2) / 2;
        fprintf(output, "%.2f %.2f %.2f\n", num1, num2, average);

        // Process sensor data
        int sensor_count = 0;
        token = strtok(NULL, " ");
        while (token != NULL && sensor_count < MAX_SENSOR_DATA) {
            if (sscanf(token, "%d %lf", &sensor_data[sensor_count].id, &sensor_data[sensor_count].timestamp) == 2) {
                sensor_count++;
            }
            token = strtok(NULL, " ");
        }

        for (int i = 0; i < sensor_count; i++) {
            fprintf(output, "%d %.2f ", sensor_data[i].id, sensor_data[i].timestamp);
        }
        fprintf(output, "\n");

        // Free allocated resources if necessary
        // ...

    }

    fclose(input);
    fclose(output);

    printf("Total lines processed: %d\n", total_lines_processed);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_log_file(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
