class DistributedFileStorage {
public:
    void uploadFile(const std::string& file_name, const FileMetadata& metadata) {
        std::lock_guard<std::mutex> lock(mutex_);
        files_[file_name] = metadata;
        std::cout << "Uploaded file: " << file_name << std::endl;
    }

    FileMetadata getFileMetadata(const std::string& file_name) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (files_.find(file_name) != files_.end()) {
            return files_[file_name];
        }
        throw std::runtime_error("File not found");
    }

private:
    std::unordered_map<std::string, FileMetadata> files_;
    std::mutex mutex_;
};

int main() {
