    FileMetadata metadata = {std::time(nullptr), 1, "text", "checksum123"};

    storage.uploadFile("example.txt", metadata);

    try {
        FileMetadata retrieved_metadata = storage.getFileMetadata("example.txt");
        std::cout << "Retrieved file metadata: upload_time=" << retrieved_metadata.upload_time
                  << ", client_id=" << retrieved_metadata.client_id
