    NFAPI_CRC_INDICATION_PDU_T *array[MAX_CONCURRENT_INSTANCES];
    int count;
    int active_instances;
    int log_enabled;
} InstanceManager;

int initialize_instance(InstanceManager *manager, int tag, int rnti, int crc_tag, int error_flag) {
    if (manager->active_instances >= MAX_CONCURRENT_INSTANCES) {
        return -1; // Too many instances
    }

    NFAPI_CRC_INDICATION_PDU_T *new_instance = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_instance) {
        return -2; // Memory allocation failed
    }

    new_instance->RX_UE_INFORMATION_TAG = tag;
    new_instance->RNTI = rnti;
    new_instance->CRC_INDICATION_REL8_TAG = crc_tag | (error_flag ? 1 : 0);

    manager->array[manager->active_instances] = new_instance;
    manager->active_instances++;

    if (manager->log_enabled) {
        time_t now = time(NULL);
        printf("Initialized instance at %s, Active instances: %d\n", ctime(&now), manager->active_instances);
    }

    return 0; // Success
}

void cleanup_manager(InstanceManager *manager) {
    for (int i = 0; i < manager->active_instances; i++) {
        free(manager->array[i]);
    }
    manager->active_instances = 0;
}
