    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

int nfaapi_crc_array_init(NFAPI_CRC_ARRAY** array, size_t N, int log_enabled) {
    *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!*array) return -1; // Memory allocation failed

    (*array)->capacity = N;
    (*array)->count = 0;
    (*array)->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*array)->array) {
        free(*array);
        return -1; // Memory allocation failed
    }

    pthread_mutex_init(&(*array)->mutex, NULL);

    if (log_enabled) {
        time_t now = time(NULL);
        printf("Initialization requested at %s with capacity %zu\n", ctime(&now), N);
    }

    return 0;
}

void nfaapi_crc_array_cleanup(NFAPI_CRC_ARRAY* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int nfaapi_crc_array_add(NFAPI_CRC_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->array[array->count++] = pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}
