#define CACHE_SIZE_LIMIT 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cache[CACHE_SIZE_LIMIT];
    int cache_count;
    pthread_mutex_t lock;
} CacheManager;

CacheManager cache_manager = {0};

void init_cache() {
    pthread_mutex_init(&cache_manager.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaip_pdu(int tag, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    // Initialize other fields...

    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T** allocate_array(int N, int *actual_size) {
    if (N <= 0) {
        printf("Invalid size\n");
        return NULL;
    }

    pthread_mutex_lock(&cache_manager.lock);
    if (cache_manager.cache_count > 0) {
        NFAPI_CRC_INDICATION_PDU_T **array = cache_manager.cache[--cache_manager.cache_count];
        *actual_size = N;
        pthread_mutex_unlock(&cache_manager.lock);
        return array;
    }
    pthread_mutex_unlock(&cache_manager.lock);

    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i] = create_nfaip_pdu(i, i); // Example initialization
        if (!array[i]) {
            printf("Failed to initialize element %d\n", i);
            // Free previously allocated elements
            for (int j = 0; j < i; j++) free(array[j]);
            free(array);
            return NULL;
        }
    }

    *actual_size = N;
    return array;
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T **array, int old_size, int new_size) {
    if (new_size <= 0) {
        printf("Invalid new size\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T **new_array = allocate_array(new_size, NULL);
    if (!new_array) {
        printf("Failed to resize array\n");
        return;
    }

    for (int i = 0; i < old_size && i < new_size; i++) {
        new_array[i] = array[i];
    }

    // Free original array elements
    for (int i = 0; i < old_size; i++) free(array[i]);
    free(array);

    pthread_mutex_lock(&cache_manager.lock);
    if (cache_manager.cache_count < CACHE_SIZE_LIMIT) {
        cache_manager.cache[cache_manager.cache_count++] = new_array;
    } else {
        // Handle cache overflow
        printf("Cache overflow, discarding old array\n");
        free(new_array);
    }
    pthread_mutex_unlock(&cache_manager.lock);
}

void clear_cache() {
    pthread_mutex_lock(&cache_manager.lock);
    for (int i = 0; i < cache_manager.cache_count; i++) {
        for (int j = 0; j < CACHE_SIZE_LIMIT; j++) free(cache_manager.cache[i][j]);
        free(cache_manager.cache[i]);
    }
    cache_manager.cache_count = 0;
    pthread_mutex_unlock(&cache_manager.lock);
}

void destroy_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    for (int i = 0; i < size; i++) free(array[i]);
    free(array);

    pthread_mutex_lock(&cache_manager.lock);
    cache_manager.cache[cache_manager.cache_count++] = array;
    pthread_mutex_unlock(&cache_manager.lock);
}

int main() {
    init_cache();

    int N = 10;
    int actual_size;
    NFAPI_CRC_INDICATION_PDU_T **array = allocate_array(N, &actual_size);

    if (array) {
        printf("Array allocated with size %d\n", actual_size);

        // Example usage of the array...

        destroy_array(array, actual_size);
    }

    return 0;
}
