#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS 1000
#define ERROR_FILE_SIZE "File exceeds maximum size limit of 10 MB"
#define ERROR_EMPTY_FILE "Input file is empty"
#define ERROR_CORRUPT_DATA "Corrupt data in input file"

typedef struct {
    double numbers[MAX_NUMBERS];
    int count;
} LineData;

int compare(const void *a, const void *b) {
    LineData *dataA = (LineData *)a;
    LineData *dataB = (LineData *)b;
    if (dataA->numbers[0] != dataB->numbers[0]) {
        return (dataA->numbers[0] > dataB->numbers[0]) ? 1 : -1;
    } else {
        return (dataA->numbers[1] < dataB->numbers[1]) ? 1 : -1;
    }
}

void processFile(const char *input, const char *output) {
    FILE *in = fopen(input, "r");
    if (!in) {
        fprintf(stderr, "Error opening input file: %s\n", strerror(errno));
        return;
    }

    int lineCount = 0;
    LineData *data = malloc(MAX_LINE_LENGTH * sizeof(LineData));
    while (fgets(data[lineCount].numbers, MAX_NUMBERS, in)) {
        char *token = strtok(data[lineCount].numbers, " ");
        data[lineCount].count = 0;
        while (token) {
            data[lineCount].numbers[data[lineCount].count++] = atof(token);
            token = strtok(NULL, " ");
        }
        if (data[lineCount].count < 2) {
            fprintf(stderr, "Error processing line %d: Insufficient numbers\n", lineCount + 1);
            return;
        } else {
            data[lineCount].numbers[data[lineCount].count] = (data[lineCount].numbers[data[lineCount].count - 1] + data[lineCount].numbers[data[lineCount].count - 2]) / 2.0;
        }
        lineCount++;
    }

    if (lineCount == 0) {
        fprintf(stderr, "%s\n", ERROR_EMPTY_FILE);
        return;
    } else if (strlen(data[0].numbers) > 10 * 1024 * 1024) {
        fprintf(stderr, "%s\n", ERROR_FILE_SIZE);
        return;
    }

    qsort(data, lineCount, sizeof(LineData), compare);

    FILE *out = fopen(output, "w");
    if (!out) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        return;
    }

    for (int i = 0; i < lineCount; i++) {
        for (int j = 0; j <= data[i].count; j++) {
            fprintf(out, "%.2f ", data[i].numbers[j]);
        }
        fprintf(out, "\n");
    }

    fclose(in);
    fclose(out);
    free(data);

    printf("Processed %d lines successfully.\n", lineCount);
}

int main() {
    processFile("input.txt", "output.txt");
    return 0;
}
