typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t allocated_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory_pool = malloc(initial_size);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->allocated_size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (size > pool->pool_size - pool->allocated_size) {
        printf("Memory allocation failed: Insufficient memory in pool\n");
        return NULL;
    }

    void* ptr = (char*)pool->memory_pool + pool->allocated_size;
    pool->allocated_size += size;

    pthread_mutex_lock(&pool->lock);
    // Simulate memory allocation from a pool
    pthread_mutex_unlock(&pool->lock);

