#include <pthread.h>

#define MAX_QUEUE_LENGTH 100

typedef struct NFAPI_SCH_MSG_T {
    // Define the structure fields here
} NFAPI_SCH_MSG_T;

typedef struct Node {
    NFAPI_SCH_MSG_T *data;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    Node *tail;
    int length;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->length = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(LinkedList *list, NFAPI_SCH_MSG_T *data) {
    pthread_mutex_lock(&list->lock);
    if (list->length >= MAX_QUEUE_LENGTH) {
        Node *temp = list->head;
        list->head = temp->next;
        free(temp->data);
        free(temp);
        list->length--;
    }
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->length++;
    pthread_mutex_unlock(&list->lock);
}

void* process_linked_list(void *arg) {
    LinkedList *list = (LinkedList*)arg;
    while (1) {
        NFAPI_SCH_MSG_T *data;
        pthread_mutex_lock(&list->lock);
        if (list->head) {
            Node *temp = list->head;
            data = temp->data;
            list->head = temp->next;
            free(temp);
            list->length--;
        } else {
            pthread_mutex_unlock(&list->lock);
            break;
        }
        pthread_mutex_unlock(&list->lock);

        // Process the data here
    }
    return NULL;
}

void destroy_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Node *temp = list->head;
    while (temp) {
        NFAPI_SCH_MSG_T *data = temp->data;
        free(temp);
        temp = data->next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->length = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
