    int packetId;
    char TX_UE_INFORMATION_TAG[10];
    int RNTI;
    unsigned char *payloadData;
    int payloadLength;
    int ACK_FLAG;
} NFAPI_pdu_t;

NFAPI_pdu_t* processNfapiPduBatch(int batchSize, int maxPacketCount) {
    NFAPI_pdu_t* batch = (NFAPI_pdu_t*)malloc(batchSize * sizeof(NFAPI_pdu_t));
    if (!batch) {
        perror("Failed to allocate memory for packet batch");
        return NULL;
    }

    for (int i = 0; i < batchSize; i++) {
        // Initialize each packet
        batch[i].packetId = i + 1;
        strcpy(batch[i].TX_UE_INFORMATION_TAG, "TAG");
        batch[i].RNTI = i * 10;

        // Simulate payload data allocation and initialization
        batch[i].payloadData = (unsigned char*)malloc(maxPacketCount * sizeof(unsigned char));
        if (!batch[i].payloadData) {
            perror("Failed to allocate memory for payload data");
            free(batch);
            return NULL;
        }
        memset(batch[i].payloadData, 0, maxPacketCount);

        // Simulate ACK_FLAG calculation based on error correction algorithms
        batch[i].ACK_FLAG = (i % 2 == 0) ? 1 : 0;

        // Calculate payload length and update cumulative payload length
        batch[i].payloadLength = maxPacketCount;
    }

    return batch;
}

void freeNfapiPduBatch(NFAPI_pdu_t* batch, int batchSize) {
    for (int i = 0; i < batchSize; i++) {
        if (batch[i].payloadData) {
            free(batch[i].payloadData);
        }
    }
    free(batch);
}

