#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define MAX_RNTRI 65535

typedef struct {
    int rx_ue_information_tag;
    unsigned short rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* cache[MAX_RNTRI] = {NULL};

int get_from_cache(unsigned short rnti) {
    pthread_mutex_lock(&cache_lock);
    if (cache[rnti]) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = cache[rnti];
        pthread_mutex_unlock(&cache_lock);
        return pdu->crc_indication_rel8_tag;
    }
    pthread_mutex_unlock(&cache_lock);
    return -1; // Tag not found in cache
}

void put_in_cache(unsigned short rnti, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&cache_lock);
    if (pdu->crc_indication_rel8_tag != get_from_cache(rnti)) {
        cache[rnti] = pdu;
    }
    pthread_mutex_unlock(&cache_lock);
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdu(int protocol_version, unsigned short rnti, int *error_code) {
    static NFAPI_CRC_INDICATION_PDU_T pdus[MAX_STRUCTS];
    static int count = 0;

    if (count >= MAX_STRUCTS) {
        *error_code = -1; // Error: Maximum structures reached
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[count++];
    pdu->rx_ue_information_tag = count;
    pdu->rnti = rnti;
    if (protocol_version == 8) {
        pdu->crc_indication_rel8_tag = get_from_cache(rnti);
        if (pdu->crc_indication_rel8_tag == -1) {
            // Simulate a new value generation
            pdu->crc_indication_rel8_tag = rand() % MAX_RNTRI;
            put_in_cache(rnti, pdu);
        }
    } else {
        *error_code = -2; // Error: Unsupported protocol version
        return NULL;
    }

    int random_value = rand();
    pdu->crcflag = (random_value & 1) ? 1 : 0;

    return pdu;
}

void read_and_find_largest() {
    int size, i;
    scanf("%d", &size);
    int* array = malloc(size * sizeof(int));

    for (i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    int max_value = array[0];
    for (i = 1; i < size; i++) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }

    printf("Largest integer: %d\n", max_value);
    free(array);
}

int main() {
    srand(time(NULL));
    int protocol_version, error_code;
    unsigned short rnti;

    // Example usage
    scanf("%d %hu", &protocol_version, &rnti);
    NFAPI_CRC_INDICATION_PDU_T* pdu = generate_pdu(protocol_version, rnti, &error_code);
    if (pdu) {
        printf("PDU generated: RX_UE_INFORMATION_TAG=%d, RNTI=%hu, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag, pdu->crcflag);
    } else {
        printf("Error: %d\n", error_code);
    }

    read_and_find_largest();

    return 0;
}
