// Define a structure for HTTP request objects
typedef struct HttpRequest {
    char *url;
    char method[10];
    char **headers;
    size_t header_count;
    char *body_data;
} HttpRequest;

// Function to create an HTTP request object
HttpRequest* create_http_request(const char *url, const char *method, int headers_size) {
    HttpRequest *request = (HttpRequest *)malloc(sizeof(HttpRequest));
    request->url = strdup(url);
    strcpy(request->method, method);
    request->headers = (char **)malloc(headers_size * sizeof(char *));
    memset(request->headers, 0, headers_size * sizeof(char *));
    request->header_count = 0;
    request->body_data = NULL;
    return request;
}

// Function to add a header to an HTTP request
void add_header(HttpRequest *request, const char *header) {
    request->headers[request->header_count++] = strdup(header);
}

// Function to set body data for an HTTP request
void set_body_data(HttpRequest *request, const char *data) {
    if (request->body_data != NULL) {
        free(request->body_data);
    }
    request->body_data = strdup(data);
}

// Function to delete an HTTP request object
void delete_http_request(HttpRequest *request) {
    if (request->url != NULL) {
        free(request->url);
    }
    for (size_t i = 0; i < request->header_count; ++i) {
        if (request->headers[i] != NULL) {
            free(request->headers[i]);
        }
    }
    if (request->body_data != NULL) {
        free(request->body_data);
    }
    free(request->headers);
    free(request);
}

// Function to process an HTTP request
void process_http_request(HttpRequest *request, int protocol_version, void (*log_function)(const char *)) {
    // Simulate processing the request based on protocol version and log details
    if (protocol_version == 1) {
        log_function("Processing HTTP/1.1 request for URL: %s", request->url);
    } else if (protocol_version == 2) {
        log_function("Processing HTTP/2 request for URL: %s", request->url);
    }
}

// Function to simulate logging
void log_request(const char *message) {
    printf("%s\n", message);
}

int main() {
    HttpRequest *request = create_http_request("https://example.com/api", "GET", 3);
    add_header(request, "Content-Type: application/json");
    add_header(request, "Authorization: Bearer token");
    add_header(request, "User-Agent: MyClient/1.0");
    set_body_data(request, "{\"key\":\"value\"}");

    process_http_request(request, 2, log_request);

    delete_http_request(request);
    return 0;
}
