#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <cstring>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
    int CRC_INDICATION_REL8_TAG;
};

enum ProtocolVersion { LTE, NR };

class NFAPICRCGenerator {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> pool;
    std::mutex poolMutex;
    std::condition_variable notFull;
    int maxPoolSize;

public:
    NFAPICRCGenerator(int initialSize = 100, int maxSize = 10000) : maxPoolSize(maxSize) {
        for (int i = 0; i < initialSize; ++i) {
            pool.push_back(new NFAPI_CRC_INDICATION_PDU_T);
        }
    }

    ~NFAPICRCGenerator() {
        for (auto& pdu : pool) {
            delete pdu;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* getNFAPI_CRC_INDICATION_PDU(ProtocolVersion version) {
        std::unique_lock<std::mutex> lock(poolMutex);
        notFull.wait(lock, [this] { return pool.size() < maxPoolSize; });
        if (pool.empty()) {
            NFAPI_CRC_INDICATION_PDU_T* newPdu = new NFAPI_CRC_INDICATION_PDU_T;
            pool.push_back(newPdu);
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = pool.back();
        pool.pop_back();
        // Initialize fields based on version
        if (version == LTE) {
            pdu->RX_UE_INFORMATION_TAG = 10; // Example value for LTE
        } else {
            pdu->RX_UE_INFORMATION_TAG = 20; // Example value for NR
        }
        pdu->RNTI = std::rand() % 65536;
        pdu->CRCFLAG = (std::rand() % 2) == 0 ? true : false;
        pdu->CRC_INDICATION_REL8_TAG = std::rand() % 1000; // Example value
        return pdu;
    }

    void releaseNFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::lock_guard<std::mutex> lock(poolMutex);
        pool.push_back(pdu);
        notFull.notify_one();
    }
};

int main() {
    NFAPICRCGenerator generator;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = generator.getNFAPI_CRC_INDICATION_PDU(LTE);
    std::cout << "Generated PDU: RX_UE_INFORMATION_TAG=" << pdu->RX_UE_INFORMATION_TAG << ", RNTI=" << pdu->RNTI 
              << ", CRCFLAG=" << (pdu->CRCFLAG ? "true" : "false") << ", CRC_INDICATION_REL8_TAG=" << pdu->CRC_INDICATION_REL8_TAG << std::endl;

    generator.releaseNFAPI_CRC_INDICATION_PDU(pdu);

    return 0;
}
