    {
        if (currentDepth > maxDepth) return;

        try
        {
            var files = Directory.GetFiles(path);
            foreach (var file in files)
            {
                if (File.Exists(file) && !file.StartsWith(".") && !file.EndsWith(".lnk"))
                {
                    var hash = CalculateMd5Hash(file);
                    hashes[file] = hash;
                }
            }

            var directories = Directory.GetDirectories(path);
            foreach (var directory in directories)
            {
                TraverseDirectory(directory, hashes, currentDepth + 1, maxDepth);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    private static string CalculateMd5Hash(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            var bytes = md5.ComputeHash(File.ReadAllBytes(filePath));
            return BitConverter.ToString(bytes).Replace("-", "").ToLower();
        }
    }
}
