typedef struct nicp_report {
    char traffic_type[20];
    double throughput;
    double latency;
    double packet_loss_rate;
    double error_rate;
} NicpReport;

typedef struct nicp_cache {
    NicpReport *reports;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NicpCache;

NicpCache *create_nicp_cache(int initial_capacity) {
    NicpCache *cache = (NicpCache *)malloc(sizeof(NicpCache));
    cache->reports = (NicpReport *)calloc(initial_capacity, sizeof(NicpReport));
    cache->size = 0;
    cache->capacity = initial_capacity;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void free_nicp_cache(NicpCache *cache) {
    free(cache->reports);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void add_to_cache(NicpCache *cache, NicpReport report) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size >= cache->capacity) {
        cache->capacity *= 2;
        cache->reports = realloc(cache->reports, cache->capacity * sizeof(NicpReport));
    }
    cache->reports[cache->size++] = report;
    pthread_mutex_unlock(&cache->lock);
}

NicpReport get_from_cache(NicpCache *cache, int index) {
    NicpReport report = {0};
    pthread_mutex_lock(&cache->lock);
    if (index >= 0 && index < cache->size) {
        report = cache->reports[index];
    }
    pthread_mutex_unlock(&cache->lock);
    return report;
}

void *report_thread(void *arg) {
    NicpCache *cache = (NicpCache *)arg;
    NicpReport report = {0};
    // Simulate report generation based on network conditions
    snprintf(report.traffic_type, sizeof(report.traffic_type), "VoLTE");
    report.throughput = 150.0; // in Mbps
    report.latency = 20.0;    // in ms
    report.packet_loss_rate = 0.01;
    report.error_rate = 0.001;

    add_to_cache(cache, report);
    return NULL;
}

int main() {
    NicpCache *cache = create_nicp_cache(10);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, report_thread, cache);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    NicpReport report = get_from_cache(cache, 2);
    printf("Traffic Type: %s\n", report.traffic_type);
    printf("Throughput: %.2f Mbps\n", report.throughput);
    printf("Latency: %.2f ms\n", report.latency);
    printf("Packet Loss Rate: %.2f%%\n", report.packet_loss_rate * 100);
    printf("Error Rate: %.2f%%\n", report.error_rate * 100);

    free_nicp_cache(cache);
    return 0;
}
