class DistributedCache {
public:
    using CacheKey = std::string;
    using CacheValue = std::string;

    DistributedCache(size_t capacity, const std::string& metadataServiceUrl)
        : capacity_(capacity), metadataServiceUrl_(metadataServiceUrl) {}

    void set(const CacheKey& key, const CacheValue& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = value;
    }

    CacheValue get(const CacheKey& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        }
        return "";
    }

private:
    size_t capacity_;
    std::string metadataServiceUrl_;
    std::unordered_map<CacheKey, CacheValue> cache_;
    std::mutex mutex_;
};

int main() {
    DistributedCache cache(1000, "http://metadata-service.com");
    cache.set("key1", "value1");
    std::cout << "Value for key1: " << cache.get("key1") << std::endl;
    return 0;
}
