import hashlib
from datetime import datetime

def process_log_files(directory, chunk_size=1024*1024):
    def calculate_file_hash(file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()

    def compare_metadata(file_path, initial_meta, current_meta):
        return all(initial_meta[key] == current_meta[key] for key in ['size', 'mtime', 'ctime'])

    def log_file_status(log_file, file_path, lines_processed, error=None):
        with open(log_file, 'a') as f:
            timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            status = 'Error' if error else 'Processed'
            f.write(f'{timestamp} - {file_path} - Lines Processed: {lines_processed}, Status: {status}\n')

    def extract_metrics(file_path):
        # Implement metric extraction logic here
        pass

    summary_report = []
    for file_name in os.listdir(directory):
        if file_name.endswith('.log'):
            file_path = os.path.join(directory, file_name)
            initial_meta = {
                'size': os.path.getsize(file_path),
                'mtime': os.path.getmtime(file_path),
                'ctime': os.path.getctime(file_path)
            }
            initial_hash = calculate_file_hash(file_path)

            try:
                current_meta = {
                    'size': os.path.getsize(file_path),
                    'mtime': os.path.getmtime(file_path),
                    'ctime': os.path.getctime(file_path)
                }
                current_hash = calculate_file_hash(file_path)

                if compare_metadata(file_path, initial_meta, current_meta):
                    metrics = extract_metrics(file_path)
                    summary_report.append((file_name, metrics))
                    log_file_status('processing_log.txt', file_path, len(metrics['lines']), error=None)
                else:
                    summary_report.append((file_name, None))
                    log_file_status('processing_log.txt', file_path, 0, error='File integrity check failed')
            except Exception as e:
                summary_report.append((file_name, None))
                log_file_status('processing_log.txt', file_path, 0, error=str(e))

    return summary_report
