#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_QUEUE_LENGTH 1000

typedef struct QUEUE_ITEM_T {
    FILE_HANDLE file_handle;
    OFFSET offset;
    BYTES_TO_READ bytes_to_read;
    struct QUEUE_ITEM_T *next;
} QUEUE_ITEM_T;

typedef struct {
    QUEUE_ITEM_T *head;
    QUEUE_ITEM_T *tail;
    int length;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} QUEUE_T;

QUEUE_T* queue_init() {
    QUEUE_T *queue = (QUEUE_T*)malloc(sizeof(QUEUE_T));
    if (queue == NULL) {
        return NULL;
    }
    queue->head = NULL;
    queue->tail = NULL;
    queue->length = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    return queue;
}

void queue_destroy(QUEUE_T *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head != NULL) {
        QUEUE_ITEM_T *temp = queue->head;
        queue->head = queue->head->next;
        free(temp);
    }
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

void queue_enqueue(QUEUE_T *queue, FILE_HANDLE file_handle, OFFSET offset, BYTES_TO_READ bytes_to_read) {
    pthread_mutex_lock(&queue->lock);
    while (queue->length == MAX_QUEUE_LENGTH) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    QUEUE_ITEM_T *new_item = (QUEUE_ITEM_T*)malloc(sizeof(QUEUE_ITEM_T));
    if (new_item != NULL) {
        new_item->file_handle = file_handle;
        new_item->offset = offset;
        new_item->bytes_to_read = bytes_to_read;
        new_item->next = NULL;
        if (queue->tail == NULL) {
            queue->head = new_item;
        } else {
            queue->tail->next = new_item;
        }
        queue->tail = new_item;
        queue->length++;
        pthread_cond_signal(&queue->not_empty);
    }
    pthread_mutex_unlock(&queue->lock);
}

QUEUE_ITEM_T* queue_dequeue(QUEUE_T *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head == NULL) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    QUEUE_ITEM_T *item = queue->head;
    queue->head = queue->head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    queue->length--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return item;
}

void* queue_compact(void *arg) {
