        structs[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        structs[i].RNTI = rand() % 10000 + 1;

        if (protocol_version == 8) {
            structs[i].CRC_INDICATION_REL8_TAG = rand() % 100 + 1;
        } else if (protocol_version == 15) {
            // Handle NR protocol specific fields
            structs[i].CRC_INDICATION_REL8_TAG = rand() % 256 + 1;
        }

        structs[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return structs;
}

