PduArray* initializeNfapiPduArray(size_t initialCapacity) {
    PduArray *pduArray = (PduArray*)malloc(sizeof(PduArray));
    if (!pduArray) {
        perror("Failed to allocate memory for PduArray");
        return NULL;
    }

    pduArray->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray->array) {
        free(pduArray);
        perror("Failed to allocate memory for PDU array");
        return NULL;
    }

    pduArray->size = 0;
    pduArray->capacity = initialCapacity;
    pthread_mutex_init(&pduArray->lock, NULL);

    return pduArray;
}

void destroyNfapiPduArray(PduArray *pduArray) {
    if (pduArray) {
        free(pduArray->array);
        pthread_mutex_destroy(&pduArray->lock);
        free(pduArray);
    }
}

int addPacketToPduArray(PduArray *pduArray, NFAPI_CRC_INDICATION_PDU_T packet) {
    pthread_mutex_lock(&pduArray->lock);

    if (pduArray->size >= pduArray->capacity) {
        size_t newCapacity = pduArray->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pduArray->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            pthread_mutex_unlock(&pduArray->lock);
            perror("Failed to reallocate memory for PDU array");
            return -1;
        }
        pduArray->array = newArray;
        pduArray->capacity = newCapacity;
    }

    pduArray->array[pduArray->size++] = packet;

    pthread_mutex_unlock(&pduArray->lock);
    return 0;
}

void resetNfapiPduArray(PduArray *pduArray) {
