#include <openssl/sha.h>
#include <jpeglib.h>
#include <exiv2/exiv2.hpp>

typedef struct {
    int width;
    int height;
    char color_space[10];
    float compression_ratio;
    size_t metadata_size;
    Exiv2::Metadata *metadata;
} ImageInfo;

ImageInfo* parseJPEG(const char *filename, const char *exifOption) {
    ImageInfo *info = (ImageInfo *)malloc(sizeof(ImageInfo));
    if (!info) return NULL;

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile;

    // Initialize JPEG decompression object
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    // Open the file and read the JPEG data
    if ((infile = fopen(filename, "rb")) == NULL) {
        free(info);
        return NULL;
    }
    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    // Extract image information
    info->width = cinfo.output_width;
    info->height = cinfo.output_height;
    snprintf(info->color_space, 10, "%s", cinfo.out_color_space == JCS_RGB ? "RGB" : "CMYK");
    info->compression_ratio = (float)cinfo.comp_info[0].h_samp_factor * cinfo.comp_info[0].v_samp_factor;

    // Extract metadata
    Exiv2::Image::AutoPtr image = Exiv2::ImageFactory::open(filename);
    if (!image.get()) {
        free(info);
        fclose(infile);
        return NULL;
    }
    image->readMetadata();
    info->metadata_size = image->exifData().size();
    info->metadata = new Exiv2::Metadata(*image);

    // Manipulate metadata based on command line option
    if (exifOption) {
        Exiv2::ExifData &exifData = info->metadata->exifData();
        exifData["Exif.Image.Artist"] = Exiv2::Value::AutoPtr(new Exiv2::AsciiValue(exifOption));
        info->metadata->write();
    }

    // Clean up
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return info;
}

void freeImageInfo(ImageInfo *info) {
    if (info->metadata) {
        delete info->metadata;
    }
    free(info);
}
