typedef struct {
    pthread_mutex_t lock;
    NFAPI_SCH_MSG_T* head;
    NFAPI_SCH_MSG_T* tail;
    int length;
} DYNAMIC_LIST;

void init_list(DYNAMIC_LIST* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->length = 0;
}

void insert_element(DYNAMIC_LIST* list, NFAPI_SCH_MSG_T* new_element) {
    pthread_mutex_lock(&list->lock);
    if (list->length < MAX_QUEUE_LENGTH) {
        if (list->head == NULL) {
            list->head = new_element;
            list->tail = new_element;
        } else {
            list->tail->next = new_element;
            new_element->prev = list->tail;
            list->tail = new_element;
        }
        list->length++;
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_SCH_MSG_T* remove_element(DYNAMIC_LIST* list) {
    NFAPI_SCH_MSG_T* removed_element = NULL;
    pthread_mutex_lock(&list->lock);
    if (list->head != NULL) {
        removed_element = list->head;
        if (list->length == 1) {
            list->head = NULL;
            list->tail = NULL;
        } else {
            list->head = list->head->next;
            list->head->prev = NULL;
        }
        list->length--;
    }
    pthread_mutex_unlock(&list->lock);
    return removed_element;
}

