void initializeCipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    unsigned char iv[16];
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        fprintf(stderr, "Failed to generate IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    unsigned char key[32];
    int derived_key_len;
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, 10000, EVP_sha256(), sizeof(key), key, &derived_key_len)) {
        fprintf(stderr, "Failed to derive encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (derived_key_len != 32) {
        fprintf(stderr, "Derived key length is not correct\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

