// Function to dynamically manage a cache of HTTP requests and responses
HTTP_MESSAGE_PDU_T* manage_cache(HTTP_MESSAGE_PDU_T **cache, int *cache_size, int max_size, HTTP_MESSAGE_PDU_T *new_entry) {
    // Implement LRU eviction policy for managing cache capacity
    if (*cache_size >= max_size) {
        // Evict the least recently used entry (not shown here)
        free(cache[0]);
        memmove(cache, cache + 1, sizeof(HTTP_MESSAGE_PDU_T*) * (*cache_size - 1));
        (*cache_size)--;
    }

    // Allocate memory for new entry and add it to the cache
    HTTP_MESSAGE_PDU_T *new_cache_entry = (HTTP_MESSAGE_PDU_T *)malloc(sizeof(HTTP_MESSAGE_PDU_T));
    if (new_cache_entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    memcpy(new_cache_entry, new_entry, sizeof(HTTP_MESSAGE_PDU_T));

    // Add the new entry to the cache
    HTTP_MESSAGE_PDU_T **new_cache = realloc(cache, sizeof(HTTP_MESSAGE_PDU_T*) * (*cache_size + 1));
    if (new_cache == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(new_cache_entry);
        return NULL;
    }
    new_cache[*cache_size] = new_cache_entry;
    (*cache_size)++;
    cache = new_cache;

    return cache;
}

// Function to handle memory deallocation and freeing resources
void free_cache(HTTP_MESSAGE_PDU_T **cache, int *cache_size) {
    for (int i = 0; i < *cache_size; i++) {
        free(cache[i]);
    }
    free(cache);
    *cache_size = 0;
}

