    // Process the request and create a response
    HTTP_MESSAGE_PDU_T *response = (HTTP_MESSAGE_PDU_T *)malloc(sizeof(HTTP_MESSAGE_PDU_T));
    if (response == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    // Populate response fields based on the request
    memcpy(response, request, sizeof(HTTP_MESSAGE_PDU_T));

