typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    char* ERROR_DETAILS;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UserSession {
    int sessionID;
    char hashedCredentials[32]; // Assuming SHA-256 hash
    time_t lastActiveTimestamp;
    char ipAddress[16];
    char browserType[50];
    char deviceInfo[100];
} UserSession;

#define N 1000
#define M (N * sizeof(UserSession) + 10 * NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    UserSession* sessions;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} SessionCache;

void initializeCache(SessionCache** cache, int initialCapacity) {
    *cache = (SessionCache*)malloc(sizeof(SessionCache));
    (*cache)->sessions = (UserSession*)calloc(initialCapacity, sizeof(UserSession));
    (*cache)->size = 0;
    (*cache)->capacity = initialCapacity;
    pthread_mutex_init(&(*cache)->mutex, NULL);
}

void resizeCache(SessionCache* cache) {
    int newCapacity = cache->capacity * 2;
    UserSession* newSessions = (UserSession*)realloc(cache->sessions, newCapacity * sizeof(UserSession));
    if (newSessions == NULL) {
        printf("Memory reallocation failed.\n");
        return;
    }
    cache->sessions = newSessions;
    cache->capacity = newCapacity;
}

void addSession(SessionCache* cache, UserSession session) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size >= cache->capacity) {
        resizeCache(cache);
    }
    cache->sessions[cache->size++] = session;
    pthread_mutex_unlock(&cache->mutex);
}

void clearCache(SessionCache* cache) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        free(cache->sessions[i].ERROR_DETAILS);
    }
    free(cache->sessions);
    cache->sessions = NULL;
    cache->size = 0;
    cache->capacity = 0;
    pthread_mutex_unlock(&cache->mutex);
}

void destroyCache(SessionCache* cache) {
    clearCache(cache);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}
```

