class ResourceExecutor {

    public static void executeCommand(String command, Path targetDir) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Future<String> stdoutFuture = executor.submit(() -> readStream(process.getInputStream()));
        Future<String> stderrFuture = executor.submit(() -> readStream(process.getErrorStream()));

        int exitCode = process.waitFor();
        String stdout = stdoutFuture.get();
        String stderr = stderrFuture.get();

        System.out.println("Execution time: " + (System.currentTimeMillis() - startTime) + "ms");
        if (!stderr.isEmpty()) {
            throw new IOException("Error: " + stderr);
        }

        executor.shutdownNow();
    }

    private static String readStream(InputStream inputStream) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }
        return output.toString();
    }
}

class CacheManager {

    private static final int MAX_RETRIES = 3;
    private ConcurrentHashMap<String, CachedResponse> cache = new ConcurrentHashMap<>();

    public Response getCachedResource(String key) throws IOException {
        CachedResponse cachedResponse = cache.get(key);
        if (cachedResponse != null && System.currentTimeMillis() - cachedResponse.timestamp < cachedResponse.expirationTime) {
            return cachedResponse.response;
        }
        return null;
    }

    public void putCachedResource(String key, Response response, long expirationTime) {
        cache.put(key, new CachedResponse(response, System.currentTimeMillis(), expirationTime));
    }

    private static class CachedResponse {
        final Response response;
        final long timestamp;
        final long expirationTime;

        CachedResponse(Response response, long timestamp, long expirationTime) {
            this.response = response;
            this.timestamp = timestamp;
            this.expirationTime = expirationTime;
        }
    }
}

class NFAPI_CRC_INDICATION_PDU_T {

    private static final int MAX_PDUS = 100;

    public static void allocateAndPopulatePDUs() {
        NFAPI_CRC_INDICATION_PDU_T[] pdus = new NFAPI_CRC_INDICATION_PDU_T[MAX_PDUS];
        Random random = new Random();
        for (int i = 0; i < MAX_PDUS; i++) {
            pdus[i] = new NFAPI_CRC_INDICATION_PDU_T();
            pdus[i].RX_UE_INFORMATION_TAG = "tag" + i;
            pdus[i].RNTI = random.nextInt(1024);
            pdus[i].CRC_INDICATION_REL8_TAG = "crcTag" + i;
            pdus[i].CRCFLAG = random.nextBoolean();
