import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class ResourceService {
    private static final int MAX_FILES = 10;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long CACHE_EXPIRATION_SECONDS = 60;
    private final File storageDir;
    private final Map<String, Long> fileTimestamps;
    private final ExecutorService executor;

    public ResourceService(String storagePath) {
        this.storageDir = new File(storagePath);
        this.fileTimestamps = Collections.synchronizedMap(new HashMap<>());
        this.executor = Executors.newFixedThreadPool(10);
        initStorage();
    }

    private void initStorage() {
        if (!storageDir.exists()) {
            storageDir.mkdirs();
        }
        fileTimestamps.clear();
        for (File file : storageDir.listFiles()) {
            if (file.isFile()) {
                fileTimestamps.put(file.getName(), file.lastModified());
            }
        }
    }

    public synchronized void put(String resourcePath, InputStream inputStream) throws IOException {
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            try {
                ensureSpace();
                File file = new File(storageDir, resourcePath);
                Files.copy(inputStream, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
                fileTimestamps.put(resourcePath, System.currentTimeMillis());
                return;
            } catch (IOException e) {
                if (attempt == RETRY_ATTEMPTS - 1) throw e;
                Thread.sleep(100 * attempt); // Exponential backoff
            }
        }
    }

    public synchronized void delete(String resourcePath) throws IOException {
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            try {
                File file = new File(storageDir, resourcePath);
                if (!file.delete()) {
                    throw new IOException("Failed to delete " + resourcePath);
                }
                fileTimestamps.remove(resourcePath);
                return;
            } catch (IOException e) {
                if (attempt == RETRY_ATTEMPTS - 1) throw e;
                Thread.sleep(100 * attempt); // Exponential backoff
            }
        }
    }

    private void ensureSpace() throws IOException {
        long oldestTimestamp = Long.MAX_VALUE;
        String oldestFile = null;
        for (Map.Entry<String, Long> entry : fileTimestamps.entrySet()) {
            if (entry.getValue() < oldestTimestamp) {
                oldestTimestamp = entry.getValue();
                oldestFile = entry.getKey();
            }
        }
        if (fileTimestamps.size() >= MAX_FILES && oldestFile != null) {
            delete(oldestFile);
        }
    }

    public HttpResponse httpRequestWithCaching(String url, String method, byte[] body) throws IOException {
        // Implement caching logic based on timestamp-based expiration policies
        // Validate cached responses and handle concurrent access safely
        return new HttpResponse();
    }

