        // Log detailed information about each operation
        NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
        pdu.RX_UE_INFORMATION_TAG = 1;
        pdu.RNTI = 2;
        pdu.CRC_INDICATION_REL8_TAG = success;
        System.out.println("Operation: " + operationType + ", Resource: " + resourcePath + ", Success: " + success);
