typedef struct {
    int tenant_id;
    char protocol[20];
    char traffic_type[20];
    float throughput;
    float latency;
    float packet_loss_rate;
    float error_rate;
} NicpReport;

NicpReport* reports[MAX_TENANTS];
pthread_mutex_t report_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_report(int tenant_id, const char* protocol, const char* traffic_type) {
    pthread_mutex_lock(&report_lock);
    NicpReport* new_report = (NicpReport*)malloc(sizeof(NicpReport));
    if (new_report == NULL) {
        perror("Failed to allocate memory for report");
        return;
    }

    new_report->tenant_id = tenant_id;
    strcpy(new_report->protocol, protocol);
    strcpy(new_report->traffic_type, traffic_type);

    // Dynamically select metrics based on protocol and traffic type
    if (strcmp(protocol, "LTE") == 0 && strcmp(traffic_type, "VoLTE") == 0) {
        new_report->throughput = 150.0;
        new_report->latency = 20.0;
        new_report->packet_loss_rate = 0.1;
        new_report->error_rate = 0.01;
    } else if (strcmp(protocol, "5G") == 0 && strcmp(traffic_type, "Video") == 0) {
        new_report->throughput = 1000.0;
        new_report->latency = 5.0;
        new_report->packet_loss_rate = 0.05;
        new_report->error_rate = 0.005;
    } else {
        new_report->throughput = 200.0;
        new_report->latency = 10.0;
        new_report->packet_loss_rate = 0.03;
        new_report->error_rate = 0.003;
    }

    reports[tenant_id] = new_report;
    pthread_mutex_unlock(&report_lock);
}

void* report_generator(void* tenant_id_ptr) {
    int tenant_id = *(int*)tenant_id_ptr;
    generate_report(tenant_id, "LTE", "VoLTE");
    return NULL;
}

int main() {
    pthread_t threads[MAX_TENANTS];
    int tenant_ids[MAX_TENANTS];

    for (int i = 0; i < MAX_TENANTS; i++) {
        tenant_ids[i] = i + 1;
        if (pthread_create(&threads[i], NULL, report_generator, &tenant_ids[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_TENANTS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (reports[i] != NULL) {
            free(reports[i]);
        }
    }

    return EXIT_SUCCESS;
}
