#define MAX_NODES 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NodeInfo;

typedef struct {
    NodeInfo *nodes;
    size_t size;
    size_t capacity;
} NodePool;

NodePool node_pool;

void init_node_pool(size_t initial_capacity) {
    node_pool.nodes = (NodeInfo *)malloc(initial_capacity * sizeof(NodeInfo));
    if (node_pool.nodes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node_pool.size = 0;
    node_pool.capacity = initial_capacity;
}

void free_node_pool() {
    free(node_pool.nodes);
}

int add_node(int RX_UE_INFORMATION_TAG, int RNTI) {
    if (node_pool.size >= node_pool.capacity) {
        size_t new_capacity = node_pool.capacity * 2;
        NodeInfo *new_nodes = (NodeInfo *)realloc(node_pool.nodes, new_capacity * sizeof(NodeInfo));
        if (new_nodes == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        node_pool.nodes = new_nodes;
        node_pool.capacity = new_capacity;
    }

    NodeInfo new_node = {RX_UE_INFORMATION_TAG, RNTI};
    node_pool.nodes[node_pool.size++] = new_node;

    return 0;
}

int remove_node(int RX_UE_INFORMATION_TAG, int RNTI) {
    for (size_t i = 0; i < node_pool.size; ++i) {
        if (node_pool.nodes[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            node_pool.nodes[i].RNTI == RNTI) {
            for (size_t j = i; j < node_pool.size - 1; ++j) {
                node_pool.nodes[j] = node_pool.nodes[j + 1];
            }
            node_pool.size--;
            return 0;
        }
    }

    fprintf(stderr, "Node not found\n");
    return -1;
}

void serialize_node_pool(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&node_pool.size, sizeof(size_t), 1, file);
    fwrite(node_pool.nodes, sizeof(NodeInfo), node_pool.size, file);

    fclose(file);
}

void deserialize_node_pool(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    if (size > node_pool.capacity) {
        free_node_pool();
        init_node_pool(size);
    }

    fread(node_pool.nodes, sizeof(NodeInfo), size, file);

    fclose(file);
}

int main() {
    init_node_pool(MAX_NODES);

    add_node(12345, 67890);
    add_node(54321, 98765);

    serialize_node_pool("nodes.dat");

    free_node_pool();
    init_node_pool(MAX_NODES);

    deserialize_node_pool("nodes.dat");

    for (size_t i = 0; i < node_pool.size; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d\n", node_pool.nodes[i].RX_UE_INFORMATION_TAG, node_pool.nodes[i].RNTI);
    }

    free_node_pool();

    return 0;
}
