typedef struct {
    time_t timestamp;
    char eventType[50];
    int id;
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} EventNode;

typedef struct {
    EventNode* head;
    size_t count;
} EventList;

void initEventList(EventList* list) {
    list->head = NULL;
    list->count = 0;
}

void addEvent(EventList* list, NetworkEvent event) {
    EventNode* newNode = (EventNode*)malloc(sizeof(EventNode));
    newNode->event = event;
    newNode->next = list->head;
    list->head = newNode;
    ++list->count;
}

void removeOldEvents(EventList* list, time_t threshold) {
    EventNode* current = list->head;
    EventNode* previous = NULL;
    while (current != NULL) {
        if (difftime(current->event.timestamp, threshold) > 0) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            --list->count;
        } else {
            previous = current;
        }
        current = current->next;
    }
}

size_t getEventsInWindow(EventList* list, time_t start, time_t end) {
    EventNode* current = list->head;
    size_t count = 0;
    while (current != NULL) {
        if (current->event.timestamp >= start && current->event.timestamp <= end) {
            ++count;
        }
        current = current->next;
    }
    return count;
}

void calculateMD5(const char* input, unsigned char outputBuffer[16]) {
