import hashlib
from typing import List, Tuple

class DistributedFileStorage:
    def __init__(self, data_centers: List[str]):
        self.data_centers = data_centers
        self.storage_nodes = {}
        self.replication_factor = 3
        self.memory_pool = CustomMemoryPool()

    def add_data_center(self, data_center: str):
        if data_center not in self.data_centers:
            self.data_centers.append(data_center)
            self.storage_nodes[data_center] = []

    def remove_data_center(self, data_center: str):
        if data_center in self.data_centers:
            del self.data_centers[data_center]
            del self.storage_nodes[data_center]

    def store_data(self, data: bytes) -> Tuple[str, List[str]]:
        hash_value = hashlib.sha256(data).hexdigest()
        nodes = []
        for i in range(self.replication_factor):
            selected_center = self.data_centers[i % len(self.data_centers)]
            node = f"Node-{hash_value}-{i}"
            if node not in self.storage_nodes[selected_center]:
                self.storage_nodes[selected_center].append(node)
                nodes.append(node)
                self.memory_pool.allocate_memory(len(data))
        return hash_value, nodes

    def retrieve_data(self, hash_value: str) -> bytes:
        data = b''
        for data_center in self.data_centers:
            if any(hash_value in node for node in self.storage_nodes[data_center]):
                node = [node for node in self.storage_nodes[data_center] if hash_value in node][0]
                data_length = self.memory_pool.get_allocated_memory(node)
                data += self.memory_pool.retrieve_memory(data_length, node)
        return data

class CustomMemoryPool:
    def __init__(self):
        self.pool = {}
        self.locked = {}

    def allocate_memory(self, size: int) -> None:
        if size not in self.pool:
            self.pool[size] = [0] * 1000
            self.locked[size] = [False] * 1000

    def retrieve_memory(self, size: int, node_id: str) -> bytes:
        for i in range(len(self.pool[size])):
            if not self.locked[size][i]:
                self.locked[size][i] = True
                return bytearray(self.pool[size][i:i + size])
        raise MemoryError("No available memory")

    def get_allocated_memory(self, node_id: str) -> int:
        for size in self.pool:
            if any(node_id in node for node in self.storage_nodes[data_center]):
                for i in range(len(self.pool[size])):
                    if not self.locked[size][i]:
                        return size
        raise ValueError("Node not found")

    def free_memory(self, node_id: str) -> None:
        for size in self.pool:
            if any(node_id in node for node in self.storage_nodes[data_center]):
                for i in range(len(self.pool[size])):
                    if not self.locked[size][i]:
                        self.locked[size][i] = False
                        break
```
