void processCSV(char *inputFile, char *outputFile, char *filters, int maxTransactions, int maxLength, double minAmount) {
    FILE *in = fopen(inputFile, "r");
    if (!in) {
        perror("Error opening input file");
        return;
    }

    FILE *out = fopen(outputFile, "w");
    if (!out) {
        perror("Error opening output file");
        fclose(in);
        return;
    }

    // Read and process transactions
    Transaction transactions[maxTransactions];
    int transactionCount = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), in) && transactionCount < maxTransactions) {
        Transaction t;
        sscanf(line, "%[^,],%[^,],%lf", t.id, t.date, &t.amount);

        // Apply filters
        if (!strstr(filters, "id") || strlen(t.id) <= maxLength)
            if (!strstr(filters, "date"))
                if (t.amount >= minAmount) {
                    transactions[transactionCount++] = t;
                }
    }

    fclose(in);

    // Sort transactions by date
    qsort(transactions, transactionCount, sizeof(Transaction), compareTransactions);

    // Write report to output file
    fprintf(out, "Summary:\n");
    fprintf(out, "Total Transactions: %d\n", transactionCount);
    fprintf(out, "Average Transaction Amount: %.2f\n", (double)sumAmounts / transactionCount);

    for (int i = 0; i < transactionCount; i++) {
        fprintf(out, "%s,%s,%.2f\n", transactions[i].id, transactions[i].date, transactions[i].amount);
    }

    fclose(out);
}
