    float throughput;
    int buffering_time;
    int bitrate_quality;
} MSA_Status_Report;

typedef struct Report_Node {
    MSA_Status_Report report;
    struct Report_Node* next;
} Report_Node;

typedef struct {
    Report_Node* head;
    pthread_mutex_t lock;
} MSA_Report_List;

MSA_Report_List* create_report_list() {
    MSA_Report_List* list = (MSA_Report_List*)malloc(sizeof(MSA_Report_List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_report(MSA_Report_List* list, MSA_Status_Report report) {
    pthread_mutex_lock(&list->lock);
    Report_Node* new_node = (Report_Node*)malloc(sizeof(Report_Node));
    new_node->report = report;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

MSA_Status_Report get_latest_report(MSA_Report_List* list) {
    pthread_mutex_lock(&list->lock);
    MSA_Status_Report latest_report = list->head->report;
    pthread_mutex_unlock(&list->lock);
    return latest_report;
}

void destroy_report_list(MSA_Report_List* list) {
    while (list->head != NULL) {
        Report_Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
