#define MAX_EVENTS 10000

typedef struct {
    time_t timestamp;
    int eventType;
    int id;
} Event;

typedef struct {
    Event* events;
    size_t count;
    size_t capacity;
} EventList;

void initEventList(EventList* list) {
    list->events = (Event*)malloc(MAX_EVENTS * sizeof(Event));
    if (!list->events) {
        fprintf(stderr, "Failed to allocate memory for event list\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_EVENTS;
}

void addEvent(EventList* list, time_t timestamp, int eventType, int id) {
    if (list->count >= list->capacity) {
        fprintf(stderr, "Event list is full\n");
        return;
    }
    list->events[list->count].timestamp = timestamp;
    list->events[list->count].eventType = eventType;
    list->events[list->count].id = id;
    list->count++;
}

void removeOldEvents(EventList* list, time_t threshold) {
    for (size_t i = 0; i < list->count;) {
        if (list->events[i].timestamp < threshold) {
            memmove(&list->events[i], &list->events[i + 1], (list->count - i - 1) * sizeof(Event));
            list->count--;
        } else {
            i++;
        }
    }
}

size_t getEventsInWindow(EventList* list, time_t start, time_t end) {
    size_t count = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (list->events[i].timestamp >= start && list->events[i].timestamp <= end) {
            count++;
        }
    }
    return count;
}

void logEvents(EventList* list, const char* serviceUrl) {
    // Simulate logging to an external service
    printf("Logging %zu events to %s\n", list->count, serviceUrl);
}

int main() {
    EventList eventList;
    initEventList(&eventList);

    time_t now = time(NULL);
    addEvent(&eventList, now, 1, 1001);
    addEvent(&eventList, now - 60, 2, 1002);

    removeOldEvents(&eventList, now - 30);
    printf("Events after removal: %zu\n", getEventsInWindow(&eventList, now - 30, now));

    logEvents(&eventList, "http://example.com/log");

    free(eventList.events);
    return 0;
}
