import java.io.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.logging.*;

public class SerializationHandler {

    private static final Logger logger = Logger.getLogger(SerializationHandler.class.getName());

    public Object deserialize(byte[] byteArray, String password) throws RuntimeException {
        try {
            byte[] ivBytes = new byte[16];
            System.arraycopy(byteArray, 0, ivBytes, 0, 16);
            IvParameterSpec iv = new IvParameterSpec(ivBytes);

            SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
            KeySpec spec = new PBEKeySpec(password.toCharArray(), ivBytes, 10000, 32 * 8);
            SecretKey secretKey = factory.generateSecret(spec);
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);

            byte[] encryptedData = new byte[byteArray.length - 16];
            System.arraycopy(byteArray, 16, encryptedData, 0, encryptedData.length);
            byte[] decryptedData = cipher.doFinal(encryptedData);
            ByteArrayInputStream bis = new ByteArrayInputStream(decryptedData);
            ObjectInputStream ois = new ObjectInputStream(bis);
            return ois.readObject();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Deserialization failed", e);
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }

    public void cleanup(Cipher cipher) {
        try {
            if (cipher != null) {
                cipher = null;
                System.gc();
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error during cleanup", e);
        }
    }

    // Additional methods for encryption and custom class loading can be added here
}
