void initializeEncryptionCipher(const char* password, EVP_CIPHER_CTX** ctx) {
    EVP_CIPHER_CTX* cipherCtx = EVP_CIPHER_CTX_new();
    if (!cipherCtx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    unsigned char key[32];
    unsigned char iv[16];
    if (RAND_bytes(iv, 16) != 1) {
        fprintf(stderr, "Failed to generate random IV\n");
        EVP_CIPHER_CTX_free(cipherCtx);
        exit(EXIT_FAILURE);
    }

    int ret = PKCS5_PBKDF2_HMAC(password, strlen(password), iv, 10000, 32, EVP_sha256(), key, NULL);
    if (ret != 1) {
        fprintf(stderr, "Failed to derive encryption key\n");
        EVP_CIPHER_CTX_free(cipherCtx);
        exit(EXIT_FAILURE);
    }

    ret = EVP_EncryptInit_ex(cipherCtx, EVP_aes_128_cbc(), NULL, key, iv);
    if (!ret) {
        fprintf(stderr, "Failed to initialize cipher for encryption\n");
        EVP_CIPHER_CTX_free(cipherCtx);
        exit(EXIT_FAILURE);
    }

    *ctx = cipherCtx;
}

int main() {
    const char* password = "examplePassword";
    EVP_CIPHER_CTX* ctx;

    initializeEncryptionCipher(password, &ctx);

    // Use the cipher context for encryption operations

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
