#include <stdlib.h>
#include <stdint.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure for demonstration purposes
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 1000

// Function to validate CRCFLAG value
int isValidCRCFlag(uint8_t crcflag) {
    // Example valid range: 0-3
    return (crcflag >= 0 && crcflag <= 3);
}

// Thread-safe queue implementation for managing requests
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** data;
    size_t front, rear, capacity;
} Queue;

Queue* createQueue(size_t capacity) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->capacity = capacity;
    queue->front = queue->rear = -1;
    queue->data = (NFAPI_CRC_INDICATION_PDU_T**)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!queue->data) {
        free(queue);
        return NULL;
    }
    return queue;
}

int isFull(Queue* queue) {
    return ((queue->rear + 1) % queue->capacity == queue->front);
}

int isEmpty(Queue* queue) {
    return (queue->front == -1);
}

void enqueue(Queue* queue, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (isFull(queue)) return;
    if (isEmpty(queue)) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % queue->capacity;
    }
    queue->data[queue->rear] = element;
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(Queue* queue) {
    if (isEmpty(queue)) return NULL;
    NFAPI_CRC_INDICATION_PDU_T* data = queue->data[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % queue->capacity;
    }
    return data;
}

// Function to dynamically allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** allocateMemory(size_t numElements, Queue* queue) {
    if (numElements > MAX_ELEMENTS || !queue) return NULL;

    NFAPI_CRC_INDICATION_PDU_T** elements = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!elements) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < numElements; ++i) {
        elements[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!elements[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) free(elements[j]);
            free(elements);
            return NULL;
        }
        elements[i]->RX_UE_INFORMATION_TAG = rand(); // Example initialization
        elements[i]->RNTI = rand();
        uint8_t crcflag = rand() % 4; // Example random CRCFLAG
        while (!isValidCRCFlag(crcflag)) crcflag = rand() % 4;
        elements[i]->CRC_INDICATION_REL8_TAG = crcflag;

        enqueue(queue, elements[i]);
    }

    return elements;
}

// Function to deallocate memory for NFAPI_CRC_INDICATION_PDU_T structures
void freeMemory(NFAPI_CRC_INDICATION_PDU_T** elements, size_t numElements) {
    if (!elements) return;
    for (size_t i = 0; i < numElements; ++i) {
        if (elements[i]) free(elements[i]);
    }
    free(elements);
}

