    uint16_t CHECKSUM;
} VIDEO_FRAME_BUFFER_T;

// Function to asynchronously fetch data from a video encoding pipeline
int fetchVideoData(FRAME *frame) {
    // Simulate asynchronous data fetching
    static int count = 0;
    if (count++ < MAX_FRAMES) {
        frame->header.frame_id = count;
        for (int i = 0; i < FRAME_PAYLOAD_SIZE; i++) {
            frame->Payload[i] = i % 256;
        }
        frame->CHECKSUM = calculateChecksum(frame);
        return 0; // Success
    } else {
        return -1; // No more data available
    }
}

// Function to initialize a single VIDEO_FRAME_BUFFER_T structure
int initFrameBuffer(VIDEO_FRAME_BUFFER_T *buffer) {
    FRAME frame;
    if (fetchVideoData(&frame) != 0) {
        return -1; // Failed to fetch data
    }
    buffer->header = frame.header;
    memcpy(buffer->Payload, frame.Payload, FRAME_PAYLOAD_SIZE);
    buffer->CHECKSUM = calculateChecksum(&frame);
    return 0; // Success
}

// Function to allocate and initialize an array of VIDEO_FRAME_BUFFER_T structures
VIDEO_FRAME_BUFFER_T* allocateFrameBuffers(int F) {
    if (F <= 0) {
        return NULL; // Invalid input value
    }

    VIDEO_FRAME_BUFFER_T *frameBuffers = (VIDEO_FRAME_BUFFER_T *)malloc(F * sizeof(VIDEO_FRAME_BUFFER_T));
    if (!frameBuffers) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < F; i++) {
        if (initFrameBuffer(&frameBuffers[i]) != 0) {
            fprintf(stderr, "Failed to initialize frame buffer %d\n", i);
            // Free previously allocated buffers
            for (int j = 0; j < i; j++) {
                free(frameBuffers[j]);
            }
            free(frameBuffers);
            return NULL;
        }
    }

    return frameBuffers;
}

// Function to verify the integrity of an array of VIDEO_FRAME_BUFFER_T structures
int verifyFrameBufferIntegrity(VIDEO_FRAME_BUFFER_T *frameBuffers, int F) {
    for (int i = 0; i < F; i++) {
        if (calculateChecksum(&frameBuffers[i]) != frameBuffers[i].CHECKSUM) {
            fprintf(stderr, "Integrity check failed for frame buffer %d\n", i);
            return -1;
        }
    }
    return 0; // All frames are valid
}
