['```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AESCBCDecryptor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _iv;
    private readonly bool _usePadding;
    private readonly HMACSHA256 _hmac;

    public AESCBCDecryptor(byte[] encryptionKey, byte[] iv, bool usePadding)
    {
        _encryptionKey = encryptionKey;
        _iv = iv;
        _usePadding = usePadding;
        _hmac = new HMACSHA256(encryptionKey);
    }

    public async Task<byte[]> DecryptAsync(string ciphertextBase64, string signatureBase64)
    {
        byte[] ciphertextBytes = Convert.FromBase64String(ciphertextBase64);
        byte[] signatureBytes = Convert.FromBase64String(signatureBase64);

        if (!VerifyHMAC(ciphertextBytes, signatureBytes))
        {
            throw new InvalidDataException("Invalid HMAC signature.");
        }

        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = _encryptionKey;
                aesAlg.IV = _iv;
                aesAlg.Mode = CipherMode.CBC;
                aesAlg.Padding = _usePadding ? PaddingMode.PKCS7 : PaddingMode.None;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertextBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (MemoryStream msOutput = new MemoryStream())
                        {
                            await csDecrypt.CopyToAsync(msOutput);
                            return msOutput.ToArray();
                        }
                    }
                }
            }
        }
        catch (CryptographicException ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

    private bool VerifyHMAC(byte[] ciphertext, byte[] signature)
    {
        byte[] computedSignature = _hmac.ComputeHash(ciphertext);
        return cryptoCompare(computedSignature, signature) == 0;
    }

    private int cryptoCompare(byte[] a, byte[] b)
    {
        if (a.Length != b.Length) return a.Length.CompareTo(b.Length);

        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i]) return a[i].CompareTo(b[i]);
        }

        return 0;
    }

    private void LogError(string message)
    {
        // Integrate with existing logging framework
        Console.WriteLine("ERROR: " + message);
    }
}
```

