const bufferUtils = (function() {
  const MAX_BUFFER_SIZE = 1024 * 1024; // 1MB

  function isValidBuffer(input) {
    return Buffer.isBuffer(input);
  }

  function calculateTotalSize(buffers) {
    return buffers.reduce((acc, buf) => acc + buf.length, 0);
  }

  function concatBuffers(buffers) {
    try {
      if (!Array.isArray(buffers)) {
        throw new Error('Input must be an array of buffers');
      }
      if (buffers.some(buf => !isValidBuffer(buf))) {
        throw new Error('All elements in the input array must be valid buffers');
      }
      const totalSize = calculateTotalSize(buffers);
      if (totalSize > MAX_BUFFER_SIZE) {
        throw new Error(`Total size of buffers exceeds maximum allowed size: ${MAX_BUFFER_SIZE}`);
      }
      return Buffer.concat(buffers);
    } catch (error) {
      console.error('Error during buffer concatenation:', error.message);
      return null;
    }
  }

  return {
    concatBuffers
  };
})();

// Example usage:
const buf1 = Buffer.from('Hello');
const buf2 = Buffer.from(' ');
const buf3 = Buffer.from('World!');
const result = bufferUtils.concatBuffers([buf1, buf2, buf3]);
console.log(result.toString()); // Output: 'Hello World!'
