#define MAX_TASK_LENGTH 256
#define TASK_LIST_SIZE 1000
#define SAVE_INTERVAL 300
#define FILE_SIZE_LIMIT 10 * 1024 * 1024 // 10 MB

typedef struct {
    char tasks[TASK_LIST_SIZE][MAX_TASK_LENGTH];
    int count;
} TaskList;

TaskList task_list = { .count = 0 };
pthread_mutex_t task_lock;
FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
}

int add_task(const char *task) {
    if (strlen(task) >= MAX_TASK_LENGTH) {
        return -1;
    }
    pthread_mutex_lock(&task_lock);
    if (task_list.count < TASK_LIST_SIZE) {
        strcpy(task_list.tasks[task_list.count], task);
        task_list.count++;
        log_event("Task added");
    } else {
        log_event("Failed to add task: Task list is full");
    }
    pthread_mutex_unlock(&task_lock);
    return 0;
}

void remove_task(int index) {
    if (index < 0 || index >= task_list.count) {
        log_event("Failed to remove task: Invalid index");
        return;
    }
    pthread_mutex_lock(&task_lock);
    for (int i = index; i < task_list.count - 1; i++) {
        strcpy(task_list.tasks[i], task_list.tasks[i + 1]);
    }
    task_list.count--;
    log_event("Task removed");
    pthread_mutex_unlock(&task_lock);
}

void update_task(int index, const char *new_task) {
    if (index < 0 || index >= task_list.count || strlen(new_task) >= MAX_TASK_LENGTH) {
        log_event("Failed to update task: Invalid index or new task too long");
        return;
    }
    pthread_mutex_lock(&task_lock);
    strcpy(task_list.tasks[index], new_task);
    log_event("Task updated");
    pthread_mutex_unlock(&task_lock);
}

void clear_tasks() {
    pthread_mutex_lock(&task_lock);
    memset(task_list.tasks, 0, sizeof(task_list.tasks));
    task_list.count = 0;
    log_event("Task list cleared");
    pthread_mutex_unlock(&task_lock);
}

void save_tasks_to_file(const char *filename) {
    size_t total_size = 0;
    for (int i = 0; i < task_list.count; i++) {
        total_size += strlen(task_list.tasks[i]) + 1;
        if (total_size > FILE_SIZE_LIMIT) {
            log_event("Failed to save tasks: File size limit exceeded");
            return;
        }
    }

    pthread_mutex_lock(&task_lock);
    FILE *file = fopen(filename, "w");
    if (!file) {
        log_event("Failed to open file for saving tasks");
        pthread_mutex_unlock(&task_lock);
        return;
    }
    for (int i = 0; i < task_list.count; i++) {
        fprintf(file, "%s\n", task_list.tasks[i]);
    }
    fclose(file);
    log_event("Tasks saved to file");
    pthread_mutex_unlock(&task_lock);
}

void *save_task_thread(void *arg) {
    while (1) {
        sleep(SAVE_INTERVAL);
        save_tasks_to_file("tasks.txt");
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    log_file = fopen("log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    pthread_mutex_init(&task_lock, NULL);
    pthread_t save_thread;
    pthread_create(&save_thread, NULL, save_task_thread, NULL);

    // Command line argument parsing and task management logic here

    fclose(log_file);
    return 0;
}
