            int payload_size;
            if (distribution_type == 0) { // Normal distribution
                double u1, u2;
                do {
                    u1 = (double)rand() / RAND_MAX;
                    u2 = (double)rand() / RAND_MAX;
                } while (u1 == 0);
                payload_size = (int)((-2 * log(u1)) * cos(2 * M_PI * u2) * std_dev + mean);
            } else if (distribution_type == 1) { // Uniform distribution
                payload_size = (int)(mean + std_dev * ((double)rand() / RAND_MAX * 2 - 1));
            }

            if (payload_size < MIN_PAYLOAD_SIZE) payload_size = MIN_PAYLOAD_SIZE;
            if (payload_size > MAX_PAYLOAD_SIZE) payload_size = MAX_PAYLOAD_SIZE;

            frames[i].pdus[j].header = i * 10 + j; // Example header
            for (int k = 0; k < payload_size; k++) {
                frames[i].pdus[j].payload[k] = 'A' + (k % 26); // Example payload content
            }
        }
    }

    return frames;
}
