        frames[i].pdus = (MAC_RX_PDU_T*)malloc(frames[i].pdu_count * sizeof(MAC_RX_PDU_T));
        for (int j = 0; j < frames[i].pdu_count; j++) {
            frames[i].pdus[j].payload_size = generate_payload_size(max_payload_size, payload_distribution);
            frames[i].pdus[j].payload = (char*)malloc(frames[i].pdus[j].payload_size * sizeof(char));
            // Initialize MAC_HEADER and fill the payload
        }
    }
    return frames;
}

size_t generate_payload_size(int max_payload_size, const char* distribution) {
    if (strcmp(distribution, "normal") == 0) {
        return rand() % (max_payload_size - 100 + 1) + 100; // Normal distribution with a mean around max_payload_size
    } else if (strcmp(distribution, "uniform") == 0) {
        return rand() % (max_payload_size - 50 + 1) + 50; // Uniform distribution within a range
    }
    return 0; // Default case for invalid distribution
}

void free_frames(LTE_PHY_RX_FRAME_T* frames, int num_frames) {
    for (int i = 0; i < num_frames; i++) {
        for (int j = 0; j < frames[i].pdu_count; j++) {
            free(frames[i].pdus[j].payload);
        }
        free(frames[i].pdus);
    }
    free(frames);
}
