TCP_CONNECTION_T* create_tcp_connection(int initial_segment_count) {
    TCP_CONNECTION_T *connection = (TCP_CONNECTION_T*)malloc(sizeof(TCP_CONNECTION_T));
    if (connection == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    connection->packet = initialize_tcp_packet(); // Initialize the packet
    connection->segments = (TCP_SEGMENT_T*)calloc(initial_segment_count, sizeof(TCP_SEGMENT_T));
    if (connection->segments == NULL) {
        fprintf(stderr, "Memory allocation failed for segments\n");
        free(connection);
        return NULL;
    }
    connection->segment_count = initial_segment_count;
    return connection;
}

void add_tcp_segment(TCP_CONNECTION_T *connection, TCP_HEADER header, int payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE || payload_size < MIN_PAYLOAD_SIZE) {
        fprintf(stderr, "Invalid payload size\n");
        return;
    }
    if (connection->segment_count >= MAX_SEGMENTS_PER_CONNECTION) {
        fprintf(stderr, "Segment limit reached\n");
        return;
    }
    TCP_SEGMENT_T *segment = &connection->segments[connection->segment_count];
    segment->header = header;
    // Populate the payload with random data for demonstration
    for (int i = 0; i < payload_size; i++) {
        segment->payload.data[i] = rand() % 256;
    }
    segment->payload.size = payload_size;
    connection->segment_count++;
}

void free_tcp_connection(TCP_CONNECTION_T *connection) {
    if (connection != NULL) {
        free(connection->segments);
        free(connection);
    }
}

int main() {
    srand(time(NULL));
    TCP_CONNECTION_T *connection = create_tcp_connection(10);
    if (connection != NULL) {
        TCP_HEADER header = initialize_tcp_header(); // Initialize the header
        for (int i = 0; i < 5; i++) {
            int payload_size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1) + MIN_PAYLOAD_SIZE;
            add_tcp_segment(connection, header, payload_size);
        }
        free_tcp_connection(connection);
    }
    return 0;
}
