import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_md5(file_path, chunk_size=65536):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            hash_md5.update(chunk)
    return file_path, hash_md5.hexdigest()

def process_files(directory, max_concurrent=4):
    hash_dict = {}
    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = {executor.submit(calculate_md5, os.path.join(directory, f)): f for f in os.listdir(directory)}
