# Python code for calculating MD5 hash of files in a directory

import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

logging.basicConfig(level=logging.INFO)

def calculate_md5(file_path, chunk_size=64*1024):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5.update(chunk)
    return file_path, md5.hexdigest()

def calculate_hashes(directory, max_workers=10):
    files = [os.path.join(root, file) for root, dirs, files in os.walk(directory) if not files]

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_file = {executor.submit(calculate_md5, file): file for file in files}
        results = {}
        for future in as_completed(future_to_file):
            try:
                file_path, md5 = future.result()
                results[file_path] = md5
            except Exception as e:
                logging.error(f'Error processing file {future_to_file[future]}: {e}')
    return results

# Example usage
hashes = calculate_hashes('/path/to/directory')
print(hashes)
