#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <mqtt.h>
#include <tsdb.h>

#define MAX_DEVICES 100
#define MAX_DATA_POINTS 500
#define MIN_BATCH_SIZE 100
#define MAX_BATCH_SIZE 10000
#define MIN_TIME_WINDOW 1
#define MAX_TIME_WINDOW 3600

typedef struct {
    char topic[MAX_TOPIC_LENGTH];
    int batch_size;
    int time_window;
    tsdb_t *db;
} SensorConfig;

typedef struct {
    double sum;
    int count;
    double min;
    double max;
    // Additional fields for standard deviation calculation
} AggregatedData;

AggregatedData aggregated_data[MAX_DEVICES];

void update_aggregation(int device_id, double data) {
    aggregated_data[device_id].sum += data;
    if (aggregated_data[device_id].count == 0 || data < aggregated_data[device_id].min) {
        aggregated_data[device_id].min = data;
    }
    if (data > aggregated_data[device_id].max) {
        aggregated_data[device_id].max = data;
    }
    aggregated_data[device_id].count++;
}

void on_message_received(void *user_data, const char *topic, const void *payload, int payload_len) {
    SensorConfig *config = (SensorConfig *)user_data;
    double data = *((double *)payload);
    int device_id = atoi(topic + strlen(config->topic));

    update_aggregation(device_id, data);

    if (aggregated_data[device_id].count >= config->batch_size) {
        // Persist aggregated data to the time-series database
        tsdb_write(config->db, topic, aggregated_data[device_id].sum / aggregated_data[device_id].count,
                   aggregated_data[device_id].min, aggregated_data[device_id].max);
        memset(&aggregated_data[device_id], 0, sizeof(AggregatedData));
    }
}

int realtimeDataAggregator(SensorConfig *configs, int config_count) {
    mqtt_t *mqtt_client = mqtt_init();
    for (int i = 0; i < config_count; i++) {
        mqtt_subscribe(mqtt_client, configs[i].topic, on_message_received, &configs[i]);
    }

    while (1) {
        mqtt_poll(mqtt_client);
        // Handle time window for triggering aggregation
        sleep(1); // Simplified example using sleep
    }

    mqtt_cleanup(mqtt_client);
    return 0;
}
```
This code snippet defines a `realtimeDataAggregator` function that initializes an MQTT client, subscribes to topics specified by a configuration array, and processes incoming messages to aggregate sensor data. Aggregated data is then persisted to a time-series database. The function uses a simple aggregation mechanism based on batch size and time window, which are configurable for each device. Error handling and logging mechanisms are not included in this example but should be added for a complete implementation.']

