#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10
#define MAX_QUEUE_SIZE 100

typedef struct {
    // Define the structure fields for PHY_STATS_PDU_T, NFAPI_CRC_INDICATION_PDU_T, and NFAPI_RRC_MEASUREMENT_REPORT
} QueueElement;

typedef struct {
    QueueElement elements[MAX_QUEUE_SIZE];
    int front;
    int rear;
    sem_t empty;
    sem_t full;
    pthread_mutex_t mutex;
} ThreadSafeQueue;

void initQueue(ThreadSafeQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
    sem_init(&queue->empty, 0, MAX_QUEUE_SIZE);
    sem_init(&queue->full, 0, 0);
    pthread_mutex_init(&queue->mutex, NULL);
}

int isQueueFull(ThreadSafeQueue *queue) {
    return (queue->rear + 1) % MAX_QUEUE_SIZE == queue->front;
}

int isQueueEmpty(ThreadSafeQueue *queue) {
    return queue->front == -1;
}

void enqueue(ThreadSafeQueue *queue, QueueElement element) {
    sem_wait(&queue->empty);
    pthread_mutex_lock(&queue->mutex);
    if (isQueueEmpty(queue)) {
        queue->front = 0;
    }
    queue->rear = (queue->rear + 1) % MAX_QUEUE_SIZE;
    queue->elements[queue->rear] = element;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->full);
}

QueueElement dequeue(ThreadSafeQueue *queue) {
    QueueElement item;
    sem_wait(&queue->full);
    pthread_mutex_lock(&queue->mutex);
    if (isQueueFull(queue)) {
        queue->front = 0;
        queue->rear = -1;
    }
    item = queue->elements[queue->front];
    queue->front = (queue->front + 1) % MAX_QUEUE_SIZE;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->empty);
    return item;
}

void *workerThread(void *arg) {
    ThreadSafeQueue *queue = (ThreadSafeQueue *) arg;
    while (1) {
        QueueElement element = dequeue(queue);
        // Process the dequeued element
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    ThreadSafeQueue queue;
    initQueue(&queue);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, workerThread, &queue);
    }

    // Simulate enqueuing elements
    QueueElement newElement;
    while (1) {
        enqueue(&queue, newElement);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
