#define MAX_REQUEST_SIZE 1024 * 1024
#define MAX_CONCURRENT_REQUESTS 10000

// Helper function to find the largest integer in an array
int findLargestInteger() {
    int max = INT_MIN;
    char input[MAX_REQUEST_SIZE];
    if (fgets(input, sizeof(input), stdin) == NULL) {
        return -1; // Error reading input
    }
    char *token = strtok(input, " ");
    while (token != NULL) {
        long num = strtol(token, NULL, 10);
        if (errno == ERANGE) {
            return -1; // Invalid integer format
        }
        if (num > max) {
            max = num;
        }
        token = strtok(NULL, " ");
    }
    return max;
}

int main() {
    int largestInteger = findLargestInteger();
    if (largestInteger != -1) {
        printf("The largest integer is: %d\n", largestInteger);
    } else {
        printf("Error processing input or invalid format.\n");
    }
    return 0;
}
