            if not file.startswith('.'):
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    md5_hash = hashlib.md5(f.read()).hexdigest()
                    hash_list.append((file, md5_hash))
    return hash_list

# Example usage
directory_path = '/path/to/directory'
md5_hashes = calculate_md5_hash(directory_path)
for file, hash in md5_hashes:
    print(f"File: {file}, MD5 Hash: {hash}")
```

