import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.KeySpec;
import javax.crypto.Cipher;
import javax.crypto.CipherInputStream;
import javax.crypto.CipherOutputStream;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;

public class SecureDeserializer {

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             CipherInputStream cis = new CipherInputStream(bis, createCipher("AES-256-CBC", "HMAC-SHA256"))) {
            ObjectInputStream ois = new ObjectInputStream(cis);
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed: " + e.getMessage(), e);
        }
    }

    private static Cipher createCipher(String algorithm, String hmacAlgorithm) throws NoSuchAlgorithmException, NoSuchPaddingException {
        SecretKey key = deriveKey("password", 10000);
        byte[] iv = generateIV(16);
        return Cipher.getInstance(algorithm + "/" + hmacAlgorithm);
    }

    private static SecretKey deriveKey(String password, int iterations) throws NoSuchAlgorithmException {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), iterations, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        return new SecretKeySpec(factory.generateSecret(spec).getEncoded(), "AES");
    }

    private static byte[] generateIV(int length) {
        byte[] iv = new byte[length];
        SecureRandom random = new SecureRandom();
        random.nextBytes(iv);
        return iv;
    }
}
