    pthread_cond_t cond;
    Record records[MAX_RECORDS];
    size_t count;
    size_t head;
    size_t tail;
    size_t capacity;
} ThreadSafeQueue;

void init_queue(ThreadSafeQueue *queue, size_t capacity) {
    queue->lock = PTHREAD_MUTEX_INITIALIZER;
    queue->cond = PTHREAD_COND_INITIALIZER;
    queue->records = (Record *)malloc(capacity * sizeof(Record));
    queue->count = 0;
    queue->head = 0;
    queue->tail = 0;
    queue->capacity = capacity;
}

void enqueue(ThreadSafeQueue *queue, Record record) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == queue->capacity) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    queue->records[queue->tail] = record;
    queue->tail = (queue->tail + 1) % queue->capacity;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

Record dequeue(ThreadSafeQueue *queue) {
    Record record;
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    record = queue->records[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return record;
}

