import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class SecureDeserializer {

    public static Object deserialize(byte[] data, Config config) {
        try {
            // Initialize cipher and key derivation
            Cipher cipher = initializeCipher(config);
            byte[] iv = generateIV();
            Key key = deriveKey(config.getPassword(), iv);

            // Decrypt the data
            byte[] decryptedData = decrypt(cipher, data, iv, key);

            // Verify HMAC
            if (!verifyHMAC(decryptedData, config.getHmac())) {
                throw new RuntimeException("HMAC verification failed");
            }

            // Deserialize the object
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decryptedData));
            return ois.readObject();
        } catch (Exception e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private static Cipher initializeCipher(Config config) throws NoSuchAlgorithmException, NoSuchPaddingException {
        switch (config.getAlgorithm()) {
            case AES_256_CBC:
                return Cipher.getInstance("AES/CBC/PKCS5Padding");
            case RSA_OAEP:
                return Cipher.getInstance("RSA/OAEPWithSHA-256AndMGF1Padding");
            case CHACHA20_POLY1305:
                return Cipher.getInstance("ChaCha20-Poly1305");
            default:
                throw new IllegalArgumentException("Unsupported algorithm: " + config.getAlgorithm());
        }
    }

    private static byte[] generateIV() {
        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);
        return iv;
    }

    private static Key deriveKey(String password, byte[] iv) throws NoSuchAlgorithmException, InvalidKeySpecException {
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), iv, 10000, 256);
        return factory.generateSecret(spec);
    }

    private static byte[] decrypt(Cipher cipher, byte[] data, byte[] iv, Key key) throws InvalidKeyException, IllegalBlockSizeException, BadPaddingException {
        cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(iv));
        return cipher.doFinal(data);
    }

    private static boolean verifyHMAC(byte[] data, byte[] hmac) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKey = new SecretKeySpec(hmac, "HmacSHA256");
            mac.init(secretKey);
            byte[] computedHmac = mac.doFinal(data);
            return Arrays.equals(computedHmac, hmac);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("HMAC verification failed", e);
        }
    }

    public static class Config {
        private String algorithm;
        private String password;
        private byte[] hmac;

        // Getters and setters
        public String getAlgorithm() {
            return algorithm;
        }

        public void setAlgorithm(String algorithm) {
            this.algorithm = algorithm;
        }

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }

        public byte[] getHmac() {
            return hmac;
        }

        public void setHmac(byte[] hmac) {
            this.hmac = hmac;
        }
    }
}
