import java.io.*;
import javax.crypto.*;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.*;

public class SerializationUtils {

    public static Object deserializeAndDecrypt(byte[] serializedData, String password) throws RuntimeException {
        try {
            byte[] iv = Arrays.copyOfRange(serializedData, 0, 16);
            byte[] encryptedData = Arrays.copyOfRange(serializedData, 16, serializedData.length);

            SecretKeySpec keySpec = generateKey(password);
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, keySpec, new IvParameterSpec(iv));

            byte[] decryptedData = cipher.doFinal(encryptedData);
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decryptedData));
            return ois.readObject();
        } catch (Exception e) {
            throw new RuntimeException("Deserialization and decryption failed", e);
        }
    }

    public static byte[] encryptAndSerialize(Object obj, String password) throws RuntimeException {
        try {
            SecretKeySpec keySpec = generateKey(password);
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            byte[] iv = new byte[16];
            SecureRandom random = SecureRandom.getInstanceStrong();
            random.nextBytes(iv);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, new IvParameterSpec(iv));

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(obj);
            byte[] encryptedData = cipher.doFinal(baos.toByteArray());

            byte[] result = new byte[iv.length + encryptedData.length];
            System.arraycopy(iv, 0, result, 0, iv.length);
            System.arraycopy(encryptedData, 0, result, iv.length, encryptedData.length);
            return result;
        } catch (Exception e) {
            throw new RuntimeException("Encryption and serialization failed", e);
        }
    }

    private static SecretKeySpec generateKey(String password) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 10000, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, "AES");
    }

    public static void cleanup(Cipher cipher) {
        try {
            if (cipher != null) {
                cipher.doFinal(new byte[0]);
                cipher = null;
            }
        } catch (Exception e) {
            // Handle exception
        }
    }
}
