import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.security.*;
import java.security.cert.CertificateFactory;
import java.util.HashMap;
import java.util.Map;

public class SecureObjectDeserializer {

    private static final String AES_CBC = "AES/CBC/PKCS5Padding";
    private static final String RSA_OAEP = "RSA/OAEPWithSHA-256AndMGF1Padding";
    private static final String CHACHA20_POLY1305 = "ChaCha20-Poly1305";

    public Object deserialize(byte[] encryptedData, Configuration config) {
        try {
            Cipher cipher = initializeCipher(config.getAlgorithm(), config.getKey());
            byte[] decryptedData = decrypt(cipher, encryptedData);
            HMACVerifier.verifyHMAC(decryptedData, config.getPassword());
            return readObject(decryptedData);
        } catch (Exception e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private Cipher initializeCipher(String algorithm, char[] key) throws NoSuchAlgorithmException, InvalidKeySpecException {
        KeyGenerator keyGen = KeyGenerator.getInstance(algorithm);
        keyGen.init(256); // For AES-256
        SecretKey secretKey = keyGen.generateKey();
        return Cipher.getInstance(algorithm);
