class RandomValueGenerator {
private:
    std::mt19937 gen;
    std::uniform_int_distribution<> intDist;
    std::uniform_real_distribution<float> floatDist;

public:
    RandomValueGenerator(unsigned long seed) : gen(seed), intDist(0, 100), floatDist(0.0f, 1.0f) {}

    void setIntRange(int min, int max) {
        intDist = std::uniform_int_distribution<>(min, max);
    }

    void setFloatRange(float min, float max) {
        floatDist = std::uniform_real_distribution<>(min, max);
    }

    int nextInt() {
        return intDist(gen);
    }

    float nextFloat() {
        return floatDist(gen);
    }

    void reset(unsigned long seed) {
        gen.seed(seed);
    }

    std::string ToString() const {
        std::ostringstream oss;
        oss << "RandomValueGenerator State - Int Range: [" << intDist.min() << ", " << intDist.max() << "] Last Int: " << intDist(gen)
            << ", Float Range: [" << floatDist.min() << ", " << floatDist.max() << "] Last Float: " << floatDist(gen);
        return oss.str();
    }
};

