// Define the structures
typedef struct {
    int TX_POWER_LEVEL;
    int CHANNEL_ID;
} PHY_STATS_PDU_T;

typedef struct {
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RRC_MEASUREMENT_REPORT;
} NFAPI_RRC_MEASUREMENT_REPORT;

// Define the queue node
typedef struct QueueNode {
    PHY_STATS_PDU_T* phy_stats_pdu;
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu;
    NFAPI_RRC_MEASUREMENT_REPORT* rrc_measurement_report;
    struct QueueNode* next;
} QueueNode;

// Define the queue structure
typedef struct Queue {
    QueueNode* front;
    QueueNode* rear;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Queue;

// Initialize the queue
void initQueue(Queue* q) {
    q->front = q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
}

// Enqueue a new node into the queue
void enqueue(Queue* q, PHY_STATS_PDU_T* phy_stats_pdu, NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu, NFAPI_RRC_MEASUREMENT_REPORT* rrc_measurement_report) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    newNode->phy_stats_pdu = phy_stats_pdu;
    newNode->crc_indication_pdu = crc_indication_pdu;
    newNode->rrc_measurement_report = rrc_measurement_report;
    newNode->next = NULL;

    pthread_mutex_lock(&q->mutex);
    if (q->rear != NULL) {
        q->rear->next = newNode;
    } else {
        q->front = newNode;
    }
    q->rear = newNode;
    q->size++;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue a node from the queue
QueueNode* dequeue(Queue* q) {
    pthread_mutex_lock(&q->mutex);
    while (q->front == NULL) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    QueueNode* temp = q->front;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    q->size--;
    pthread_mutex_unlock(&q->mutex);
    return temp;
}

// Free the queue and its nodes
void freeQueue(Queue* q) {
    while (q->front != NULL) {
        QueueNode* temp = q->front;
        q->front = q->front->next;
        free(temp->phy_stats_pdu);
        free(temp->crc_indication_pdu);
        free(temp->rrc_measurement_report);
        free(temp);
    }
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->cond);
}

int main(int argc, char* argv[]) {
    // Your implementation here
    return 0;
}
