#include <pthread.h>

#define MAX_CONNECTIONS 1000000

typedef struct {
    int CONNECTION_ID;
    time_t LAST_ACTIVE_TIME;
} TCPConnectionStats;

TCPConnectionStats *connection_stats = NULL;
pthread_mutex_t lock;

void init_connection_stats() {
    connection_stats = (TCPConnectionStats *)malloc(MAX_CONNECTIONS * sizeof(TCPConnectionStats));
    if (connection_stats == NULL) {
        fprintf(stderr, "Failed to allocate memory for connection stats\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_stats[i].CONNECTION_ID = i;
        connection_stats[i].LAST_ACTIVE_TIME = time(NULL);
    }
}

void update_connection_active_time(int connection_id) {
    pthread_mutex_lock(&lock);
    if (connection_id >= 0 && connection_id < MAX_CONNECTIONS) {
        connection_stats[connection_id].LAST_ACTIVE_TIME = time(NULL);
    } else {
        fprintf(stderr, "Invalid connection ID\n");
    }
    pthread_mutex_unlock(&lock);
}

void destroy_connection_stats() {
    free(connection_stats);
    pthread_mutex_destroy(&lock);
}

int main() {
    init_connection_stats();

    // Example usage
    update_connection_active_time(500000);

    destroy_connection_stats();
    return 0;
}
```

