} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_RRC_MEASUREMENT_REPORT {
    int PHY_CELL_ID;
    float MEASUREMENT_QUALITY;
    float* PHY_SIGNAL_STRENGTH;
    int SIGNAL_STRENGTH_COUNT;
} NFAPI_RRC_MEASUREMENT_REPORT;

typedef struct Metric {
    long timestamp;
    char metric_type[50];
    double value;
} Metric;

// Function to dynamically populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* populate_crc_indication_array(int N, int RNTI_MIN, int RNTI_MAX) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = RNTI_MIN + rand() % (RNTI_MAX - RNTI_MIN + 1);
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG within the valid range
    }
    return array;
}

// Function to populate a dynamic array of NFAPI_RRC_MEASUREMENT_REPORT structures
NFAPI_RRC_MEASUREMENT_REPORT* populate_measurement_report_array(int N) {
    NFAPI_RRC_MEASUREMENT_REPORT* array = (NFAPI_RRC_MEASUREMENT_REPORT*)malloc(N * sizeof(NFAPI_RRC_MEASUREMENT_REPORT));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < N; i++) {
        array[i].PHY_CELL_ID = rand() % 500 + 1; // Validate PHY_CELL_ID ranges
        array[i].MEASUREMENT_QUALITY = (float)rand() / RAND_MAX;
        array[i].SIGNAL_STRENGTH_COUNT = 16;
        array[i].PHY_SIGNAL_STRENGTH = (float*)malloc(16 * sizeof(float));
        if (array[i].PHY_SIGNAL_STRENGTH == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        for (int j = 0; j < 16; j++) {
            array[i].PHY_SIGNAL_STRENGTH[j] = (float)rand() / RAND_MAX;
        }
    }
    return array;
}

// Function to serialize the entire array to a binary file with metadata
void serialize_array(NFAPI_RRC_MEASUREMENT_REPORT* array, int N, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(&N, sizeof(int), 1, file); // Write the number of measurement reports
    for (int i = 0; i < N; i++) {
        fwrite(&array[i], sizeof(NFAPI_RRC_MEASUREMENT_REPORT), 1, file);
    }
    fclose(file);
}

// Function to add a new metric to the list
void add_metric(Metric** metrics, int* count, Metric new_metric) {
    *metrics = realloc(*metrics, (*count + 1) * sizeof(Metric));
    if (*metrics == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    (*metrics)[*count] = new_metric;
    (*count)++;
}

// Function to remove older metrics based on a specified retention period
void remove_older_metrics(Metric** metrics, int* count, long retention_period) {
    Metric* new_metrics = (Metric*)malloc((*count - 1) * sizeof(Metric));
    if (new_metrics == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    int new_count = 0;
    for (int i = 1; i < *count; i++) {
        if ((*metrics)[i].timestamp > (*metrics)[0].timestamp - retention_period) {
            new_metrics[new_count++] = (*metrics)[i];
        }
    }
    free(*metrics);
    *metrics = new_metrics;
    *count = new_count;
}

// Function to retrieve the average value within a given time window
double get_average_metric(Metric* metrics, int count, long start_time, long end_time) {
    double sum = 0;
    int count_in_window = 0;
    for (int i = 0; i < count; i++) {
        if (metrics[i].timestamp >= start_time && metrics[i].timestamp <= end_time) {
            sum += metrics[i].value;
            count_in_window++;
        }
    }
    return count_in_window > 0 ? sum / count_in_window : 0;
}

// Custom binary tree data structure
typedef struct TreeNode {
    Metric metric;
    int height;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

// Function to create a new tree node
TreeNode* create_node(Metric metric) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->metric = metric;
    node->height = 1;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Function to perform left rotation
TreeNode* rotate_left(TreeNode* y) {
    TreeNode* x = y->right;
    TreeNode* T2 = x->left;

    // Perform rotation
    x->left = y;
    y->right = T2;

    // Update heights
    y->height = 1 + (y->left ? y->left->height : 0) + (y->right ? y->right->height : 0);
    x->height = 1 + (x->left ? x->left->height : 0) + (x->right ? x->right->height : 0);

    return x;
}

// Function to perform right rotation
TreeNode* rotate_right(TreeNode* x) {
    TreeNode* y = x->left;
    TreeNode* T2 = y->right;

    // Perform rotation
    y->right = x;
    x->left = T2;

    // Update heights
    x->height = 1 + (x->left ? x->left->height : 0) + (x->right ? x->right->height : 0);
    y->height = 1 + (y->left ? y->left->height : 0) + (y->right ? y->right->height : 0);

    return y;
}

// Function to get the balance factor
int get_balance(TreeNode* node) {
    if (node == NULL)
        return 0;
    return (node->left ? node->left->height : 0) - (node->right ? node->right->height : 0);
}

// Function to insert a new metric into the binary tree
TreeNode* insert_metric(TreeNode* root, Metric metric) {
    if (root == NULL)
        return create_node(metric);

    if (metric.timestamp < root->metric.timestamp)
        root->left = insert_metric(root->left, metric);
    else if (metric.timestamp > root->metric.timestamp)
        root->right = insert_metric(root->right, metric);
    else
        return root; // Duplicate keys are not allowed

    // Update height of this ancestor node
    root->height = 1 + (root->left ? root->left->height : 0) + (root->right ? root->right->height : 0);

    int balance = get_balance(root);

    // If this node becomes unbalanced, then there are 4 cases

    if (balance > 1 && metric.timestamp < root->left->metric.timestamp)
        return rotate_right(root);

    if (balance < -1 && metric.timestamp > root->right->metric.timestamp)
        return rotate_left(root);

    if (balance > 1 && metric.timestamp > root->left->metric.timestamp) {
        root->left = rotate_left(root->left);
        return rotate_right(root);
    }

    if (balance < -1 && metric.timestamp < root->right->metric.timestamp) {
        root->right = rotate_right(root->right);
        return rotate_left(root);
    }

    return root;
}

// Function to traverse and print the binary tree
void in_order_traversal(TreeNode* root) {
    if (root != NULL) {
        in_order_traversal(root->left);
        printf("Timestamp: %ld, Metric Type: %s, Value: %.2f\n", root->metric.timestamp, root->metric.metric_type, root->metric.value);
        in_order_traversal(root->right);
    }
}

// Function to free the memory allocated for a binary tree
void delete_tree(TreeNode* root) {
    if (root != NULL) {
        delete_tree(root->left);
        delete_tree(root->right);
        free(root);
    }
}
