#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int FRAME_NUMBER;
    int TX_POWER_LEVEL;
    float RB_UTILIZATION;
    time_t LAST_UPDATE_TIME;
} LTE_PHY_FRAME_STATS;

LTE_PHY_FRAME_STATS *frame_stats[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex;

void init_frame_stats() {
    pthread_mutex_init(&mutex, NULL);
}

int add_update_entry(int frame_number, int tx_power_level, float rb_utilization) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < entry_count; i++) {
        if (frame_stats[i]->FRAME_NUMBER == frame_number) {
            free(frame_stats[i]);
            break;
        }
    }
    LTE_PHY_FRAME_STATS *new_entry = malloc(sizeof(LTE_PHY_FRAME_STATS));
    if (!new_entry) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failed
    }
    new_entry->FRAME_NUMBER = frame_number;
    new_entry->TX_POWER_LEVEL = tx_power_level;
    new_entry->RB_UTILIZATION = rb_utilization;
    new_entry->LAST_UPDATE_TIME = time(NULL);
    if (entry_count >= MAX_ENTRIES) {
        free(new_entry);
        pthread_mutex_unlock(&mutex);
        return -2; // Maximum entries reached
    }
    frame_stats[entry_count++] = new_entry;
    pthread_mutex_unlock(&mutex);
    return 0;
}

LTE_PHY_FRAME_STATS* get_entry(int frame_number) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < entry_count; i++) {
        if (frame_stats[i]->FRAME_NUMBER == frame_number) {
            pthread_mutex_unlock(&mutex);
            return frame_stats[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup_outdated_entries(time_t threshold) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < entry_count; ) {
        if (time(NULL) - frame_stats[i]->LAST_UPDATE_TIME > threshold) {
            free(frame_stats[i]);
            memmove(&frame_stats[i], &frame_stats[i + 1], sizeof(LTE_PHY_FRAME_STATS*) * (entry_count - i - 1));
            entry_count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void destroy_frame_stats() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < entry_count; i++) {
        free(frame_stats[i]);
    }
    entry_count = 0;
    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);
}
