import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import javax.crypto.Cipher;
import javax.crypto.CipherInputStream;
import javax.crypto.CipherOutputStream;
import javax.crypto.KeyGenerator;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class SecureSerialization {

    public static <T> T deserialize(byte[] data, String algorithm, byte[] password) throws RuntimeException {
        try {
            // HMAC verification
            if (!verifyHMAC(data, password)) {
                throw new RuntimeException("Integrity check failed");
            }

            // AES encryption
            SecretKey secretKey = generateAESKey(password);
            IvParameterSpec iv = generateIV();
            Cipher cipher = Cipher.getInstance(algorithm);
            cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);

            // Custom class loader for dynamic class loading and unloading
            ClassLoader customClassLoader = new CustomClassLoader();

            ByteArrayInputStream bais = new ByteArrayInputStream(data);
            CipherInputStream cis = new CipherInputStream(bais, cipher);
            ObjectInputStream ois = new ObjectInputStream(cis);

            // Use the custom class loader to load the deserialized object
            return (T) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private static SecretKey generateAESKey(byte[] password) throws NoSuchAlgorithmException, InvalidKeySpecException {
        KeySpec spec = new PBEKeySpec(password, "salt".getBytes(), 10000, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, "AES");
    }

    private static IvParameterSpec generateIV() {
        byte[] iv = new byte[16];
        // SecureRandom.getInstanceStrong().nextBytes(iv); // Uncomment for secure random IV
        return new IvParameterSpec(iv);
    }

    private static boolean verifyHMAC(byte[] data, byte[] password) throws NoSuchAlgorithmException {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec secretKeySpec = new SecretKeySpec(password, "HmacSHA256");
        mac.init(secretKeySpec);
        byte[] hmacBytes = mac.doFinal(data);
        // Compare the HMAC with the one stored in the data
        return MessageDigest.isEqual(hmacBytes, Arrays.copyOfRange(data, data.length - 32, data.length));
    }

    static class CustomClassLoader extends ClassLoader {
        public CustomClassLoader() {
            super(SecureSerialization.class.getClassLoader());
        }

        @Override
        protected Class<?> findClass(String name) throws ClassNotFoundException {
            // Custom logic for loading classes
            try {
