import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;

public class SecureSerializer {

    public static byte[] serializeAndEncrypt(byte[] data, Config config) throws Exception {
        Cipher cipher = initCipher(config.getAlgorithm(), "ENCRYPT_MODE", config.getKey());
        byte[] encryptedData = cipher.doFinal(data);
        return encryptedData;
    }

    public static byte[] decryptAndDeserialize(byte[] encryptedData, Config config) throws Exception {
        Cipher cipher = initCipher(config.getAlgorithm(), "DECRYPT_MODE", config.getKey());
        byte[] decryptedData = cipher.doFinal(encryptedData);
        return decryptedData;
    }

    private static Cipher initCipher(String algorithm, String mode, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        if (algorithm.equals("AES/CBC/PKCS5Padding") || algorithm.equals("ChaCha20-Poly1305")) {
            IvParameterSpec iv = generateIV(16);
            cipher.init(Cipher.ENCRYPT_MODE, key, iv);
        } else if (algorithm.equals("RSA/OAEPWithSHA-256AndMGF1Padding")) {
            KeyFactory keyFactory = KeyFactory.getInstance("RSA");
            PublicKey publicKey = keyFactory.generatePublic(new X509EncodedKeySpec(key.getEncoded()));
            cipher.init(Cipher.ENCRYPT_MODE, publicKey);
        }
        return cipher;
    }

    private static IvParameterSpec generateIV(int ivLength) throws NoSuchAlgorithmException {
        byte[] iv = new byte[ivLength];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        return new IvParameterSpec(iv);
    }

    public static SecretKey deriveKey(String password, int iterations, int keyLength) throws Exception {
        KeyGenerator kgen = KeyGenerator.getInstance("AES");
        kgen.init(keyLength);
        byte[] salt = generateSalt();
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec spec = new PBEKeySpec(password.toCharArray(), salt, iterations, keyLength * 8);
        return new SecretKeySpec(factory.generateSecret(spec).getEncoded(), "AES");
    }

    private static byte[] generateSalt() throws NoSuchAlgorithmException {
        SecureRandom.getInstanceStrong().nextBytes(16);
        return new byte[16];
    }

    public static class Config {
        private String algorithm;
        private SecretKey key;

        public Config(String algorithm, SecretKey key) {
            this.algorithm = algorithm;
            this.key = key;
        }

        public String getAlgorithm() {
            return algorithm;
        }

        public SecretKey getKey() {
            return key;
        }
    }
}
