    printf("Usage: task_manager [options]\n");
    printf("Options:\n");
    printf("  -h, --help                Display help information\n");
    printf("  --manpage                 Display detailed documentation\n");
    printf("  -a <task>                  Add a new task to the list\n");
    printf("  -r <index>                 Remove a specific task from the list by its index\n");
    printf("  -l                         List all tasks currently stored in the list\n");
    printf("  -u <index> <new_task>      Update a task at a specific index with a new task description\n");
    printf("  -c                         Clear the entire task list\n");
}

void save_tasks() {
    // Implement file saving logic here
}

void load_tasks() {
    // Implement file loading logic here
}

void *save_task_thread(void *arg) {
    while (1) {
        sleep(60); // Save tasks every minute
        pthread_mutex_lock(&task_lock);
        save_tasks();
        pthread_mutex_unlock(&task_lock);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t save_thread;
    pthread_create(&save_thread, NULL, save_task_thread, NULL);

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            display_help();
        } else if (strcmp(argv[i], "--manpage") == 0) {
            // Display manpage logic here
        } else if (strncmp(argv[i], "-a ", 3) == 0) {
            pthread_mutex_lock(&task_lock);
            char *new_task = argv[i] + 3;
            if (strlen(new_task) > MAX_TASK_LENGTH) {
                printf("Task too long\n");
                continue;
            }
            if (task_count >= max_task_count) {
                task_count++;
                task_list = realloc(task_list, task_count * sizeof(Task));
            }
            strcpy(task_list[task_count - 1].description, new_task);
            task_list[task_count - 1].priority = 0; // Default priority
            pthread_mutex_unlock(&task_lock);
        } else if (strncmp(argv[i], "-r ", 3) == 0) {
            // Remove task logic here
        } else if (strcmp(argv[i], "-l") == 0) {
            pthread_mutex_lock(&task_lock);
            for (int j = 0; j < task_count; j++) {
                printf("%d: %s\n", j, task_list[j].description);
            }
            pthread_mutex_unlock(&task_lock);
        } else if (strncmp(argv[i], "-u ", 3) == 0) {
            // Update task logic here
        } else if (strcmp(argv[i], "-c") == 0) {
            pthread_mutex_lock(&task_lock);
            free(task_list);
            task_count = 0;
            task_list = NULL;
            pthread_mutex_unlock(&task_lock);
        } else {
            printf("Invalid option: %s\n", argv[i]);
        }
    }

    pthread_join(save_thread, NULL);
    return 0;
}
