void process_file(const char *filename, const char *output_format, int keywords_count, char **keywords) {
    FILE *input = fopen(filename, "r");
    if (!input) {
        log_error("Failed to open input file.");
        return;
    }

    FILE *output = NULL;
    if (strcmp(output_format, "CSV") == 0) {
        output = fopen("output.csv", "w");
        fprintf(output, "Line Number, Line Length\n");
    } else if (strcmp(output_format, "JSON") == 0) {
        output = fopen("output.json", "w");
        fprintf(output, "{\n  \"summary\": {\n    \"line_count\": 0,\n    \"average_line_length\": 0.0,\n    \"keyword_frequency\": {\n");
    }

    char line[MAX_LINE_LENGTH];
    int line_number = 0;
    size_t total_length = 0;

    while (fgets(line, MAX_LINE_LENGTH, input)) {
        line_number++;
        total_length += strlen(line);

        if (output) {
            if (strcmp(output_format, "CSV") == 0) {
                fprintf(output, "%d,%zu\n", line_number, strlen(line));
            } else if (strcmp(output_format, "JSON") == 0) {
                // Process JSON output
            }
        }

        // Check for keywords
        for (int i = 0; i < keywords_count; i++) {
            char *pos = strstr(line, keywords[i]);
            while (pos) {
                printf("Keyword '%s' found at line %d.\n", keywords[i], line_number);
                pos = strstr(pos + strlen(keywords[i]), keywords[i]);
            }
        }
    }

    if (output && strcmp(output_format, "JSON") == 0) {
        fprintf(output, "\n    }\n  }\n}\n");
    }

    fclose(input);
    if (output) {
        fclose(output);
    }

    printf("Processed %d lines with average length of %.2f.\n", line_number, (double)total_length / line_number);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_format> [keywords...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    const char *output_format = argv[2];
    int keywords_count = argc - 3;
    char **keywords = &argv[3];

    log_progress("Starting file processing.");

    process_file(filename, output_format, keywords_count, keywords);

    log_progress("File processing completed successfully.");

    return EXIT_SUCCESS;
}
