typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    if (list_size < MAX_LIST_SIZE) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = head;
        head = new_node;
        list_size++;
    } else {
        printf("List size exceeded. Cannot add more elements.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void remove_from_list(int rnti) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list_size--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

