typedef struct NFAPI_RRC_MEASUREMENT_REPORT {
    int RX_UE_INFORMATION_TAG;
} NFAPI_RRC_MEASUREMENT_REPORT;

// Define thread-safe queue structure
typedef struct ThreadSafeQueue {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int *data;
    int front, rear, size, count;
} ThreadSafeQueue;

// Initialize thread-safe queue
void init_thread_safe_queue(ThreadSafeQueue *queue, int size) {
    queue->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    queue->cond = (pthread_cond_t)PTHREAD_COND_INITIALIZER;
    queue->data = (int *)malloc(size * sizeof(int));
    queue->front = 0;
    queue->rear = -1;
    queue->size = size;
    queue->count = 0;
}

// Enqueue element
void enqueue(ThreadSafeQueue *queue, int item) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == queue->size) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    if (queue->rear == queue->size - 1) {
        queue->rear = -1;
    }
    queue->data[++queue->rear] = item;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

// Dequeue element
int dequeue(ThreadSafeQueue *queue) {
    int item;
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    item = queue->data[queue->front++];
    if (queue->front == queue->size) {
        queue->front = 0;
    }
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return item;
}

// Free thread-safe queue
void free_thread_safe_queue(ThreadSafeQueue *queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
}

