public class ProtobufSerializer {

    public static <T extends GeneratedMessageV3> byte[] serialize(T message) throws RuntimeException {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            message.writeTo(baos);
            return baos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Serialization failed", e);
        }
    }

    public static <T extends GeneratedMessageV3> T deserialize(Class<T> clazz, byte[] data) throws RuntimeException {
        try {
            return clazz.getConstructor().newInstance().toBuilder().mergeFrom(data).build();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
            throw new RuntimeException("Deserialization failed", e);
        } catch (InvalidProtocolBufferException e) {
            throw new RuntimeException("Failed to parse Protocol Buffer data", e);
        }
    }

    // Custom serializer for complex nested objects
    public static <T extends GeneratedMessageV3> byte[] serializeNested(T message, Map<String, Object> fieldDefaults) throws RuntimeException {
