#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 50000
#define MAX_LOG_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} SafeList;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
} DuplicateLogEntry;

DuplicateLogEntry log_entries[MAX_LOG_ENTRIES];
int log_count = 0;
pthread_mutex_t log_mutex;

void initialize_list(SafeList *list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
}

void destroy_list(SafeList *list) {
    pthread_mutex_destroy(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    list->count = 0;
}

bool add_to_list(SafeList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->data[i]->rnti == pdu->rnti || list->data[i]->rx_tag == pdu->rx_tag && time(NULL) - list->data[i]->timestamp < 24 * 60 * 60) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }
    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    list->data[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void log_duplicate_entry(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&log_mutex);
    if (log_count < MAX_LOG_ENTRIES) {
        log_entries[log_count].pdu = *pdu;
        log_entries[log_count].timestamp = time(NULL);
        log_count++;
    }
    pthread_mutex_unlock(&log_mutex);
}

void print_list(SafeList *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        printf("RX Tag: %d, RNTI: %d, CRC Flag: %d\n", 
               list->data[i]->rx_tag, list->data[i]->rnti, list->data[i]->crc_indication.crcflag);
    }
    pthread_mutex_unlock(&list->mutex);
}

// Example usage:
int main() {
    SafeList myList;
    initialize_list(&myList);

    // Populate the list with random data
    srand(time(NULL));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newPdu->rx_tag = rand();
        newPdu->rnti = rand();
        newPdu->crc_indication.crcflag = (rand() % 2) == 0;
        if (!add_to_list(&myList, newPdu)) {
            log_duplicate_entry(newPdu);
            free(newPdu);
        }
    }

    print_list(&myList);

    destroy_list(&myList);
    return 0;
}
