#define MAX_ENTRIES 50000

typedef struct {
    int cellID;
    char RRCstate[20];
    char PLMNidentifier[16];
} LTE_UE_context;

LTE_UE_context *ue_list[MAX_ENTRIES];
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
time_t expiration_time[MAX_ENTRIES];

void initialize_UE_contexts() {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        ue_list[i] = NULL;
        expiration_time[i] = 0;
    }
}

void add_UE_context(int cellID, char *RRCstate, char *PLMNidentifier) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (ue_list[i] == NULL) {
            ue_list[i] = (LTE_UE_context *)malloc(sizeof(LTE_UE_context));
            expiration_time[i] = time(NULL) + 3600; // Example: Context expires in 1 hour
            snprintf(ue_list[i]->cellID, sizeof(ue_list[i]->cellID), "%d", cellID);
            snprintf(ue_list[i]->RRCstate, sizeof(ue_list[i]->RRCstate), "%s", RRCstate);
            snprintf(ue_list[i]->PLMNidentifier, sizeof(ue_list[i]->PLMNidentifier), "%s", PLMNidentifier);
            pthread_mutex_unlock(&list_lock);
            return;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void print_UE_contexts() {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (ue_list[i] != NULL && expiration_time[i] > time(NULL)) {
            printf("Cell ID: %s, RRC State: %s, PLMN Identifier: %s\n", ue_list[i]->cellID, ue_list[i]->RRCstate, ue_list[i]->PLMNidentifier);
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void cleanup_UE_contexts() {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (ue_list[i] != NULL && expiration_time[i] <= time(NULL)) {
            free(ue_list[i]);
            ue_list[i] = NULL;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void *thread_function(void *arg) {
    int cellID = *(int *)arg;
    char RRCstate[] = "Connected";
    char PLMNidentifier[] = "1234567890";
    add_UE_context(cellID, RRCstate, PLMNidentifier);
    return NULL;
}

int main() {
    initialize_UE_contexts();
    pthread_t threads[MAX_ENTRIES];
    int cellIDs[MAX_ENTRIES];

    for (int i = 0; i < MAX_ENTRIES; i++) {
        cellIDs[i] = i + 1;
        pthread_create(&threads[i], NULL, thread_function, &cellIDs[i]);
    }

    for (int i = 0; i < MAX_ENTRIES; i++) {
        pthread_join(threads[i], NULL);
    }

    print_UE_contexts();
    cleanup_UE_contexts();

    return 0;
}
```

This code snippet provides a basic implementation of the requested functionality. It includes functions to initialize, add, print, and clean up LTE UE context information structures in a thread-safe manner. The `add_UE_context` function ensures that no two entries share the same cell ID by using dynamic memory allocation for each new entry. The `print_UE_contexts` function iterates over the list and prints out each entry's details. The `cleanup_UE_contexts` function periodically cleans up expired contexts based on a predefined expiration time. The code also includes thread creation and joining to simulate concurrent access from multiple threads.']

