    size_t pool_size;
    size_t allocated_count;
    pthread_mutex_t lock;
} PoolAllocator;

PoolAllocator allocator = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&allocator.lock);
    if (allocator.allocated_count >= allocator.pool_size) {
        pthread_mutex_unlock(&allocator.lock);
        return NULL; // Pool full
    }
    NFAPI_CRC_INDICATION_PDU_T* new_struct = &allocator.pool[allocator.allocated_count++];
    pthread_mutex_unlock(&allocator.lock);
    return new_struct;
}

