    pthread_mutex_lock(&allocator.lock);
    for (size_t i = 0; i < allocator.allocated_count; ++i) {
        if (&allocator.pool[i] == ptr) {
            allocator.allocated_count--;
            memmove(&allocator.pool[i], &allocator.pool[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (allocator.allocated_count - i));
            break;
        }
    }
    pthread_mutex_unlock(&allocator.lock);
}

