    size_t count;
    pthread_mutex_t lock;
    time_t last_cleanup_time;
    int ttl;
} LTE_UE_List;

LTE_UE_List* create_lte_ue_list(int ttl) {
    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->last_cleanup_time = time(NULL);
    list->ttl = ttl;
    for (size_t i = 0; i < MAX_UE_CONTEXTS; ++i) {
        list->contexts[i] = NULL;
    }
    return list;
}

void destroy_lte_ue_list(LTE_UE_List* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i]);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_ue_context(LTE_UE_List* list, LTE_UE_Context* context) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->cell_id == context->cell_id) {
            pthread_mutex_unlock(&list->lock);
            return -2;
        }
    }
    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* clean_up_thread(void* arg) {
    LTE_UE_List* list = (LTE_UE_List*)arg;
    while (1) {
        sleep(list->ttl);
        time_t current_time = time(NULL);
        if (current_time - list->last_cleanup_time >= list->ttl) {
            pthread_mutex_lock(&list->lock);
            for (size_t i = 0; i < list->count; ++i) {
                if (current_time - list->contexts[i]->cell_id > list->ttl) {
                    free(list->contexts[i]);
                    list->contexts[i] = NULL;
                }
            }
            list->last_cleanup_time = current_time;
            pthread_mutex_unlock(&list->lock);
        }
    }
    return NULL;
}

void print_ue_contexts(LTE_UE_List* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        printf("Cell ID: %d, RRC State: %s, PLMN ID: %s\n",
               list->contexts[i]->cell_id,
               list->contexts[i]->rrc_state,
               list->contexts[i]->plmn_id);
    }
    pthread_mutex_unlock(&list->lock);
}
