void initialize_crc_indication(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 500 + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 32768;
