int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s -i input_file -o output_file\n", argv[0]);
        return 1;
    }

    const char* input_file = NULL;
    const char* output_file = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s -i input_file -o output_file\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            input_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        }
    }

    if (!input_file || !output_file) {
        fprintf(stderr, "Missing input or output file.\n");
        return 1;
    }

    FILE* input = fopen(input_file, "r");
    if (!input) {
        perror("Failed to open input file");
        return 1;
    }

    size_t N = 0;
    while (fgets(NULL, 0, input)) ++N; // Count lines
    rewind(input);

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        fclose(input);
        return 1;
    }

    initialize_crc_indication(array, N);

    // Process array...

    free(array);
    fclose(input);

    return 0;
}
