import com.google.protobuf.InvalidProtocolBufferException;

public class ProtocolBuffersService {

    public static byte[] serialize(ComplexObject object) {
        try {
            return object.toByteArray();
        } catch (RuntimeException e) {
            throw new RuntimeException("Failed to serialize ComplexObject", e);
        }
    }

    public static ComplexObject deserialize(byte[] byteArray, Class<ComplexObject> clazz) {
        try {
            return clazz.newBuilder().mergeFrom(byteArray).build();
        } catch (InvalidProtocolBufferException e) {
            // Handle corrupted data gracefully by providing sensible defaults
            return clazz.newBuilder().buildPartial();
        }
    }
}
