#include <stdlib.h>
#include <pthread.h>

#define MAX_PDUS 1024

typedef struct {
    uint32_t RACH_REQUEST_TAG;
    uint16_t RNTI;
    uint8_t PHICH_GROUP_HOPPING_PATTERN;
} NFAPI_RACH_INDICATION_PDU_T;

typedef struct {
    NFAPI_RACH_INDICATION_PDU_T pdus[MAX_PDUS];
    int count;
    pthread_mutex_t mutex;
} PduList;

void initPduList(PduList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int addPduToList(PduList *list, NFAPI_RACH_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int removePduFromList(PduList *list, uint32_t tag) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        if (list->pdus[i].RACH_REQUEST_TAG == tag) {
            for (int j = i; j < list->count - 1; ++j) {
                list->pdus[j] = list->pdus[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Tag not found
}

void freePduList(PduList *list) {
    pthread_mutex_destroy(&list->mutex);
}
