#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_RACH_INDICATION_PDU_T pdu;
    pthread_mutex_t lock;
} RACH_LIST_ENTRY;

typedef struct {
    RACH_LIST_ENTRY* entries;
    size_t capacity;
    size_t size;
    int debug_level;
    size_t batch_size;
    pthread_mutex_t resize_lock;
    pthread_cond_t resize_cv;
} RACH_LIST;

RACH_LIST* rach_list_create(size_t initial_capacity, int debug_level, size_t batch_size) {
    RACH_LIST* list = (RACH_LIST*)malloc(sizeof(RACH_LIST));
    if (!list) return NULL;

    list->entries = (RACH_LIST_ENTRY*)calloc(initial_capacity, sizeof(RACH_LIST_ENTRY));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    list->debug_level = debug_level;
    list->batch_size = batch_size;

    pthread_mutex_init(&list->resize_lock, NULL);
    pthread_cond_init(&list->resize_cv, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&list->entries[i].lock, NULL);
    }

    return list;
}

void rach_list_destroy(RACH_LIST* list) {
    if (!list) return;

    for (size_t i = 0; i < list->capacity; ++i) {
        pthread_mutex_destroy(&list->entries[i].lock);
    }

    pthread_mutex_destroy(&list->resize_lock);
    pthread_cond_destroy(&list->resize_cv);

    free(list->entries);
    free(list);
}

int rach_list_add(RACH_LIST* list, const NFAPI_RACH_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    pthread_mutex_lock(&list->resize_lock);
    while (list->size >= list->capacity) {
        pthread_cond_wait(&list->resize_cv, &list->resize_lock);
    }

    size_t index = list->size++;
    pthread_mutex_unlock(&list->resize_lock);

    pthread_mutex_lock(&list->entries[index].lock);
    list->entries[index].pdu = *pdu;
    pthread_mutex_unlock(&list->entries[index].lock);

    return 0;
}

int rach_list_batch_add(RACH_LIST* list, const NFAPI_RACH_INDICATION_PDU_T* pdus, size_t count) {
    if (!list || !pdus || count == 0) return -1;

    for (size_t i = 0; i < count; ++i) {
        if (rach_list_add(list, &pdus[i]) != 0) {
            return -1;
        }
    }

    return 0;
}

void rach_list_reset(RACH_LIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->resize_lock);
    for (size_t i = 0; i < list->size; ++i) {
        pthread_mutex_lock(&list->entries[i].lock);
        memset(&list->entries[i], 0, sizeof(RACH_LIST_ENTRY));
        pthread_mutex_unlock(&list->entries[i].lock);
    }
    list->size = 0;
    pthread_cond_broadcast(&list->resize_cv);
    pthread_mutex_unlock(&list->resize_lock);
}
