#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_PDUS 1024
#define DEFAULT_BATCH_SIZE 32

typedef struct {
    int RACH_REQUEST_TAG;
    unsigned short RNTI;
    int PHICH_GROUP_HOPPING_PATTERN;
} NFAPI_RACH_INDICATION_PDU_T;

typedef struct {
    NFAPI_RACH_INDICATION_PDU_T *pdus[MAX_PDUS];
    int size;
    int capacity;
    int batch_size;
    pthread_mutex_t mutex;
    bool debug_logging;
} RACH_List;

RACH_List* rach_list_create(int initial_capacity, int batch_size, bool debug_logging) {
    RACH_List* list = (RACH_List*)malloc(sizeof(RACH_List));
    if (!list) return NULL;

    list->pdus[0] = (NFAPI_RACH_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_RACH_INDICATION_PDU_T));
    if (!list->pdus[0]) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    list->batch_size = batch_size ? batch_size : DEFAULT_BATCH_SIZE;
    pthread_mutex_init(&list->mutex, NULL);
    list->debug_logging = debug_logging;

    return list;
}

void rach_list_destroy(RACH_List* list) {
    for (int i = 0; i < list->size; ++i) {
        free(list->pdus[i]);
    }
    free(list->pdus[0]);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool rach_list_add(RACH_List* list, NFAPI_RACH_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NFAPI_RACH_INDICATION_PDU_T** new_pdus = (NFAPI_RACH_INDICATION_PDU_T**)realloc(list->pdus, new_capacity * sizeof(NFAPI_RACH_INDICATION_PDU_T*));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    list->pdus[list->size] = (NFAPI_RACH_INDICATION_PDU_T*)malloc(sizeof(NFAPI_RACH_INDICATION_PDU_T));
    if (!list->pdus[list->size]) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    *list->pdus[list->size] = pdu;
    ++list->size;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void rach_list_process_batch(RACH_List* list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size && i < list->batch_size; ++i) {
        NFAPI_RACH_INDICATION_PDU_T pdu = *list->pdus[i];
        // Process the PDU
        if (list->debug_logging) {
            printf("Processing PDU with RNTI: %d, TAG: %d\n", pdu.RNTI, pdu.RACH_REQUEST_TAG);
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void rach_list_reset(RACH_List* list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; ++i) {
        free(list->pdus[i]);
    }
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);
}
